TURATH_CHUNK(48,[{"num":9600,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عَبَّاسٍ قَالَ: كَانَ نعل النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَالاَنِ، مثْنيّ شِرَاكُهُمَا."],"takhrij":"صحيح: رواه الترمذي في الشمائل (72) وابن ماجة (3614) كلاهما من طريق وكيع، عن سفيان، عن خالد الحذّاء، عن عبد الله بن الحارث عن ابن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في نعل النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī in Al-Shamā’il (72) and Ibn Mājah (3614).","chapter_en":"The Prophet’s ﷺ Sandals","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās said: Each sandal of the Prophet ﷺ had two straps, with its thong doubled."]}},"tuhfa":{},"voc":["seerah",1352],"full":1,"dr":1,"tks":"صحيح: رواه الترمذي في الشمائل (72)، وابن ماجه (3614)."},{"num":9601,"demo":false,"sanad":"","matn":["عَنْ ابْنِ عُمَرَ أَنَّهُ قِيلَ لَهُ: يَا أَبَا عَبْدِ الرَّحْمَـٰنِ رَأَيْتُكَ تَصْنَعُ أَرْبَعًا لَمْ أَرَ أَحَدًا مِنْ أَصْحَابِكَ يَصْنَعُهَا قَالَ: وَمَا هِيَ يَا ابْنَ جُرَيْجٍ؟ فَذَكَرَهَا وَمِنْهَا: وَرَأَيْتُكَ تَلْبَسُ النِّعَالَ السَّبَتِيَّةَ، فَقَالَ: وَأَمَّا النِّعَالُ السَّبَتِيَّةُ فَإِنِّي رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم يَلْبَسُ النَّعْلَ الَّتِي لَيْسَ فِيهَا شَعَرٌ وَيَتَوَضَّأُ فِيهَا، فَأَنَا أُحِبُّ أَنْ أَلْبَسَهَا...الحديث."],"takhrij":"متفق عليه: رواه مالك في الحج (33) عن سعيد بن أبي سعيد المقبري، عن عبيد بن جريج أنه قال لعبد الله بن عمر: فذكره. ورواه البخاري في اللباس (5851) ومسلم في الحج (25:1187) كلاهما من طريق مالك به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في نعل النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik in the Book of Ḥajj (33), al-Bukhārī (5851), and Muslim (1187/25).","chapter_en":"The Prophet’s ﷺ Sandals","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿUmar was asked: “O Abū ʿAbd al-Raḥmān, I have seen you do four things that I have not seen any of your companions do.” He said: “What are they, Ibn Jurayj?” He mentioned them, including: “I have seen you wearing sabtī sandals.” Ibn ʿUmar replied: “As for the sabtī sandals, I saw the Messenger of Allah ﷺ wearing sandals made from leather from which the hair had been removed, and he would perform ablution while wearing them. Therefore, I love to wear them”… the remainder of the hadith."]}},"tuhfa":{},"voc":["seerah",1353],"full":1,"tks":"متفق عليه: رواه مالك (33)، والبخاري (5851)، ومسلم (25:1187)."},{"num":9602,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: كَانَ لِنَعْلِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِبَالَانِ."],"takhrij":"حسن: رواه الترمذي في الشمائل (75) والطبراني في الصغير (254) كلاهما من طريق عبد الرزاق، حدثنا معمر، عن ابن أبي ذئب، عن صالح مولى التوأمة، عن أبي هريرة قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في نعل النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī in Al-Shamā’il (75) and al-Ṭabarānī in Al-Muʿjam al-Ṣaghīr (254).","chapter_en":"The Prophet’s ﷺ Sandals","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":3,"content":{"translation":{"en":["Abū Hurayrah said: Each sandal of the Messenger of Allah ﷺ had two straps."]}},"tuhfa":{},"voc":["seerah",1354],"full":1,"dr":1,"tks":"حسن: رواه الترمذي في الشمائل (75)، والطبراني في الصغير (254)."},{"num":9603,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: لَمَّا أَرَادَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الرُّومِ، قَالَ: قَالُوا: إِنَّهُمْ لاَ يقرؤون كِتَابًا إِلاَّ مَخْتُومًا قَالَ: فَاتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ فِضَّةٍ كَأَنِّي أَنْظُرُ إِلَى بياضه فِي يَدِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، نقشه مُحَمَّدٌ رَسُولُ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2938) وفي اللباس bukhari(5875) ومسلم في اللباس (56:2092) كلاهما من طريق شعبة قال: سمعت قتادة يحدث عن أنس بن مالك قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2938, 5875) and Muslim (2092:56).","chapter_en":"The Signet Ring of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported: When the Messenger of Allah ﷺ intended to write to the Byzantines, he was informed, “They do not read a letter unless it bears a seal.” The Messenger of Allah ﷺ therefore had a silver signet ring made. It is as though I can still see its whiteness upon the Messenger of Allah’s ﷺ hand. Its inscription was: Muḥammad, the Messenger of Allah."]},"buhuth":{"en":["Other wordings state: “When he intended to write to the non-Arabs,” and: “to Chosroes, Caesar, and the Negus.”"]}},"tuhfa":{},"voc":["seerah",1355],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2938)، وفي اللباس bukhari(5875)، ومسلم (56: 2092)."},{"num":9604,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: اتَّخَذَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ، وَكَانَ فِي يَدِهِ، ثُمَّ كَانَ بَعْدُ فِي يَدِ أَبِي بَكْرٍ، ثُمَّ كَانَ بَعْدُ فِي يَدِ عُمَرَ، ثُمَّ كَانَ بَعْدُ فِي يَدِ عُثْمَانَ، حَتَّى وَقَعَ بَعْدُ فِي بِئْرِ أَرِيسَ، نَقْشُهُ مُحَمَّدٌ رَسُولُ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5873) ومسلم في اللباس (54:2091) كلاهما من طريق عبد الله بن نمير، حدثنا عبيد الله، عن نافع، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5873) and Muslim (2091:54).","chapter_en":"The Signet Ring of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar said: The Messenger of Allah ﷺ had a silver signet ring made. It remained in his possession, then afterward with Abū Bakr, then with ʿUmar, and then with ʿUthmān, until it fell into the well of Arīs. Its inscription read: Muḥammad, the Messenger of Allah."]},"buhuth":{"en":["A narration recorded by al-Tirmidhī in Al-Shamā’il (83) and Aḥmad (5366) states: “He used it to seal documents but did not wear it.” Its chain is authentic.","This does not contradict the report in the two Ṣaḥīḥ collections. It may be understood as describing different occasions: he sometimes wore the ring and sometimes left it unworn. The narration is therefore not anomalous."]}},"tuhfa":{},"voc":["seerah",1356],"full":1,"dr":1,"rep":[15578],"tks":"متفق عليه: رواه البخاري (5873)، ومسلم (54: 2091)."},{"num":9605,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ ـ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ ذَهَبٍ أَوْ فِضَّةٍ، وَجَعَلَ فَصَّهُ مِمَّا يَلِي كَفَّهُ، وَنَقَشَ فِيهِ مُحَمَّدٌ رَسُولُ اللَّهِ. فَاتَّخَذَ النَّاسُ مِثْلَهُ، فَلَمَّا رَآهُمْ قَدِ اتَّخَذُوهَا رَمَى بِهِ، وَقَالَ: لاَ أَلْبَسُهُ أَبَدًا. ثُمَّ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، فَاتَّخَذَ النَّاسُ خَوَاتِيمَ الْفِضَّةِ.","قَالَ ابْنُ عُمَرَ: فَلَبِسَ الْخَاتَمَ بَعْدَ النَّبِيِّ صلى الله عليه وسلم أَبُو بَكْرٍ ثُمَّ عُمَرُ ثُمَّ عُثْمَانُ حَتَّى وَقَعَ مِنْ عُثْمَانَ فِي بِئْرِ أَرِيسَ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5866) واللفظ له، ومسلم في اللباس (54:2091) كلاهما من طريق عبيد الله، عن نافع، عن ابن عمر قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5866), whose wording this is, and Muslim (2091:54).","chapter_en":"The Signet Ring of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":4,"content":{"translation":{"en":["Ibn ʿUmar reported that the Messenger of Allah ﷺ had a ring made from gold—or silver—and positioned its stone toward the palm of his hand. He had the words “Muḥammad, the Messenger of Allah” engraved upon it. The people began making similar rings. When he saw that they had done so, he threw his ring away and said, “I shall never wear it again.” He then had a silver ring made, and the people likewise began wearing silver rings. Ibn ʿUmar said: After the Prophet ﷺ, Abū Bakr wore the ring, followed by ʿUmar and then ʿUthmān, until it fell from ʿUthmān into the well of Arīs."]},"buhuth":{"en":["Muslim (2091:55) also narrated through another chain from Ibn ʿUmar:","The Prophet ﷺ had a gold ring made and then discarded it. He afterward had a silver ring made and engraved upon it: “Muḥammad, the Messenger of Allah.” He said, “No one should engrave an inscription identical to the inscription upon my ring.”","When he wore it, he positioned its stone toward the inner part of his palm. This was the ring that fell from Muʿayqīb into the well of Arīs.","Arīs was a well located near the mosque of Qubāʾ. It is now situated within the mosque’s courtyards.","Muʿayqīb embraced Islam at an early stage, participated at Badr, and migrated to Abyssinia. He was entrusted with the Prophet’s ﷺ ring, and Abū Bakr, ʿUmar, and ʿUthmān appointed him to oversee the public treasury."]}},"tuhfa":{},"voc":["seerah",1357],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (5866) واللفظ له، ومسلم (54: 2091)."},{"num":9606,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّهُ رَأَى فِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمًا مِنْ وَرِقٍ يَوْمًا وَاحِدًا، ثُمَّ إِنَّ النَّاسَ اصْطَنَعُوا الْخَوَاتِيمَ مِنْ وَرِقٍ وَلَبِسُوهَا، فَطَرَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَاتَمَهُ، فَطَرَحَ النَّاسُ خَوَاتِيمَهُمْ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5868) ومسلم في اللباس (59:2093) كلاهما من طريق ابن شهاب الزهري، عن أنس أنه قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5868) and Muslim (2093:59).","chapter_en":"The Signet Ring of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported that he saw a silver ring upon the hand of the Messenger of Allah ﷺ for one day. The people then had silver rings made and wore them. The Messenger of Allah ﷺ discarded his ring, so the people discarded theirs as well."]},"buhuth":{"en":["The wording “a silver ring,” followed by the statement that the Prophet ﷺ and the people discarded their rings, appears to conflict with Ibn ʿUmar’s hadith stating that the silver ring remained after the Prophet ﷺ with Abū Bakr, then ʿUmar, and then ʿUthmān until it fell into the well. Scholars therefore said that an error occurred in the words “a silver ring,” and that the correct wording is “a gold ring.”"]}},"tuhfa":{},"voc":["seerah",1358],"full":1,"dr":1,"rep":[15515],"tks":"متفق عليه: رواه البخاري (5868)، ومسلم (59: 2093)."},{"num":9607,"demo":false,"sanad":"","matn":["عن أنس بن مالك قال: كان خاتم رسول الله صلى الله عليه وسلم من ورق، وكان فصه حبشياً. وفي رواية: كان فصه منه."],"takhrij":"متفق عليه: رواه مسلم في اللباس (61:2094) عن يحيى بن أيوب، حدثنا عبد الله بن وهب المصري، أخبرني يونس بن يزيد، عن ابن شهاب، حدثني أنس بن مالك قال: فذكره. والرواية الأخرى: رواها البخاري في اللباس (5870) عن إسحاق، أخبرنا معتمر، قال سمعت حميداً يحدث عن أنس به.","grade":"متفق عليه","chapter_ar":"باب ما جاء في خاتم رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2094:61) and al-Bukhārī (5870).","chapter_en":"The Signet Ring of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik said: The signet ring of the Messenger of Allah ﷺ was made of silver, and its stone was Abyssinian. Another narration states: Its stone was made from the same silver as the ring."]},"buhuth":{"en":["Al-Ḥāfiẓ said: There is no contradiction between the two reports. They may refer to more than one ring, or the stone may have been attributed to Abyssinia because of one of its characteristics, such as its craftsmanship or engraving."]}},"tuhfa":{},"voc":["seerah",1359],"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (61: 2094)، والبخاري (5870)."},{"num":9608,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، أَنَّ أَبَا بَكْرٍ رَضِيَ اللَّهُ عَنْهُ لَمَّا اسْتُخْلِفَ بَعَثَهُ إِلَى الْبَحْرَيْنِ، وَكَتَبَ لَهُ هَذَا الْكِتَابَ وَخَتَمَهُ، وَكَانَ نَقْشُ الْخَاتَمِ ثَلاَثَةَ أَسْطُرٍ مُحَمَّدٌ سَطْرٌ، وَرَسُولُ سَطْرٌ، وَاللَّهِ سَطْرٌ."],"takhrij":"صحيح: رواه البخاري في فرض الخمس (3106) وفي اللباس bukhari(5878) عن محمد بن عبدالله الأنصاري، قال: حدثني أبي، عن ثمامة، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"نقش خاتم النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of the One-Fifth (3106) and Clothing (5878), through Muḥammad ibn ʿAbdullāh al-Anṣārī → his father → Thumāmah → Anas.","chapter_en":"The Inscription upon the Prophet’s ﷺ Signet Ring","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":5,"content":{"translation":{"en":["Anas reported that when Abū Bakr became caliph, he sent him to Bahrain and wrote a document for him, which he sealed with the signet ring. The ring’s inscription consisted of three lines: Muḥammad — on one line Messenger — on one line Allah — on one line"]}},"tuhfa":{},"voc":["seerah",1360],"full":1,"tks":"صحيح: رواه البخاري (3106)، وفي اللباس bukhari(5878)، عن محمد بن عبد الله الأنصاري، قال: حدثني أبي، عن ثمامة، عن أنس، قال: فذكره."},{"num":9609,"demo":false,"sanad":"","matn":["عَنْ أبي أَنَسِ بْنِ مَالِكٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لَبِسَ خَاتَمَ فِضَّةٍ فِي يَمِينِهِ، فِيهِ فَصٌّ حَبَشِيٌّ، كَانَ يَجْعَلُ فَصَّهُ مِمَّا يَلِي كَفَّهُ."],"takhrij":"صحيح: رواه مسلم في اللباس (62:2094) من طرق عن طلحة بن يحيى (هو الأنصاري ثم الزرقي) عن يونس، عن ابن شهاب، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب لبس النبي ﷺ الخاتم في اليمين","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Clothing (2094:62), through Ṭalḥah ibn Yaḥyā al-Anṣārī al-Zuraqī → Yūnus → Ibn Shihāb → Anas.","chapter_en":"The Prophet ﷺ Wore His Ring on His Right Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ wore a silver ring on his right hand. It contained an Abyssinian stone, which he positioned toward the palm of his hand."]}},"tuhfa":{},"voc":["seerah",1361],"full":1,"tks":"صحيح: رواه مسلم (62: 2094)."},{"num":9610,"demo":false,"sanad":"","matn":["عَنْ عَلِيِّ بْنِ أَبِي طَالِبٍ: أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَلْبَسُ خَاتَمَهُ فِي يَمِينِهِ."],"takhrij":"صحيح: رواه أبو داود (4226) والترمذي في الشمائل (90) والنسائي (5203) وأبو الشيخ في أخلاق النبي (ص110) وصححه ابن حبان (5501) كلهم من طريق سليمان بن بلال، حدثنا شريك بن عبد الله بن أبي نمر، عن إبراهيم بن عبد الله بن حنين، عن أبيه، عن علي قال: فذكره.","grade":"صحيح","chapter_ar":"باب لبس النبي ﷺ الخاتم في اليمين","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4226), al-Tirmidhī in Al-Shamā’il (90), al-Nasā’ī (5203), Abū al-Shaykh in Akhlāq al-Nabī (p. 110), and authenticated by Ibn Ḥibbān (5501).","chapter_en":"The Prophet ﷺ Wore His Ring on His Right Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":6,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib reported that the Prophet ﷺ used to wear his ring on his right hand."]}},"tuhfa":{},"voc":["seerah",1362],"full":1,"dr":1,"rep":[15586],"tks":"صحيح: رواه أبو داود (4226)، والترمذي في الشمائل (90)، والنسائي (5203)، وأبو الشيخ في أخلاق النبي (ص 110)، وصححه ابن حبان (5501)."},{"num":9611,"demo":false,"sanad":"","matn":["عَنِ ابْن عَبَّاسٍ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَتَخَتَّمُ فِي يَمِينِهِ."],"takhrij":"حسن: رواه أبو داود (4229) والترمذي في السنن (1742) واللفظ له، وفي الشمائل (94) وأبو الشيخ في أخلاق النبي (ص 108) كلهم من طريق محمد بن إسحاق، عن الصلت بن عبد الله بن نوفل، قال: رأيت ابن عباس يتختم في يمينه، ولا إخاله إلا قال: فذكره.","grade":"حسن","chapter_ar":"باب لبس النبي ﷺ الخاتم في اليمين","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4229), al-Tirmidhī in his Sunan (1742), whose wording this is, and in Al-Shamā’il (94), and Abū al-Shaykh in Akhlāq al-Nabī (p. 108).","chapter_en":"The Prophet ﷺ Wore His Ring on His Right Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":6,"content":{"translation":{"en":["Ibn ʿAbbās said: I saw the Messenger of Allah ﷺ wearing his ring on his right hand."]}},"tuhfa":{},"voc":["seerah",1363],"full":1,"dr":1,"tks":"حسن: رواه أبو داود (4229)، والترمذي في السنن (1742) واللفظ له، وفي الشمائل (94)، وأبو الشيخ في أخلاق النبي (ص 108)."},{"num":9612,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللهِ بْنِ جَعْفَرٍ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ يَتَخَتَّمُ فِي يَمِينِهِ."],"takhrij":"حسن: رواه الترمذي في السنن (1744) وفي الشمائل (91) والنسائي (5204) وأحمد (1755،1746) كلهم من طريق حماد بن سلمة قال: رأيت ابن أبي رافع، يتختم في يمينه، فسألته عن ذلك، فقال: رأيت عبد الله بن جعفر يتختم في يمينه، وقال: كان النبي صلى الله عليه وسلم.. الحديث.","grade":"حسن","chapter_ar":"باب لبس النبي ﷺ الخاتم في اليمين","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī in his Sunan (1744) and Al-Shamā’il (91), al-Nasā’ī (5204), and Aḥmad (1746, 1755).","chapter_en":"The Prophet ﷺ Wore His Ring on His Right Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":6,"content":{"translation":{"en":["ʿAbdullāh ibn Jaʿfar said: The Prophet ﷺ used to wear his ring on his right hand."]}},"tuhfa":{},"voc":["seerah",1364],"full":1,"dr":1,"tks":"حسن: رواه الترمذي في السنن (1744)، وفي الشمائل (91)، والنسائي (5204)، وأحمد (1755، 1746). الحديث."},{"num":9613,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ، قَالَ كَانَ خَاتِمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  فِي هَذِهِ. وَأَشَارَ إِلَى الْخِنْصَرِ مِنْ يَدِهِ الْيُسْرَى."],"takhrij":"صحيح: رواه مسلم في اللباس (63:2095) عن أبي بكر بن خلاّد الباهلي، حدثنا عبد الرحمن بن مهدي، حدثنا حماد بن سلمة، عن ثابت، عن أنس فذكره.","grade":"صحيح","chapter_ar":"باب لبس النبي ﷺ الخاتم في اليسار","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Clothing (2095:63), through Abū Bakr ibn Khallād al-Bāhilī → ʿAbd al-Raḥmān ibn Mahdī → Ḥammād ibn Salamah → Thābit → Anas.","chapter_en":"The Prophet ﷺ Wore His Ring on His Left Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":7,"content":{"translation":{"en":["Anas said: The Prophet’s ﷺ ring was worn upon this finger, and he pointed to the little finger of his left hand."]},"buhuth":{"en":["The reports concerning the right and left hands are understood as referring to different occasions. The Prophet ﷺ sometimes wore his ring on his right hand and sometimes on his left. This reconciliation is preferable to declaring one of the reports weak."]}},"tuhfa":{},"voc":["seerah",1365],"full":1,"dr":1,"rep":[15589],"tks":"صحيح: رواه مسلم (63: 2095)."},{"num":9614,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ:  أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ اتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، وَقَالَ لِلنَّاسِ: إِنِّي اتَّخَذْتُ خَاتَمًا مِنْ فِضَّةٍ، وَنَقَشْتُ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ، فَلَا يَنْقُشْ أَحَدٌ عَلَى نَقْشِهِ.","قال أنس: فَإِنِّي لَأَرَى بَرِيقَهُ فِي خِنْصَرِهِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5876،5874) ومسلم في اللباس (2092) كلاهما من طريق عبد العزيز بن صهيب، عن أنس قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب لبسه ﷺ الخاتم في خنصره","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5874, 5876) and Muslim (2092).","chapter_en":"The Prophet ﷺ Wore His Ring on His Little Finger","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":8,"content":{"translation":{"en":["Anas reported that the Prophet ﷺ had a silver signet ring made and engraved upon it: Muḥammad, the Messenger of Allah. He said to the people: “I have had a silver signet ring made and engraved upon it, ‘Muḥammad, the Messenger of Allah.’ No one should engrave an inscription identical to its inscription.” Anas said: It is as though I can still see its gleam upon his little finger."]}},"tuhfa":{},"voc":["seerah",1366],"full":1,"tks":"متفق عليه: رواه البخاري (5874، 5876)، ومسلم (2092)."},{"num":9615,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ بْنِ سَهْلٍ، قَالَ: كَانَتْ قَبِيعَةُ سَيْفِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ فِضَّةٍ."],"takhrij":"صحيح: رواه النسائي (5373) عن عمران بن يزيد قال: حدثنا عيسى بن يونس، حدثنا عثمان بن حكيم، عن أبي أمامة بن سهل فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في سيف النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī (5373).","chapter_en":"The Prophet’s ﷺ Sword","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":10,"content":{"translation":{"en":["Abū Umāmah ibn Sahl said: The pommel of the Messenger of Allah’s ﷺ sword was made of silver."]},"buhuth":{"en":["The sword’s qabīʿah is the silver or iron fitting located at the end of its hilt."]}},"tuhfa":{},"voc":["seerah",1368],"full":1,"dr":1,"rep":[7942],"tks":"صحيح: رواه النسائي (5373)."},{"num":9616,"demo":false,"sanad":"","matn":["عَنِ الزُّبَيْرِ بْنِ الْعَوَّامِ، قَالَ: كَانَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دِرْعَانِ يَوْمَ أُحُدٍ، فَنَهَضَ إِلَى الصَّخْرَةِ فَلَمْ يَسْتَطِعْ، فَأَقْعَدَ طَلْحَةَ تَحْتَهُ، فَصَعِدَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ، حَتَّى اسْتَوَى عَلَى الصَّخْرَةِ، فَقَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: أَوْجَبَ طَلْحَةُ."],"takhrij":"حسن: رواه الترمذي (1692)، (3738) وأحمد (1417) وابن حبان (6979) والحاكم (5602) والبيهقي (6/370، 9/46) من طرق عن محمد بن إسحاق وهو في سيرته كما في سيرة ابن هشام (2/86) قال: حدثني يحيى بن عباد بن عبد الله بن الزبير، عن أبيه، عن جده عبد الله بن الزبير، عن الزبير بن العوام فذكره، وسقط ذكر أبيه من الإحسان. وإسناده حسن من أجل محمد بن إسحاق.","grade":"حسن","chapter_ar":"باب ما جاء في درع رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Tirmidhī (1692, 3738), Aḥmad (1417), and Ibn Ḥibbān (6979).","chapter_en":"The Armor of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":11,"content":{"translation":{"en":["Al-Zubayr ibn al-ʿAwwām said: The Prophet ﷺ was wearing two coats of armor on the day of Uḥud. He attempted to climb onto a rock but was unable to do so, so Ṭalḥah crouched beneath him. The Prophet ﷺ stepped upon him until he stood firmly upon the rock. Al-Zubayr said: I heard the Prophet ﷺ say, “Ṭalḥah has secured Paradise.”"]},"buhuth":{"en":["The statement “Ṭalḥah has made it obligatory” means that he performed a deed that made Paradise obligatory for him.","Other hadiths on this subject have been included in the Book of Jihad and Military Campaigns."]}},"tuhfa":{},"voc":["seerah",1369],"full":1,"dr":1,"rep":[7937,8813,9934],"tks":"حسن: رواه الترمذي (1692، 3738)، وأحمد (1417)، وابن حبان (6979)."},{"num":9617,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ دَخَلَ مَكَّةَ وَعَلَيْهِ عِمَامَةٌ سَوْدَاءُ بِغَيْرِ إِحْرَامٍ."],"takhrij":"صحيح: رواه مسلم في الحج (451:1358) من طرق عن معاوية بن عمار الدهني، عن أبي الزبير، عن جابر بن عبد الله الأنصاري قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عمامته ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1358:451).","chapter_en":"The Prophet’s ﷺ Turban","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":12,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Prophet ﷺ entered Makkah wearing a black turban while not in the state of iḥrām."]}},"tuhfa":{},"voc":["seerah",1370],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (451: 1358)."},{"num":9618,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَعَلَيْهِ مِلْحَفَةٌ مُتَعَطِّفًا بِهَا عَلَى مَنْكِبَيْهِ، وَعَلَيْهِ عِصَابَةٌ دَسْمَاءُ...الحديث في فضائل الأنصار."],"takhrij":"صحيح: رواه البخاري في مناقب الأنصار (3800) عن أحمد بن يعقوب، حدثنا ابن الغسيل (واسمه عبد الرحمن بن الغسيل، والغسيل هو حنظلة الأنصاري) سمعت عكرمة يقول: سمعت ابن عباس يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في عمامته ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Virtues (3800).","chapter_en":"The Prophet’s ﷺ Turban","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":12,"content":{"translation":{"en":["Ibn ʿAbbās reported: The Messenger of Allah ﷺ came out wearing a cloak wrapped around his shoulders and a dark turban… the remainder of the hadith concerning the virtues of the Anṣār."]},"buhuth":{"en":["The word ʿiṣābah means a turban.","The word dasmāʾ refers to something darkened by the oiliness of his hair from perfume; what is intended here is that the turban was black."]}},"tuhfa":{},"voc":["seerah",1371],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3800)."},{"num":9619,"demo":false,"sanad":"","matn":["عن أَبِي جُحَيْفَةَ، عَنْ أَبِيهِ قَالَ:  أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِمَكَّةَ، وَهُوَ بِالْأَبْطَحِ فِي قُبَّةٍ لَهُ حَمْرَاءَ مِنْ أَدَمٍ. قَالَ: فَخَرَجَ بِلَالٌ بِوَضُوئِهِ فَمِنْ نَائِلٍ وَنَاضِحٍ قَالَ: فَخَرَجَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَيْهِ حُلَّةٌ حَمْرَاءُ كَأَنِّي أَنْظُرُ إِلَى بَيَاضِ سَاقَيْهِ. قَالَ:"],"takhrij":"متفق عليه: رواه البخاري في المناقب (3566) ومسلم في الصلاة (249:503) كلاهما من طريق عون بن أبي جحيفة، عن أبي جحيفة قال: فذكره.","grade":"متفق عليه","chapter_ar":"ما جاء في إزار رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3566) and Muslim (503:249).","chapter_en":"The Prophet’s ﷺ Waist-Wrapper","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":13,"content":{"translation":{"en":["Abū Juḥayfah reported: I came to the Prophet ﷺ in Makkah while he was at al-Abṭaḥ in a red leather tent. Bilāl came out carrying the water the Prophet ﷺ had used for ablution; some people obtained some of it, while others received drops sprinkled upon them. Then the Prophet ﷺ came out wearing a red garment, and it is as though I can still see the whiteness of his legs… the remainder of the hadith."]}},"tuhfa":{},"voc":["seerah",1372],"full":1,"dr":1,"rep":[9454,15314],"tks":"متفق عليه: رواه البخاري (3566)، ومسلم (249: 503)."},{"num":9620,"demo":false,"sanad":"","matn":["عَنْ أَبِي بُرْدَةَ قَالَ:  دَخَلْتُ عَلَى عَائِشَةَ، فَأَخْرَجَتْ إِلَيْنَا إِزَارًا غَلِيظًا مِمَّا يُصْنَعُ بِالْيَمَنِ، وَكِسَاءً مِنَ الَّتِي يُسَمُّونَهَا الْمُلَبَّدَةَ. قَالَ: فَأَقْسَمَتْ بِاللهِ إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُبِضَ فِي هَذَيْنِ الثَّوْبَيْنِ."],"takhrij":"متفق عليه: رواه البخاري في اللباس (5818) ومسلم في اللباس والزينة (34:2080) كلاهما من طريق حميد بن هلال، عن أبي بردة قال: فذكره واللفظ لمسلم.","grade":"متفق عليه","chapter_ar":"ما جاء في إزار رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (5818) and Muslim (2080:34); the wording is Muslim’s.","chapter_en":"The Prophet’s ﷺ Waist-Wrapper","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":13,"content":{"translation":{"en":["Abū Burdah said: I entered upon ʿĀ’ishah, and she brought out for us a coarse waist-wrapper made in Yemen and a cloak of the type known as mulabbadah. She swore by Allah that the Messenger of Allah ﷺ died while wearing these two garments."]},"buhuth":{"en":["Mulabbadah means either a patched cloak or a thick garment that had become like felt."]}},"tuhfa":{},"voc":["seerah",1373],"full":1,"dr":1,"rep":[15353],"tks":"متفق عليه: رواه البخاري (5818)، ومسلم (34: 2080)، واللفظ لمسلم."},{"num":9621,"demo":false,"sanad":"","matn":["عن عِكْرِمَةَ أَنَّهُ رَأَى ابْنَ عَبَّاسٍ يَأْتَزِرُ، فَيَضَعُ حَاشِيَةَ إِزَارِهِ مِنْ مُقَدَّمِهِ عَلَى ظَهْرِ قَدَمَيْهِ، وَيَرْفَعُ مِنْ مُؤَخَّرِهِ. قُلْتُ: لِمَ تَأْتَزِرُ هَذِهِ الإِزْرَةَ؟ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْتَزِرُهَا."],"takhrij":"حسن: رواه أبو داود (4096) وابن سعد (1/459) وأبو الشيخ في أخلاق النبي (ص97) كلهم من طريق محمد بن أبي يحيى، حدثني عكرمة، أنه رأى ابن عباس فذكره.","grade":"حسن","chapter_ar":"ما جاء في إزار رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (4096), Ibn Saʿd (1/459), and Abū al-Shaykh in Akhlāq al-Nabī ﷺ (p. 97).","chapter_en":"The Prophet’s ﷺ Waist-Wrapper","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":13,"content":{"translation":{"en":["ʿIkrimah reported that he saw Ibn ʿAbbās wearing his waist-wrapper with its front edge resting upon the tops of his feet while raising it higher at the back. I asked, “Why do you wear your waist-wrapper in this manner?” He replied, “I saw the Messenger of Allah ﷺ wear his waist-wrapper in this manner.”"]}},"tuhfa":{},"voc":["seerah",1374],"full":1,"dr":1,"rep":[15379],"tks":"حسن: رواه أبو داود (4096)، وابن سعد (1/459)، وأبو الشيخ في أخلاق النبي ﷺ (ص 97)."},{"num":9622,"demo":false,"sanad":"","matn":["عَنْ عَاصِمٍ الأَحْوَلِ، قَالَ: رَأَيْتُ قَدَحَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ أَنَسِ بْنِ مَالِكٍ، وَكَانَ قَدِ انْصَدَعَ، فَسَلْسَلَهُ بِفِضَّةٍ قَالَ: وَهْوَ قَدَحٌ جَيِّدٌ عَرِيضٌ مِنْ نُضَارٍ. قَالَ: قَالَ أَنَسٌ: لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي هَذَا الْقَدَحِ أَكْثَرَ مِنْ كَذَا وَكَذَا.","قَالَ: وَقَالَ ابْنُ سِيرِينَ: إِنَّهُ كَانَ فِيهِ حَلْقَةٌ مِنْ حَدِيدٍ، فَأَرَادَ أَنَسٌ أَنْ يَجْعَلَ مَكَانَهَا حَلْقَةً مِنْ ذَهَبٍ أَوْ فِضَّةٍ، فَقَالَ لَهُ أَبُو طَلْحَةَ: لاَ تُغَيِّرَنَّ شَيْئًا صَنَعَهُ رَسُولُ اللَّهِ صلى الله عليه وسلم فَتَرَكَهُ."],"takhrij":"صحيح: رواه البخاري في الأشربة (5638) عن الحسن بن مدرك، قال: حدثني يحيى بن حماد، أخبرنا أبو عوانة عن عاصم الأحول قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قدح رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (5638).","chapter_en":"The Drinking Cup of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":14,"content":{"translation":{"en":["ʿĀṣim al-Aḥwal said: I saw the Prophet’s ﷺ cup in the possession of Anas ibn Mālik. It had cracked, so Anas bound it with silver. It was a fine, broad cup made from naḍār wood. Anas said: I served the Messenger of Allah ﷺ drink from this cup on more occasions than I could count. Ibn Sīrīn said: The cup had an iron ring upon it. Anas wished to replace it with a ring of gold or silver, but Abū Ṭalḥah said to him, “Do not alter anything made by the Messenger of Allah ﷺ.” Anas therefore left it unchanged."]},"buhuth":{"en":["Naḍār refers to pure, select wood. It has also been said to be the finest wood used for making vessels."]}},"tuhfa":{},"voc":["seerah",1375],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (5638)."},{"num":9623,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ:  لَقَدْ سَقَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقَدَحِي هَذَا الشَّرَابَ كُلَّهُ: الْعَسَلَ وَالنَّبِيذَ، وَالْمَاءَ، وَاللَّبَنَ."],"takhrij":"صحيح: رواه مسلم في الأشربة (89:2008) من طرق عن عفان، حدثنا حماد بن سلمة، عن ثابت عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في قدح رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2008:89).","chapter_en":"The Drinking Cup of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":14,"content":{"translation":{"en":["Anas said: I served the Messenger of Allah ﷺ every kind of drink from this cup of mine: honey, nabīdh, water, and milk."]},"buhuth":{"en":["Nabīdh here means water in which dates were placed to sweeten it. Dates would be placed in the water at the beginning of the night, and he would drink it the following morning."]}},"tuhfa":{},"voc":["seerah",1376],"full":1,"dr":1,"rep":[7561,7583],"tks":"صحيح: رواه مسلم (89: 2008)."},{"num":9624,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  إِنَّمَا كَانَ فِرَاشُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي يَنَامُ عَلَيْهِ، أَدَمًا حَشْوُهُ لِيفٌ."],"takhrij":"متفق عليه: رواه البخاري في الرقاق (6456) ومسلم في اللباس والزينة (38:2082) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة قالت: فذكرته.","grade":"متفق عليه","chapter_ar":"باب ما جاء في فراش رسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6456) and Muslim (2082:38).","chapter_en":"The Bedding of the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":15,"content":{"translation":{"en":["ʿĀ’ishah said: The mattress upon which the Messenger of Allah ﷺ slept was made of leather and stuffed with palm fibers."]},"buhuth":{"en":["Another wording states, “The bedding of the Messenger of Allah ﷺ,” instead of, “The mattress of the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"voc":["seerah",1377],"full":1,"dr":1,"rep":[15167,15400],"tks":"متفق عليه: رواه البخاري (6456)، ومسلم (38: 2082)."},{"num":9625,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، قَالَتْ: كَانَ وِسَادَةُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  الَّتِي يَتَّكِئُ عَلَيْهَا مِنْ أَدَمٍ حَشْوُهَا لِيفٌ."],"takhrij":"صحيح: رواه مسلم في اللباس (37:2082) عن أبي بكر بن أبي شيبة، حدثنا عبدة بن سليمان، عن هشام بن عروة، عن أبيه، عن عائشة قالت: فذكرته.","grade":"صحيح","chapter_ar":"باب ما جاء في وسادة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in The Book of Clothing (2082:37).","chapter_en":"The Prophet’s ﷺ Cushion","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":16,"content":{"translation":{"en":["ʿĀ’ishah said: The cushion upon which the Messenger of Allah ﷺ reclined was made of leather and stuffed with palm fibers."]}},"tuhfa":{},"voc":["seerah",1378],"full":1,"rep":[15168,15399],"tks":"صحيح: رواه مسلم (37: 2082)."},{"num":9626,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى الأشعري قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وهو يستنُّ بِسِوَاكٍ بِيَدِهِ، وَيَقُولُ:  أعْ أعْ وَالسِّوَاكُ فِي فِيهِ، كَأَنَّهُ يتهوَّع."],"takhrij":"متفق عليه: أخرجه البخاري في الوضوء (244)، ومسلم في الطهارة (254)، كلاهما من حديث حماد بن زيد، عن غيلان بن جرير، عن أبي بردَة، عن أبيه فذكره. وهذا لفظ البخاري.","grade":"متفق عليه","chapter_ar":"باب هدي النبي ﷺ في السواك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (244) and Muslim (254); this is al-Bukhārī’s wording.","chapter_en":"The Prophet’s ﷺ Practice in Using the Tooth-Stick","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":17,"content":{"translation":{"en":["Abū Mūsā al-Ashʿarī said: I came to the Messenger of Allah ﷺ while he was cleaning his teeth with a tooth-stick held in his hand. He was making the sound, “Aʿ, aʿ,” while the tooth-stick was in his mouth, as though he were retching."]},"buhuth":{"en":["Muslim’s wording states: “I entered upon the Prophet ﷺ while the end of the tooth-stick was upon his tongue.”","The word “retching” refers to the motion preceding vomiting. In this context, it means drawing phlegm up from the deepest part of the throat and bringing it out so that it may be expelled, resembling the action of someone about to vomit."]}},"tuhfa":{},"voc":["seerah",1379],"full":1,"dr":1,"tks":"متفق عليه: أخرجه البخاري (244)، ومسلم (254)، وهذا لفظ البخاري."},{"num":9627,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  كَانَ إِذَا دَخَلَ بَيْتَهُ بَدَأَ بِالسِّوَاكِ.","وفي رواية: قَالَ شُرَيْحٍ: سَأَلْتُ عَائِشَةَ قُلْتُ: بِأَيِّ شَيْءٍ كَانَ يَبْدَأُ النبيصلى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا دَخَلَ بَيْتَهُ؟ قَالَتْ: بِالسِّوَاكِ."],"takhrij":"صحيح: رواه مسلم في الطهارة (253) من حديث مِسْعَر، عن المقدام بن شريح، عن أبيه، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب هدي النبي ﷺ في السواك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (253).","chapter_en":"The Prophet’s ﷺ Practice in Using the Tooth-Stick","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah reported that whenever the Prophet ﷺ entered his home, he began by using the tooth-stick. Another narration states: Shurayḥ said: I asked ʿĀ’ishah, “What did the Prophet ﷺ begin with when he entered his home?” She replied, “The tooth-stick.”"]}},"tuhfa":{},"voc":["seerah",1380],"full":1,"tks":"صحيح: رواه مسلم (253)."},{"num":9628,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، قَالَ: كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا قَامَ مِنَ اللَّيْلِ يَشُوصُ فَاهُ بِالسِّوَاكِ."],"takhrij":"متفق عليه: رواه البخاري في الوضوء (245)، ومسلم في الطهارة (255) كلاهما من حديث جرير، عن منصور، عن أبي وائل، عن حذيفة فذكر الحديث.","grade":"متفق عليه","chapter_ar":"باب هدي النبي ﷺ في السواك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (245) and Muslim (255).","chapter_en":"The Prophet’s ﷺ Practice in Using the Tooth-Stick","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":17,"content":{"translation":{"en":["Ḥudhayfah ibn al-Yamān said: When the Prophet ﷺ rose during the night, he would vigorously clean his mouth with the tooth-stick."]},"buhuth":{"en":["In the narration of Ḥuṣayn ibn ʿAbd al-Raḥmān from Abū Wā’il recorded by Muslim: “When he rose to perform the night prayer, he would vigorously clean his mouth with the tooth-stick.”","Shawṣ means rubbing the teeth horizontally with the tooth-stick."]}},"tuhfa":{},"voc":["seerah",1381],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (245)، ومسلم (255)."},{"num":9629,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَانَ يَسْأَلُ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ يَقُولَ: أَيْنَ أَنَا غَدًا؟ أَيْنَ أَنَا غَدًا؟ يُرِيدُ يَوْمَ عَائِشَةَ، فَأَذِنَ لَهُ أَزْوَاجُهُ يَكُونُ حَيْثُ شَاءَ، فَكَانَ فِي بَيْتِ عَائِشَةَ حَتَّى مَاتَ عِنْدَهَا، قَالَتْ عَائِشَةُ فَمَاتَ فِي الْيَوْمِ الَّذِي كَانَ يَدُورُ عَلَىَّ فِيهِ فِي بَيْتِي، فَقَبَضَهُ اللَّهُ وَإِنَّ رَأْسَهُ لَبَيْنَ نَحْرِي وَسَحْرِي، وَخَالَطَ رِيقُهُ رِيقِي. ـ ثُمَّ قَالَتْ: ـ دَخَلَ عَبْدُ الرَّحْمَنِ بْنُ أَبِي بَكْرٍ وَمَعَهُ سِوَاكٌ يَسْتَنُّ بِهِ، فَنَظَرَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ لَهُ: أَعْطِنِي هَذَا السِّوَاكَ يَا عَبْدَ الرَّحْمَنِ. فَأَعْطَانِيهِ، فَقَضِمْتُهُ، ثُمَّ مَضَغْتُهُ، فَأَعْطَيْتُهُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاسْتَنَّ بِهِ وَهْوَ مُسْتَنِدٌ إِلَى صَدْرِي."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4450)، ومسلم في فضائل الصحابة (2443: 84) كلاهما من طريق هشام بن عروة، عن أبيه، عن عائشة فذكرته.","grade":"متفق عليه","chapter_ar":"باب هدي النبي ﷺ في السواك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4450) and Muslim (2443:84).","chapter_en":"The Prophet’s ﷺ Practice in Using the Tooth-Stick","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":17,"content":{"translation":{"en":["ʿĀ’ishah, the wife of the Prophet ﷺ, reported that during the illness in which the Messenger of Allah ﷺ died, he repeatedly asked, “Where will I be tomorrow? Where will I be tomorrow?” eagerly awaiting ʿĀ’ishah’s allotted day. His wives permitted him to remain wherever he wished, so he stayed in ʿĀ’ishah’s house until he died there. ʿĀ’ishah said: He died in my house on the day that had been allotted to me. Allah took his soul while his head rested between my upper chest and neck, and his saliva became mixed with mine. ʿAbd al-Raḥmān ibn Abī Bakr entered carrying a tooth-stick with which he was cleaning his teeth. The Messenger of Allah ﷺ looked at it, so I said, “ʿAbd al-Raḥmān, give me that tooth-stick.” He gave it to me. I bit and softened it, then gave it to the Messenger of Allah ﷺ. He cleaned his teeth with it while leaning against my chest."]}},"tuhfa":{},"voc":["seerah",1382],"full":1,"rep":[9321],"tks":"متفق عليه: رواه البخاري (4450)، ومسلم (2443: 84)."},{"num":9630,"demo":false,"sanad":"","matn":["عن سلمة بن الأكوع قَالَ: لَقَدْ قُدْتُ بِنَبِيِّ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَالحَسَنِ وَالحُسَيْنِ بَغْلَتَهُ الشَّهْبَاءَ، حَتَّى أَدْخَلْتُهُمْ حُجْرَةَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، هَذَا قُدَّامَهُ، وَهَذَا خَلْفَهُ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2423: 60) من طرق عن النضر بن محمد، حدثنا عكرمة –وهو ابن عمار-، حدثنا إياس (هو ابن سلمة بن الأكوع)، عن أبيه قال: فذكره.","grade":"صحيح","chapter_ar":"باب بغلة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2423:60).","chapter_en":"The Prophet’s ﷺ Mule","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في صفة أشياء النبي ﷺ","group_en":"A Collection of Reports Describing the Prophet’s ﷺ Personal Belongings","part_no":48,"group_no":35,"chapter_no":18,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: I led the gray mule carrying the Prophet of Allah ﷺ, al-Ḥasan, and al-Ḥusayn until I brought them into the Prophet’s ﷺ chamber. One of the two boys was seated in front of him and the other behind him."]}},"tuhfa":{},"voc":["seerah",1383],"full":1,"tks":"صحيح: رواه مسلم (2423: 60)."},{"num":9631,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، ـ رَضِيَ اللَّهُ عَنْهُمَا ـ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: نُصِرْتُ بِالصَّبَا، وَأُهْلِكَتْ عَادٌ بِالدَّبُورِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4105) ومسلم في صلاة الاستسقاء (17:900) كلاهما من طريق شعبة، حدثني الحكم، عن مجاهد، عن ابن عباس عن النبي صلى الله عليه وسلم قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب نصر النبي ﷺ بالصَّبا","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4105) and Muslim (900:17).","chapter_en":"The Prophet ﷺ Was Granted Victory by the East Wind","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":1,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Prophet ﷺ said: “I was granted victory by the east wind, while ʿĀd was destroyed by the west wind.”"]},"buhuth":{"en":["The word al-ṣabā—with the letter ṣād pronounced with fatḥah and the bāʾ without gemination—means the east wind. Al-dabūr means the west wind."]}},"tuhfa":{},"full":1,"dr":1,"rep":[13045],"tks":"متفق عليه: رواه البخاري (4105)، ومسلم (17: 900)."},{"num":9632,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بُعِثْتُ بِجَوَامِعِ الْكَلِمِ، وَنُصِرْتُ بِالرُّعْبِ، فَبَيْنَا أَنَا نَائِمٌ أُتِيتُ بِمَفَاتِيحِ خَزَائِنِ الأَرْضِ، فَوُضِعَتْ فِي يَدِي.","قَالَ أَبُو هُرَيْرَةَ: وَقَدْ ذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنْتُمْ تَنْتَثِلُونَهَا."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2977) ومسلم في المساجد (6:523) من طرق عن ابن شهاب، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب نصر النبي ﷺ بالرعب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2977) and Muslim (523:6).","chapter_en":"The Prophet ﷺ Was Granted Victory Through Fear","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “I was sent with concise, comprehensive speech; I was granted victory through fear; and while I was asleep, the keys to the treasures of the earth were brought to me and placed in my hand.” Abū Hurayrah said: “The Messenger of Allah ﷺ has departed, while you are extracting those treasures.”"]},"buhuth":{"en":["Abū Hurayrah’s words, “The Messenger of Allah ﷺ has departed, while you are extracting them,” mean that they were bringing forth the contents of those treasures."]}},"tuhfa":{},"voc":["seerah",1386],"full":1,"dr":1,"rep":[801,7832,11714],"tks":"متفق عليه: رواه البخاري (2977)، ومسلم (6: 523)."},{"num":9633,"demo":false,"sanad":"","matn":["عن علي بن أَبِي طَالِبٍ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أُعْطِيتُ مَا لَمْ يُعْطَ أَحَدٌ مِنَ الْأَنْبِيَاءِ فَقُلْنَا: يَا رَسُولَ اللَّهِ، مَا هُوَ؟ قَالَ؟: نُصِرْتُ بِالرُّعْبِ، وَأُعْطِيتُ مَفَاتِيحَ الْأَرْضِ، وَسُمِّيتُ أَحْمَدَ، وَجُعِلَ التُّرَابُ لِي طَهُورًا، وَجُعِلَتْ أُمَّتِي خَيْرَ الْأُمَمِ."],"takhrij":"حسن: رواه أحمد (763) وابن أبي شيبة (31647) من طريق زهير (وهو ابن محمد التميمي) عن عبد الله بن محمد بن عقيل، عن محمد بن علي بن الحنفية، أنه سمع علي بن أبي طالب فذكره.","grade":"حسن","chapter_ar":"باب نصر النبي ﷺ بالرعب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (763) and Ibn Abī Shaybah (11/434).","chapter_en":"The Prophet ﷺ Was Granted Victory Through Fear","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":2,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib reported that the Messenger of Allah ﷺ said: “I have been given what none of the prophets was given.” We asked, “What is it, O Messenger of Allah?” He replied: “I was granted victory through fear; I was given the keys of the earth; I was named Aḥmad; the earth was made a means of purification for me; and my nation was made the best of nations.”"]}},"tuhfa":{},"voc":["seerah",1387],"full":1,"dr":1,"tks":"حسن: رواه أحمد (763)، وابن أبي شيبة (31647)."},{"num":9634,"demo":false,"sanad":"","matn":["عَنْ عَمْرِو بْنِ شُعَيْبٍ، عَنْ أَبِيهِ، عَنْ جَدِّهِ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ قَامَ مِنَ اللَّيْلِ يُصَلِّي، فَاجْتَمَعَ وَرَاءَهُ رِجَالٌ مِنْ أَصْحَابِهِ يَحْرُسُونَهُ، حَتَّى إِذَا صَلَّى وَانْصَرَفَ إِلَيْهِمْ، فَقَالَ لَهُمْ: لَقَدْ أُعْطِيتُ اللَّيْلَةَ خَمْسًا، مَا أُعْطِيَهُنَّ أَحَدٌ قَبْلِي: أَمَّا أَنَا فَأُرْسِلْتُ إِلَى النَّاسِ كُلِّهِمْ عَامَّةً، وَكَانَ مَنْ قَبْلِي إِنَّمَا يُرْسَلُ إِلَى قَوْمِهِ، وَنُصِرْتُ عَلَى الْعَدُوِّ بِالرُّعْبِ، وَلَوْ كَانَ بَيْنِي وَبَيْنَهُمْ مَسِيرَةُ شَهْرٍ لَمُلِئَ مِنْهُ رُعْبًا، وَأُحِلَّتْ لِي الْغَنَائِمُ آكُلُهَا، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ أَكْلَهَا، كَانُوا يُحْرِقُونَهَا، وَجُعِلَتْ لِي الْأَرْضُ مَسَاجِدَ وَطَهُورًا، أَيْنَمَا أَدْرَكَتْنِي الصَّلَاةُ تَمَسَّحْتُ وَصَلَّيْتُ، وَكَانَ مَنْ قَبْلِي يُعَظِّمُونَ ذَلِكَ، إِنَّمَا كَانُوا يُصَلُّونَ فِي كَنَائِسِهِمْ وَبِيَعِهِمْ، وَالْخَامِسَةُ، هِيَ مَا هِيَ، قِيلَ لِي: سَلْ، فَإِنَّ كُلَّ نَبِيٍّ قَدْ سَأَلَ، فَأَخَّرْتُ مَسْأَلَتِي إِلَى يَوْمِ الْقِيَامَةِ، فَهِيَ لَكُمْ وَلِمَنْ شَهِدَ أَنْ لَا إِلَهَ إِلَّا اللَّهُ."],"takhrij":"حسن: رواه أحمد (7068) عن قتيبة بن سعيد، حدثنا بكر بن مضر، عن ابن الهاد، عن عمرو بن شعيب، عن أبيه، عن جده فذكره.","grade":"حسن","chapter_ar":"باب نصر النبي ﷺ بالرعب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (7068).","chapter_en":"The Prophet ﷺ Was Granted Victory Through Fear","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":2,"content":{"translation":{"en":["ʿAmr ibn Shuʿayb reported from his father, from his grandfather, that during the campaign of Tabūk, the Messenger of Allah ﷺ stood in prayer one night. Some of his Companions gathered behind him to guard him. When he had finished praying and turned toward them, he said: “Tonight I was granted five things that no one before me was granted. I was sent to all humanity, whereas those before me were sent only to their own people. I was granted victory over the enemy through fear: even if a month’s journey separated me from them, they would be filled with fear of me. The spoils of war were made lawful for me to consume, whereas those before me regarded consuming them as forbidden and would burn them. The earth was made for me a place of prayer and a means of purification; wherever the time for prayer reaches me, I perform dry ablution and pray. Those before me treated this matter differently and prayed only in their churches and synagogues. “As for the fifth—and what a thing it is!—I was told: ‘Ask, for every prophet has made his request.’ So I deferred my request until the Day of Resurrection. It is for you and for everyone who bears witness that there is no deity worthy of worship except Allah.”"]}},"tuhfa":{},"voc":["seerah",1388],"full":1,"dr":1,"rep":[799,925,8012],"tks":"حسن: رواه أحمد (7068)."},{"num":9635,"demo":false,"sanad":"","matn":["عَنْ أَبِي أُمَامَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: فَضَّلَنِي رَبِّي عَلَى الْأَنْبِيَاءِ، أَوْ قَالَ: عَلَى الْأُمَمِ، بِأَرْبَعٍ: قَالَ: أُرْسِلْتُ إِلَى النَّاسِ كَافَّةً، وَجُعِلَتِ الْأَرْضُ كُلُّهَا لِي وَلِأُمَّتِي مَسْجِدًا وَطَهُورًا، فَأَيْنَمَا أَدْرَكَتْ رَجُلًا مِنْ أُمَّتِي الصَّلَاةُ فَعِنْدَهُ مَسْجِدُهُ، وَعِنْدَهُ طَهُورُهُ، وَنُصِرْتُ بِالرُّعْبِ مَسِيرَةَ شَهْرٍ يَقْذِفُهُ فِي قُلُوبِ أَعْدَائِي، وَأَحَلَّ لَنَا الْغَنَائِمَ."],"takhrij":"حسن: رواه الإمام أحمد (22137) (22209) والترمذي (1553) والبيهقي (1059)، (2/433-434) من طرق عن سليمان التميمي، عن سيّار، عن أبي أمامة فذكره، والسياق لأحمد.","grade":"حسن","chapter_ar":"باب نصر النبي ﷺ بالرعب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22137, 22209) and al-Tirmidhī (1553). The wording is that of Aḥmad.","chapter_en":"The Prophet ﷺ Was Granted Victory Through Fear","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":2,"content":{"translation":{"en":["Abū Umāmah reported that the Messenger of Allah ﷺ said: “My Lord favored me over the prophets—or he said: over the nations—with four things: I was sent to all people; the whole earth was made a place of prayer and a means of purification for me and my nation, so wherever the time of prayer reaches a man from my nation, there he has his place of prayer and his means of purification; I was granted victory through fear cast into the hearts of my enemies from a month’s journey away; and the spoils of war were made lawful for us.”"]}},"tuhfa":{},"voc":["seerah",1389],"full":1,"dr":1,"rep":[8011],"tks":"حسن: رواه الإمام أحمد (22137، 22209)، والترمذي (1553)، والبيهقي (1/212، 2/433-434)."},{"num":9636,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أُعْطِيتُ خَمْسًا لَمْ يُعْطَهُنَّ أَحَدٌ قَبْلِي: بُعِثْتُ إِلَى الأَحْمَرِ وَالأَسْوَدِ، وَجُعِلَتْ لِي الأَرْضُ طَهُورًا وَمَسْجِدًا، وَأُحِلَّتْ لِيَ الْغَنَائِمُ، وَلَمْ تَحِلَّ لأَحَدٍ قَبْلِي، وَنُصِرْتُ بِالرُّعْبِ، فَيَرْعَبُ الْعَدُوُّ، وَهِيَ مِنِّي مَسِيرَةِ شَهْرٍ، وَقِيلَ لِي: سَلْ تُعْطَهْ، وَاخْتَبَأْتُ دَعْوَتِي شَفَاعَةً لأُمَّتِي، فَهِيَ نَائِلَةٌ مِنْكُمْ – إِنْ شَاءَ اللَّهُ – مِنْ لَمْ يُشْرِكْ بِاللهِ شَيْئًا."],"takhrij":"صحيح: رواه أبو داود (489) وأحمد (21299،21314) وصحّحه ابن حبان (6462) والحاكم (3587) من طرق عن سليمان الأعمش، عن مجاهد، عن عبيد بن عمير الليثي، عن أبي ذر فذكره.","grade":"صحيح","chapter_ar":"باب نصر النبي ﷺ بالرعب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (489) and Aḥmad (21299, 21314); authenticated by Ibn Ḥibbān (6462).","chapter_en":"The Prophet ﷺ Was Granted Victory Through Fear","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":2,"content":{"translation":{"en":["Abū Dharr reported that the Messenger of Allah ﷺ said: “I was granted five things that no one before me was granted: I was sent to the red and the black; the earth was made a means of purification and a place of prayer for me; the spoils of war were made lawful for me, though they had not been lawful for anyone before me; I was granted victory through fear, so that an enemy a month’s journey away from me is struck with fear; and I was told, ‘Ask and you will be granted.’ “I reserved my supplication as intercession for my nation. It will reach—if Allah wills—those among you who do not associate anything with Allah.”"]}},"tuhfa":{},"voc":["seerah",1390],"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (489)، وأحمد (21299، 21314)، وصححه ابن حبان (6462)، والحاكم (3587)."},{"num":9637,"demo":false,"sanad":"","matn":["عَنِ الْمُغِيرَةِ رَضِيَ اللَّهُ عَنْهُ قَالَ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّ كَذِبًا عَلَىَّ لَيْسَ كَكَذِبٍ عَلَى أَحَدٍ، مَنْ كَذَبَ عَلَىَّ مُتَعَمِّدًا فَلْيَتَبَوَّأْ مَقْعَدَهُ مِنَ النَّارِ. سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ نِيحَ عَلَيْهِ يُعَذَّبُ بِمَا نِيحَ عَلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في الجنائز (1291) ومسلم في الجنائز (28:933) كلاهما من حديث سعيد بن عبيد، عن علي بن ربيعة، عن المغيرة بن شعبة فذكره واللفظ للبخاري. وأما مسلم فاكتفى بالجزء الثاني من الحديث.","grade":"متفق عليه","chapter_ar":"الكذب على النبي ﷺ ليس كالكذب على أحد من الناس","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1291) and Muslim (933:28).","chapter_en":"Lying About the Prophet ﷺ Is Unlike Lying About Anyone Else","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":3,"content":{"translation":{"en":["Al-Mughīrah ibn Shuʿbah said: I heard the Prophet ﷺ say: “Telling a lie about me is unlike telling a lie about anyone else. Whoever deliberately lies about me, let him take his seat in the Fire.” I also heard the Prophet ﷺ say: “Whoever is lamented over is punished because of the lamentation made over him.”"]}},"tuhfa":{},"voc":["seerah",1395],"full":1,"rep":[3569],"tks":"متفق عليه: رواه البخاري (1291)، ومسلم (28: 933). وأما مسلم فاكتفى بالجزء الثاني من الحديث."},{"num":9638,"demo":false,"sanad":"","matn":["عَنْ علي بن أَبِي طَالِبٍ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لاَ تَكْذِبُوا علي فَإِنَّهُ مَنْ كَذَبَ علي فَلْيَلِجِ النَّارَ."],"takhrij":"متفق عليه: رواه البخاري في العلم (106) ومسلم في المقدمة (1) كلاهما من حديث شعبة، عن منصور، عن ربعي بن حراش، أنه سمع عليا يخطب قال: فقال: فذكره.","grade":"متفق عليه","chapter_ar":"الكذب على النبي ﷺ ليس كالكذب على أحد من الناس","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (106) and Muslim in his Introduction (1).","chapter_en":"Lying About the Prophet ﷺ Is Unlike Lying About Anyone Else","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":3,"content":{"translation":{"en":["ʿAlī reported that the Prophet ﷺ said: “Do not lie about me, for whoever lies about me shall enter the Fire.”"]}},"tuhfa":{},"voc":["seerah",1396],"full":1,"dr":1,"rep":[1255],"tks":"متفق عليه: رواه البخاري (106)، ومسلم (1)."},{"num":9639,"demo":false,"sanad":"","matn":["9639- عَنْ جابِرِ بنِ عبدالله يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: إِنَّمَا أَنَا بَشَرٌ، وَإِنِّي اشْتَرَطْتُ عَلَى رَبِّي عَزَّ وَجَلَّ، أَيُّ عَبْدٍ مِنَ الْمُسْلِمِينَ سَبَبْتُهُ أَوْ شَتَمْتُهُ أَنْ يَكُونَ ذَلِكَ لَهُ زَكَاةً وَأَجْرًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2602: 94) من طرق عن ابن جريج، أخبرني أبو الزبير أنه سمع جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب من لعنه النبي ﷺ أو سبَّه وليس هو أهلًا لذلك، كان له زكاة وأجرًا ورحمة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2602:94).","chapter_en":"If the Prophet ﷺ Cursed or Rebuked Someone Who Did Not Deserve It, It Became Purification, Reward, and Mercy for That Person","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":4,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: I heard the Messenger of Allah ﷺ say: “I am only a human being, and I stipulated with my Lord, Mighty and Majestic, that any Muslim servant whom I rebuke or insult should have that made a purification and reward for him.”"]}},"tuhfa":{},"voc":["seerah",1397],"full":1,"dr":1,"rep":[783],"tks":"صحيح: رواه مسلم (2602: 94)."},{"num":9640,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ: رَضِيَ اللَّهُ عَنْهُ أَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اللَّهُمَّ فَأَيُّمَا مُؤْمِنٍ سَبَبْتُهُ، فَاجْعَلْ ذَلِكَ لَهُ قُرْبَةً إِلَيْكَ يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في الدعوات (6361)، ومسلم في البر والصلة (2601: 92) من طرق عن ابن وهب، أخبرني يونس، عن ابن شهاب، أخبرني سعيد بن المسيب، عن أبي هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب من لعنه النبي ﷺ أو سبَّه وليس هو أهلًا لذلك، كان له زكاة وأجرًا ورحمة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6361) and Muslim (2601:92).","chapter_en":"If the Prophet ﷺ Cursed or Rebuked Someone Who Did Not Deserve It, It Became Purification, Reward, and Mercy for That Person","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that he heard the Messenger of Allah ﷺ say: “O Allah, whichever believing servant I may have rebuked, make that a means of nearness to You for him on the Day of Resurrection.”"]}},"tuhfa":{},"voc":["seerah",1398],"full":1,"tks":"متفق عليه: رواه البخاري (6361)، ومسلم (2601: 92)."},{"num":9641,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اللَّهُمَّ إِنَّمَا مُحَمَّدٌ بَشَرٌ يَغْضَبُ كَمَا يَغْضَبُ الْبَشَرُ، وَإِنِّي قَدِ اتَّخَذْتُ عِنْدَكَ عَهْدًا لَنْ تُخْلِفَنِيهِ، فَأَيُّمَا مُؤْمِنٍ آذَيْتُهُ، أَوْ سَبَبْتُهُ، أَوْ جَلَدْتُهُ، فَاجْعَلْهَا لَهُ كَفَّارَةً وَقُرْبَةً تُقَرِّبُهُ بِهَا إِلَيْكَ يَوْمَ الْقِيَامَةِ.","وفي لفظ: فَاجْعَلْهَا لَهُ صَلَاةً وَزَكَاةً وَقُرْبَةً تُقَرِّبُهُ به إِلَيْكَ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2601: 91) عن قتيبة بن سعيد، حدثنا ليث، عن سعيد بن أبي سعيد، عن سالم مولى النصريين قال: سمعت أبا هريرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب من لعنه النبي ﷺ أو سبَّه وليس هو أهلًا لذلك، كان له زكاة وأجرًا ورحمة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2601:91).","chapter_en":"If the Prophet ﷺ Cursed or Rebuked Someone Who Did Not Deserve It, It Became Purification, Reward, and Mercy for That Person","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah said: I heard the Messenger of Allah ﷺ say: “O Allah, Muhammad is only a human being who becomes angry as other human beings become angry. I have taken from You a covenant that You will never break: whichever believer I may have harmed, rebuked, or struck, make it an expiation for him and a means by which You bring him near to You on the Day of Resurrection.” Another wording states: “Make it a blessing, purification, and means of nearness by which You bring him close to You on the Day of Resurrection.”"]}},"tuhfa":{},"voc":["seerah",1399],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2601: 91)."},{"num":9642,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ قَالَتْ:  دَخَلَ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلَانِ، فَكَلَّمَاهُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ؟ فَأَغْضَبَاهُ، فَلَعَنَهُمَا وَسَبَّهُمَا، فَلَمَّا خَرَجَا، قُلْتُ: يَا رَسُولَ اللَّهِ مَنْ أَصَابَ مِنَ الْخَيْرِ شَيْئًا مَا أَصَابَهُ هَذَانِ، قَالَ: وَمَا ذَاكِ؟ قَالَتْ: قُلْتُ: لَعَنْتَهُمَا وَسَبَبْتَهُمَا. قَالَ: أَوَمَا عَلِمْتِ مَا شَارَطْتُ عَلَيْهِ رَبِّي؟ قُلْتُ: اللَّهُمَّ إِنَّمَا أَنَا بَشَرٌ، فَأَيُّ الْمُسْلِمِينَ لَعَنْتُهُ أَوْ سَبَبْتُهُ فَاجْعَلْهُ لَهُ زَكَاةً وَأَجْرًا."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2600) من طرق عن الأعمش، عن أبي الضحى، عن مسروق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب من لعنه النبي ﷺ أو سبَّه وليس هو أهلًا لذلك، كان له زكاة وأجرًا ورحمة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2600).","chapter_en":"If the Prophet ﷺ Cursed or Rebuked Someone Who Did Not Deserve It, It Became Purification, Reward, and Mercy for That Person","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":4,"content":{"translation":{"en":["ʿĀ’ishah said: Two men entered upon the Messenger of Allah ﷺ and spoke to him about something whose nature I do not know. They angered him, so he cursed and rebuked them. After they had left, I said, “O Messenger of Allah, no one has received as much good as these two have!” He asked, “Why is that?” I replied, “You cursed and rebuked them.” He said: “Do you not know the condition I made with my Lord? I said: ‘O Allah, I am only a human being, so whichever Muslim I curse or rebuke, make it a purification and reward for him.’”"]}},"tuhfa":{},"voc":["seerah",1400],"full":1,"tks":"صحيح: رواه مسلم (2600)."},{"num":9643,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ:  كَانَتْ عِنْدَ أُمِّ سُلَيْمٍ يَتِيمَةٌ، وَهِيَ أُمُّ أَنَسٍ، فَرَأَى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْيَتِيمَةَ، فَقَالَ: آنْتِ هِيَهْ؟ لَقَدْ كَبِرْتِ لَا كَبِرَ سِنُّكِ، فَرَجَعَتِ الْيَتِيمَةُ إِلَى أُمِّ سُلَيْمٍ تَبْكِي، فَقَالَتْ أُمُّ سُلَيْمٍ: مَا لَكِ يَا بُنَيَّةُ؟ قَالَتِ الْجَارِيَةُ: دَعَا عَلَيَّ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ لَا يَكْبَرَ سِنِّي، فَالْآنَ لَا يَكْبَرُ سِنِّي أَبَدًا، أَوْ قَالَتْ: قَرْنِي. فَخَرَجَتْ أُمُّ سُلَيْمٍ مُسْتَعْجِلَةً تَلُوثُ خِمَارَهَا حَتَّى لَقِيَتْ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ لَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا لَكِ يَا أُمَّ سُلَيْمٍ؟ فَقَالَتْ: يَا نَبِيَّ اللَّهِ أَدَعَوْتَ عَلَى يَتِيمَتِي؟ قَالَ: وَمَا ذَاكِ يَا أُمَّ سُلَيْمٍ؟ قَالَتْ: زَعَمَتْ أَنَّكَ دَعَوْتَ أَنْ لَا يَكْبَرَ سِنُّهَا، وَلَا يَكْبَرَ قَرْنُهَا، قَالَ: فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ثُمَّ قَالَ: يَا أُمَّ سُلَيْمٍ أَمَا تَعْلَمِينَ أَنَّ شَرْطِي عَلَى رَبِّي، أَنِّي اشْتَرَطْتُ عَلَى رَبِّي، فَقُلْتُ: إِنَّمَا أَنَا بَشَرٌ أَرْضَى كَمَا يَرْضَى الْبَشَرُ، وَأَغْضَبُ كَمَا يَغْضَبُ الْبَشَرُ، فَأَيُّمَا أَحَدٍ دَعَوْتُ عَلَيْهِ مِنْ أُمَّتِي بِدَعْوَةٍ لَيْسَ لَهَا بِأَهْلٍ، أَنْ تَجْعَلَهَا لَهُ طَهُورًا، وَزَكَاةً، وَقُرْبَةً يُقَرِّبُهُ بِهَا مِنْهُ يَوْمَ الْقِيَامَةِ."],"takhrij":"صحيح: رواه مسلم في البر والصلة (2603) من طرق عن عمر بن يونس، حدثنا عكرمة بن عمار، حدثنا إسحاق بن أبي طلحة، حدثني أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب من لعنه النبي ﷺ أو سبَّه وليس هو أهلًا لذلك، كان له زكاة وأجرًا ورحمة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2603).","chapter_en":"If the Prophet ﷺ Cursed or Rebuked Someone Who Did Not Deserve It, It Became Purification, Reward, and Mercy for That Person","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported: There was an orphan girl in the care of Umm Sulaym, the mother of Anas. The Messenger of Allah ﷺ saw the orphan girl and said: “Is it you? You have grown! May your age not increase!” The orphan girl returned to Umm Sulaym weeping. Umm Sulaym asked, “What is wrong, my daughter?” The girl replied, “The Prophet of Allah ﷺ supplicated against me that my age should not increase. Now my age will never increase”—or she said, “my lifetime.” Umm Sulaym hurried out, hastily wrapping her head-covering, until she met the Messenger of Allah ﷺ. He asked her: “What is the matter, Umm Sulaym?” She replied, “O Prophet of Allah, did you supplicate against my orphan girl?” He asked, “What do you mean, Umm Sulaym?” She said, “She claims that you supplicated that neither her age nor her lifetime should increase.” The Messenger of Allah ﷺ laughed and then said: “O Umm Sulaym, do you not know the condition I made with my Lord? I stipulated with my Lord, saying: ‘I am only a human being. I am pleased as human beings are pleased, and I become angry as human beings become angry. So if I supplicate against anyone from my nation with a supplication he does not deserve, make it a purification, a blessing, and a means by which You bring him near to You on the Day of Resurrection.’”"]}},"tuhfa":{},"voc":["seerah",1401],"full":1,"rep":[784],"tks":"صحيح: رواه مسلم (2603)."},{"num":9644,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  قَالَ: أَتَرَوْنَ قِبْلَتِي هَاهُنَا؟ فَوَاللَّهِ مَا يَخْفَى عَلَىَّ خُشُوعُكُمْ وَلاَ رُكُوعُكُمْ، إِنِّي لأَرَاكُمْ مِنْ وَرَاءِ ظَهْرِي."],"takhrij":"متفق عليه: رواه مالك، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن النبي ﷺ كان يرى خلف ظهره كما يرى من بين يديه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Mālik (399), al-Bukhārī (418), and Muslim (424:109).","chapter_en":"The Prophet ﷺ Could See Behind His Back Just as He Saw What Was Before Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “Do you think my attention is directed only toward my prayer direction here? By Allah, neither your humility nor your bowing is hidden from me. Indeed, I see you from behind my back.”"]}},"tuhfa":{},"voc":["seerah",1403],"full":1,"dr":1,"rep":[2049],"tks":"متفق عليه: رواه مالك، عن أبي الزناد، عن الأعرج، عن أبي هريرة فذكره."},{"num":9645,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: أَقِيمُوا الرُّكُوعَ وَالسُّجُودَ، فَوَاللَّهِ إِنِّي لأَرَاكُمْ مِنْ بَعْدِي ـ وَرُبَّمَا قَالَ: مِنْ بَعْدِ ظَهْرِي ـ إِذَا رَكَعْتُمْ وَسَجَدْتُمْ."],"takhrij":"متفق عليه: رواه البخاري في الأذان (742) ومسلم في الصلاة (110:425) كلاهما عن محمد بن بشّار، حدثنا غندر محمد بن جعفر، حدثنا شعبة، قال: سمعت قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء أن النبي ﷺ كان يرى خلف ظهره كما يرى من بين يديه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (742) and Muslim (425:110).","chapter_en":"The Prophet ﷺ Could See Behind His Back Just as He Saw What Was Before Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":6,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said: “Perform the bowing and prostration properly. By Allah, I see you behind me”—or he may have said, “from behind my back”—“when you bow and prostrate.”"]},"buhuth":{"en":["Al-Nawawī said in his commentary on Ṣaḥīḥ Muslim:","“The scholars said that this means Allah created for him ﷺ a faculty of perception in the back of his head by which he could see what was behind him. Even greater customary laws were miraculously suspended for him ﷺ. Neither reason nor revelation makes this impossible. Rather, revelation has conveyed it according to its apparent meaning, so it must be affirmed accordingly.”","Al-Qāḍī said:","“Aḥmad ibn Ḥanbal—may Allah Most High have mercy upon him—and the majority of scholars held that this was actual sight with the eyes.”"]}},"tuhfa":{},"voc":["seerah",1404],"full":1,"dr":1,"rep":[2051],"tks":"متفق عليه: رواه البخاري (742) ومسلم (110: 425)."},{"num":9646,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، قَالَ: كَانَ أَصْحَابُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَمْشُونَ أَمَامَهُ إِذَا خَرَجَ، وَيَدَعُونَ ظَهْرَهُ لِلْمَلَائِكَةِ."],"takhrij":"صحيح: رواه ابنُ ماجه (246)، وأحمد (14236) -واللفظ له، والحارث في مسنده كما في بغية الباحث (946)، وابن حبان (6312)، كلهم من طريق سفيان الثوري، عن الأسود بن قيس، عن نُبيح العنزي، عن جابر بن عبد الله قال: فذكره.","grade":"صحيح","chapter_ar":"من خصائص النبي ﷺ أن الملائكة يمشون خلفه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (246) and Aḥmad (14236), whose wording this is.","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That the Angels Walked Behind Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":7,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: When the Prophet ﷺ went out, his Companions would walk ahead of him and leave the space behind him for the angels."]}},"tuhfa":{},"voc":["seerah",1405],"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (246)، وأحمد (14236) -واللفظ له-، والحارث في مسنده كما في بغية الباحث (946)، وابن حبان (6312)."},{"num":9647,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ عن النبي صلى الله عليه وسلم قال: مَنْ رَآنِي فِي الْمَنَامِ فَسَيَرَانِي فِي الْيَقَظَةِ، أَوْ لَكَأَنَّمَا رَآنِي فِي الْيَقَظَةِ، لَا يَتَمَثَّلُ الشَّيْطَانُ بِي.","وهذا لفظ مسلم، وزاد البخاري قال ابن سيرين: إذا رآه في صورته."],"takhrij":"متفق عليه: رواه البخاري في كتاب التعبير (6993) ومسلم في كتاب الرؤيا (2266-11) من طريقين عن الزهري، حدثني أبو سلمة بن عبد الرحمن أن أبا هريرة قال: فذكره.","grade":"متفق عليه","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6993) and Muslim (2266:11).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “Whoever sees me in a dream will see me while awake—or it is as though he has seen me while awake—for Satan cannot assume my form.” This is Muslim’s wording. Al-Bukhārī adds that Ibn Sīrīn said: “This applies when he sees him in his actual form.”"]}},"tuhfa":{},"voc":["seerah",1406],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6993) ومسلم (2266: 11)."},{"num":9648,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي، فَإِنَّ الشَّيْطَانَ لاَ يَتَخَيَّلُ بِي، وَرُؤْيَا الْمُؤْمِنِ جُزْءٌ مِنْ سِتَّةٍ وَأَرْبَعِينَ جُزْءًا مِنَ النُّبُوَّةِ."],"takhrij":"متفق عليه: رواه البخاري في كتاب التعبير (6994) واللفظ له، ومسلم في كتاب الرؤيا (2264) من طريقين عن ثابت البناني عن أنس بن مالك فذكره، وسياق مسلم مختصر مقتصر على الشطر الأخير من المتن.","grade":"متفق عليه","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6994), whose wording this is, and Muslim (2264).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet ﷺ said: “Whoever sees me in a dream has truly seen me, for Satan cannot appear in my likeness. The dream of a believer is one of forty-six parts of prophethood.”"]}},"tuhfa":{},"voc":["seerah",1407],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6994) واللفظ له، ومسلم (2264)."},{"num":9649,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ، سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: مَنْ رَآنِي فَقَدْ رَأَى الْحَقَّ، فَإِنَّ الشَّيْطَانَ لاَ يَتَكَوَّنُنِي."],"takhrij":"صحيح: رواه البخاري في كتاب التعبير (6997) عن عبد الله بن يوسف حدثنا الليث، حدثني ابن الهاد عن عبد الله بن خبّاب عن أبي سعيد الخدري فذكره.","grade":"صحيح","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6997).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī reported that he heard the Prophet ﷺ say: “Whoever sees me has truly seen the truth, for Satan cannot take on my form.”"]},"buhuth":{"en":["The expression “cannot take on my form” means that Satan cannot assume the Prophet’s appearance."]}},"tuhfa":{},"voc":["seerah",1408],"full":1,"dr":1,"rep":[11693],"tks":"صحيح: رواه البخاري (6997)."},{"num":9650,"demo":false,"sanad":"","matn":["عَنْ أَبِي قَتَادَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: الرُّؤْيَا الصَّالِحَةُ مِنَ اللَّهِ، وَالْحُلْمُ مِنَ الشَّيْطَانِ، فَمَنْ رَأَى شَيْئًا يَكْرَهُهُ فَلْيَنْفِثْ عَنْ شِمَالِهِ ثَلاَثًا، وَلْيَتَعَوَّذْ مِنَ الشَّيْطَانِ، فَإِنَّهَا لاَ تَضُرُّهُ، وَإِنَّ الشَّيْطَانَ لاَ يَتَرَاءَى بِي."],"takhrij":"متفق عليه: رواه البخاري في كتاب التعبير (6995) عن يحيى بن بكير، حدثنا الليث، عن عبيد الله بن أبي جعفر، أخبرني أبو سلمة، عن أبي قتادة فذكره.","grade":"متفق عليه","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6995) and Muslim in the Book of Dreams (2261:2).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["Abū Qatādah reported that the Prophet ﷺ said: “A good dream is from Allah, while a disturbing dream is from Satan. Whoever sees something he dislikes should lightly spit to his left three times and seek refuge from Satan, and it will not harm him. Satan cannot appear in my guise.”"]},"buhuth":{"en":["The expression lā yatazāyā bī is written with the letter zāy and a yāʾ after the alif, according to the narrations other than that of Abū Dharr. This was stated by al-Ḥāfiẓ in Fatḥ al-Bārī (12/386). It means that Satan cannot appear in the Prophet’s guise.","The narration of Abū Dharr reads lā yatarāʾā bī, with the letter rāʾ, meaning that Satan cannot become visible in the Prophet’s form."]}},"tuhfa":{},"voc":["seerah",1409],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6995)."},{"num":9651,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  قَالَ مَنْ رَآنِي فِي النَّوْمِ فَقَدْ رَآنِي، إِنَّهُ لاَ يَنْبَغِي لِلشَّيْطَانِ أَنْ يَتَمَثَّلَ فِي صُورَتِي. وَقَالَ: إِذَا حَلَمَ أَحَدُكُمْ فَلاَ يُخْبِرْ أَحَدًا بِتَلَعُّبِ الشَّيْطَانِ بِهِ فِي الْمَنَامِ."],"takhrij":"صحيح: رواه مسلم في كتاب الرؤيا (2268-12) من طريقين عن الليث بن سعد، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2268:12). Another wording of his (13) states: “Satan is not able to resemble me.”","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allah ﷺ said: “Whoever sees me in sleep has truly seen me, for Satan is not able to assume my form.” He also said: “When one of you has a disturbing dream, he should not tell anyone about Satan’s playing with him in his sleep.”"]},"buhuth":{"en":["The words “cannot assume my form” mean that Satan cannot resemble the Prophet in his actual appearance. See Fatḥ al-Bārī (12/386)."]}},"tuhfa":{},"voc":["seerah",1410],"full":1,"dr":1,"rep":[11685],"tks":"صحيح: رواه مسلم (2268: 12)."},{"num":9652,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنْ رَآنِي فِي الْمَنَامِ فَقَدْ رَآنِي فِي الْيَقَظَةِ، فَإِنَّ الشَّيْطَانَ لاَ يَتَمَثَّلُ عَلَى صُورَتِي."],"takhrij":"صحيح: رواه الترمذي (2276) وابن ماجة (3900) والإمام أحمد (3559) والدرامي (2143) كلهم من طرق عن سفيان الثوري، عن أبي إسحاق، عن أبي الأحوص، عن عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated and authenticated by al-Tirmidhī (2276), and narrated by Ibn Mājah (3900), Imām Aḥmad (3559), and al-Dārimī (2143).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd reported that the Prophet ﷺ said: “Whoever sees me in a dream has indeed seen me as though awake, for Satan cannot assume my form.”"]}},"tuhfa":{},"voc":["seerah",1411],"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (2276)، وابن ماجه (3900)، والإمام أحمد (3559)، والدارمي (2143)."},{"num":9653,"demo":false,"sanad":"","matn":["عَنْ عَوْنِ بْنِ أَبِي جُحَيْفَةَ، عَنْ أَبِيهِ، عَنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ مَنْ رَآنِي فِي الْمَنَامِ فَكَأَنَّمَا رَآنِي فِي الْيَقَظَةِ، إِنَّ الشَّيْطَانَ لاَ يَسْتَطِيعُ أَنْ يَتَمَثَّلَ بِي.","وفي لفظ ابن حبان: \"فإن الشيطان لا يتشبه بي\"."],"takhrij":"صحيح: رواه ابن ماجة (3904) وأبو يعلى في مسنده (881) كلاهما من رواية صدقة بن أبي عمران، وابن حبان (6053) من رواية زيد بن أبي أنيسة كلاهما عن عون بن أبي جحيفة فذكره.","grade":"صحيح","chapter_ar":"من خصائص النبي ﷺ أن الشيطان لا يتمثل به","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Mājah (3904) and Abū Yaʿlā in his Musnad (881).","chapter_en":"One of the Prophet’s Distinctive Qualities ﷺ Is That Satan Cannot Assume His Form","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":8,"content":{"translation":{"en":["ʿAwn ibn Abī Juḥayfah reported from his father that the Prophet ﷺ said: “Whoever sees me in a dream, it is as though he has seen me while awake. Satan cannot assume my form.” Ibn Ḥibbān’s wording states: “Satan cannot resemble me.”"]},"buhuth":{"en":["The summary of this chapter is that the claim of someone who says he saw the Prophet ﷺ in a dream is not accepted unless two conditions are fulfilled:","First: The person must know the Prophet’s physical characteristics ﷺ as transmitted in the authentic collections and books of Sunnah. These include that he was of medium height, fair-skinned with a reddish complexion, the most handsome person on earth, and had black hair containing only a few white hairs, along with the other characteristics mentioned in the section describing the physical appearance of the Messenger of Allah ﷺ in the collection on his characteristics.","If someone sees him contrary to these descriptions—such as with a dark complexion, a white beard, or short stature—then it is Satan and not the Prophet ﷺ. Satan may claim to be the Prophet ﷺ. If the figure’s appearance does not correspond to the Prophet’s description given above, it is not the Prophet; it is Satan seeking to cause confusion in the dreamer’s religion.","Second: The figure must not command anything newly introduced into the religion or prohibit anything legitimately prescribed, because Allah Most High completed this religion during the Prophet’s lifetime ﷺ. He said:","“Today I have perfected your religion for you, completed My favor upon you, and chosen Islam as your religion.” [Al-Māʾidah: 3]","After the death of the Messenger of Allah ﷺ, legislation and abrogation came to an end. If either or both of these conditions are absent, then the figure is not the Prophet ﷺ. Rather, it is Satan seeking to corrupt the person’s religion, for Allah Most High has protected His noble Prophet’s form from being assumed by Satan."]}},"tuhfa":{},"voc":["seerah",1412],"full":1,"dr":1,"tks":"صحيح: رواه ابن ماجه (3904)، وأبو يعلى في مسنده (881)."},{"num":9654,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ رَسُولُ اللهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ  : وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَيَأْتِيَنَّ عَلَى أَحَدِكُمْ يَوْمٌ لَأَنْ يَرَانِي، ثُمَّ لَأَنْ يَرَانِي، أَحَبُّ إِلَيْهِ مِنْ أَنْ يَكُونَ لَهُ مِثْلُ أَهْلِهِ وَمَالِهِ.","قَالَ أَبُو إِسْحَاقَ : الْمَعْنَى فِيهِ عِنْدِي لَأَنْ يَرَانِي مَعَهُمْ أَحَبُّ إِلَيْهِ مِنْ أَهْلِهِ وَمَالِهِ، وَهُوَ عِنْدِي مُقَدَّمٌ وَمُؤَخَّرٌ."],"takhrij":"متفق عليه: رواه مسلم في الفضائل (142،2364) عن محمد بن رافع، حدثنا عبد الرزاق، أخبرنا معمر، عن همام بن منبه، قال: هذا ما حدثنا أبو هريرة عن رسول الله صلى الله عليه وسلم فذكر أحاديث منها، وقال رسول الله صلى الله عليه وسلم فذكره.","grade":"متفق عليه","chapter_ar":"باب فضل النظر إلى النبي ﷺ وتمنِّيه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2364:142) and al-Bukhārī (3589).","chapter_en":"The Virtue of Seeing the Prophet ﷺ and Longing to See Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع خصائص النبي ﷺ","group_en":"A Collection Concerning the Distinctive Qualities of the Prophet ﷺ","part_no":48,"group_no":36,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “By Him in Whose hand is the soul of Muhammad, a day will certainly come upon one of you when he will no longer see me; then seeing me would be dearer to him than having his family and wealth together.” Abū Isḥāq said: “In my view, its meaning is: ‘Seeing me along with them would be dearer to him than his family and wealth.’ I regard the wording as containing an instance of transposition.”"]}},"tuhfa":{},"voc":["seerah",1413],"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (142: 2364)."},{"num":9655,"demo":false,"sanad":"","matn":["عن خَالِدِ بْنِ مَعْدَانَ عَنْ أَصْحَابِ رَسُولِ اللَّهِ صلى الله عليه وسلم أَنَّهُمْ قَالُوا :يَا رَسُولَ اللَّهِ أَخْبِرْنَا عَنْ نَفْسِكَ فقال: دَعْوَةُ أَبِي إِبْرَاهِيمَ وَبُشْرَى عِيسَى عَلَيْهِمَا السَّلَامُ، وَرَأَتْ أُمِّي حِينَ حَمَلَتْ بِي أَنَّهُ خَرَجَ مِنْهَا نُورٌ أَضَاءَتْ لَهُ قُصُورُ بُصْرَى مِنْ أَرْضِ الشَّامِ، وَاسْتَرْضَعْتُ فِي بَنِي سَعْدِ بْنِ بَكْرٍ، فبينا أَنَا مَعَ أَخٍ لِي فِي بَهْمٍ لَنَا أَتَانِي رَجُلَانِ عَلَيْهِمَا ثِيَابٌ بِيضٌ مَعَهُمَا طَسْتٌ مِنْ ذَهَبٍ مَمْلُوءَةٌ ثَلْجًا فَأَضْجَعَانِي فَشَقَّا بَطْنِي ثُمَّ اسْتَخْرَجَا قَلْبِي فَشَقَّاهُ فَأَخْرَجَا مِنْهُ عَلَقَةً سَوْدَاءَ فَالقَيَاهَا. ثُمَّ غَسَلَا قَلْبِي وَبَطْنِي بِذَٰلِكَ الثَّلْجِ، حَتَّىٰ إِذَا أَنْقَيَاهُ رَدَّاهُ كَمَا كَانَ، ثُمَّ قَالَ أَحَدُهُمَا لِصَاحِبِهِ زِنْهُ بِعَشَرَةٍ مِنْ أُمَّتِهِ فَوَزَنَنِي بِعَشَرَةٍ فَوَزَنْتُهُمْ، ثُمَّ قَالَ زِنْهُ بِمِائَةٍ مِنْ أُمَّتِهِ فَوَزَنَنِي بِمِائَةٍ فَوَزَنْتُهُمْ، ثُمَّ قَالَ زِنْهُ بِأَلْفٍ مِنْ أُمَّتِهِ فَوَزَنَنِي بِأَلْفٍ فَوَزَنْتُهُمْ، فقال دَعْهُ عَنكَ فَلَوْ وَزَنْتَهُ بِأُمَّتِهِ لَوَزَنَهُمْ."],"takhrij":"حسن: رواه محمد بن إسحاق في السيرة (ص28) فقال: حدثني ثور بن يزيد، عن خالد بن معدان فذكره.","grade":"حسن","chapter_ar":"المعجزات التي ظهرت عند ولادة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Muḥammad ibn Isḥāq in Al-Sīrah (p. 28), who said: Thawr ibn Yazīd narrated to me from Khālid ibn Maʿdān, who related it.","chapter_en":"Miracles That Appeared Around the Birth of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":1,"content":{"translation":{"en":["Khālid ibn Maʿdān reported from some Companions of the Messenger of Allah ﷺ that they said, “O Messenger of Allah, tell us about yourself.” He replied: “I am the answer to the supplication of my forefather Abraham and the glad tidings given by Jesus—peace be upon them both. While my mother was carrying me, she saw a light emerge from her by which the palaces of Buṣrā in the land of Syria were illuminated. “I was then placed in the care of a wet nurse among Banū Saʿd ibn Bakr. While I was with a foster brother of mine among some young sheep belonging to us, two men dressed in white came to me. They had with them a golden basin filled with snow. They laid me down, opened my abdomen, removed my heart and opened it. They took a black clot from it and cast it away. They then washed my heart and abdomen with that snow until they had thoroughly cleansed them, after which they restored my heart as it had been. “One of them then said to the other, ‘Weigh him against ten members of his nation.’ He weighed me against ten, and I outweighed them. He then said, ‘Weigh him against one hundred members of his nation.’ He weighed me against one hundred, and I outweighed them. He then said, ‘Weigh him against one thousand members of his nation.’ He weighed me against one thousand, and I outweighed them. “He then said, ‘Leave him, for if you weighed him against his entire nation, he would outweigh them.’”"]},"intro_majmu":{"ar":["ذكر البيهقي في الدلائل (١/١٠) عن بعض أهل العلم أن دلائل نبوة النبي ﷺ تبلغ ألفًا.","وهنا أكتفي بذكر عدد منها، والباقي مذكور في الكتاب في المواضع المتفرقة حسب مناسبتها؛ وذلك تجنبًا من التكرار والإطالة."],"en":["Al-Bayhaqī related in Dalā’il al-Nubuwwah (1/10), from certain scholars, that the proofs of the Prophet’s prophethood ﷺ number as many as one thousand.","Here I shall mention only some of them. The rest are cited throughout the book in their appropriate places, thereby avoiding repetition and undue length."]}},"tuhfa":{},"voc":["seerah",1615],"full":1,"dr":1,"tks":"حسن: رواه محمد بن إسحاق في السيرة (ص 28) فقال: حدثني ثور بن يزيد، عن خالد بن معدان فذكره."},{"num":9656,"demo":false,"sanad":"","matn":["عَنْ عُتْبَةَ بْنِ عَبْدٍ السُّلَمِيِّ أَنَّهُ حَدَّثَهُمْ: أَنَّ رَجُلًا سَأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: كَيْفَ كَانَ أَوَّلُ شَأْنِكَ يَا رَسُولَ اللَّهِ؟ قَالَ: كَانَتْ حَاضِنَتِي مِنْ بَنِي سَعْدِ بْنِ بَكْرٍ، فَانْطَلَقْتُ أَنَا وَابْنٌ لَهَا فِي بَهْمٍ لَنَا، وَلَمْ نَأْخُذْ مَعَنَا زَادًا، فَقُلْتُ: يَا أَخِي، اذْهَبْ فَأْتِنَا بِزَادٍ مِنْ عِنْدِ أُمِّنَا، فَانْطَلَقَ أَخِي وَمَكَثْتُ عِنْدَ الْبَهْمِ، فَأَقْبَلَ طَيْرَانِ أَبْيَضَانِ كَأَنَّهُمَا نَسْرَانِ، فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ: أَهُوَ هُوَ؟ قَالَ: نَعَمْ. فَأَقْبَلَا يَبْتَدِرَانِي، فَأَخَذَانِي فَبَطَحَانِي إِلَى الْقَفَا، فَشَقَّا بَطْنِي، ثُمَّ اسْتَخْرَجَا قَلْبِي، فَشَقَّاهُ فَأَخْرَجَا مِنْهُ عَلَقَتَيْنِ سوادوين، فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ – قَالَ يَزِيدُ فِي حَدِيثِهِ: ائْتِنِي بِمَاءِ ثَلْجٍ – فَغَسَلَا بِهِ جَوْفِي، ثُمَّ قَالَ: ائْتِنِي بِمَاءِ بَرَدٍ، فَغَسَلَا بِهِ قَلْبِي، ثُمَّ قَالَ: ائْتِنِي بِالسَّكِينَةِ، فَذرَّاهَا فِي قَلْبِي، ثُمَّ قَالَ أَحَدُهُمَا لِصَاحِبِهِ: حِصْهُ، فَحَاصَهُ، وَخَتَمَ عَلَيْهِ بِخَاتَمِ النُّبُوَّةِ – وَقَالَ حَيْوَةُ فِي حَدِيثِهِ: اجْعَلْهُ فِي كِفَّةٍ، وَاجْعَلْ أَلْفًا مِنْ أُمَّتِهِ فِي كِفَّةٍ، فَإِذَا أَنَا أَنْظُرُ إِلَى الْأَلْفِ فَوْقِي، أُشْفِقُ أَنْ يخرّ عليّ بَعْضُهُمْ، فَقَالَ: لَوْ أَنَّ أُمَّتَهُ وُزِنَتْ بِهِ لَمَالَ بِهِمْ، ثُمَّ انْطَلَقَا وَتَرَكَانِي، وَفَرِقْتُ فَرَقًا شَدِيدًا، ثُمَّ انْطَلَقْتُ إِلَى أُمِّي فَأَخْبَرْتُهَا بِالَّذِي لَقِيتُهُ، فَأَشْفَقَتْ عليّ أَنْ يَكُونَ أُلْبِسَ بِي، قَالَتْ: أُعِيذُكَ بِاللهِ، فَرَحَلَتْ بَعِيرًا لَهَا فَجَعَلَتْنِي – وَقَالَ يَزِيدُ: فَحَمَلَتْنِي- عَلَى الرَّحْلِ، وَرَكِبَتْ خَلْفِي حَتَّى بَلَغْنَا إِلَى أُمِّي. فَقَالَتْ: أَوْ أديت أَمَانَتِي وَذِمَّتِي؟ وَحَدَّثَتْهَا بِالَّذِي لَقِيتُ. فَلَمْ يرُعْها ذَلِكَ. فَقَالَتْ: إِنِّي رَأَيْتُ خَرَجَ مِنِّي نُورٌ أَضَاءَتْ مِنْهُ قُصُورُ الشَّامِ."],"takhrij":"حسن: رواه أحمد (17648) عن حيوة ويزيد بن عبد ربه، قالا: حدثنا بقية، حدثني بحير بن سعد، عن خالد بن معدان عن ابن عمرو السلمي، عن عتبة بن عبد السلمي فذكره. ورواه الطبراني في الكبير (17/131) من هذا الوجه إلا أنه لم يسق لفظ الحديث.","grade":"حسن","chapter_ar":"المعجزات التي ظهرت عند ولادة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17648) and authenticated by al-Ḥākim (2/616–617).","chapter_en":"Miracles That Appeared Around the Birth of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":1,"content":{"translation":{"en":["ʿUtbah ibn ʿAbd al-Sulamī related that a man asked the Messenger of Allah ﷺ, “How did your story first begin, O Messenger of Allah?” He replied: “My nurse belonged to Banū Saʿd ibn Bakr. Her son and I went out among some young sheep belonging to us, but we took no provisions with us. I said, ‘My brother, go and bring us some provisions from our mother.’ My brother departed while I remained with the sheep. “Two white figures resembling eagles approached. One said to the other, ‘Is this he?’ He replied, ‘Yes.’ They rushed toward me, took hold of me, laid me flat upon my back, and opened my abdomen. They then removed my heart and opened it, extracting two black clots from it. “One of them said to the other—as Yazīd’s narration states—‘Bring me snow-water.’ They washed my abdomen with it. He then said, ‘Bring me hail-water,’ and they washed my heart with it. He then said, ‘Bring me serenity,’ and they sprinkled it into my heart. One of them then said to the other, ‘Stitch it.’ He stitched it and sealed it with the Seal of Prophethood.” Ḥaywah’s narration states: “Stitch it.” He stitched it and was told, “Seal it with the Seal of Prophethood.” The Prophet ﷺ continued: “One of them then said to the other, ‘Place him in one pan of the scale and place one thousand members of his nation in the other.’ I could see the thousand above me and feared that some of them might fall upon me. He said, ‘If his entire nation were weighed against him, he would outweigh them.’ “They then departed and left me. I became extremely frightened, so I went to my nurse and told her what had happened to me. She feared that something might have been inflicted upon me and said, ‘I seek Allah’s protection for you.’ “She prepared her camel, placed me upon the saddle—or, according to Yazīd, carried me upon it—and rode behind me until we reached my mother. She said, ‘I have fulfilled my trust and my obligation,’ and told her what had happened to me. “This did not alarm my mother. She said, ‘When I gave birth to him, I saw a light emerge from me by which the palaces of Syria were illuminated.’”"]}},"tuhfa":{},"voc":["seerah",1616],"full":1,"dr":1,"tks":"حسن: رواه أحمد (17648). ورواه الطبراني في الكبير (17/131) من هذا الوجه إلا أنه لم يسق لفظ الحديث."},{"num":9657,"demo":false,"sanad":"","matn":["عَنْ الْعِرْبَاضِ بن سَارِيَةَ مرفوعا: إِنِّي عِنْدَ اللَّهِ لَخَاتَمُ النَّبِيِّينَ وَإِنَّ آدَمَ عَلَيْهِ السلام لَمُنْجَدِلٌ فِي طِينَتِهِ، وَسَأُنَبِّئُكُمْ بِأَوَّلِ ذَلِكَ دَعْوَةُ أَبِي إِبْرَاهِيمَ، وَبِشَارَةُ عِيسَى بِي، وَرُؤْيَا أُمِّي الَّتِي رَأَتْ، وَكَذَلِكَ أُمَّهَاتُ النَّبِيِّينَ يرين."],"takhrij":"حسن: رواه الإمام أحمد (17150) عن عبد الرحمن بن مهدي، حدثنا معاوية بن صالح، عن سعيد بن سويد الكلبي، عن عبد الله بن هلال السلمي، عن عرباض بن سارية فذكر الحديث.","grade":"حسن","chapter_ar":"المعجزات التي ظهرت عند ولادة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (17150), from ʿAbd al-Raḥmān ibn Mahdī, from Muʿāwiyah ibn Ṣāliḥ, from Saʿīd ibn Suwayd al-Kalbī, from ʿAbdullāh ibn Hilāl al-Sulamī, from al-ʿIrbāḍ ibn Sāriyah.","chapter_en":"Miracles That Appeared Around the Birth of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":1,"content":{"translation":{"en":["Al-ʿIrbāḍ ibn Sāriyah reported that the Prophet ﷺ said: “Indeed, I was recorded with Allah as the Seal of the Prophets while Adam—peace be upon him—was still lying in his clay. I shall tell you of the beginning of that: the supplication of my forefather Abraham, Jesus’s glad tidings concerning me, and the vision my mother saw. The mothers of the prophets likewise see such visions.”"]}},"tuhfa":{},"voc":["seerah",1617],"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17150)."},{"num":9658,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا مِنَ الأَنْبِيَاءِ نَبِيٌّ إِلاَّ أُعْطِيَ مَا مِثْلُهُ آمَنَ عَلَيْهِ الْبَشَرُ، وَإِنَّمَا كَانَ الَّذِي أُوتِيتُ وَحْيًا أَوْحَاهُ اللَّهُ إِلَىَّ، فَأَرْجُو أَنْ أَكُونَ أَكْثَرَهُمْ تَابِعًا يَوْمَ الْقِيَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في فضائل القرآن (4981) ومسلم في الإيمان (152) كلاهما من حديث الليث، عن سعيد بن أبي سعيد، عن أبيه أبي سعيد المقبري، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب أن القرآن من أكبر الدلائل لنبوة النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Virtues of the Qurʾān (4981) and Muslim in the Book of Faith (152), both through al-Layth, from Saʿīd ibn Abī Saʿīd, from his father Abū Saʿīd al-Maqburī, from Abū Hurayrah.","chapter_en":"The Qur’an Is Among the Greatest Proofs of the Prophet’s Prophethood ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":2,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “There was no prophet who was not given signs by which people would believe in him. What I was given was revelation that Allah revealed to me, so I hope to have the greatest number of followers on the Day of Resurrection.”"]}},"tuhfa":{},"voc":["seerah",1618],"full":1,"rep":[3,733,11819,11895,12747],"tks":"متفق عليه: رواه البخاري (4981) ومسلم (152)."},{"num":9659,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنِّي لأَعْرِفُ حَجَرًا بِمَكَّةَ كَانَ يُسَلِّمُ عَلَىَّ قَبْلَ أَنْ أُبْعَثَ، إِنِّي لأَعْرِفُهُ الآنَ."],"takhrij":"صحيح: رواه مسلم في الفضائل (2:2277) عن أبي بكر بن أبي شيبة، حدثنا يحيى بن أبي بكير، عن إبراهيم بن طهمان، حدثني سماك بن حرب، عن جابر بن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب تسليم الحجر على النبي ﷺ قبل النبوة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of Virtues (2277:2), from Abū Bakr ibn Abī Shaybah, from Yaḥyā ibn Abī Bukayr, from Ibrāhīm ibn Ṭahmān, from Simāk ibn Ḥarb, from Jābir ibn Samurah.","chapter_en":"A Stone Greeted the Prophet ﷺ Before His Prophethood","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":3,"content":{"translation":{"en":["Jābir ibn Samurah reported that the Messenger of Allah ﷺ said: “I certainly know a stone in Makkah that used to greet me before I was commissioned as a prophet. I still know it now.”"]}},"tuhfa":{},"voc":["seerah",1619],"full":1,"rep":[777,8546],"tks":"صحيح: رواه مسلم (2: 2277)."},{"num":9660,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ مَسْعُودٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: انْشَقَّ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شِقَّتَيْنِ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اشْهَدُوا."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3636) ومسلم في صفات المنافقين (43:2800) كلاهما من حديث سفيان بن عيينة، عن ابن أبي نجيح، عن مجاهد، عن أبي معمر، عن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب سؤال المشركين أن يريهم النبي ﷺ آية فأراهم انشقاق القمر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3636) and Muslim in the Book of the Characteristics of the Hypocrites (2800:43), both through Sufyān ibn ʿUyaynah, from Ibn Abī Najīḥ, from Mujāhid, from Abū Maʿmar, from ʿAbdullāh.","chapter_en":"The Polytheists Asked the Prophet ﷺ to Show Them a Sign, So He Showed Them the Splitting of the Moon","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: The moon split into two parts during the lifetime of the Messenger of Allah ﷺ, whereupon the Prophet ﷺ said: “Bear witness.”"]},"buhuth":{"en":["Al-Bukhārī (3869) and Muslim (2800:44) also narrated that ʿAbdullāh ibn Masʿūd said:","“While we were with the Messenger of Allah ﷺ at Minā, the moon split into two portions: one portion was behind the mountain and the other was on this side of it. The Messenger of Allah ﷺ then said to us, ‘Bear witness.’”"]}},"tuhfa":{},"voc":["seerah",1620],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3636) ومسلم (43: 2800)."},{"num":9661,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بن مَسْعُودٍ قَالَ: انْشَقَّ القَمَرُ وَنَحْنُ بِمَكَّةَ فَقَالَ كُفَّارُ قُرَيْشٍ مِنْ أَهْلِ مَكَّةَ: هَٰذَا سِحْرٌ سَحَرْنَا بِهِ ابْنَ أَبِي كَبْشَةَ، فَانْظُرُوا إِلَىٰ السفار يَأْتُونَكُمْ فَإِنْ أَخْبَرُوكُمْ أَنَّهُمْ رَأَوْا مِثْلَ مَا رَأَيْتُمْ، وَإِلَّا فَقَدْ كَذَبْتُمْ قَالَ: فَمَا جَاءَهُمْ أَحَدٌ مِنْ وَجْهٍ مِنَ الْوُجُوهِ إِلَّا أَخْبَرَهُمْ أَنَّهُمْ رَأَوْا مِثْلَ مَا رَأَوْا."],"takhrij":"صحيح: رواه أبو داود الطيالسي (293) والبزار (1971) والشاشي في مسنده (404) – واللفظ له – والبيهقي في الدلائل (2/266) كلهم من طريق المغيرة (هو ابن مقسم الضبي) عن أبي الضحى (واسمه: مسلم بن صبيح) عن مسروق، عن عبد الله فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب سؤال المشركين أن يريهم النبي ﷺ آية فأراهم انشقاق القمر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd al-Ṭayālisī (293), al-Bazzār (1971), al-Shāshī in his Musnad (404), whose wording this is, and al-Bayhaqī in Al-Dalā’il (2/266), all through al-Mughīrah ibn Miqsam al-Ḍabbī, from Abū al-Ḍuḥā Muslim ibn Ṣubayḥ, from Masrūq, from ʿAbdullāh. Its chain is authentic.","chapter_en":"The Polytheists Asked the Prophet ﷺ to Show Them a Sign, So He Showed Them the Splitting of the Moon","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":4,"content":{"translation":{"en":["Ibn Masʿūd said: The moon split while we were in Makkah. The disbelievers of Quraysh among the people of Makkah said, “This is magic with which the son of Abū Kabshah has bewitched us. Wait for the travelers who come to you. If they report that they saw what you saw, then it is true; otherwise, he has deceived you.” No traveler came to them from any direction without reporting that they had seen the same thing."]}},"tuhfa":{},"voc":["seerah",1621],"full":1,"dr":1,"rep":[13450],"tks":"صحيح: رواه أبو داود الطيالسي (293)، والبزار (1971)، والشاشي في مسنده (404) - واللفظ له -، والبيهقي في الدلائل (2/266). وإسناده صحيح."},{"num":9662,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ ـ رَضِيَ اللَّهُ عَنْهُ أَنَّ أَهْلَ، مَكَّةَ سَأَلُوا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُرِيَهُمْ آيَةً، فَأَرَاهُمُ الْقَمَرَ شِقَّتَيْنِ، حَتَّى رَأَوْا حِرَاءً بَيْنَهُمَا."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3868) ومسلم في صفات المنافقين (46:2802) كلاهما من حديث قتادة، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب سؤال المشركين أن يريهم النبي ﷺ آية فأراهم انشقاق القمر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3868) and Muslim in the Book of the Characteristics of the Hypocrites (2802:46), both through Qatādah, from Anas ibn Mālik.","chapter_en":"The Polytheists Asked the Prophet ﷺ to Show Them a Sign, So He Showed Them the Splitting of the Moon","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik related that the people of Makkah asked the Messenger of Allah ﷺ to show them a sign. He therefore showed them the moon split into two parts, until they could see Mount Ḥirāʾ between them."]}},"tuhfa":{},"voc":["seerah",1622],"full":1,"dr":1,"rep":[13448],"tks":"متفق عليه: رواه البخاري (3868)، ومسلم (46: 2802)."},{"num":9663,"demo":false,"sanad":"","matn":["عن عَبْدِ اللَّهِ بن عَبَّاسٍ مَسْعُودٍ، عَنِ ابْنِ عَبَّاسٍ ـ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ الْقَمَرَ، انْشَقَّ فِي زَمَانِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3870) ومسلم في صفات المنافقين (48:2803) من حديث بكر بن جعفر، عن جعفر بن ربيعة، عن عراك بن مالك، عن عبيدالله بن عبد الله بن مسعود، عن ابن عباس فذكر مثله.","grade":"متفق عليه","chapter_ar":"باب سؤال المشركين أن يريهم النبي ﷺ آية فأراهم انشقاق القمر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3870) and Muslim in the Book of the Characteristics of the Hypocrites (2803:48), through Bakr ibn Jaʿfar, from Jaʿfar ibn Rabīʿah, from ʿIrāk ibn Mālik, from ʿUbaydullāh ibn ʿAbdullāh ibn Masʿūd, from Ibn ʿAbbās.","chapter_en":"The Polytheists Asked the Prophet ﷺ to Show Them a Sign, So He Showed Them the Splitting of the Moon","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the moon split during the time of the Prophet ﷺ."]}},"tuhfa":{},"voc":["seerah",1623],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3870)، ومسلم (48: 2803)، من حديث بكر بن جعفر، عن جعفر بن ربيعة، عن عراك بن مالك، عن عبيد الله بن عبد الله بن مسعود، عن ابن عباس، فذكر مثله."},{"num":9664,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ، قَالَ: انْفَلَقَ الْقَمَرُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اشْهَدُوا."],"takhrij":"صحيح: رواه مسلم في صفة القيامة (2801) ولم يسق لفظه – والترمذي (2182) واللفظ له – كلاهما من طريق شعبة، عن الأعمش، عن مجاهد، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب سؤال المشركين أن يريهم النبي ﷺ آية فأراهم انشقاق القمر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in the Book of the Description of the Resurrection (2801), though he did not give its wording, and by al-Tirmidhī (2182), whose wording this is, both through Shuʿbah, from al-Aʿmash, from Mujāhid, from Ibn ʿUmar.","chapter_en":"The Polytheists Asked the Prophet ﷺ to Show Them a Sign, So He Showed Them the Splitting of the Moon","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":4,"content":{"translation":{"en":["ʿAbdullāh ibn ʿUmar said: The moon split during the lifetime of the Messenger of Allah ﷺ, whereupon the Messenger of Allah ﷺ said: “Bear witness.”"]}},"tuhfa":{},"voc":["seerah",1624],"full":1,"dr":1,"rep":[13451],"tks":"صحيح: رواه مسلم (2801) ولم يسق لفظه، والترمذي (2182) - واللفظ له."},{"num":9665,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عَبْدِ اللَّهِ قَالَ– فِي حَدِيثِهِ الطويل -: سِرْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى نَزَلْنَا وَادِيًا أَفْيَحَ، فَذَهَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْضِي حَاجَتَهُ، فَاتَّبَعْتُهُ بِإِدَاوَةٍ مِنْ مَاءٍ، فَنَظَرَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ يَرَ شَيْئًا يَسْتَتِرُ بِهِ، فَإِذَا شَجَرَتَانِ بِشَاطِئِ الْوَادِي، فَانْطَلَقَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى إِحْدَاهُمَا فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ: انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ فَانْقَادَتْ مَعَهُ كَالْبَعِيرِ الْمَخْشُوشِ، الَّذِي يُصَانِعُ قَائِدَهُ، حَتَّى أَتَى الشَّجَرَةَ الْأُخْرَى، فَأَخَذَ بِغُصْنٍ مِنْ أَغْصَانِهَا، فَقَالَ:\" انْقَادِي عَلَيَّ بِإِذْنِ اللَّهِ \" فَانْقَادَتْ مَعَهُ كَذَلِكَ، حَتَّى إِذَا كَانَ بِالْمَنْصَفِ مِمَّا بَيْنَهُمَا، لَأَمَ بَيْنَهُمَا (يَعْنِي جَمَعَهُمَا) فَقَالَ: الْتَئِمَا عَلَيَّ بِإِذْنِ اللَّهِ فَالْتَأَمَتَا، قَالَ جَابِرٌ: فَخَرَجْتُ أُحْضِرُ مَخَافَةَ أَنْ يحش رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِقُرْبِي فَيَبْتَعِدَ (وَقَالَ مُحَمَّدُ بْنُ عَبَّادٍ: فَيَتَبَعَّدَ) فَجَلَسْتُ أُحَدِّثُ نَفْسِي، فَحَانَتْ مِنِّي لَفْتَةٌ، فَإِذَا أَنَا بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مُقْبِلًا، وَإِذَا الشَّجَرَتَانِ قَدِ افْتَرَقَتَا، فَقَامَتْ كُلُّ وَاحِدَةٍ مِنْهُمَا عَلَى سَاقٍ، فَرَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَفَ وَقْفَةً، فَقَالَ: بِرَأْسِهِ هَكَذَا (وَأَشَارَ أَبُو إِسْمَاعِيلَ بِرَأْسِهِ يَمِينًا وَشِمَالًا) ثُمَّ أَقْبَلَ، فَلَمَّا انْتَهَى إِلَيَّ قَالَ: يَا جَابِرُ! هَلْ رَأَيْتَ مَقَامِي؟ قُلْتُ: نَعَمْ، يَا رَسُولَ اللَّهِ ! قَالَ: فَانْطَلِقْ إِلَى الشَّجَرَتَيْنِ فَاقْطَعْ مِنْ كُلِّ وَاحِدَةٍ مِنْهُمَا غُصْنًا، فَأَقْبِلْ بِهِمَا، حَتَّى إِذَا قُمْتَ مَقَامِي فَأَرْسِلْ غُصْنًا عَنْ يَمِينِكَ وَغُصْنًا عَنْ يَسَارِكَ.","قَالَ جَابِرٌ: فَقُمْتُ فَأَخَذْتُ حَجَرًا فَكَسَرْتُهُ وَحَسَرْتُهُ، فَانْذَلَقَ لِي، فَأَتَيْتُ الشَّجَرَتَيْنِ فَقَطَعْتُ مِنْ كُلِّ وَاحِدَةٍ مِنْهُمَا غُصْنًا، ثُمَّ أَقْبَلْتُ أَجُرُّهُمَا حَتَّى قُمْتُ مَقَامَ رَسُولِ اللهِ صلى الله عليه وسلم، أَرْسَلْتُ غُصْنًا عَنْ يَمِينِي وَغُصْنًا عَنْ يَسَارِي، ثُمَّ لَحِقْتُهُ فَقُلْتُ: قَدْ فَعَلْتُ، يَا رَسُولَ اللهِ! فَعَمَّ ذَاكَ؟ قَالَ: إِنِّي مَرَرْتُ بِقَبْرَيْنِ يُعَذَّبَانِ، فَأَحْبَبْتُ بِشَفَاعَتِي أَنْ يُرَفَّهَ عَنْهُمَا مَا دَامَ الْغُصْنَانِ رَطْبَيْنِ... الحديث."],"takhrij":"صحيح: رواه مسلم في الزهد (3012: 74) من طرق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حزرة، عن عبادة بن الوليد بن عبادة بن الصامت قال: خرجت أنا وأبي نطلب العلم حتى أتينا جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب انقياد الشجرتين لرسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3012).","chapter_en":"Two Trees Obeyed the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":5,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported in the course of his lengthy hadith: We traveled with the Messenger of Allah ﷺ until we stopped in a wide valley. The Messenger of Allah ﷺ went to relieve himself, and I followed him carrying a vessel of water. He looked around but saw nothing with which he could conceal himself. There were two trees at the edge of the valley. The Messenger of Allah ﷺ went to one of them, took hold of one of its branches, and said: “Come under my command by Allah’s permission.” It came along with him like a haltered camel that complies with its handler. He then went to the other tree, took hold of one of its branches, and said: “Come under my command by Allah’s permission.” It came along with him likewise. When he reached the midpoint between them, he brought them together and said: “Join together over me by Allah’s permission.” So they joined together. Jābir said: I hurried away out of fear that the Messenger of Allah ﷺ might sense that I was nearby and move farther away—Muḥammad ibn ʿAbbād said: “distance himself farther.” I sat speaking to myself, then happened to glance around and saw the Messenger of Allah ﷺ approaching. The two trees had separated, and each had returned to stand upon its own trunk. I saw the Messenger of Allah ﷺ stop briefly and move his head like this—Abū Ismāʿīl gestured by moving his head right and left—then he came toward me. When he reached me, he said: “O Jābir, did you see the place where I stood?” I replied: “Yes, O Messenger of Allah.” He said: “Go to the two trees, cut a branch from each of them, and bring them back. When you reach the place where I stood, put one branch on your right and the other on your left.” Jābir said: I got up, took a stone, broke and sharpened it until it became sharp, then went to the two trees and cut a branch from each. I dragged them back until I reached the place where the Messenger of Allah ﷺ had stood, and I placed one branch on my right and the other on my left.","Then I caught up with him and said: “I have done it, O Messenger of Allah. Why did you tell me to do that?” He said: “I passed by two graves whose occupants were being punished, and I wished, through my intercession, that their punishment might be lightened for as long as the two branches remain fresh”… the remainder of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3012)."},{"num":9666,"demo":false,"sanad":"","matn":["عَنْ يَعْلَى بْنِ مُرَّةَ، قَالَ: لَقَدْ رَأَيْتُ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلَاثًا، مَا رَآهَا أَحَدٌ قَبْلِي، وَلَا يَرَاهَا أَحَدٌ بَعْدِي، لَقَدْ خَرَجْتُ مَعَهُ فِي سَفَرٍ حَتَّى إِذَا كُنَّا بِبَعْضِ الطَّرِيقِ مَرَرْنَا بِامْرَأَةٍ جَالِسَةٍ، مَعَهَا صَبِيٌّ لَهَا، فَقَالَتْ: يَا رَسُولَ اللَّهِ، هَذَا صَبِيٌّ، أَصَابَهُ بَلَاءٌ، وَأَصَابَنَا مِنْهُ بَلَاءٌ، يُؤْخَذُ فِي الْيَوْمِ، مَا أَدْرِي كَمْ مَرَّةً، قَالَ: نَاوِلِينِيهِ فَرَفَعَتْهُ إِلَيْهِ، فَجَعَلتْهُ بَيْنَهُ وَبَيْنَ وَاسِطَةِ الرَّحْلِ، ثُمَّ فَغَرَ فَاهُ، فَنَفَثَ فِيهِ ثَلَاثًا، وَقَالَ: بِسْمِ اللَّهِ، أَنَا عَبْدُ اللَّهِ، اخْسَأْ عَدُوَّ اللَّهِ ثُمَّ نَاوَلَهَا إِيَّاهُ، فَقَالَ: الْقَيْنَا فِي الرَّجْعَةِ فِي هَذَا الْمَكَانِ، فَأَخْبِرِينَا مَا فَعَلَ قَالَ: فَذَهَبْنَا وَرَجَعْنَا، فَوَجَدْنَاهَا فِي ذَلِكَ الْمَكَانِ، مَعَهَا شِيَاهٌ ثَلَاثٌ، فَقَالَ: مَا فَعَلَ صَبِيُّكِ؟ فَقَالَتْ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، مَا حَسَسْنَا مِنْهُ شَيْئًا حَتَّى السَّاعَةِ، فَاجْتَرِرْ هَذِهِ الْغَنَمَ. قَالَ: انْزِلْ فَخُذْ مِنْهَا وَاحِدَةً، وَرُدَّ الْبَقِيَّةَ قَالَ: وَخَرَجْنَا ذَاتَ يَوْمٍ إِلَى الْجَبَّانَةِ، حَتَّى إِذَا بَرَزْنَا قَالَ: انْظُرْ وَيْحَكَ، هَلْ تَرَى مِنْ شَيْءٍ يُوَارِينِي؟ قُلْتُ: مَا أَرَى شَيْئًا يُوَارِيكَ إِلَّا شَجَرَةً مَا أُرَاهَا تُوَارِيكَ. قَالَ: فَمَا قُرْبُهَا؟ قُلْتُ: شَجَرَةٌ مِثْلُهَا، أَوْ قَرِيبٌ مِنْهَا. قَالَ: فَاذْهَبْ إِلَيْهِمَا، فَقُلْ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمَا أَنْ تَجْتَمِعَا بِإِذْنِ اللَّهِ قَالَ: فَاجْتَمَعَتَا، فَبَرَزَ لِحَاجَتِهِ، ثُمَّ رَجَعَ، فَقَالَ: اذْهَبْ إِلَيْهِمَا، فَقُلْ لَهُمَا: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَأْمُرُكُمَا أَنْ تَرْجِعَ كُلُّ وَاحِدَةٍ مِنْكُمَا إِلَى مَكَانِهَا قَالَ: وَكُنْتُ مَعَهُ جَالِسًا ذَاتَ يَوْمٍ إِذْ جَاءَ جَمَلٌ يُخَبِّبُ، حَتَّى ضَرَبَ بِجِرَانِهِ بَيْنَ يَدَيْهِ، ثُمَّ ذَرَفَتْ عَيْنَاهُ، فَقَالَ: وَيْحَكَ، انْظُرْ لِمَنْ هَذَا الْجَمَلُ، إِنَّ لَهُ لَشَأْنًا قَالَ: فَخَرَجْتُ أَلْتَمِسُ صَاحِبَهُ، فَوَجَدْتُهُ لِرَجُلٍ مِنَ الْأَنْصَارِ، فَدَعَوْتُهُ إِلَيْهِ، فَقَالَ: مَا شَأْنُ جَمَلِكَ هَذَا؟ فَقَالَ: وَمَا شَأْنُهُ؟ قَالَ: لَا أَدْرِي وَاللهِ مَا شَأْنُهُ، عَمِلْنَا عَلَيْهِ، وَنَضَحْنَا عَلَيْهِ، حَتَّى عَجَزَ عَنِ السِّقَايَةِ، فَأْتَمَرْنَا الْبَارِحَةَ أَنْ نَنْحَرَهُ، وَنُقَسِّمَ لَحْمَهُ. قَالَ: فَلَا تَفْعَلْ، هَبْهُ لِي، أَوْ بِعْنِيهِ فَقَالَ: بَلْ هُوَ لَكَ يَا رَسُولَ اللَّهِ. قَالَ: فَوَسَمَهُ بِسِمَةِ الصَّدَقَةِ، ثُمَّ بَعَثَ بِهِ."],"takhrij":"حسن: رواه أحمد (17548) عن عبد الله بن نمير، عن عثمان بن حكيم، قال: أخبرني عبد الرحمن بن عبد العزيز، عن يعلى بن مرة، قال: فذكره.","grade":"حسن","chapter_ar":"باب انقياد الشجرتين لرسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (17548), from ʿAbdullāh ibn Numayr, from ʿUthmān ibn Ḥakīm, from ʿAbd al-Raḥmān ibn ʿAbd al-ʿAzīz, from Yaʿlā ibn Murrah.","chapter_en":"Two Trees Obeyed the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":5,"content":{"translation":{"en":["Yaʿlā ibn Murrah said: I witnessed three things from the Messenger of Allah ﷺ that no one before me had witnessed and no one after me would witness. I once traveled with him. While we were on part of the road, we passed a seated woman who had a young boy with her. She said, “O Messenger of Allah, this boy has been afflicted by a disorder, and we have suffered greatly because of it. He is seized by it I do not know how many times each day.” He said: “Hand him to me.” She lifted the boy to him, and he placed him between himself and the middle of the saddle. He then opened the boy’s mouth, blew lightly into it three times and said: “In the name of Allah. I am the servant of Allah. Be driven away, enemy of Allah!” He then returned the boy to her and said: “Meet us at this place on our return and tell us what happened to him.” We continued our journey and later returned. We found the woman at the same place with three sheep. He asked: “What happened to your boy?” She replied, “By the One Who sent you with the truth, we have not noticed anything affecting him up to this very moment. Take these sheep.” He said: “Dismount, take one of them, and return the others.” Yaʿlā continued: One day, I went with him toward the open land. When we had gone out into the open, he said: “Look around—may Allah rectify you—and see whether there is anything that can conceal me.” I replied, “I see nothing that could conceal you except a tree, but I do not think it can fully hide you.” He asked: “What is near it?” I replied, “Another tree like it, or close to its size.” He said: “Go to the two trees and tell them: ‘The Messenger of Allah ﷺ commands you both to come together by Allah’s permission.’” The two trees came together, and he went behind them to relieve himself. When he returned, he said: “Go to them and say: ‘The Messenger of Allah ﷺ commands each of you to return to its place.’” They both returned to their places. Yaʿlā continued: One day, while I was sitting with him, a camel came trotting toward him. It lowered the underside of its neck before him, and then its eyes began to shed tears. He said: “Go and see to whom this camel belongs, for it has a matter of concern.” I went out searching for its owner and discovered that it belonged to a man from the Anṣār. I summoned him to the Prophet ﷺ, who asked: “What is the matter with this camel of yours?” The man asked, “What is wrong with it?” He replied, “By Allah, I do not know what its problem is. We used it for work and for drawing water until it became unable to continue providing water. Last night we consulted one another and decided to slaughter it and divide its meat.” The Prophet ﷺ said: “Do not do that. Give it to me as a gift or sell it to me.” The man replied, “Rather, it is yours, O Messenger of Allah.” The Prophet ﷺ marked it with the mark used for animals given in charity and then sent it away."]}},"tuhfa":{},"voc":["seerah",1626],"full":1,"dr":1,"tks":"حسن: رواه أحمد (17548) عن عبد الله بن نمير، عن عثمان بن حكيم، قال: أخبرني عبد الرحمن بن عبد العزيز، عن يعلى بن مرة، قال: فذكره."},{"num":9667,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: جَاءَ أَعْرَابِيٌّ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: بِمَ أَعْرِفُ أَنَّكَ نَبِيٌّ؟ قَالَ: إِنْ دَعَوْتُ هَذَا الْعِذْقَ مِنْ هَذِهِ النَّخْلَةِ أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ. فَدَعَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ يَنْزِلُ مِنَ النَّخْلَةِ حَتَّى سَقَطَ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثُمَّ قَالَ: ارْجِعْ. فَعَادَ، فَأَسْلَمَ الأَعْرَابِيُّ."],"takhrij":"صحيح: رواه الترمذي (3628) واللفظ له – وأحمد (1954) وصححه ابن حبان (6523) والحاكم (4237) كلهم من طرق عن أبي ظبيان (واسمه: حصين بن جندب البجلي) عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب انقياد الشجرتين لرسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Tirmidhī (3628), whose wording this is, Aḥmad (1954), Ibn Ḥibbān (6523), who authenticated it, and al-Ḥākim (4237), through routes from Abū Ẓabyān Ḥuṣayn ibn Jundab al-Bajalī, from Ibn ʿAbbās.","chapter_en":"Two Trees Obeyed the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":5,"content":{"translation":{"en":["Ibn ʿAbbās said: A Bedouin came to the Messenger of Allah ﷺ and asked, “How can I know that you are a prophet?” He replied: “If I call this cluster of dates from this palm tree, and it testifies that I am the Messenger of Allah, will you believe?” The man replied, “Yes.” The Messenger of Allah ﷺ called it, and it began descending from the palm tree until it fell before the Prophet ﷺ. He then said: “Return.” It returned to its place, whereupon the Bedouin embraced Islam."]}},"tuhfa":{},"voc":["seerah",1627],"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3628) - واللفظ له -، وأحمد (1954)، وصححه ابن حبان (6523)، والحاكم (4237)."},{"num":9668,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ: جَاءَ جِبْرِيلُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ذَاتَ يَوْمٍ، وَهُوَ جَالِسٌ حَزِينًا، قَدْ خُضِبَ بِالدِّمَاءِ، ضَرَبَهُ بَعْضُ أَهْلِ مَكَّةَ، قَالَ: فَقَالَ لَهُ: مَا لَكَ؟ قَالَ: فَقَالَ لَهُ: فَعَلَ بِي هَؤُلَاءِ وَفَعَلُوا، قَالَ: فَقَالَ لَهُ جِبْرِيلُ عَلَيْهِ السلام: أَتُحِبُّ أَنْ أُرِيَكَ آيَةً؟ قَالَ: نَعَمْ، قَالَ: فَنَظَرَ إِلَى شَجَرَةٍ مِنْ وَرَاءِ الْوَادِي، فَقَالَ: ادْعُ بِتِلْكَ الشَّجَرَةِ، فَدَعَاهَا، فَجَاءَتْ تَمْشِي، حَتَّى قَامَتْ بَيْنَ يَدَيْهِ، فَقَالَ: مُرْهَا فَلْتَرْجِعْ، فَأَمَرَهَا فَرَجَعَتْ إِلَى مَكَانِهَا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: حَسْبِي."],"takhrij":"حسن: رواه ابن ماجة (4208) وأحمد (12112) والدارمي (23) كلهم من طريق أبي معاوية، عن الأعمش، عن أبي سفيان (هو: طلحة بن نافع) عن أنس بن مالك فذكره.","grade":"حسن","chapter_ar":"باب انقياد الشجرتين لرسول الله ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (4208), Aḥmad (12112), and al-Dārimī (23), all through Abū Muʿāwiyah, from al-Aʿmash, from Abū Sufyān Ṭalḥah ibn Nāfiʿ, from Anas ibn Mālik.","chapter_en":"Two Trees Obeyed the Messenger of Allah ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":5,"content":{"translation":{"en":["Anas ibn Mālik said: Gabriel came to the Prophet ﷺ one day while he was sitting sorrowfully, stained with blood after some of the people of Makkah had struck him. Gabriel asked him, “What has happened to you?” He replied: “These people did such and such to me.” Gabriel—peace be upon him—asked, “Would you like me to show you a sign?” He replied: “Yes.” Gabriel looked toward a tree on the other side of the valley and said, “Call that tree.” The Prophet ﷺ called it, and it came walking until it stood before him. Gabriel said, “Command it to return.” He commanded it, and it returned to its place. The Messenger of Allah ﷺ then said: “That is sufficient for me.”"]}},"tuhfa":{},"voc":["seerah",1628],"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (4208)، وأحمد (12112)، والدارمي (23)."},{"num":9669,"demo":false,"sanad":"","matn":["عَنْ عِمْرَانَ، قَالَ: كُنَّا فِي سَفَرٍ مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَإِنَّا أَسْرَيْنَا، حَتَّى كُنَّا فِي آخِرِ اللَّيْلِ، وَقَعْنَا وَقْعَةً، وَلاَ وَقْعَةَ أَحْلَى عِنْدَ الْمُسَافِرِ مِنْهَا، فَمَا أَيْقَظَنَا إِلاَّ حَرُّ الشَّمْسِ، وَكَانَ أَوَّلَ مَنِ اسْتَيْقَظَ فُلاَنٌ ثُمَّ فُلاَنٌ ثُمَّ فُلاَنٌ ـ يُسَمِّيهِمْ أَبُو رَجَاءٍ فَنَسِيَ عَوْفٌ ـ ثُمَّ عُمَرُ بْنُ الْخَطَّابِ الرَّابِعُ، وَكَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذَا نَامَ لَمْ يُوقَظْ حَتَّى يَكُونَ هُوَ يَسْتَيْقِظُ، لأَنَّا لاَ نَدْرِي مَا يَحْدُثُ لَهُ فِي نَوْمِهِ، فَلَمَّا اسْتَيْقَظَ عُمَرُ، وَرَأَى مَا أَصَابَ النَّاسَ، وَكَانَ رَجُلاً جَلِيدًا، فَكَبَّرَ وَرَفَعَ صَوْتَهُ بِالتَّكْبِيرِ، فَمَا زَالَ يُكَبِّرُ وَيَرْفَعُ صَوْتَهُ بِالتَّكْبِيرِ، حَتَّى اسْتَيْقَظَ لِصَوْتِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا اسْتَيْقَظَ شَكَوْا إِلَيْهِ الَّذِي أَصَابَهُمْ، قَالَ: لاَ ضَيْرَ ـ أَوْ لاَ يَضِيرُ، ـ ارْتَحِلُوا. فَارْتَحَلَ فَسَارَ غَيْرَ بَعِيدٍ، ثُمَّ نَزَلَ، فَدَعَا بِالْوَضُوءِ، فَتَوَضَّأَ، وَنُودِيَ بِالصَّلاَةِ فَصَلَّى بِالنَّاسِ، فَلَمَّا انْفَتَلَ مِنْ صَلاَتِهِ، إِذَا هُوَ بِرَجُلٍ مُعْتَزِلٍ لَمْ يُصَلِّ مَعَ الْقَوْمِ، قَالَ: مَا مَنَعَكَ يَا فُلاَنُ أَنْ تُصَلِّيَ مَعَ الْقَوْمِ. قَالَ: أَصَابَتْنِي جَنَابَةٌ وَلاَ مَاءَ. قَالَ: عَلَيْكَ بِالصَّعِيدِ، فَإِنَّهُ يَكْفِيكَ. ثُمَّ سَارَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَاشْتَكَى إِلَيْهِ النَّاسُ مِنَ الْعَطَشِ، فَنَزَلَ، فَدَعَا فُلاَنًا ـ كَانَ يُسَمِّيهِ أَبُو رَجَاءٍ نَسِيَهُ عَوْفٌ ـ وَدَعَا عَلِيًّا فَقَالَ: اذْهَبَا فَابْتَغِيَا الْمَاءَ. فَانْطَلَقَا، فَتَلَقَّيَا امْرَأَةً بَيْنَ مَزَادَتَيْنِ، ـ أَوْ سَطِيحَتَيْنِ ـ مِنْ مَاءٍ عَلَى بَعِيرٍ لَهَا، فَقَالاَ لَهَا: أَيْنَ الْمَاءُ؟ قَالَتْ: عَهْدِي بِالْمَاءِ أَمْسِ هَذِهِ السَّاعَةَ، وَنَفَرُنَا خُلُوفًا. قَالاَ لَهَا: انْطَلِقِي إِذًا. قَالَتْ: إِلَى أَيْنَ؟ قَالاَ: إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. قَالَتِ: الَّذِي يُقَالُ لَهُ الصَّابِئُ قَالاَ: هُوَ الَّذِي تَعْنِينَ، فَانْطَلِقِي. فَجَاءَا بِهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَدَّثَاهُ الْحَدِيثَ، قَالَ: فَاسْتَنْزَلُوهَا عَنْ بَعِيرِهَا، وَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِنَاءٍ، فَفَرَّغَ فِيهِ مِنْ أَفْوَاهِ الْمَزَادَتَيْنِ، ـ أَوِ السَّطِيحَتَيْنِ ـ وَأَوْكَأَ أَفْوَاهَهُمَا، وَأَطْلَقَ الْعَزَالِيَ، وَنُودِيَ فِي النَّاسِ: اسْقُوا وَاسْتَقُوا. فَسَقَى مَنْ شَاءَ، وَاسْتَقَى مَنْ شَاءَ، وَكَانَ آخِرَ ذَاكَ أَنْ أَعْطَى الَّذِي أَصَابَتْهُ الْجَنَابَةُ إِنَاءً مِنْ مَاءٍ، قَالَ: اذْهَبْ، فَأَفْرِغْهُ عَلَيْكَ. وَهْىَ قَائِمَةٌ تَنْظُرُ إِلَى مَا يُفْعَلُ بِمَائِهَا، وَايْمُ اللَّهِ، لَقَدْ أُقْلِعَ عَنْهَا، وَإِنَّهُ لَيُخَيَّلُ إِلَيْنَا أَنَّهَا أَشَدُّ مِلأَةً مِنْهَا حِينَ ابْتَدَأَ فِيهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اجْمَعُوا لَهَا. فَجَمَعُوا لَهَا مِنْ بَيْنِ عَجْوَةٍ وَدَقِيقَةٍ وَسَوِيقَةٍ، حَتَّى جَمَعُوا لَهَا طَعَامًا، فَجَعَلُوهَا فِي ثَوْبٍ، وَحَمَلُوهَا عَلَى بَعِيرِهَا، وَوَضَعُوا الثَّوْبَ بَيْنَ يَدَيْهَا، قَالَ لَهَا: تَعْلَمِينَ مَا رَزِئْنَا مِنْ مَائِكِ شَيْئًا، وَلَكِنَّ اللَّهَ هُوَ الَّذِي أَسْقَانَا. فَأَتَتْ أَهْلَهَا، وَقَدِ احْتَبَسَتْ عَنْهُمْ، قَالُوا: مَا حَبَسَكِ يَا فُلاَنَةُ قَالَتِ: الْعَجَبُ، لَقِيَنِي رَجُلاَنِ، فَذَهَبَا بِي إِلَى هَذَا الَّذِي يُقَالُ لَهُ الصَّابِئُ، فَفَعَلَ كَذَا وَكَذَا، فَوَاللَّهِ، إِنَّهُ لأَسْحَرُ النَّاسِ مِنْ بَيْنِ هَذِهِ وَهَذِهِ. وَقَالَتْ بِإِصْبَعَيْهَا الْوُسْطَى وَالسَّبَّابَةِ، فَرَفَعَتْهُمَا إِلَى السَّمَاءِ: ـ تَعْنِي السَّمَاءَ وَالأَرْضَ ـ أَوْ إِنَّهُ لَرَسُولُ اللَّهِ حَقًّا، فَكَانَ الْمُسْلِمُونَ بَعْدَ ذَلِكَ، يُغِيرُونَ عَلَى مَنْ حَوْلَهَا مِنَ الْمُشْرِكِينَ، وَلاَ يُصِيبُونَ الصِّرْمَ الَّذِي هِيَ مِنْهُ، فَقَالَتْ يَوْمًا لِقَوْمِهَا: مَا أُرَى أَنَّ هَؤُلاَءِ الْقَوْمَ يَدَعُونَكُمْ عَمْدًا، فَهَلْ لَكُمْ فِي الإِسْلاَمِ فَأَطَاعُوهَا فَدَخَلُوا فِي الإِسْلاَمِ."],"takhrij":"متفق عليه: رواه البخاري في التيمم (344) ومسلم في المساجد (312:682) كلاهما من حديث عوف بن أبي جميلة الأعرابي، عن أبي رجاء العطاردي، عن عمران بن الحصين فذكره. واللفظ للبخاري، ولفظ مسلم قريب منه.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Tayammum (344) and Muslim in the Book of Mosques (682:312), both through ʿAwf ibn Abī Jamīlah al-Aʿrābī, from Abū Rajāʾ al-ʿAṭāridī, from ʿImrān ibn al-Ḥuṣayn. The wording is al-Bukhārī’s; Muslim’s is similar.","chapter_en":"Reports Concerning the Miraculous Multiplication of Water","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":6,"content":{"translation":{"en":["ʿImrān reported: We were traveling with the Prophet ﷺ and continued traveling by night until its final part. We then lay down and fell into a deep sleep—and no sleep is sweeter to a traveler than that. Nothing awakened us except the heat of the sun. The first to awaken was one man, then another, then another—Abū Rajāʾ used to name them, but ʿAwf forgot their names—and the fourth was ʿUmar ibn al-Khaṭṭāb. When the Prophet ﷺ slept, he would not be awakened until he awoke by himself, because we did not know what might be occurring to him in his sleep. When ʿUmar awoke and saw what had happened to the people—and he was a strong, resolute man—he proclaimed Allah’s greatness and raised his voice. He continued saying “Allāhu akbar” in a loud voice until the Prophet ﷺ awoke. When he awoke, they complained to him about what had happened. He said: “There is no harm—or: it will cause no harm. Resume your journey.” He traveled a short distance and then stopped. He called for water for ablution and performed ablution. The call to prayer was made, and he led the people in prayer. When he finished the prayer, he saw a man sitting apart who had not prayed with the people. He asked: “What prevented you, so-and-so, from praying with the people?” The man replied, “I was in a state of major ritual impurity, and there was no water.” He said: “Use the clean earth, for it is sufficient for you.” The Prophet ﷺ then resumed the journey. The people complained to him of thirst, so he stopped and summoned a man—Abū Rajāʾ used to name him, but ʿAwf forgot his name—and also summoned ʿAlī. He told them: “Go and search for water.” They departed and encountered a woman riding a camel between two large water-skins—or two leather water containers. They asked her, “Where is the water?” She replied, “The last time I was at the water was at this hour yesterday, and the men of our household are away.” They said, “Then come with us.” She asked, “Where?” They replied, “To the Messenger of Allah ﷺ.” She asked, “The one who is called the Ṣābiʾ?” They replied, “He is the one you mean. Come with us.” They brought her to the Prophet ﷺ and told him what had happened. They helped her dismount from her camel, and the Prophet ﷺ called for a vessel. He poured some water into it from the mouths of the two water-skins—or containers—then tied their mouths and opened their lower spouts. A call was made among the people: “Give water to others and draw water for yourselves!” Everyone who wished was given water, and everyone who wished drew water. Finally, he gave the man who had been in a state of major ritual impurity a vessel of water and said: “Go and pour it over yourself.” The woman remained standing, watching what they were doing with her water. By Allah, when they stopped drawing from the water-skins, it appeared to us that they were even fuller than they had been at the beginning. The Prophet ﷺ then said: “Collect something for her.” They collected dates, flour, and roasted grain for her until they had gathered a quantity of food. They placed it in a cloth, lifted her onto her camel, and placed the bundle before her. He said to her: “You know that we have not diminished your water at all. Rather, it was Allah Who gave us water.” She returned to her people after having been delayed. They asked, “What detained you, so-and-so?” She replied, “Something astonishing! Two men met me and took me to the man called the Ṣābiʾ, and he did such and such. By Allah, either he is the greatest magician between these two”—she gestured with her middle and index fingers, raising them toward the sky, meaning between the heavens and earth—“or he truly is the Messenger of Allah.” Thereafter, the Muslims would raid the polytheistic tribes surrounding her people but would leave untouched the small community to which she belonged. One day she said to her people, “I think these people are deliberately sparing you. Would you consider accepting Islam?” They obeyed her and entered Islam."]}},"tuhfa":{},"voc":["seerah",1629],"full":1,"tks":"متفق عليه: رواه البخاري (344)، ومسلم (312: 682). واللفظ للبخاري، ولفظ مسلم قريب منه."},{"num":9670,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ قَالَ: عَطِشَ النَّاسُ يَوْمَ الحُدَيْبِيَةِ وَرَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَيْنَ يَدَيْهِ رَكْوَةٌ، فَتَوَضَّأَ مِنْهَا، ثُمَّ أَقْبَلَ النَّاسُ نَحْوَهُ فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَا لَكُمْ؟. قَالُوا: يَا رَسُولَ الله لَيْسَ عِنْدَنَا مَاءٌ نَتَوَضَّأُ بِهِ، وَلاَ نَشْرَبُ إِلاَّ مَا فِي رَكْوَتِكَ. قَالَ: فَوَضَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ فِي الرَّكْوَةِ، فَجَعَلَ المَاءُ يَفُورُ مِنْ بَيْنِ أَصَابِعِهِ كَأَمْثَالِ الْعُيُونِ، قَالَ: فَشَرِبْنَا وَتَوَضَّأْنَا. فَقُلْتُ لِجَابِرٍ: كَمْ كُنْتُمْ يَوْمَئِذٍ؟ قَالَ: لَوْ كُنَّا مِائَةَ أَلْفٍ لَكَفَانَا، كُنَّا خَمْسَ عَشْرَةَ مِائَةً."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4152) ومسلم في الإمارة (73:1856) كلاهما من طريق حصين (هو ابن عبد الرحمن) عن سالم بن أبي الجعد، عن جابر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Military Campaigns (4152) and Muslim in the Book of Leadership (1856:73), both through Ḥuṣayn ibn ʿAbd al-Raḥmān, from Sālim ibn Abī al-Jaʿd, from Jābir.","chapter_en":"Reports Concerning the Miraculous Multiplication of Water","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":6,"content":{"translation":{"en":["Jābir reported: The people became thirsty on the day of al-Ḥudaybiyah. The Messenger of Allah ﷺ had a small leather vessel before him and performed ablution from it. The people then approached him, so he asked: “What is the matter with you?” They replied, “O Messenger of Allah, we have no water with which to perform ablution or drink except what is in your vessel.” The Prophet ﷺ placed his hand in the vessel, and water began gushing from between his fingers like springs. We drank and performed ablution. I asked Jābir, “How many were you that day?” He replied, “Had we been one hundred thousand, it would have been sufficient for us. We were fifteen hundred.”"]},"buhuth":{"en":["His statement, “We were fifteen hundred,” may be reconciled with ʿAmr ibn Dīnār’s narration from Jābir, “We were fourteen hundred,” by understanding that they numbered more than fourteen hundred. Whoever reported fifteen hundred rounded the number upward, while whoever reported fourteen hundred omitted the remaining fraction.","As for ʿAbdullāh ibn Abī Awfā’s report that they were thirteen hundred, it may refer to the number known to him, while others knew of additional participants. Alternatively, the number he mentioned may have been the total when they first departed Madinah, with others joining them later. It may also refer specifically to the fighting men, while the additional number consisted of attendants, women, and children who had not yet reached puberty."]}},"tuhfa":{},"voc":["seerah",1630],"full":1,"dr":1,"rep":[8982],"tks":"متفق عليه: رواه البخاري (4152)، ومسلم (73: 1856)."},{"num":9671,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ قَالَ: تَعُدُّونَ أَنْتُمُ الْفَتْحَ فَتْحَ مَكَّةَ، وَقَدْ كَانَ فَتْحُ مَكَّةَ فَتْحًا، وَنَحْنُ نَعُدُّ الْفَتْحَ بَيْعَةَ الرُّضْوَانِ يَوْمَ الحُدَيْبِيَةِ. كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعَ عَشْرَةَ مِائَةً، وَالحُدَيْبِيَةُ بِئْرٌ فَنَزَحْنَاهَا، فَلَمْ نَتْرُكْ فِيهَا قَطْرَةً، فَبَلَغَ ذَلِكَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَتَاهَا، فَجَلَسَ عَلَى شَفِيرِهَا، ثُمَّ دَعَا بِإِنَاءٍ مِنْ مَاءٍ فَتَوَضَّأَ ثُمَّ مَضْمَضَ وَدَعَا، ثُمَّ صَبَّهُ فِيهَا فَتَرَكْنَاهَا غَيْرَ بَعِيدٍ، ثُمَّ إِنَّهَا أَصْدَرَتْنَا مَا شِئْنَا نَحْنُ وَرِكَابَنَا."],"takhrij":"صحيح: رواه البخاري في المغازي (4150) عن عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Military Campaigns (4150), from ʿUbaydullāh ibn Mūsā, from Isrāʾīl, from Abū Isḥāq, from al-Barāʾ.","chapter_en":"Reports Concerning the Miraculous Multiplication of Water","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":6,"content":{"translation":{"en":["Al-Barāʾ said: You consider the conquest to be the conquest of Makkah—and the conquest of Makkah was indeed a conquest—but we regarded the true conquest as the Pledge of al-Riḍwān on the day of al-Ḥudaybiyah. We were fourteen hundred with the Prophet ﷺ. Al-Ḥudaybiyah had a well, and we drew all its water until we did not leave a single drop in it. News of this reached the Prophet ﷺ, so he came to the well and sat at its edge. He then called for a vessel of water, performed ablution, rinsed his mouth, supplicated, and poured the water into the well. We left it for a short while, after which it supplied all the water that we and our riding animals desired."]}},"tuhfa":{},"voc":["seerah",1631],"full":1,"rep":[8966,13310],"tks":"صحيح: رواه البخاري (4150) عن عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء، قال: فذكره."},{"num":9672,"demo":false,"sanad":"","matn":["عن مُعَاذِ بن جَبَلٍ أَخْبَرَهُ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَامَ غَزْوَةِ تَبُوكَ، فَكَانَ يَجْمَعُ الصَّلَاةَ، فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، وَالْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، حَتَّى إِذَا كَانَ يَوْمًا أَخَّرَ الصَّلَاةَ، ثُمَّ خَرَجَ فَصَلَّى الظُّهْرَ وَالْعَصْرَ جَمِيعًا، ثُمَّ دَخَلَ، ثُمَّ خَرَجَ بَعْدَ ذَلِكَ، فَصَلَّى الْمَغْرِبَ وَالْعِشَاءَ جَمِيعًا، ثُمَّ قَالَ: إِنَّكُمْ سَتَأْتُونَ غَدًا، إِنْ شَاءَ اللَّهُ، عَيْنَ تَبُوكَ، وَإِنَّكُمْ لَنْ تَأْتُوهَا حَتَّى يُضْحِيَ النَّهَارُ، فَمَنْ جَاءَهَا مِنْكُمْ فَلَا يَمَسَّ مِنْ مَائِهَا شَيْئًا حَتَّى آتِيَ. فَجِئْنَاهَا وَقَدْ سَبَقَنَا إِلَيْهَا رَجُلَانِ، وَالْعَيْنُ مِثْلُ الشِّرَاكِ تَبِضُّ بِشَيْءٍ مِنْ مَاءٍ، قَالَ: فَسَأَلَهُمَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَلْ مَسَسْتُمَا مِنْ مَائِهَا شَيْئًا؟ قَالَا: نَعَمْ! فَسَبَّهُمَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَقَالَ لَهُمَا مَا شَاءَ اللَّهُ أَنْ يَقُولَ. قَالَ: ثُمَّ غَرَفُوا بِأَيْدِيهِمْ مِنَ الْعَيْنِ قَلِيلًا قَلِيلًا، حَتَّى اجْتَمَعَ فِي شَيْءٍ. قَالَ: وَغَسَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِيهِ يَدَيْهِ وَوَجْهَهُ، ثُمَّ أَعَادَهُ فِيهَا، فَجَرَتِ الْعَيْنُ بِمَاءٍ مُنْهَمِرٍ، أَوْ قَالَ غَزِيرٍ - شَكَّ أَبُو عَلِيٍّ أَيُّهُمَا قَالَ حَتَّى اسْتَقَى النَّاسُ، ثُمَّ قَالَ: يُوشِكُ يَا مُعَاذُ إِنْ طَالَتْ بِكَ حَيَاةٌ، أَنْ تَرَى مَا هَا هُنَا قَدْ مُلِئَ جِنَانًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (10:706) عن عبد الله بن عبد الرحمن الدارمي، حدثنا أبو علي الحنفي، حدثنا مالك (هو ابن أنس) عن أبي الزبير المكي، أن أبا الطفيل عامر بن واثلة أخبره أن معاذ بن جبل أخبره فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (706:10).","chapter_en":"Reports Concerning the Miraculous Multiplication of Water","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":6,"content":{"translation":{"en":["Muʿādh ibn Jabal said: We went out with the Messenger of Allah ﷺ during the campaign of Tabūk. He would combine the prayers, performing Ẓuhr and ʿAṣr together and Maghrib and ʿIshāʾ together. One day he delayed the prayer, then came out and performed Ẓuhr and ʿAṣr together. He went inside, then later emerged and performed Maghrib and ʿIshāʾ together. He then said: “Tomorrow, if Allah wills, you will reach the spring of Tabūk. You will not reach it until the morning has advanced. Whoever among you reaches it must not touch any of its water until I arrive.” When we reached it, two men had preceded us there. The spring was like a sandal strap, trickling only a small amount of water. The Messenger of Allah ﷺ asked them: “Did you touch any of its water?” They replied, “Yes.” The Prophet ﷺ rebuked them and said to them whatever Allah willed that he should say. The people then scooped small amounts of water from the spring with their hands until some had collected in a vessel. The Messenger of Allah ﷺ washed his hands and face in it and then poured it back into the spring. The spring began flowing with abundant, gushing water—Abū ʿAlī was uncertain which of the two expressions was used—until all the people drew water. He then said: “O Muʿādh, if you live a long life, you will soon see this entire place filled with gardens.”"]},"buhuth":{"en":["The word tabiḍḍ, written with the letter ḍād, means “to trickle or flow.” The word munhamir means water pouring forth forcefully and abundantly."]}},"tuhfa":{},"voc":["seerah",1632],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (10: 706)."},{"num":9673,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، أَنَّهُ قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَحَانَتْ صَلاَةُ الْعَصْرِ، فَالْتَمَسَ النَّاسُ الْوَضُوءَ فَلَمْ يَجِدُوهُ، فَأُتِيَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِوَضُوءٍ، فَوَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي ذَلِكَ الإِنَاءِ يَدَهُ، وَأَمَرَ النَّاسَ أَنْ يَتَوَضَّئُوا مِنْهُ.","قَالَ أَنَسٌ: فَرَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ تَحْتِ أَصَابِعِهِ، فَتَوَضَّأَ النَّاسُ حَتَّى تَوَضَّئُوا مِنْ عِنْدِ آخِرِهِمْ."],"takhrij":"متفق عليه: رواه مالك في الطهارة (32) والبخاري في الوضوء (169) ومسلم في الفضائل (2279) كلاهما من حديث مالك به مثله.","grade":"متفق عليه","chapter_ar":"باب نبع الماء بين أصابع النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (32), al-Bukhārī (169), and Muslim (2279).","chapter_en":"Water Sprang from Between the Fingers of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":7,"content":{"translation":{"en":["Anas ibn Mālik said: I saw the Messenger of Allah ﷺ when the time for the ʿAṣr prayer had arrived. The people searched for water with which to perform ablution but could not find any. A vessel containing a small amount of water was brought to the Messenger of Allah ﷺ. He placed his hand in the vessel and then instructed the people to perform ablution from it. Anas said: I saw the water springing from beneath his fingers. The people continued performing ablution until the very last of them had done so."]}},"tuhfa":{},"voc":["seerah",1633],"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (32)، والبخاري (169)، ومسلم (2279)."},{"num":9674,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ، قَالَ: كُنَّا نَعُدُّ الآيَاتِ بَرَكَةً، وَأَنْتُمْ تَعُدُّونَهَا تَخْوِيفًا، كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سَفَرٍ، فَقَلَّ الْمَاءُ فَقَالَ: اطْلُبُوا فَضْلَةً مِنْ مَاءٍ. فَجَاءُوا بِإِنَاءٍ فِيهِ مَاءٌ قَلِيلٌ، فَأَدْخَلَ يَدَهُ فِي الإِنَاءِ، ثُمَّ قَالَ: حَىَّ عَلَى الطَّهُورِ الْمُبَارَكِ، وَالْبَرَكَةُ مِنَ اللَّهِ فَلَقَدْ رَأَيْتُ الْمَاءَ يَنْبُعُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَلَقَدْ كُنَّا نَسْمَعُ تَسْبِيحَ الطَّعَامِ وَهْوَ يُؤْكَلُ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3579) عن محمد بن المثنى، حدثنا أبو أحمد الزبيري، حدثنا إسرائيل، عن منصور، عن إبراهيم، عن علقمة، عن عبدالله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"باب نبع الماء بين أصابع النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3579), from Muḥammad ibn al-Muthannā, from Abū Aḥmad al-Zubayrī, from Isrāʾīl, from Manṣūr, from Ibrāhīm, from ʿAlqamah, from ʿAbdullāh ibn Masʿūd.","chapter_en":"Water Sprang from Between the Fingers of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":7,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: We used to regard miraculous signs as blessings, whereas you regard them as warnings that inspire fear. We were traveling with the Messenger of Allah ﷺ when the water became scarce. He said: “Search for any remaining water.” They brought a vessel containing a small quantity of water. He placed his hand in the vessel and said: “Come to the blessed, purifying water. The blessing is from Allah.” I certainly saw water springing from between the fingers of the Messenger of Allah ﷺ. We also used to hear the food glorifying Allah while it was being eaten."]},"buhuth":{"en":["The words “during a journey” apparently refer to al-Ḥudaybiyah. A similar event also occurred during the campaign of Khaybar, as narrated by Abū Nuʿaym in Al-Dalā’il through Yaḥyā ibn Salamah ibn Kuhayl, from his father, from Ibrāhīm, through his chain of transmission.","Al-Ḥāfiẓ said in Fatḥ al-Bārī (6/591):","“This is more likely and indicates that this miracle occurred repeatedly, whether at home or during journeys.”"]}},"tuhfa":{},"voc":["seerah",1634],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (3579)."},{"num":9675,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ – فِي حَدِيثِهِ الطويل – قَالَ: فَأَتَيْنَا الْعَسْكَرَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا جَابِرُ، نَادِ بِوَضُوءٍ. فَقُلْتُ: أَلَا وَضُوءَ، أَلَا وَضُوءَ، أَلَا وَضُوءَ. قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، مَا وَجَدْتُ فِي الرَّكْبِ مِنْ قَطْرَةٍ. وَكَانَ رَجُلٌ مِنَ الْأَنْصَارِ يُبَرِّدُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَاءَ، فِي أَشْجَابٍ لَهُ، عَلَى حِمَارَةٍ مِنْ جَرِيدٍ، قَالَ: فَقَالَ لِيَ: انْطَلِقْ إِلَى فُلَانِ بْنِ فُلَانٍ الْأَنْصَارِيِّ، فَانْظُرْ هَلْ فِي أَشْجَابِهِ مِنْ شَيْءٍ. قَالَ: فَانْطَلَقْتُ إِلَيْهِ فَنَظَرْتُ فِيهَا، فَلَمْ أَجِدْ فِيهَا إِلَّا قَطْرَةً فِي عَزْلَاءِ شَجْبٍ مِنْهَا، لَوْ أَنِّي أُفْرِغُهُ لَشَرِبَهُ يَابِسُهُ. فَأَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، إِنِّي لَمْ أَجِدْ فِيهَا إِلَّا قَطْرَةً فِي عَزْلَاءِ شَجْبٍ مِنْهَا، لَوْ أَنِّي أُفْرِغُهُ لَشَرِبَهُ يَابِسُهُ. قَالَ: اذْهَبْ فَأْتِنِي بِهِ. فَأَتَيْتُهُ بِهِ، فَأَخَذَهُ بِيَدِهِ فَجَعَلَ يَتَكَلَّمُ بِشَيْءٍ لَا أَدْرِي مَا هُوَ، وَيَغْمِزُهُ بِيَدَيْهِ، ثُمَّ أَعْطَانِيهِ فَقَالَ: يَا جَابِرُ، نَادِ بِجَفْنَةٍ. فَقُلْتُ: يَا جَفْنَةَ الرَّكْبِ، فَأُتِيتُ بِهَا تُحْمَلُ، فَوَضَعْتُهَا بَيْنَ يَدَيْهِ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِيَدِهِ فِي الْجَفْنَةِ هَكَذَا، فَبَسَطَهَا وَفَرَّقَ بَيْنَ أَصَابِعِهِ، ثُمَّ وَضَعَهَا فِي قَعْرِ الْجَفْنَةِ، وَقَالَ: خُذْ، يَا جَابِرُ! فَصُبَّ عَلَيَّ، وَقُلْ: بِاسْمِ اللَّهِ. فَصَبَبْتُ عَلَيْهِ وَقُلْتُ: بِاسْمِ اللَّهِ، فَرَأَيْتُ الْمَاءَ يَتَفَوَّرُ مِنْ بَيْنِ أَصَابِعِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ فَارَتِ الْجَفْنَةُ وَدَارَتْ حَتَّى امْتَلَأَتْ، فَقَالَ: يَا جَابِرُ، نَادِ مَنْ كَانَ لَهُ حَاجَةٌ بِمَاءٍ. قَالَ: فَأَتَى النَّاسُ فَاسْتَقَوْا حَتَّى رَوُوا. قَالَ: فَقُلْتُ: هَلْ بَقِيَ أَحَدٌ لَهُ حَاجَةٌ؟ فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ مِنَ الْجَفْنَةِ وَهِيَ مَلْأَى. (٣٠١٤)."],"takhrij":"صحيح: رواه مسلم في الزهد (74:3031) من طريق عن حاتم بن إسماعيل، عن يعقوب بن مجاهد أبي حزرة، عن عبادة بن الوليد بن عبادة بن الصامت، قال: خرجت أنا وأبي نطلب العلم حتى أتينا جابر بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب نبع الماء بين أصابع النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (3012).","chapter_en":"Water Sprang from Between the Fingers of the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":7,"content":{"translation":{"en":["Jābir reported in the course of his lengthy hadith: We reached the encampment, and the Messenger of Allah ﷺ said: “O Jābir, call out for water for ablution.” So I called: “Is there any water for ablution? Is there any water for ablution? Is there any water for ablution?” I then said: “O Messenger of Allah, I have not found even a single drop among the people.” There was a man from the Anṣār who used to keep water cool for the Messenger of Allah ﷺ in some leather water-skins placed upon a wooden frame. He said to me: “Go to so-and-so, the Anṣārī, and see whether there is anything in his water-skins.” I went to him and looked inside them, but found only a drop remaining in the spout of one of the water-skins; if I were to pour it out, the dry leather itself would absorb it. I came to the Messenger of Allah ﷺ and said: “O Messenger of Allah, I found only a drop in the spout of one of the water-skins. If I were to pour it out, the dry leather itself would absorb it.” He said: “Go and bring it to me.” So I brought it to him. He took it in his hand and began saying something that I could not make out while pressing it with his hands. Then he handed it to me and said: “O Jābir, call for a large basin.” I called out: “Bring the basin of the travelers!” It was brought, carried by people, and I placed it before him. The Messenger of Allah ﷺ placed his hand in the basin like this, spreading his fingers apart, then put his hand at the bottom of the basin and said: “Take it, O Jābir. Pour upon my hand and say: ‘In the name of Allah.’” So I poured upon his hand and said: “In the name of Allah.” I saw water gush forth from between the fingers of the Messenger of Allah ﷺ. Then the basin filled and overflowed until it was completely full. He said: “O Jābir, call everyone who has need of water.” The people came and drew water until they had all drunk their fill. I asked: “Is there anyone left who still needs water?” The Messenger of Allah ﷺ then lifted his hand from the basin while it was still full… the remainder of the hadith."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (3012)."},{"num":9676,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ رَضِيَ اللَّهُ عَنْهُ قَالَ: كُنَّا يَوْمَ الْحُدَيْبِيَةِ أَرْبَعَ عَشْرَةَ مِائَةً، وَالْحُدَيْبِيَةُ بِئْرٌ، فَنَزَحْنَاهَا حَتَّى لَمْ نَتْرُكْ فِيهَا قَطْرَةً، فَجَلَسَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى شَفِيرِ الْبِئْرِ، فَدَعَا بِمَاءٍ فَمَضْمَضَ وَمَجَّ فِي الْبِئْرِ، فَمَكَثْنَا غَيْرَ بَعِيدٍ، ثُمَّ اسْتَقَيْنَا حَتَّى رَوِينَا، وَرَوَتْ ـ أَوْ صَدَرَتْ ـ رَكَائِبُنَا."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3577) عن مالك بن إسماعيل، حدثنا إسرائيل، عن أبي إسحاق، عن البراء فذكره.","grade":"صحيح","chapter_ar":"باب مجّ النبي ﷺ في البئر يوم الحديبية فخرج منها الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3577).","chapter_en":"The Prophet ﷺ Rinsed His Mouth into the Well at al-Ḥudaybiyah, Whereupon Water Flowed from It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":8,"content":{"translation":{"en":["Al-Barāʾ said: We numbered fourteen hundred on the day of al-Ḥudaybiyah. Al-Ḥudaybiyah had a well, and we drew from it until we did not leave a single drop. The Prophet ﷺ sat at the edge of the well, called for some water, rinsed his mouth, and spat the water into the well. We waited only a short while and then drew water until we had drunk our fill and our riding animals had also drunk their fill—or departed fully refreshed."]}},"tuhfa":{},"voc":["seerah",1636],"full":1,"tks":"صحيح: رواه البخاري (3577)."},{"num":9677,"demo":false,"sanad":"","matn":["عَنْ سَلَمَةَ بن الأكوع قَالَ: قَدِمْنَا الْحُدَيْبِيَةَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَنَحْنُ أَرْبَعَ عشر مِائَةً. وَعَلَيْهَا خَمْسُونَ شَاةً لَا تُرْوِيهَا، قَالَ: فَقَعَدَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى جَبَا الرَّكِيَّةِ فَإِمَّا دَعَا، وَإِمَّا بسق فِيهَا، قَالَ: فَجَاشَتْ فَسَقَيْنَا وَاسْتَقَيْنَا."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1807 :132) من طرق عن عكرمة بن عمار، قال: حدثني إياس بن سلمة، قال: حدثني أبي قال: قدمنا الحديبية فذكر الحديث بطوله.","grade":"صحيح","chapter_ar":"باب مجّ النبي ﷺ في البئر يوم الحديبية فخرج منها الماء","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1807:132).","chapter_en":"The Prophet ﷺ Rinsed His Mouth into the Well at al-Ḥudaybiyah, Whereupon Water Flowed from It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":8,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We arrived at al-Ḥudaybiyah with the Messenger of Allah ﷺ, numbering fourteen hundred. Its well could not provide sufficient water even for fifty sheep. The Messenger of Allah ﷺ sat upon the raised stonework surrounding the well. He either supplicated or spat into it, whereupon the water surged forth. We gave water to our animals and drew water for ourselves."]}},"tuhfa":{},"voc":["seerah",1637],"full":1,"tks":"صحيح: رواه مسلم (1807 :132)."},{"num":9678,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ يَقُولُ: قَالَ أَبُو طَلْحَةَ لأُمِّ سُلَيْمٍ: لَقَدْ سَمِعْتُ صَوْتَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ضَعِيفًا، أَعْرِفُ فِيهِ الْجُوعَ، فَهَلْ عِنْدَكِ مِنْ شَيْءٍ ؟ قَالَتْ: نَعَمْ، فَأَخْرَجَتْ أَقْرَاصًا مِنْ شَعِيرٍ، ثُمَّ أخذت خِمَارًا لَهَا، فلفَّت الْخُبْزَ بِبَعْضِهِ، ثُمَّ دَسَّتْهُ تَحْتَ يَدِي وردتني بِبَعْضِهِ، ثُمَّ أَرْسَلَتْنِي إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، قَالَ: فَذَهَبْتُ بِهِ، فَوَجَدْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جَالِسًا فِي الْمَسْجِدِ وَمَعَهُ النَّاسُ، فَقُمْتُ عَلَيْهِمْ، فَقَالَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : آرْسَلَكَ أَبُو طَلْحَةَ؟. قَالَ: فَقُلْتُ: نَعَمْ، قَالَ: للطعام. فَقُلْتُ: نَعَمْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِمَنْ مَعَهُ: قُومُوا. قَالَ: فَانْطَلَقَ وَانْطَلَقْتُ بَيْنَ أَيْدِيهِمْ، حَتَّى جِئْتُ أَبَا طَلْحَةَ فَأَخْبَرْتُهُ، فَقَالَ أَبُو طَلْحَةَ: يَا أُمَّ سُلَيْمٍ، قَدْ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالنَّاسِ، وَلَيْسَ عِنْدَنَا مِنْ الطَّعَامِ مَا نُطْعِمُهُمْ ؟ فَقَالَتِ: اللَّهُ وَرَسُولُهُ أَعْلَمُ، قَالَ: فَانْطَلَقَ أَبُو طَلْحَةَ حَتَّى لَقِيَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَأَقْبَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَبُو طَلْحَةَ مَعَهُ حَتَّى دخلا، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : هَلُمِّي يَا أُمَّ سُلَيْمٍ، مَا عِنْدَكِ؟. فَأَتَتْ بِذَلِكَ الْخُبْزِ، فَأَمَرَ بِهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَفُتَّ، وَعَصَرَتْ أُمُّ سُلَيْمٍ عُكَّةً لَهَا فآدمته، ثُمَّ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَا شَاءَ أَنْ يَقُولَ، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ بالدخول. فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ. فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ فَأَذِنَ لَهُمْ، فَأَكَلُوا حَتَّى شَبِعُوا ثُمَّ خَرَجُوا، ثُمَّ قَالَ: ائْذَنْ لِعَشَرَةٍ حَتَّى آكُلَ الْقَوْمُ كُلُّهُمْ وَشَبِعُوا، وَالْقَوْمُ سَبْعُونَ أَوْ ثَمَانُونَ رَجُلاً."],"takhrij":"متفق عليه: رواه مالك في كتاب صفة النبي صلى الله عليه وسلم (19) عن إسحاق بن عبد الله بن أبي طلحة، أنه سمع أنس بن مالك يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Mālik (19), al-Bukhārī (3578), and Muslim (2040).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik reported: Abū Ṭalḥah said to Umm Sulaym, “I have heard the voice of the Messenger of Allah ﷺ sounding weak, and I recognize hunger in it. Do you have any food?” She replied, “Yes.” She brought out some small loaves of barley bread, took a head-covering of hers and wrapped part of it around the bread. She then concealed the bread under my arm, wrapped the remaining part of the cloth around me, and sent me to the Messenger of Allah ﷺ. I took it and found the Messenger of Allah ﷺ sitting in the mosque with other people. I stood before them, and the Messenger of Allah ﷺ asked: “Did Abū Ṭalḥah send you?” I replied, “Yes.” He asked: “Because of food?” I replied, “Yes.” The Messenger of Allah ﷺ then said to those with him: “Get up.” He set out, and I went ahead of them until I reached Abū Ṭalḥah and informed him. Abū Ṭalḥah said, “Umm Sulaym, the Messenger of Allah ﷺ has brought the people, but we do not have enough food to feed them.” She replied, “Allah and His Messenger know best.” Abū Ṭalḥah went out to meet the Messenger of Allah ﷺ. The Messenger of Allah ﷺ came accompanied by Abū Ṭalḥah, and they entered the house. He said: “Bring whatever you have, Umm Sulaym.” She brought the bread. The Messenger of Allah ﷺ ordered that it be crumbled, and Umm Sulaym squeezed clarified butter from a leather container over it to season it. The Messenger of Allah ﷺ then said whatever Allah willed him to say and instructed: “Admit ten people.” Ten were admitted, and they ate until they were satisfied and then left. He again said, “Admit ten people.” They entered, ate until they were satisfied, and departed. He continued admitting them in groups of ten until all the people had eaten their fill. They numbered seventy or eighty men."]},"buhuth":{"en":["Muslim also narrated through another chain (2040:143) that Anas ibn Mālik said:","Abū Ṭalḥah sent me to invite the Messenger of Allah ﷺ after he had prepared some food. I approached while the Messenger of Allah ﷺ was among the people. He looked at me, and I felt shy, so I said, “Accept Abū Ṭalḥah’s invitation.”","He said to the people:","“Get up.”","Abū Ṭalḥah said, “O Messenger of Allah, I prepared only a small amount specifically for you.”","The Messenger of Allah ﷺ touched the food and prayed that it be blessed. He then said:","“Admit ten of my Companions.”","He told them, “Eat,” and brought food out for them from between his fingers. They ate until they were satisfied and then departed. He said, “Admit ten more.” They ate until they were satisfied and departed.","He continued admitting ten and dismissing ten until every one of them had entered and eaten his fill. The food was then set in order, and it appeared just as it had been before they ate from it."]}},"tuhfa":{},"voc":["seerah",1638],"full":1,"dr":1,"tks":"متفق عليه: رواه مالك (19)، والبخاري (3578)، ومسلم (2040)."},{"num":9679,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  تَزَوَّجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَدَخَلَ بِأَهْلِهِ، قَالَ: فَصَنَعَتْ أُمِّي أُمُّ سُلَيْمٍ حَيْسًا، فَجَعَلَتْهُ فِي تَوْرٍ، فَقَالَتْ: يَا أَنَسُ! اذْهَبْ بِهَذَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْ: بَعَثَتْ بِهَذَا إِلَيْكَ أُمِّي، وَهِْيَ تُقْرِئُكَ السَّلَامَ، وَتَقُولُ: إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ، يَا رَسُولَ اللَّهِ. قَالَ: فَذَهَبْتُ بِهَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْتُ: إِنَّ أُمِّي تُقْرِئُكَ السَّلَامَ، وَتَقُولُ: إِنَّ هَذَا لَكَ مِنَّا قَلِيلٌ، يَا رَسُولَ اللَّهِ، فَقَالَ: ضَعْهُ، ثُمَّ قَالَ: اذْهَبْ فَادْعُ لِي فُلَانًا وَفُلَانًا وَفُلَانًا. وَمَنْ لَقِيتَ وَسَمَّى رِجَالًا، قَالَ: فَدَعَوْتُ مَنْ سَمَّى، وَمَنْ لَقِيتُ.","قَالَ: قُلْتُ لِأَنَسٍ: عَدَدَ كَمْ كَانُوا ؟ قَالَ: زُهَاءَ ثَلَاثِمِائَةٍ.","وَقَالَ لِي رَسُولُ اللهِ صلى الله عليه وسلم: يَا أَنَسُ! هَاتِ التَّوْرَ قَالَ: فَدَخَلُوا حَتَّى امْتَلَأَتِ الصُّفَّةُ وَالْحُجْرَةُ. فَقَالَ رَسُولُ اللهِ صلى الله عليه وسلم: لِيَتَحَلَّقْ عَشَرَةٌ عَشَرَةٌ وَلْيَأْكُلْ كُلُّ إِنْسَانٍ مِمَّا يَلِيهِ قَالَ: فَأَكَلُوا حَتَّى شَبِعُوا. قَالَ: فَخَرَجَتْ طَائِفَةٌ وَدَخَلَتْ طَائِفَةٌ حَتَّى أَكَلُوا كُلُّهُمْ. فَقَالَ لِي: يَا أَنَسُ! ارْفَعْ قَالَ: فَرَفَعْتُ. فَمَا أَدْرِي حِينَ وَضَعْتُ كَانَ أَكْثَرَ أَمْ حِينَ رَفَعْتُ.","قَالَ: وَجَلَسَ طَوَائِفُ مِنْهُمْ يَتَحَدَّثُونَ فِي بَيْتِ رَسُولِ اللهِ صلى الله عليه وسلم، وَرَسُولُ اللهِ صلى الله عليه وسلم جَالِسٌ، وَزَوْجَتُهُ مُوَلِّيَةٌ وَجْهَهَا إِلَى الْحَائِطِ، فَثَقُلُوا عَلَى رَسُولِ اللهِ صلى الله عليه وسلم، فَخَرَجَ رَسُولُ اللهِ صلى الله عليه وسلم، فَسَلَّمَ عَلَى نِسَائِهِ ثُمَّ رَجَعَ، فَلَمَّا رَأَوْا رَسُولَ اللهِ صلى الله عليه وسلم قَدْ رَجَعَ ظَنُّوا أَنَّهُمْ قَدْ ثَقُلُوا عَلَيْهِ.","قال: فابتدروا الباب، فخرجوا كلهم، وجاء رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حتى أرخى الستر ودخل وأنا جالس في الحجرة، فلم يلبث إلا يسيرا حتى خرج علي، وأنزلت هذه الآية، فخرج رسول الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وقرأهن على الناس: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَدْخُلُوا بُيُوتَ النَّبِيِّ إِلَّا أَنْ يُؤْذَنَ لَكُمْ إِلَى طَعَامٍ غَيْرَ نَاظِرِينَ إِنَاهُ وَلَكِنْ إِذَا دُعِيتُمْ فَادْخُلُوا فَإِذَا طَعِمْتُمْ فَانْتَشِرُوا وَلَا مُسْتَأْنِسِينَ لِحَدِيثٍ إِنَّ ذَلِكُمْ كَانَ يُؤْذِي النَّبِيَّ﴾ [الأحزاب: 53] إلى آخر الآية."],"takhrij":"صحيح: رواه مسلم في النكاح (94:1428) عن قتيبة بن سعيد حدثنا جعفر بن سليمان، عن الجعد أبي عثمان، عن أنس، فذكره بطوله وفيه قصة الحجاب.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1428:94).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Anas ibn Mālik said: The Messenger of Allah ﷺ married and consummated his marriage. My mother, Umm Sulaym, prepared ḥays—a mixture of dates, clarified butter, and dried curds—and placed it in a stone vessel. She said, “Anas, take this to the Messenger of Allah ﷺ and say: ‘My mother has sent this to you. She conveys her greetings of peace and says: This is only a small offering from us, O Messenger of Allah.’” I took it to the Messenger of Allah ﷺ and said, “My mother conveys her greetings of peace and says: ‘This is only a small offering from us, O Messenger of Allah.’” He said: “Set it down.” He then said: “Go and invite so-and-so, so-and-so, and so-and-so, as well as anyone else you meet.” He named several men. I invited those whom he named and everyone else I encountered. The narrator asked Anas, “Approximately how many were there?” He replied, “Around three hundred.” The Messenger of Allah ﷺ said to me: “O Anas, bring the vessel.” The people entered until the shaded platform and the room were filled. The Messenger of Allah ﷺ said: “Let them form circles of ten, and let each person eat from what is directly before him.”","They ate until they were satisfied. One group departed and another entered until everyone had eaten. He then said to me: “O Anas, remove it.” I removed the vessel, but I could not tell whether it had contained more food when I first set it down or when I lifted it afterward. Some groups remained sitting and conversing in the house of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ was seated, while his wife had turned her face toward the wall. Their prolonged stay became burdensome for the Messenger of Allah ﷺ, so he went out, greeted his other wives, and then returned.","When they saw that the Messenger of Allah ﷺ had returned, they realized that their presence had become burdensome to him. They hurried toward the door, and all of them departed. The Messenger of Allah ﷺ came, lowered the curtain and entered, while I remained seated in the room. A short while later, he came out to me after this verse had been revealed. The Messenger of Allah ﷺ went out and recited it to the people: “O you who believe, do not enter the houses of the Prophet unless permission is given to you for a meal, without waiting for its preparation. But when you are invited, then enter; and when you have eaten, disperse without remaining for conversation. Indeed, that was troubling the Prophet.” [Al-Aḥzāb: 53] The remainder of the verse follows."]},"buhuth":{"en":["Al-Bukhārī cited it in suspended form in the Book of Marriage (5163), from Anas ibn Mālik, who said:","He passed by us in the mosque of Banū Rifāʿah, and I heard him say:","“When the Prophet ﷺ passed near the home of Umm Sulaym, he would enter and greet her.”","He then said:","“The Prophet ﷺ had newly married Zaynab. Umm Sulaym said to me, ‘We should give the Messenger of Allah ﷺ a gift.’","“I replied, ‘Do so.’","“She took dates, clarified butter, and dried curds and prepared ḥays in a cooking pot. She then sent it with me to him.”","The remainder of the narration is similar."]}},"tuhfa":{},"full":1,"dr":1,"tks":"صحيح: رواه مسلم (94: 1428)."},{"num":9680,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن أَبِي بَكْرٍ رَضِيَ اللَّهُ عَنْهُمَا أَنَّ أَصْحَابَ، الصُّفَّةِ كَانُوا أُنَاسًا فُقَرَاءَ، وَأَنَّ النَّبِيَّ ـ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ مَرَّةً: مَنْ كَانَ عِنْدَهُ طَعَامُ اثْنَيْنِ فَلْيَذْهَبْ بِثَالِثٍ، وَمَنْ كَانَ عِنْدَهُ طَعَامُ أَرْبَعَةٍ فَلْيَذْهَبْ بِخَامِسٍ أَوْ سَادِسٍ. أَوْ كَمَا قَالَ، وَأَنَّ أَبَا بَكْرٍ جَاءَ بِثَلاَثَةٍ، وَانْطَلَقَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعَشَرَةٍ، وَأَبُو بَكْرٍ وَثَلاَثَةً، قَالَ: فَهْوَ أَنَا وَأَبِي وَأُمِّي، ـ وَلاَ أَدْرِي هَلْ قَالَ: امْرَأَتِي وَخَادِمِي، ـ بَيْنَ بَيْتِنَا وَبَيْنَ بَيْتِ أَبِي بَكْرٍ، وَأَنَّ أَبَا بَكْرٍ تَعَشَّى عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ لَبِثَ حَتَّى صَلَّى الْعِشَاءَ، ثُمَّ رَجَعَ فَلَبِثَ حَتَّى تَعَشَّى رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ بَعْدَ مَا مَضَى مِنَ اللَّيْلِ مَا شَاءَ اللَّهُ، قَالَتْ لَهُ امْرَأَتُهُ: مَا حَبَسَكَ عَنْ أَضْيَافِكَ أَوْ ضَيْفِكَ. قَالَ: أَوَ عَشَّيْتِهِمْ؟ قَالَتْ: أَبَوْا حَتَّى تَجِيءَ، قَدْ عَرَضُوا عَلَيْهِمْ فَغَلَبُوهُمْ، فَذَهَبْتُ فَاخْتَبَأْتُ، فَقَالَ: يَا غُنْثَرُ. فَجَدَّعَ وَسَبَّ، وَقَالَ: كُلُوا، وَقَالَ: لاَ أَطْعَمُهُ أَبَدًا. قَالَ: وَايْمُ اللَّهِ، مَا كُنَّا نَأْخُذُ مِنَ اللُّقْمَةِ إِلاَّ رَبَا مِنْ أَسْفَلِهَا أَكْثَرُ مِنْهَا حَتَّى شَبِعُوا، وَصَارَتْ أَكْثَرَ مِمَّا كَانَتْ قَبْلُ، فَنَظَرَ أَبُو بَكْرٍ: فَإِذَا شَىْءٌ أَوْ أَكْثَرُ، قَالَ لاِمْرَأَتِهِ: يَا أُخْتَ بَنِي فِرَاسٍ. قَالَتْ: لاَ وَقُرَّةِ عَيْنِي، لَهْىَ الْآنَ أَكْثَرُ مِمَّا قَبْلُ بِثَلاَثِ مَرَّاتٍ. فَأَكَلَ مِنْهَا أَبُو بَكْرٍ، وَقَالَ: إِنَّمَا كَانَ الشَّيْطَانُ، ـ يَعْنِي يَمِينَهُ، ـ ثُمَّ أَكَلَ مِنْهَا لُقْمَةً، ثُمَّ حَمَلَهَا إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَصْبَحَتْ عِنْدَهُ. وَكَانَ بَيْنَنَا وَبَيْنَ قَوْمٍ عَهْدٌ، فَمَضَى الأَجَلُ، فَتَفَرَّقْنَا اثْنَا عَشَرَ رَجُلاً، مَعَ كُلِّ رَجُلٍ مِنْهُمْ أُنَاسٌ. اللَّهُ أَعْلَمُ كَمْ مَعَ كُلِّ رَجُلٍ، غَيْرَ أَنَّهُ بَعَثَ مَعَهُمْ، قَالَ: أَكَلُوا مِنْهَا أَجْمَعُونَ. أَوْ كَمَا قَالَ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3581) ومسلم في كتاب الأشربة (2057) كلاهما من حديث معتمر بن سليمان، عن أبيه، قال: حدثنا أبو عثمان، أنه حدثه عبد الرحمن بن أبي بكر فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3581) and Muslim (2057).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Bakr reported: The Companions of al-Ṣuffah were poor people. On one occasion, the Prophet ﷺ said: “Whoever has food sufficient for two should take a third person with him, and whoever has food sufficient for four should take a fifth or a sixth.” Or he said words to that effect. The Prophet ﷺ took ten people with him, while Abū Bakr brought three. Those at our home were myself, my father, and my mother—and I do not know whether he also mentioned my wife—as well as a servant shared between our household and that of Abū Bakr. Abū Bakr ate dinner with the Prophet ﷺ and remained until the ʿIshāʾ prayer had been performed. He then stayed until the Messenger of Allah ﷺ had eaten dinner. He came home after as much of the night as Allah willed had passed. His wife asked him, “What detained you from your guests—or your guest?” He asked, “Have you not served them dinner?” She replied, “They refused to eat until you came. Food was presented to them, but they insisted on waiting for you.” I withdrew and hid. Abū Bakr exclaimed, “You foolish fellow!” He reproached and rebuked me, then told the guests, “Eat.” He also declared, “By Allah, I will never eat it.” By Allah, whenever we took a morsel from the food, more than it rose from beneath it. They ate until they were satisfied, yet the food became more abundant than it had been before. Abū Bakr looked at it and found that it was as plentiful as before—or even more so. He said to his wife, “Sister of Banū Firās!” She replied, “By the delight of my eyes, it is now three times more plentiful than it was before.” Abū Bakr ate from it and said that it had only been Satan—meaning that his oath not to eat had been prompted by Satan. He then ate a morsel from it and carried the food to the Prophet ﷺ, where it remained until morning. There was a treaty between us and another people, and its term came to an end. We divided ourselves into twelve groups, each under the leadership of a man, and Allah knows how many men accompanied each leader. The Prophet ﷺ sent them out, and all of them ate from that food—or he related words to that effect."]}},"tuhfa":{},"voc":["seerah",1640],"full":1,"tks":"متفق عليه: رواه البخاري (3581)، ومسلم (2057)."},{"num":9681,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ أَبِي بَكْرٍ قَالَ: كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ثَلاَثِينَ وَمِائَةً، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : هَلْ مَعَ أَحَدٍ مِنْكُمْ طَعَامٌ؟. فَإِذَا مَعَ رَجُلٍ صَاعٌ مِنْ طَعَامٍ أَوْ نَحْوُهُ، فَعُجِنَ، ثُمَّ جَاءَ رَجُلٌ مُشْرِكٌ مُشْعَانٌّ طَوِيلٌ، بِغَنَمٍ يَسُوقُهَا، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أبيع أَمْ عَطِيَّةً، أَوْ قَالَ: هِبَةً. قَالَ: لاَ، بَلْ بَيْعٌ، قَالَ: فَاشْتَرَى مِنْهُ شَاةً فَصُنِعَتْ، فَأَمَرَ نبي اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِسَوَادِ الْبَطْنِ يُشْوَى، وَايْمُ اللَّهِ، مَا مِنْ الثَّلاَثِينَ وَمِائَةً إِلاَّ قَدْ حَزَّ لَهُ حُزَّةً مِنْ سَوَادِ بَطْنِهَا، إِنْ كَانَ شَاهِدًا أَعْطَاهَا إِيَّاهُ، وَإِنْ كَانَ غَائِبًا خبأها لَهُ، ثُمَّ جَعَلَ فِيهَا قَصْعَتَيْنِ، فَأَكَلْنَا أَجْمَعُونَ وَشَبِعْنَا، وفضل فِي القصعتين، فحملته عَلَى الْبَعِيرِ، أَوْ كَمَا قَالَ."],"takhrij":"متفق عليه: رواه البخاري في الهبة (2618) ومسلم في الأشربة (175:2056) كلاهما من طريق المعتمر بن سليمان، عن أبيه، عن أبي عثمان، عن عبد الرحمن بن أبي بكر قال: فذكره. قوله: بسواد البطن أي: الكبد.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2618) and Muslim (2056:175).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn Abī Bakr said: We were with the Prophet ﷺ, numbering one hundred and thirty. The Prophet ﷺ asked: “Does anyone among you have any food?” One man had approximately one ṣāʿ of food, so it was kneaded. A tall polytheist with disheveled hair then came driving some sheep. The Prophet ﷺ asked him: “Are they for sale or a gift?” —or he said, “A donation?” The man replied, “No, they are for sale.” The Prophet ﷺ bought a sheep from him, and it was prepared. The Prophet of Allah ﷺ ordered that its liver be roasted. By Allah, there was not one of the one hundred and thirty people for whom he did not cut a portion of its liver. If the person was present, he gave it to him; and if he was absent, he reserved it for him. He then placed the prepared food in two large dishes. All of us ate and were satisfied, yet food remained in both dishes, so I loaded them onto the camel—or he related words to that effect."]},"buhuth":{"ar":["قوله: «مشعان» أي منتفش الشعر ومتفرقه، وقوله: «سواد البطن» هو الكبد."],"en":["The word mishʿān means that his hair was disheveled and scattered. The expression “the dark organ of the abdomen” refers to the liver."]}},"tuhfa":{},"voc":["seerah",1641],"full":1,"rep":[14351],"tks":"متفق عليه: رواه البخاري (2618)، ومسلم (175: 2056)."},{"num":9682,"demo":false,"sanad":"","matn":["عَنْ جابر بْنِ عبدالله قَالَ: لَمَّا حُفِرَ الْخَنْدَقُ رَأَيْتُ بِالنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا شَدِيدًا، فَانْكَفَأْتُ إِلَى امْرَأَتِي، فَقُلْتُ: هَلْ عِنْدَكِ شيء؟ فَإِنِّي رَأَيْتُ بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَمَصًا شَدِيدًا، فَأَخْرَجَتْ إِلَى جِرَابًا فِيهِ صَاعٌ مِنْ شَعِيرٍ، وَلَنَا بُهَيْمَةٌ دَاجِنٌ فَذَبَحْتُهَا، وَطَحَنَتِ الشَّعِيرَ، فَفَرَغَتْ إِلَى فَرَاغِي، وَقَطَّعْتُهَا فِي بُرْمَتِهَا، ثُمَّ وَلَّيْتُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَتْ: لاَ تَفْضَحْنِي بِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَبِمَنْ مَعَهُ، فَجِئْتُهُ فَسَارَرْتُهُ، فَقُلْتُ: يَا رَسُولَ اللَّهِ! إنا قَدْ ذَبَحْنَا بُهَيْمَةً لَنَا وَطَحَنَّا صَاعًا مِنْ شَعِيرٍ كَانَ عِنْدَنَا، فَتَعَالَ أَنْتَ وَنَفَرٌ مَعَكَ، فَصَاحَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَقَالَ: يَا أَهْلَ الْخَنْدَقِ إِنَّ جَابِرًا قَدْ صَنَعَ سُورًا، فحيهلا بِكُمْ. وَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لاتنزلن بُرْمَتَكُمْ، وَلاَ تَخْبِزُنَّ عجينتكم حَتَّى أَجِيءَ. فَجِئْتُ وَجَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقْدُمُ النَّاسَ حَتَّى جِئْتُ امْرَأَتِي، فَقَالَتْ: بِكَ وَبِكَ، فَقُلْتُ: قَدْ فَعَلْتُ الَّذِي قُلْتِ لِي، فَأَخْرَجَتْ لَهُ عجينتنا فَبَصَقَ فِيهَا وَبَارَكَ، ثُمَّ عَمَدَ إِلَى بُرْمَتِنَا فَبَصَقَ فِيهَا وَبَارَكَ، ثُمَّ قَالَ: ادْعُ خَابِزَةً فَلْتَخْبِزْ مَعِي، وَاقْدَحِي مِنْ بُرْمَتِكُمْ وَلاَ تُنْزِلُوهَا. وَهُمْ أَلْفٌ، فَأُقْسِمُ بِاللَّهِ لأكلوا حَتَّى تَرَكُوهُ وَانْحَرَفُوا، وَإِنَّ بُرْمَتَنَا لَتَغِطُّ كَمَا هِيَ، وَإِنَّ عَجِينَنَا – أَوْ كَمَا قَالَ الضحاك - لتخبز كَمَا هُوَ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4102) ومسلم في الأشربة (141:2039) كلاهما من حديث حنظلة بن أبي سفيان، حدثنا سعيد بن ميناء، قال: سمعت جابر بن عبدالله يقول: فذكره ولفظهما سواء.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4102) and Muslim (2039:141).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: While the trench was being dug, I noticed that the Prophet ﷺ was suffering from severe hunger. I returned to my wife and asked, “Do you have any food? I have observed severe hunger in the Messenger of Allah ﷺ.” She brought out a leather bag containing one ṣāʿ of barley. We also had a young domesticated animal, so I slaughtered it while she ground the barley. She finished grinding when I finished slaughtering, and I cut the meat and placed it in the cooking pot. I then went to the Messenger of Allah ﷺ. My wife said, “Do not embarrass me before the Messenger of Allah ﷺ and those who are with him.” I approached him privately and said, “O Messenger of Allah, we have slaughtered a young animal of ours and ground one ṣāʿ of barley that we had. Please come with a small group of people.” The Prophet ﷺ called out loudly: “People of the trench! Jābir has prepared a meal, so come along!” The Messenger of Allah ﷺ then instructed me: “Do not remove your pot from the fire, and do not bake your dough until I arrive.” I returned home, and the Messenger of Allah ﷺ came leading the people. When I reached my wife, she exclaimed, “May such-and-such happen to you!” blaming me for what I had done. I said, “I did exactly what you told me.” She brought out our dough. The Prophet ﷺ spat lightly into it and invoked blessing upon it. He then went to our cooking pot, spat lightly into it, and invoked blessing upon it. He said: “Call another woman to bake with you. Keep ladling from your pot, but do not remove it from the fire.” They numbered one thousand. I swear by Allah that they all ate until they left the food and withdrew fully satisfied. Our pot continued bubbling just as it had been, and our dough continued being baked just as it had been before."]}},"tuhfa":{},"voc":["seerah",1642],"full":1,"tks":"متفق عليه: رواه البخاري (4102)، ومسلم (141: 2039)."},{"num":9683,"demo":false,"sanad":"","matn":["عَنْ أَبِيهِ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، فَأَصَابَنَا جَهْدٌ. حَتَّى هَمَمْنَا أَنْ نَنْحَرَ بَعْضَ ظَهْرِنَا، فَأَمَرَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَمَعْنَا مَزَاوِدَنَا، فَبَسَطْنَا لَهُ نِطَعًا، فَاجْتَمَعَ زَادُ الْقَوْمِ عَلَى النِّطَعِ، قَالَ: فَتَطَاوَلْتُ لأَحْزُرَهُ كَمْ هُوَ؟ فَحَزَرْتُهُ كَرَبْضَةِ الْعَنْزِ، وَنَحْنُ أَرْبَعَ عَشْرَةَ مِائَةً، قَالَ: فَأَكَلْنَا حَتَّى شَبِعْنَا جَمِيعًا، ثُمَّ حَشَوْنَا جُرُبَنَا، فَقَالَ نَبِيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَهَلْ مِنْ وَضُوءٍ؟ قَالَ: فَجَاءَ رَجُلٌ بِإِدَاوَةٍ لَهُ، فِيهَا نُطْفَةٌ، فَأَفْرَغَهَا فِي قَدَحٍ. فَتَوَضَّأْنَا كُلُّنَا، نُدَغْفِقُهُ دَغْفَقَةً، أَرْبَعَ عَشْرَةَ مِائَةً.","قَالَ: ثُمَّ جَاءَ بَعْدَ ذَلِكَ ثَمَانِيَةٌ فَقَالُوا: هَلْ مِنْ طَهُورٍ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: فَرِغَ الْوَضُوءُ."],"takhrij":"متفق عليه: رواه مسلم في اللقطة (19:1729) عن أحمد بن يوسف الأزدي، حدثنا النضر (يعني ابن محمد اليمامي) حدثنا عكرمة (هو ابن عمار) حدثنا إياس بن سلمة، عن أبيه سلمة بن الأكوع فذكره.","grade":"متفق عليه","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by Muslim (1729:19) and al-Bukhārī (2484).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Salamah ibn al-Akwaʿ said: We went out with the Messenger of Allah ﷺ on a military expedition and suffered severe hardship, until we considered slaughtering some of our riding animals. The Prophet of Allah ﷺ instructed us to gather our provision bags. We spread out a leather mat for him, and the people’s remaining provisions were collected upon it. I stretched upward to estimate how much there was and judged it to be approximately the size of a resting goat, although we numbered fourteen hundred. We all ate until we were satisfied and then filled our provision bags. The Prophet of Allah ﷺ asked: “Is there any water for ablution?” A man brought a small leather vessel containing only a little water and poured it into a cup. All fourteen hundred of us performed ablution from it, pouring from it freely. Eight people then arrived afterward and asked, “Is there any water for purification?” The Messenger of Allah ﷺ replied: “The water for ablution has been exhausted.”"]}},"tuhfa":{},"voc":["seerah",1643],"full":1,"dr":1,"tks":"متفق عليه: رواه مسلم (19: 1729)، والبخاري (2484)."},{"num":9684,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: تُوُفِّيَ عَبْدُ اللَّهِ بْنُ عَمْرِو بْنِ حَرَامٍ، وَعَلَيْهِ دَيْنٌ، فَاسْتَعَنْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى غُرَمَائِهِ أَنْ يَضَعُوا مِنْ دَيْنِهِ، فَطَلَبَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَيْهِمْ، فَلَمْ يَفْعَلُوا، فَقَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اذْهَبْ فَصَنِّفْ تَمْرَكَ أَصْنَافًا، الْعَجْوَةَ عَلَى حِدَةٍ، وَعَذْقَ زَيْدٍ عَلَى حِدَةٍ، ثُمَّ أَرْسِلْ إِلَىَّ. فَفَعَلْتُ، ثُمَّ أَرْسَلْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَلَسَ عَلَى أَعْلاَهُ، أَوْ فِي وَسَطِهِ ثُمَّ قَالَ: كِلْ لِلْقَوْمِ. فَكِلْتُهُمْ حَتَّى أَوْفَيْتُهُمُ الَّذِي لَهُمْ، وَبَقِيَ تَمْرِي، كَأَنَّهُ لَمْ يَنْقُصْ مِنْهُ شَىْءٌ."],"takhrij":"صحيح: رواه البخاري في البيوع (2127) عن عبدان، أخبرنا جرير، عن مغيرة، عن الشعبي، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2127, 2405–2406).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: ʿAbdullāh ibn ʿAmr ibn Ḥarām died while owing a debt. I sought the assistance of the Prophet ﷺ in asking his creditors to reduce some of the debt. The Prophet ﷺ appealed to them, but they refused. The Prophet ﷺ then said to me: “Go and separate your dates according to their varieties: place the ʿajwah dates separately and the dates of ʿAdhq ibn Zayd separately. Then send for me.” I did so and sent for the Prophet ﷺ. He sat upon the upper part of the dates—or in their midst—and said: “Measure them out for the creditors.” I measured the dates for them until I had fully paid everything they were owed, yet my dates remained as though nothing had been taken from them."]},"buhuth":{"en":["Concerning the expression “ʿAdhq ibn Zayd”: ʿadhaq, with the letter ʿayn bearing fatḥah, means a date palm; with kasrah, ʿidhq means a date cluster. Ibn Zayd was a man after whom this particular variety of dates was named.","The varieties of dates in Madinah are extremely numerous. Shaykh Abū Muḥammad al-Juwaynī mentioned in Al-Furūq that while he was in Madinah, he learned that more than sixty varieties of black dates alone had been counted in the presence of its governor. He added that the varieties of red dates there were even more numerous than the black ones. See Fatḥ al-Bārī (4/345)."]}},"tuhfa":{},"voc":["seerah",1644],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2127، 2405-2406)."},{"num":9685,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: دَخَلْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَجَدَ لَبَنًا فِي قَدَحٍ، فَقَالَ: أَبَا هِرٍّ الْحَقْ أَهْلَ الصُّفَّةِ، فَادْعُهُمْ إِلَىَّ. قَالَ: فَأَتَيْتُهُمْ فَدَعَوْتُهُمْ، فَأَقْبَلُوا، فَاسْتَأْذَنُوا، فَأُذِنَ لَهُمْ، فَدَخَلُوا."],"takhrij":"صحيح: رواه البخاري في الاستئذان (6246) عن أبي نعيم، حدثنا عمر بن ذر، وحدثنا محمد بن مقاتل، أخبرنا عبد الله، أخبرنا عمر بن ذر، أخبرنا مجاهد، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (6246).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: I entered with the Messenger of Allah ﷺ, and he found some milk in a cup. He said: “O Abū Hurayrah, go to the people of al-Ṣuffah and invite them to come to me.” I went to them and invited them. They came, sought permission to enter, and were granted permission. They then entered and drank."]},"buhuth":{"en":["Al-Bukhārī also narrated (6452) that Abū Hurayrah used to say:","By Allah, besides Whom there is no deity worthy of worship, I would press my stomach against the ground because of hunger, and I would tie a stone against my abdomen because of hunger.","One day, I sat along the road by which the Companions usually passed. Abū Bakr passed by, so I asked him about a verse from the Book of Allah. I asked him only so that he might notice my hunger and feed me, but he continued on without doing so.","ʿUmar then passed by me, and I asked him about a verse from the Book of Allah. I asked him only so that he might feed me, but he also continued on without doing so.","Abū al-Qāsim ﷺ then passed by me. When he saw me, he smiled and recognized from my face what I was feeling within myself. He said:","“O Abū Hirr!”","I replied, “At your service, O Messenger of Allah.”","He said:","“Follow me.”","He continued on, and I followed him. He entered his home. I sought permission to enter, and he gave me permission. Upon entering, he found some milk in a cup and asked:","“Where did this milk come from?”","They replied, “So-and-so, a man or a woman, gave it to you as a gift.”","He said:","“Abū Hirr!”","I replied, “At your service, O Messenger of Allah.”","He said:","“Go to the people of al-Ṣuffah and invite them to come to me.”","The people of al-Ṣuffah were the guests of Islam. They had neither families nor wealth to support them, nor anyone upon whom they could depend. Whenever charity came to the Prophet ﷺ, he would send it to them without taking any of it himself. Whenever a gift came to him, he would send for them, take some of it himself, and share it with them.","His command troubled me, and I thought: What will this small amount of milk do for all the people of al-Ṣuffah? I was more in need of drinking from it so that I might regain my strength. If they came, he would order me to serve them. What amount of milk could possibly remain for me?","Nevertheless, obedience to Allah and His Messenger ﷺ was unavoidable. I went to the people of al-Ṣuffah and invited them. They came, sought permission to enter, and were admitted. They took their places in the house.","The Prophet ﷺ said:","“O Abū Hirr!”","I replied, “At your service, O Messenger of Allah.”","He said:","“Take the cup and give it to them.”","I took the cup and began handing it to each man. He would drink until fully satisfied and return the cup to me. I would then give it to the next man, who would drink until fully satisfied and return it to me. This continued until I reached the Prophet ﷺ after all the people had drunk their fill.","He took the cup and held it in his hand. He looked at me, smiled, and said:","“Abū Hirr!”","I replied, “At your service, O Messenger of Allah.”","He said:","“Only you and I remain.”","I replied, “You have spoken the truth, O Messenger of Allah.”","He said:","“Sit down and drink.”","I sat and drank. He again said:","“Drink.”","So I drank again. He continued telling me, “Drink,” until I said, “No, by the One Who sent you with the truth, I can find no more room for it.”","He said:","“Then give it to me.”","I gave him the cup. He praised Allah, pronounced His name, and drank what remained."]}},"tuhfa":{},"voc":["seerah",1645],"full":1,"dr":1,"rep":[14204],"tks":"صحيح: رواه البخاري (6246)."},{"num":9686,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ أُمَّ مَالِكٍ كَانَتْ تُهْدِي لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي عُكَّةٍ لَهَا سَمْنًا، فَيَأْتِيهَا بَنُوهَا فَيَسْأَلُونَ الْأُدْمَ، وَلَيْسَ عِنْدَهُمْ شَيْءٌ، فَتَعْمِدُ إِلَى الَّذِي كَانَتْ تُهْدِي فِيهِ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَجِدُ فِيهِ سَمْنًا، فَمَا زَالَ يُقِيمُ لَهَا أُدْمَ بَيْتِهَا حَتَّى عَصَرَتْهُ، فَأَتَتِ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: عَصَرْتِيهَا؟ قَالَتْ: نَعَمْ. قَالَ: لَوْ تَرَكْتِيهَا مَا زَالَ قَائِمًا."],"takhrij":"صحيح: رواه مسلم في الفضائل (8:2280) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2280:8).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: Umm Mālik used to present clarified butter to the Prophet ﷺ in a leather container. Her sons would later come to her asking for something to eat with their bread when they had nothing else. She would go to the container in which she had sent the butter to the Prophet ﷺ and find butter in it. It continued providing the condiment needed by her household until she squeezed the container completely. She then came to the Prophet ﷺ, who asked: “Did you squeeze it?” She replied, “Yes.” He said: “Had you left it alone, it would have continued to provide for you.”"]},"buhuth":{"en":["The words “it would have continued” mean that it would have remained present and available."]}},"tuhfa":{},"voc":["seerah",1646],"full":1,"dr":1,"rep":[7383],"tks":"صحيح: رواه مسلم (8: 2280)."},{"num":9687,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ  أَنَّ رَجُلًا أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَطْعِمُهُ، فَأَطْعَمَهُ شَطْرَ وَسْقِ شَعِيرٍ، فَمَا زَالَ الرَّجُلُ يَأْكُلُ مِنْهُ، وَامْرَأَتُهُ وَضَيْفُهُمَا حَتَّى كَالَهُ، فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: لَوْ لَمْ تَكِلْهُ لَأَكَلْتُمْ مِنْهُ وَلَقَامَ لَكُمْ."],"takhrij":"صحيح: رواه مسلم في الفضائل (9:2281) عن سلمة بن شبيب، حدثنا الحسن بن أعين، حدثنا معقل، عن أبي الزبير، عن جابر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2281:9).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported: A man came to the Prophet ﷺ asking for food. The Prophet ﷺ gave him half a wasq of barley. The man, his wife, and their guests continued eating from it until he measured it. He then came to the Prophet ﷺ, who said: “Had you not measured it, you would have continued eating from it, and it would have remained available for you.”"]}},"tuhfa":{},"voc":["seerah",1647],"full":1,"tks":"صحيح: رواه مسلم (9: 2281)."},{"num":9688,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ:  كُنَّا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَسِيرٍ، قَالَ: فَنَفِدَتْ أَزْوَادُ الْقَوْمِ، قَالَ: حَتَّى هَمَّ بِنَحْرِ بَعْضِ حَمَائِلِهِمْ، قَالَ: فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، لَوْ جَمَعْتَ مَا بَقِيَ مِنْ أَزْوَادِ الْقَوْمِ، فَدَعَوْتَ اللَّهَ عَلَيْهَا، قَالَ: فَفَعَلَ، قَالَ: فَجَاءَ ذُو الْبُرِّ بِبُرِّهِ، وَذُو التَّمْرِ بِتَمْرِهِ، قَالَ: وَقَالَ مُجَاهِدٌ: وَذُو النَّوَاةِ بِنَوَاهُ، قُلْتُ: وَمَا كَانُوا يَصْنَعُونَ بِالنَّوَى؟ قَالَ: كَانُوا يَمُصُّونَهُ وَيَشْرَبُونَ عَلَيْهِ الْمَاءَ، قَالَ: فَدَعَا عَلَيْهَا. - قَالَ - حَتَّى مَلَأَ الْقَوْمُ أَزْوِدَتَهُمْ، قَالَ: فَقَالَ عِنْدَ ذَلِكَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ، لَا يَلْقَى اللهَ بِهِمَا عَبْدٌ، غَيْرَ شَاكٍّ فِيهِمَا، إِلَّا دَخَلَ الْجَنَّةَ.","وفي رواية: لَمَّا كانت غَزْوَةُ تَبُوكَ أَصَابَ النَّاسَ مَجَاعَةٌ. قَالُوا: يَا رَسُولَ اللَّهِ، لَوْ أَذِنْتَ لَنَا فَنَحَرْنَا نَوَاضِحَنَا فَأَكَلْنَا وَادَّهَنَّا؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: افْعَلُوا قَالَ: فَجَاءَ عُمَرُ، فَقَالَ: يَا رَسُولَ اللَّهِ! إِنْ فَعَلْتَ قَلَّ الظَّهْرُ. وَلَكِنِ ادْعُهُمْ بِفَضْلِ أَزْوَادِهِمْ. ثُمَّ ادْعُ اللَّهَ لَهُمْ عَلَيْهَا بِالْبَرَكَةِ. لَعَلَّ اللَّهَ أَنْ يَجْعَلَ فِي ذَلِكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَعَمْ قَالَ: فَدَعَا بِنِطَعٍ فَبَسَطَهُ. ثُمَّ دَعَا بِفَضْلِ أَزْوَادِهِمْ. قَالَ: فَجَعَلَ الرَّجُلُ يَجِيءُ بِكَفِّ ذُرَةٍ. قَالَ: وَيَجِيءُ الْآخَرُ بِكَفِّ تَمْرٍ. قَالَ: وَيَجِيءُ الْآخَرُ بِكِسْرَةٍ. حَتَّى اجْتَمَعَ عَلَى النِّطَعِ مِنْ ذَلِكَ شَيْءٌ يَسِيرٌ. قَالَ: فَدَعَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِالْبَرَكَةِ. ثُمَّ قَالَ: خُذُوا فِي أَوْعِيَتِكُمْ قَالَ: فَأَخَذُوا فِي أَوْعِيَتِهِمْ حَتَّى مَا تَرَكُوا فِي الْعَسْكَرِ وِعَاءً إِلَّا ملأوه. قَالَ: فَأَكَلُوا حَتَّى شَبِعُوا. وَفَضَلَتْ فَضْلَةٌ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَنِّي رَسُولُ اللَّهِ. لَا يَلْقَى اللَّهَ بِهِمَا عَبْدٌ، غَيْرَ شَاكٍّ، فَيُحْجَبَ عَنِ الْجَنَّةِ."],"takhrij":"صحيح: رواه مسلم في الإيمان (27) عن أبي بكر بن النضر بن أبي النضر، قال: حدثني أبو النضر هاشم بن القاسم، حدثنا عبيد الله الأشجعي، عن مالك بن مغول، عن طلحة بن مصرف، عن أبي صالح، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (27).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: We were traveling with the Prophet ﷺ when the people’s provisions were exhausted, until they considered slaughtering some of the animals carrying their loads. ʿUmar said, “O Messenger of Allah, why not gather whatever remains of the people’s provisions and supplicate to Allah to bless them?” The Prophet ﷺ did so. Those who had wheat brought their wheat, and those who had dates brought their dates. Mujāhid added, “Those who had date stones brought their date stones.” The narrator asked, “What did they do with the date stones?” He replied, “They would suck them and then drink water over them.” The Prophet ﷺ invoked Allah’s blessing upon the provisions until the people had filled their provision bags. He then said: “I bear witness that there is no deity worthy of worship except Allah and that I am the Messenger of Allah. No servant will meet Allah affirming these two testimonies without doubting them except that he will enter Paradise.”","Another narration states: During the campaign of Tabūk, the people suffered from famine. They said, “O Messenger of Allah, if only you would permit us to slaughter our camels used for drawing water, so that we might eat their meat and use their fat.” The Messenger of Allah ﷺ said: “Do so.” ʿUmar then came and said, “O Messenger of Allah, if you do that, there will be too few riding animals left. Instead, ask the people to bring the remnants of their provisions and then supplicate to Allah to bless them. Perhaps Allah will place blessing in them.” The Messenger of Allah ﷺ replied: “Yes.” He called for a leather mat and spread it out. He then asked the people to bring the remnants of their provisions. One man brought a handful of millet, another brought a handful of dates, and another brought a piece of bread, until a small quantity had been collected upon the mat. The Messenger of Allah ﷺ invoked blessing upon it and then said: “Fill your containers from it.” They filled their containers until there was not a single container in the entire encampment that they had not filled. They ate until they were satisfied, and some food still remained. The Messenger of Allah ﷺ then said: “I bear witness that there is no deity worthy of worship except Allah and that I am the Messenger of Allah. No servant will meet Allah affirming these two testimonies without doubt and then be barred from Paradise.”"]}},"tuhfa":{},"voc":["seerah",1648],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (27)."},{"num":9689,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّ شَاةً، طُبِخَتْ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ، فَقَالَ: أَعْطِنِي الذِّرَاعَ فَنَاوَلَهَا إِيَّاهُ، ثُمَّ قَالَ: أَعْطِنِي الذِّرَاعَ فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّمَا لِلشَّاةِ ذِرَاعَانِ! قَالَ: أَمَا إِنَّكَ لَوِ الْتَمَسْتَهَا لَوَجَدْتَهَا."],"takhrij":"حسن: رواه الإمام أحمد (10706) عن الضحاك، حدثنا ابن عجلان، عن أبيه، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (10706).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah reported: A sheep was cooked, and the Messenger of Allah ﷺ said: “Give me a foreleg.” He was handed one. He again said: “Give me a foreleg.” He was handed another. He then said: “Give me a foreleg.” The man said, “O Messenger of Allah, a sheep has only two forelegs!” He replied: “Had you continued looking for them, you would have found them.”"]}},"tuhfa":{},"voc":["seerah",1649],"full":1,"dr":1,"rep":[7321],"tks":"حسن: رواه الإمام أحمد (10706)."},{"num":9690,"demo":false,"sanad":"","matn":["عَنْ أَبِي عُبَيْدٍ، أَنَّهُ طَبَخَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِدْرًا فِيهَا لَحْمٌ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: نَاوِلْنِي ذِرَاعَهَا فَنَاوَلْتُهُ فَقَالَ: نَاوِلْنِي ذِرَاعَهَا فَنَاوَلْتُهُ، فَقَالَ: نَاوِلْنِي ذِرَاعَهَا فَقَالَ: يَا نَبِيَّ اللَّهِ! كَمْ لِلشَّاةِ مِنْ ذِرَاعٍ؟ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ سَكَتَّ لَأَعْطَتْكَ ذِرَاعًا مَا دَعَوْتَ بِهِ."],"takhrij":"حسن: رواه الإمام أحمد (15967) والطبراني في الكبير (22/335-336) والترمذي في الشمائل (170) كلهم من طريق أبان بن العطار، حدثنا قتادة، عن شهر بن حوشب، عن أبي عبيد فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (15967), al-Ṭabarānī in Al-Muʿjam al-Kabīr (22/335–336), and al-Tirmidhī in Al-Shamā’il (170).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū ʿUbayd reported: I prepared a pot of meat for the Messenger of Allah ﷺ. The Messenger of Allah ﷺ said: “Hand me its foreleg.” I handed him one. He again said: “Hand me its foreleg.” I handed him another. He then said: “Hand me its foreleg.” I asked, “O Prophet of Allah, how many forelegs does a sheep have?” He replied: “By Him in Whose hand is my soul, had you remained silent, you would have continued handing me a foreleg each time I requested one.”"]}},"tuhfa":{},"voc":["seerah",1650],"full":1,"dr":1,"tks":"حسن: رواه أحمد (15967)، والطبراني في الكبير (22/335-336)، والترمذي في الشمائل (170)."},{"num":9691,"demo":false,"sanad":"","matn":["عَنْ سَمُرَةَ بْنِ جُنْدَبٍ، قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَتَدَاوَلُ مِنْ قَصْعَةٍ مِنْ غُدْوَةٍ حَتَّى اللَّيْلِ، يَقُومُ عَشَرَةٌ، وَيَقْعُدُ عَشَرَةٌ. قُلْنَا: فَمَا كَانَتْ تُمَدُّ؟ قَالَ: مِنْ أَىِّ شَيْءٍ تَعْجَبُ؟ مَا كَانَتْ تُمَدُّ إِلاَّ مِنْ هَا هُنَا وَأَشَارَ بِيَدِهِ إِلَى السَّمَاءِ."],"takhrij":"صحيح: رواه الترمذي (3625) عن محمد بن بشار، حدثنا يزيد بن هارون، حدثنا سليمان التيمي، عن أبي العلاء، عن سمرة بن جندب فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated and authenticated by al-Tirmidhī (3625), narrated by Aḥmad (20196), and authenticated by Ibn Ḥibbān (6529).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Samurah ibn Jundab said: We were with the Messenger of Allah ﷺ, taking turns eating from a single large dish from morning until night. Ten people would rise after eating, and another ten would sit down to eat. We asked, “From where was the food continually replenished?” He replied, “Why are you astonished? It was replenished only from there,” and he pointed with his hand toward the sky."]}},"tuhfa":{},"voc":["seerah",1651],"full":1,"dr":1,"tks":"صحيح: رواه الترمذي (3625) وصححه، وأحمد (20196)، وصححه ابن حبان (6529)."},{"num":9692,"demo":false,"sanad":"","matn":["عن أَبِي عَمْرَةَ الأنصاري حَدَّثَنِي أَبِي قَالَ: كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزَاةٍ، فَأَصَابَ النَّاسَ مَخْمَصَةٌ، فَاسْتَأْذَنَ النَّاسُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي نَحْرِ بَعْضِ ظُهُورِهِمْ، وَقَالُوا: يُبَلِّغُنَا اللهُ بِهِ، فَلَمَّا رَأَى عُمَرُ بْنُ الْخَطَّابِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدْ هَمَّ أَنْ يَأْذَنَ لَهُمْ فِي نَحْرِ بَعْضِ ظَهْرِهِمْ، قَالَ: يَا رَسُولَ اللَّهِ، كَيْفَ بِنَا إِذَا نَحْنُ لَقِينَا الْقَوْمَ غَدًا جِيَاعًا رِجَالًا؟ وَلَكِنْ إِنْ رَأَيْتَ يَا رَسُولَ اللَّهِ أَنْ تَدْعُوَ لَنَا بِبَقَايَا أَزْوَادِهِمْ، فَتَجْمَعَهَا، ثُمَّ تَدْعُوَ اللَّهَ فِيهَا بِالْبَرَكَةِ، فَإِنَّ اللَّهَ، تَبَارَكَ وَتَعَالَى، سَيُبَلِّغُنَا بِدَعْوَتِكَ - أَوْ قَالَ: سَيُبَارِكُ لَنَا فِي دَعْوَتِكَ، - فَدَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِبَقَايَا أَزْوَادِهِمْ، فَجَعَلَ النَّاسُ يُجِيئُونَ بِالْحَثْيَةِ مِنَ الطَّعَامِ، وَفَوْقَ ذَلِكَ، وَكَانَ أَعْلَاهُمْ مَنْ جَاءَ بِصَاعٍ مِنْ تَمْرٍ، فَجَمَعَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ثُمَّ قَامَ فَدَعَا مَا شَاءَ اللَّهُ أَنْ يَدْعُوَ، ثُمَّ دَعَا الْجَيْشَ بِأَوْعِيَتِهِمْ، فَأَمَرَهُمْ أَنْ يَحْتَثُوا، فَمَا بَقِيَ فِي الْجَيْشِ وِعَاءٌ إِلَّا مَلَئُوهُ، وَبَقِيَ مِثْلُهُ، فَضَحِكَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَتَّى بَدَتْ نَوَاجِذُهُ، فَقَالَ: أَشْهَدُ أَنْ لَا إِلَهَ إِلَّا اللَّهُ، وَأَشْهَدُ أَنِّي رَسُولُ اللَّهِ، لَا يَلْقَى اللهَ عَبْدٌ مُؤْمِنٌ بِهَا إِلَّا حُجِبَتْ عَنْهُ النَّارُ يَوْمَ الْقِيَامَةِ."],"takhrij":"حسن: رواه الإمام أحمد (15449) عن علي بن إسحاق، أخبرنا عبد الله – يعني ابن المبارك، قال: أخبرنا الأوزاعي، قال: حدثنا المطلب بن حنطب المخزومي، قال: حدثني عبد الرحمن بن أبي عمرة الأنصاري، حدثني أبي قال: فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (15449).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū ʿAmrah al-Anṣārī said: We were with the Messenger of Allah ﷺ on a military expedition when the people were afflicted by severe hunger. They sought the permission of the Messenger of Allah ﷺ to slaughter some of their riding animals, saying, “Allah will enable us to reach our destination by means of their meat.” When ʿUmar ibn al-Khaṭṭāb saw that the Messenger of Allah ﷺ was about to permit them to slaughter some of their mounts, he said: “O Messenger of Allah, what will become of us if we encounter the enemy tomorrow while hungry and on foot? Instead, if you deem it appropriate, ask them to bring the remnants of their provisions. Gather them together and supplicate to Allah to bless them. Allah, Blessed and Most High, will enable us to reach our destination through your supplication”—or he said, “Allah will bless your supplication for us.” The Prophet ﷺ called for the remnants of their provisions. The people began bringing handfuls of food or a little more. The largest contribution anyone brought was one ṣāʿ of dates. The Messenger of Allah ﷺ gathered it all together, stood, and supplicated for as long as Allah willed. He then called upon the army to bring their containers and instructed them to scoop food into them. Not a single container remained in the army without being filled, yet an equal amount of food still remained. The Messenger of Allah ﷺ laughed until his molar teeth became visible and said: “I bear witness that there is no deity worthy of worship except Allah and that I am the Messenger of Allah. No servant who believes in these two testimonies will meet Allah without the Fire being screened from him on the Day of Resurrection.”"]}},"tuhfa":{},"voc":["seerah",1652],"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (15449)."},{"num":9693,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: أَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِتَمَرَاتٍ فَقُلْتُ: يَا رَسُولَ اللَّهِ ادْعُ اللَّهَ فِيهِنَّ بِالْبَرَكَةِ. فَضَمَّهُنَّ ثُمَّ دَعَا لِي فِيهِنَّ بِالْبَرَكَةِ، فَقَالَ لِي: خُذْهُنَّ وَاجْعَلْهُنَّ فِي مِزْوَدِكَ هَذَا، أَوْ فِي هَذَا الْمِزْوَدِ، كُلَّمَا أَرَدْتَ أَنْ تَأْخُذَ مِنْهُ شَيْئًا فَأَدْخِلْ فِيهِ يَدَكَ فَخُذْهُ وَلاَ تَنْثُرْهُ نَثْرًا. فَقَدْ حَمَلْتُ مِنْ ذَلِكَ التَّمْرِ كَذَا وَكَذَا مِنْ وَسْقٍ فِي سَبِيلِ اللَّهِ فَكُنَّا نَأْكُلُ مِنْهُ وَنُطْعِمُ وَكَانَ لاَ يُفَارِقُ حَقْوِي حَتَّى كَانَ يَوْمُ قَتْلِ عُثْمَانَ فَإِنَّهُ انْقَطَعَ."],"takhrij":"حسن: رواه الترمذي (3839) واللفظ له، وأحمد (8628) وابن حبان (6532) والبيهقي في الدلائل (6/109) كلهم من طرق عن حماد بن زيد، عن المهاجر، عن أبي العالية الرياحي، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated and graded it good by al-Tirmidhī (3839), and narrated by Aḥmad (8628) and Ibn Ḥibbān (6532).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: I brought some dates to the Prophet ﷺ and said, “O Messenger of Allah, ask Allah to bless them.” He gathered them together and invoked Allah’s blessing upon them for me. He then said: “Take them and place them in this provision bag of yours—or in this bag. Whenever you wish to take something from it, put your hand inside and remove what you need, but do not empty it out by scattering its contents.” From those dates I supplied many wasqs in the cause of Allah. We continued eating from them and feeding others. The bag never left my waist until the day ʿUthmān was killed, when it was cut away and lost."]}},"tuhfa":{},"voc":["seerah",1653],"full":1,"dr":1,"tks":"حسن: رواه الترمذي (3839) وحسنه، وأحمد (8628)، وابن حبان (6532)."},{"num":9694,"demo":false,"sanad":"","matn":["عَنْ دُكَيْنِ بْنِ سَعِيدٍ الْمُزَنِيِّ، قَالَ: أَتَيْنَا رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَرْبَعِينَ رَاكِبًا وَأَرْبَعَ مِائَةٍ، نَسْأَلُهُ الطَّعَامَ، فَقَالَ لِعُمَرَ: اذْهَبْ فَأَعْطِهِمْ فَقَالَ: يَا رَسُولَ اللَّهِ، مَا بَقِيَ إِلَّا آصُعٌ مِنْ تَمْرٍ، مَا أَرَى أَنْ يَقِيظَنِي. قَالَ: اذْهَبْ فَأَعْطِهِمْ قَالَ: سَمْعًا وَطَاعَةً. قَالَ: فَأَخْرَجَ عُمَرُ الْمِفْتَاحَ مِنْ حَجُزَتِهِ، فَفَتَحَ الْبَابَ، فَإِذَا شِبْهُ الْفَصِيلِ الرَّابِضِ مِنْ تَمْرٍ، فَقَالَ لَنَا: خُذُوا. فَأَخَذَ كُلُّ رَجُلٍ مِنَّا مَا أَحَبَّ، ثُمَّ الْتَفَتُّ، وَكُنْتُ مِنْ آخِرِ الْقَوْمِ، وَكَأَنَّا لَمْ نَرْزَأْ تَمْرَةً."],"takhrij":"صحيح: رواه أحمد (17577) واللفظ له – وأبو داود (5238) مختصرا – وابن حبان (6528) والطبراني في الكبير (4/270-271) كلهم من طرق عن إسماعيل بن أبي خالد، عن قيس بن أبي حازم قال: حدثني دكين بن سعيد المزني فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب ما جاء في تكثير الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17577), whose wording this is; Abū Dāwūd (5238) in abbreviated form; and Ibn Ḥibbān (6528).","chapter_en":"Reports Concerning the Miraculous Multiplication of Food","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":9,"content":{"translation":{"en":["Dukayn ibn Saʿīd al-Muzanī said: Four hundred and forty riders came to the Messenger of Allah ﷺ asking him for food. He said to ʿUmar: “Go and give them food.” ʿUmar replied, “O Messenger of Allah, only a few ṣāʿs of dates remain—hardly enough to sustain me.” He said: “Go and give them food.” ʿUmar replied, “I hear and obey.” ʿUmar took a key from his waistband and opened the door. There was a pile of dates resembling a young camel lying upon the ground. He told us, “Take what you need.” Each man took as much as he wished. I then looked back, as I was among the last of the people, and it appeared as though we had not diminished the pile by even a single date."]},"buhuth":{"en":["The expression “hardly enough to sustain me” means “not enough to suffice me.” A “young camel lying down” refers to the offspring of a she-camel sitting firmly upon the ground. The words “we had not diminished it” mean that we appeared neither to have reduced nor taken anything from it."]}},"tuhfa":{},"voc":["seerah",1654],"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17577) واللفظ له، وأبو داود (5238) مختصرا، وابن حبان (6528)."},{"num":9695,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ قَالَ: كُنَّا نَسْمَعُ تَسْبِيحَ الطَّعَامِ وَهْوَ يُؤْكَلُ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3579) عن محمد بن المثنى، حدثنا أبو أحمد الزبيري، حدثنا إسرائيل، عن منصور، عن إبراهيم، عن علقمة، عن عبد الله فذكره. وذلك في عهد النبي صلى الله عليه وسلم كما جاء التصريح به في رواية عند الإسماعيلي أخرجه عن الحسن بن سفيان، عن بندار، عن أبي أحمد الزبيري في هذا الحديث: \"كنا نأكل مع النبي صلى الله عليه وسلم الطعام، ونحن نسمع تسبيح الطعام\".","grade":"صحيح","chapter_ar":"باب ما جاء في تسبيح الطعام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3579), from Muḥammad ibn al-Muthannā, from Abū Aḥmad al-Zubayrī, from Isrāʾīl, from Manṣūr, from Ibrāhīm, from ʿAlqamah, from ʿAbdullāh ibn Masʿūd.","chapter_en":"Reports Concerning Food Glorifying Allah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":10,"content":{"translation":{"en":["ʿAbdullāh ibn Masʿūd said: We used to hear the food glorifying Allah while it was being eaten."]}},"tuhfa":{},"voc":["seerah",1655],"full":1,"tks":"صحيح: رواه البخاري (3579)."},{"num":9696,"demo":false,"sanad":"","matn":["عن جابر بْنِ عَبْدِ اللَّهِ قَالَ: كَانَ جِذْعٌ يَقُومُ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَلَمَّا وُضِعَ لَهُ الْمِنْبَرُ سَمِعْنَا لِلْجِذْعِ مِثْلَ أَصْوَاتِ الْعِشَارِ، حَتَّى نَزَلَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَضَعَ يَدَهُ عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في الجمعة (918) عن سعيد بن أبي مريم، قال: حدثنا محمد بن جعفر قال: أخبرني يحيى بن سعيد، قال: أخبرني ابن أنس، أنه سمع جابر بن عبد الله يقول: فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حنين الجذع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (918).","chapter_en":"Reports Concerning the Palm Trunk’s Longing for the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":11,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: There was a palm trunk beside which the Prophet ﷺ used to stand. When the pulpit was erected for him, we heard the trunk making sounds like those of pregnant she-camels, until the Prophet ﷺ descended and placed his hand upon it."]}},"tuhfa":{},"voc":["seerah",1656],"full":1,"dr":1,"rep":[3299],"tks":"صحيح: رواه البخاري (918)."},{"num":9697,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُمَرَ رَضِيَ اللَّهُ عَنْهُمَا كَانَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ إِلَى جِذْعٍ فَلَمَّا اتَّخَذَ الْمِنْبَرَ تَحَوَّلَ إِلَيْهِ، فَحَنَّ الْجِذْعُ، فَأَتَاهُ فَمَسَحَ يَدَهُ عَلَيْهِ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3583) عن محمد بن المثنى، حدثنا يحيى بن كثير أبو غسان، حدثنا أبو حفص – واسمه عمر بن العلاء أخو أبي عمرو بن العلاء – قال: سمعت نافعا، عن ابن عمر فذكره.","grade":"صحيح","chapter_ar":"باب ما جاء في حنين الجذع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3583).","chapter_en":"Reports Concerning the Palm Trunk’s Longing for the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿUmar said: The Prophet ﷺ used to deliver his sermons beside a palm trunk. When a pulpit was made for him, he moved to it, whereupon the trunk cried with longing. He went to it and passed his hand over it."]}},"tuhfa":{},"voc":["seerah",1657],"full":1,"rep":[3301],"tks":"صحيح: رواه البخاري (3583)."},{"num":9698,"demo":false,"sanad":"","matn":["عَنْ أَبِي حَازِمٍ قَالَ: أَتَوْا سَهْلَ بْنَ سَعْدٍ فَقَالُوا: مِنْ أَيِّ شَيْءٍ مِنْبَرُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ؟ قَالَ: مَا بَقِيَ أَحَدٌ مِنَ النَّاسِ أَعْلَمُ بِهِ مِنِّي، قَالَ: هُوَ مِنْ أَثْلِ الْغَابَةِ، وَعَمِلَهُ فُلَانٌ مَوْلَى فُلَانَةَ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْتَنِدُ إِلَى جِذْعٍ فِي الْمَسْجِدِ يُصَلِّي إِلَيْهِ إِذَا خَطَبَ، فَلَمَّا اتَّخَذَ الْمِنْبَرَ فَقَعَدَ عَلَيْهِ حَنَّ الْجِذْعُ، قَالَ: فَأَتَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَوَطَّدَهُ، وَلَيْسَ فِي حَدِيثِ أَبِي حَازِمٍ: حَتَّى سَكَنَ."],"takhrij":"صحيح: رواه ابن أبي شيبة (32406) عن ابن عيينة، عن أبي حازم قال: فذكره. ورواه مسلم في المساجد (544 :45) عن أبي بكر بن أبي شيبة به إلا أنه لم يسق لفظه، وأحال إلى حديث عبد العزيز بن أبي حازم، عن أبيه.","grade":"صحيح","chapter_ar":"باب ما جاء في حنين الجذع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Abī Shaybah (32406) and Muslim (544:45).","chapter_en":"Reports Concerning the Palm Trunk’s Longing for the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":11,"content":{"translation":{"en":["Abū Ḥāzim reported: Some people came to Sahl ibn Saʿd and asked, “From what was the pulpit of the Messenger of Allah ﷺ made?” He replied, “No one remaining among the people knows more about it than I do. It was made from the tamarisk wood of al-Ghābah. So-and-so, the freed slave of a certain woman, made it for the Messenger of Allah ﷺ.” The Messenger of Allah ﷺ used to lean against a palm trunk in the mosque, standing beside it when delivering a sermon. When the pulpit was made and he sat upon it, the trunk cried with longing. The Messenger of Allah ﷺ went to it and soothed it—although Abū Ḥāzim’s narration does not contain the words “and soothed it”—until it became quiet."]}},"tuhfa":{},"voc":["seerah",1658],"full":1,"dr":1,"tks":"صحيح: رواه ابن أبي شيبة (32406)، ومسلم (544 :45)."},{"num":9699,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ قَالَ: أَصَابَ أَهْلَ الْمَدِينَةِ قَحْطٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَيْنَا هُوَ يَخْطُبُ يَوْمَ جُمُعَةٍ، إِذْ قَامَ رَجُلٌ فَقَالَ: يَا رَسُولَ اللَّهِ! هَلَكَتِ الْكُرَاعُ، وهلكت الشَّاءُ، فَادْعُ اللَّهَ يَسْقِينَا فَمَدَّ يَدَيْهِ، وَدَعَا.","قَالَ أَنَسٌ: وَإِنَّ السَّمَاءَ لَمِثْلُ الزُّجَاجَةِ، فَهَاجَتْ رِيحٌ أَنْشَأَتْ سَحَابًا، ثُمَّ اجْتَمَعَ، ثُمَّ أَرْسَلَتِ السَّمَاءُ عَزَالِيَهَا، فَخَرَجْنَا نَخُوضُ الْمَاءَ، حَتَّى أَتَيْنَا مَنَازِلَنَا، فَلَمْ نَزَلْ نُمْطَرُ إِلَى الْجُمُعَةِ الأُخْرَى، فَقَامَ إِلَيْهِ ذَلِكَ الرَّجُلُ أَوْ غَيْرُهُ فَقَالَ: يَا رَسُولَ اللهِ! تَهَدَّمَتِ الْبُيُوتُ، فَادْعُ اللَّهَ يَحْبِسْهُ، فَتَبَسَّمَ ثُمَّ قَالَ: حَوَالَيْنَا وَلَا عَلَيْنَا فَنَظَرْتُ إِلَى السَّحَابِ تَصَدَّعَ حَوْلَ الْمَدِينَةِ كَأَنَّهُ إِكْلِيلٌ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3582) ومسلم في صلاة الاستسقاء (897) كلاهما من حديث ثابت البناني، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب نزول المطر بدعاء النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3582) and Muslim (897).","chapter_en":"Rain Fell in Response to the Prophet’s Supplication ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":12,"content":{"translation":{"en":["Anas said: The people of Madinah suffered a drought during the lifetime of the Messenger of Allah ﷺ. While he was delivering the Friday sermon, a man stood and said, “O Messenger of Allah, the horses and camels are perishing and the sheep are dying. Supplicate to Allah to send us rain.” The Prophet ﷺ extended his hands and supplicated. Anas said: The sky had been as clear as glass. A wind then arose and formed clouds. The clouds gathered together, and the sky opened its channels of rain. We left the mosque wading through water until we reached our homes.","It continued raining until the following Friday. The same man—or another man—stood and said, “O Messenger of Allah, the houses are collapsing. Supplicate to Allah to withhold the rain.” The Prophet ﷺ smiled and said: “O Allah, let it fall around us and not upon us.” I looked at the clouds as they separated around Madinah until they resembled a circular crown."]}},"tuhfa":{},"voc":["seerah",1659],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3582)، ومسلم (897)."},{"num":9700,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ قَالَ: أَصَابَتِ النَّاسَ سَنَةٌ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَبَيْنَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَخْطُبُ عَلَى الْمِنْبَرِ يَوْمَ الْجُمُعَةِ، قَامَ أَعْرَابِيٌّ فَقَالَ: يَا رَسُولَ اللَّهِ، هَلَكَ الْمَالُ، وَجَاعَ الْعِيَالُ، فَادْعُ اللَّهَ لَنَا أَنْ يَسْقِيَنَا. قَالَ: فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ، وَمَا فِي السَّمَاءِ قَزَعَةٌ، قَالَ: فَثَارَ سَحَابٌ أَمْثَالُ الْجِبَالِ، ثُمَّ لَمْ يَنْزِلْ عَنْ مِنْبَرِهِ حَتَّى رَأَيْتُ الْمَطَرَ يَتَحَادَرُ عَلَى لِحْيَتِهِ، قَالَ: فَمُطِرْنَا يَوْمَنَا ذَلِكَ، وَفِي الْغَدِ، وَمِنْ بَعْدِ الْغَدِ، وَالَّذِي يَلِيهِ إِلَى الْجُمُعَةِ الأُخْرَى، فَقَامَ ذَلِكَ الأَعْرَابِيُّ، أَوْ رَجُلٌ غَيْرُهُ، فَقَالَ: يَا رَسُولَ اللَّهِ، تَهَدَّمَ الْبِنَاءُ، وَغَرِقَ الْمَالُ، فَادْعُ اللَّهَ لَنَا. فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ وَقَالَ: اللَّهُمَّ حَوَالَيْنَا وَلاَ عَلَيْنَا. قَالَ: فَمَا جَعَلَ يُشِيرُ بِيَدِهِ إِلَى نَاحِيَةٍ مِنَ السَّمَاءِ إِلاَّ تَفَرَّجَتْ، حَتَّى صَارَتِ الْمَدِينَةُ فِي مِثْلِ الْجَوْبَةِ، حَتَّى سَالَ الْوَادِي، ـ وَادِي قَنَاةَ، ـ شَهْرًا. قَالَ: فَلَمْ يَجِئْ أَحَدٌ مِنْ نَاحِيَةٍ إِلاَّ حَدَّثَ بِالْجَوْدِ."],"takhrij":"متفق عليه: رواه البخاري في الاستسقاء (1033) ومسلم في الاستسقاء (9:897) كلاهما من طريق الأوزاعي، قال: حدثنا إسحاق بن عبد الله بن أبي طلحة الأنصاري، قال: حدثني أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب نزول المطر بدعاء النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1033) and Muslim (897:9).","chapter_en":"Rain Fell in Response to the Prophet’s Supplication ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":12,"content":{"translation":{"en":["Anas ibn Mālik said: The people were afflicted by drought during the lifetime of the Messenger of Allah ﷺ. While the Messenger of Allah ﷺ was delivering the Friday sermon from the pulpit, a Bedouin stood and said, “O Messenger of Allah, our wealth and livestock are perishing and our families are hungry. Supplicate to Allah to send us rain.” The Messenger of Allah ﷺ raised his hands while there was not a single wisp of cloud in the sky. Clouds then arose resembling mountains. He had not yet descended from the pulpit when I saw rainwater flowing down his beard. Rain fell upon us that day, the following day, the day after that, and the next day, continuing until the following Friday. That Bedouin—or another man—then stood and said, “O Messenger of Allah, the buildings are collapsing and our wealth is being submerged. Supplicate to Allah for us.” The Messenger of Allah ﷺ raised his hands and said: “O Allah, let it fall around us and not upon us.” Whenever he pointed toward any part of the sky, the clouds dispersed from that direction, until Madinah resembled an open hollow surrounded by clouds. The valley of Qanāh continued flowing for a month. No one came from any direction without reporting abundant rainfall."]}},"tuhfa":{},"voc":["seerah",1660],"full":1,"dr":1,"rep":[2965,10973],"tks":"متفق عليه: رواه البخاري (1033)، ومسلم (9: 897)."},{"num":9701,"demo":false,"sanad":"","matn":["عَنْ عُرْوَةَ، أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَعْطَاهُ دِينَارًا يَشْتَرِي بِهِ شَاةً، فَاشْتَرَى لَهُ بِهِ شَاتَيْنِ، فَبَاعَ إِحْدَاهُمَا بِدِينَارٍ، وَجَاءَهُ بِدِينَارٍ وَشَاةٍ، فَدَعَا لَهُ بِالْبَرَكَةِ فِي بَيْعِهِ، وَكَانَ لَوِ اشْتَرَى التُّرَابَ لَرَبِحَ فِيهِ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3642) عن علي بن عبد الله، أخبرنا سفيان، حدثنا شبيب بن غرقدة قال: سمعت الحي يحدّثون، عن عروة فذكره.","grade":"صحيح","chapter_ar":"باب دعاء النبي ﷺ لعروة البارقي","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3642).","chapter_en":"The Prophet’s Supplication ﷺ for ʿUrwah al-Bāriqī","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":13,"content":{"translation":{"en":["ʿUrwah reported: The Prophet ﷺ gave him one dinar with which to purchase a sheep. He bought two sheep for that dinar and then sold one of them for a dinar. He returned to the Prophet ﷺ with both the original dinar and a sheep. The Prophet ﷺ supplicated that his business transactions be blessed. Thereafter, even if he had purchased dust, he would have made a profit from it."]}},"tuhfa":{},"voc":["seerah",1661],"full":1,"rep":[5531],"tks":"صحيح: رواه البخاري (3642)."},{"num":9702,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ قَالَ: غَزَوْتُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَتَلاَحَقَ بِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَأَنَا عَلَى نَاضِحٍ لَنَا قَدْ أَعْيَا، فَلاَ يَكَادُ يَسِيرُ، فَقَالَ لِي: مَا لِبَعِيرِكَ؟ قَالَ: قُلْتُ: عَيِيَ، قَالَ: فَتَخَلَّفَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَزَجَرَهُ وَدَعَا لَهُ فَمَا زَالَ بَيْنَ يدي الإِبِلِ قُدَّامَهَا..الحديث بِطُولِهِ فِي قِصَّةِ بيع الجمل."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2967) ومسلم في المساقاة (110:715) كلاهما عن إسحاق بن إبراهيم، أخبرنا جرير، عن المغيرة، عن الشعبي، عن جابر بن عبدالله فذكره.","grade":"متفق عليه","chapter_ar":"باب سرعة جمل جابر بعد دعاء النبي ﷺ له","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2967) and Muslim (715:110).","chapter_en":"Jābir’s Camel Became Swift After the Prophet ﷺ Supplicated for It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: I participated in a military expedition with the Messenger of Allah ﷺ. The Prophet ﷺ caught up with me while I was riding a water-carrying camel of ours that had become exhausted and could scarcely move. He asked: “What is wrong with your camel?” I replied, “It has become exhausted.” The Messenger of Allah ﷺ fell behind with it, urged it forward, and supplicated for it. Thereafter, it continued traveling at the front of the other camels, ahead of them. The complete hadith appears in the account of the sale of the camel."]}},"tuhfa":{},"voc":["seerah",1662],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2967)، ومسلم (110: 715)."},{"num":9703,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: فَزِعَ النَّاسُ، فَرَكِبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَرَسًا لأَبِي طَلْحَةَ بَطِيئًا، ثُمَّ خَرَجَ يَرْكُضُ وَحْدَهُ، فَرَكِبَ النَّاسُ يَرْكُضُونَ خَلْفَهُ، فَقَالَ: لَمْ تُرَاعُوا، إِنَّهُ لَبَحْرٌ. فَمَا سُبِقَ بَعْدَ ذَلِكَ الْيَوْمِ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد (2969) عن الفضل بن سهل، حدثنا حسين بن محمد، حدثنا جرير بن حازم، عن محمد، عن أنس بن مالك فذكره.","grade":"متفق عليه","chapter_ar":"باب ركوب النبي ﷺ على فرس أبي طلحة وكان بطيئًا فأصبح سريعًا","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2969) and Muslim (2307:48).","chapter_en":"The Prophet ﷺ Rode Abū Ṭalḥah’s Slow Horse, After Which It Became Swift","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":15,"content":{"translation":{"en":["Anas said: The people were alarmed, so the Messenger of Allah ﷺ mounted a slow horse belonging to Abū Ṭalḥah and rode off alone at a gallop. The people then mounted their horses and galloped after him. He said: “You have nothing to fear. This horse is truly like a sea in its speed.” After that day, the horse was never outrun."]}},"tuhfa":{},"voc":["seerah",1663],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2969)، ومسلم (48: 2307)."},{"num":9704,"demo":false,"sanad":"","matn":["عَنْ أنس بْنِ مَالِكٍ أَنَّ عَبْدَ اللَّهِ بْنَ سَلاَمٍ بَلَغَهُ مَقْدَمُ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَدِينَةَ، فَأَتَاهُ يَسْأَلُهُ عَنْ أَشْيَاءَ، فَقَالَ: إِنِّي سَائِلُكَ عَنْ ثَلاَثٍ لاَ يَعْلَمُهُنَّ إِلاَّ نَبِيٌّ: مَا أَوَّلُ أَشْرَاطِ السَّاعَةِ، وَمَا أَوَّلُ طَعَامٍ يَأْكُلُهُ أَهْلُ الْجَنَّةِ، وَمَا بَالُ الْوَلَدِ يَنْزِعُ إِلَى أَبِيهِ أَوْ إِلَى أُمِّهِ؟ قَالَ: أَخْبَرَنِي بِهِ جِبْرِيلُ آنِفًا . قَالَ ابْنُ سَلاَمٍ: ذَاكَ عَدُوُّ الْيَهُودِ مِنَ الْمَلاَئِكَةِ، قَالَ: أَمَّا أَوَّلُ أَشْرَاطِ السَّاعَةِ فَنَارٌ تَحْشُرُهُمْ مِنَ الْمَشْرِقِ إِلَى الْمَغْرِبِ، وَأَمَّا أَوَّلُ طَعَامٍ يَأْكُلُهُ أَهْلُ الْجَنَّةِ فَزِيَادَةُ كَبِدِ الْحُوتِ، وَأَمَّا الْوَلَدُ: فَإِذَا سَبَقَ مَاءُ الرَّجُلِ مَاءَ الْمَرْأَةِ نَزَعَ الْوَلَدَ، وَإِذَا سَبَقَ مَاءُ الْمَرْأَةِ مَاءَ الرَّجُلِ نَزَعَتِ الْوَلَدَ . قَالَ: أَشْهَدُ أَنَّ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّكَ رَسُولُ اللَّهِ، قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ الْيَهُودَ قَوْمٌ بُهُتٌ، فَاسْأَلْهُمْ عَنِّي قَبْلَ أَنْ يَعْلَمُوا بِإِسْلاَمِي، فَجَاءَتِ الْيَهُودُ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أي رَجُلٍ عَبْدُ اللَّهِ بْنُ سَلاَمٍ فِيكُمْ . قَالُوا: خَيْرُنَا وَابْنُ خَيْرِنَا، وَأَفْضَلُنَا وَابْنُ أَفْضَلِنَا . فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَرَأَيْتُمْ إِنْ أَسْلَمَ عَبْدُ اللَّهِ بْنُ سَلاَمٍ. قَالُوا: أَعَاذَهُ اللَّهُ مِنْ ذَلِكَ، فَأَعَادَ عَلَيْهِمْ فَقَالُوا مِثْلَ ذَلِكَ، فَخَرَجَ إِلَيْهِمْ عَبْدُ اللَّهِ فَقَالَ: أَشْهَدُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، قَالُوا: شَرُّنَا وَابْنُ شَرِّنَا، وَتَنَقَّصُوهُ، قَالَ: هَذَا كُنْتُ أَخَافُ يَا رَسُولَ اللَّهِ."],"takhrij":"صحيح: رواه البخاري في المناقب (3938) عن حامد بن عمر، عن بشر بن المفضل، حدثنا حميد، حدثنا أنس فذكره.","grade":"صحيح","chapter_ar":"باب جواب النبي ﷺ لبعض الأسئلة التي لا يعلمها من الإنس إلا نبي","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3938).","chapter_en":"The Prophet ﷺ Answered Questions Whose Answers No Human Being Knows Except a Prophet","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":16,"content":{"translation":{"en":["Anas ibn Mālik reported: When ʿAbdullāh ibn Salām learned that the Prophet ﷺ had arrived in Madinah, he came to ask him several questions. He said: “I shall ask you three questions whose answers are known only to a prophet: What is the first sign of the Hour? What is the first food the people of Paradise will eat? And what causes a child to resemble either its father or its mother?” The Prophet ﷺ replied: “Gabriel informed me of these things just now.” Ibn Salām said, “He is the enemy of the Jews among the angels.” The Prophet ﷺ said: “As for the first sign of the Hour, it will be a fire that gathers the people from the east to the west. The first food eaten by the people of Paradise will be the extra lobe of a fish’s liver. As for the child, when the man’s fluid precedes the woman’s fluid, the child resembles him; and when the woman’s fluid precedes the man’s fluid, the child resembles her.” ʿAbdullāh ibn Salām said, “I bear witness that there is no deity worthy of worship except Allah and that you are the Messenger of Allah.” He then said, “O Messenger of Allah, the Jews are a people of falsehood and slander. Ask them about me before they learn that I have embraced Islam.” The Jews came, and the Prophet ﷺ asked them: “What kind of man is ʿAbdullāh ibn Salām among you?” They replied, “He is the best of us and the son of the best of us, the most virtuous of us and the son of the most virtuous of us.” The Prophet ﷺ asked: “What would you think if ʿAbdullāh ibn Salām were to embrace Islam?” They replied, “May Allah protect him from doing so.” He repeated the question, and they gave the same answer. ʿAbdullāh then came out before them and said, “I bear witness that there is no deity worthy of worship except Allah and that Muhammad is the Messenger of Allah.” They immediately said, “He is the worst of us and the son of the worst of us,” and began disparaging him. ʿAbdullāh said, “This is what I feared, O Messenger of Allah.”"]}},"tuhfa":{},"voc":["seerah",1664],"full":1,"tks":"صحيح: رواه البخاري (3938)."},{"num":9705,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ مَوْلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَهُ قَالَ: كُنْتُ قَائِمًا عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَجَاءَ حَِبْرٌ مِنْ أَحْبَارِ الْيَهُودِ فَقَالَ: السَّلَامُ عَلَيْكَ يَا مُحَمَّدُ! فَدَفَعْتُهُ دَفْعَةً كَادَ يُصْرَعُ مِنْهَا، فَقَالَ: لِمَ تَدْفَعُنِي؟ فَقُلْتُ: أَلَا تَقُولُ يَا رَسُولَ اللَّهِ! فَقَالَ الْيَهُودِيُّ: إِنَّمَا نَدْعُوهُ بِاسْمِهِ الَّذِي سَمَّاهُ بِهِ أَهْلُهُ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّ اسْمِي مُحَمَّدٌ الَّذِي سَمَّانِي بِهِ أَهْلِي فَقَالَ الْيَهُودِيُّ: جِئْتُ أَسْأَلُكَ، فَقَالَ لَهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَيَنْفَعُكَ شَيْءٌ إِنْ حَدَّثْتُكَ؟ قَالَ: أَسْمَعُ بِأُذُنَيَّ، فَنَكَتَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِعُودٍ مَعَهُ، فَقَالَ: سَلْ فَقَالَ الْيَهُودِيُّ: أَيْنَ يَكُونُ النَّاسُ يَوْمَ تُبَدَّلُ الْأَرْضُ غَيْرَ الْأَرْضِ وَالسَّمَاوَاتُ؟ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : هُمْ فِي الظُّلْمَةِ دُونَ الْجِسْرِ قَالَ: فَمَنْ أَوَّلُ النَّاسِ إِجَازَةً؟ قَالَ: فُقَرَاءُ الْمُهَاجِرِينَ قَالَ الْيَهُودِيُّ: فَمَا تُحْفَتُهُمْ حِينَ يَدْخُلُونَ الْجَنَّةَ؟ قَالَ: زِيَادَةُ كَبِدِ النُّونِ قَالَ: فَمَا غِذَاؤُهُمْ عَلَى إِثْرِهَا؟ قَالَ: يُنْحَرُ لَهُمْ ثَوْرُ الْجَنَّةِ الَّذِي كَانَ يَأْكُلُ مِنْ أَطْرَافِهَا قَالَ: فَمَا شَرَابُهُمْ عَلَيْهِ؟ قَالَ: مِنْ عَيْنٍ فِيهَا تُسَمَّى سَلْسَبِيلًا قَالَ: صَدَقْتَ، قَالَ: وَجِئْتُ أَسْأَلُكَ عَنْ شَيْءٍ لَا يَعْلَمُهُ أَحَدٌ مِنْ أَهْلِ الْأَرْضِ، إِلَّا نَبِيٌّ أَوْ رَجُلٌ أَوْ رَجُلَانِ، قَالَ: يَنْفَعُكَ إِنْ حَدَّثْتُكَ؟ قَالَ: أَسْمَعُ بِأُذُنَيَّ، قَالَ: جِئْتُ أَسْأَلُكَ عَنِ الْوَلَدِ؟ قَالَ: مَاءُ الرَّجُلِ أَبْيَضُ وَمَاءُ الْمَرْأَةِ أَصْفَرُ، فَإِذَا اجْتَمَعَا، فَعَلَا منيُ الرَّجُلِ منيَ الْمَرْأَةِ أَذْكَرَا بِإِذْنِ اللَّهِ، وَإِذَا عَلَا منيُ الْمَرْأَةِ منيَ الرَّجُلِ، آنَثَا بِإِذْنِ اللَّهِ قَالَ الْيَهُودِيُّ: لَقَدْ صَدَقْتَ، وَإِنَّكَ لَنَبِيٌّ، ثُمَّ انْصَرَفَ فَذَهَبَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لَقَدْ سَأَلَنِي هَذَا عَنِ الَّذِي سَأَلَنِي عَنْهُ، وَمَا لِي عِلْمٌ بِشَيْءٍ مِنْهُ، حَتَّى أَتَانِيَ اللهُ بِهِ."],"takhrij":"صحيح: رواه مسلم في الحيض (34:315) عن الحسن بن علي بن الحلواني، حدثنا أبو ثوبة (وهو الربيع بن نافع)، حدثنا معاوية (يعني ابن سلام)، عن زيد (يعني أخاه)، أنه سمع أبا سلام، قال: حدثني أبو أسماء الرحبي، أن ثوبان مولى رسول الله صلى الله عليه وسلم حدّثه فذكره.","grade":"صحيح","chapter_ar":"باب جواب النبي ﷺ لبعض الأسئلة التي لا يعلمها من الإنس إلا نبي","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (315:34).","chapter_en":"The Prophet ﷺ Answered Questions Whose Answers No Human Being Knows Except a Prophet","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":16,"content":{"translation":{"en":["Thawbān, the freed slave of the Messenger of Allah ﷺ, said: I was standing beside the Messenger of Allah ﷺ when a Jewish rabbi came and said, “Peace be upon you, Muhammad.” I pushed him so forcefully that he nearly fell. He asked, “Why did you push me?” I replied, “Why did you not say, ‘O Messenger of Allah’?” The Jewish man said, “We call him only by the name his family gave him.” The Messenger of Allah ﷺ said: “My name is Muhammad—the name my family gave me.” The Jewish man said, “I have come to ask you some questions.” The Messenger of Allah ﷺ asked: “Will it benefit you if I answer you?” He replied, “I shall listen with my own ears.” The Messenger of Allah ﷺ began drawing upon the ground with a stick he held and said: “Ask.” The Jewish man asked, “Where will the people be on the day when the earth is changed into another earth, and the heavens as well?” The Messenger of Allah ﷺ replied: “They will be in darkness before the bridge.” He asked, “Who will be the first people permitted to cross?” He replied: “The poor among the Emigrants.” The Jewish man asked, “What will be presented to them when they enter Paradise?” He replied: “The extra lobe of a fish’s liver.” He asked, “What will their meal be after that?” He replied: “The bull of Paradise, which used to graze along its edges, will be slaughtered for them.” He asked, “What will they drink with it?” He replied: “They will drink from a spring therein called Salsabīl.” The Jewish man said, “You have spoken the truth.” He then said, “I have also come to ask you about something that no one on earth knows except a prophet, or perhaps one or two other men.” The Prophet ﷺ asked: “Will it benefit you if I tell you?” He replied, “I shall listen with my own ears. I have come to ask you about the child.” The Prophet ﷺ said: “The man’s reproductive fluid is white, and the woman’s reproductive fluid is yellow. When they meet and the man’s fluid prevails over the woman’s fluid, it results in a male by Allah’s permission. When the woman’s fluid prevails over the man’s fluid, it results in a female by Allah’s permission.” The Jewish man said, “You have indeed spoken the truth, and you are certainly a prophet.” He then turned and departed. The Messenger of Allah ﷺ said: “This man asked me about matters of which I had no knowledge until Allah gave me knowledge of them.”"]}},"tuhfa":{},"voc":["seerah",1665],"full":1,"rep":[12598],"tks":"صحيح: رواه مسلم (34: 315)."},{"num":9706,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ رَضِيَ اللَّهُ عَنْهُ قَالَ: كَانَ رَجُلٌ نَصْرَانِيًّا فَأَسْلَمَ وَقَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ، فَكَانَ يَكْتُبُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَعَادَ نَصْرَانِيًّا، فَكَانَ يَقُولُ: مَا يَدْرِي مُحَمَّدٌ إِلاَّ مَا كَتَبْتُ لَهُ، فَأَمَاتَهُ اللَّهُ فَدَفَنُوهُ، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ، لَمَّا هَرَبَ مِنْهُمْ، نَبَشُوا عَنْ صَاحِبِنَا. فَأَلْقُوهُ، فَحَفَرُوا لَهُ فَأَعْمَقُوا، فَأَصْبَحَ وَقَدْ لَفَظَتْهُ الأَرْضُ، فَقَالُوا: هَذَا فِعْلُ مُحَمَّدٍ وَأَصْحَابِهِ، نَبَشُوا عَنْ صَاحِبِنَا لَمَّا هَرَبَ مِنْهُمْ. فَأَلْقَوْهُ، فَحَفَرُوا لَهُ، وَأَعْمَقُوا لَهُ فِي الأَرْضِ مَا اسْتَطَاعُوا، فَأَصْبَحَ قَدْ لَفَظَتْهُ الأَرْضُ، فَعَلِمُوا: أَنَّهُ لَيْسَ مِنَ النَّاسِ فَأَلْقَوْهُ.","وفي لفظ: كَانَ مِنَّا رَجُلٌ مِنْ بَنِي النَّجَّارِ، قَدْ قَرَأَ الْبَقَرَةَ وَآلَ عِمْرَانَ، وَكَانَ يَكْتُبُ لِرَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَانْطَلَقَ هَارِبًا حَتَّى لَحِقَ بِأَهْلِ الْكِتَابِ، قَالَ فَرَفَعُوهُ، قَالُوا: هَذَا قَدْ كَانَ يَكْتُبُ لِمُحَمَّدٍ، فَأُعْجِبُوا بِهِ، فَمَا لَبِثَ أَنْ قَصَمَ اللَّهُ عُنُقَهُ فِيهِمْ، فَحَفَرُوا لَهُ فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، ثُمَّ عَادُوا فَحَفَرُوا لَهُ، فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، ثُمَّ عَادُوا فَحَفَرُوا لَهُ، فَوَارَوْهُ، فَأَصْبَحَتِ الْأَرْضُ قَدْ نَبَذَتْهُ عَلَى وَجْهِهَا، فَتَرَكُوهُ مَنْبُوذًا."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3617) عن أبي معمر، حدثنا عبد الوارث، حدثنا عبد العزيز، عن أنس فذكره.","grade":"متفق عليه","chapter_ar":"باب لفظ الأرض من كذب على النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3617) and Muslim (2781).","chapter_en":"The Earth Cast Out a Man Who Lied About the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":17,"content":{"translation":{"en":["Anas ibn Mālik said: A Christian man embraced Islam and learned Sūrat al-Baqarah and Sūrat Āl ʿImrān. He used to write for the Prophet ﷺ, but he later returned to Christianity and would say, “Muhammad knows only what I wrote for him.” Allah caused him to die, and his people buried him. By morning, the earth had cast him out. They said, “Muhammad and his Companions did this. Because he fled from them, they dug up our companion and threw him out.” They dug another grave for him and made it deeper. By morning, the earth had again cast him out. They again said, “Muhammad and his Companions did this. Because he fled from them, they dug up our companion and threw him out.” They then dug as deeply into the ground as they possibly could and buried him. By morning, the earth had once more cast him out. They realized that this was not the work of human beings, so they left his body exposed. Another wording states: There was a man from Banū al-Najjār among us who had learned Sūrat al-Baqarah and Sūrat Āl ʿImrān and used to write for the Messenger of Allah ﷺ. He fled and joined the People of the Book.","They held him in high esteem, saying, “This man used to write for Muhammad,” and they admired him. It was not long before Allah caused him to die among them. They dug a grave and concealed him in it, but by morning the earth had thrown him onto its surface. They dug another grave and buried him, but by morning the earth had again thrown him onto its surface. They dug and buried him a third time, but by morning the earth had once more thrown him onto its surface, so they left him lying exposed."]}},"tuhfa":{},"voc":["seerah",1666],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3617)، ومسلم (2781)."},{"num":9707,"demo":false,"sanad":"","matn":["عن الْبَرَاءِ بْنِ عَازِبٍ يَقُولُ: جَاءَ أَبُو بَكْرٍ رَضِيَ اللَّهُ عَنْهُ إِلَى أَبِي فِي مَنْزِلِهِ، فَاشْتَرَى مِنْهُ رَحْلاً، فَقَالَ لِعَازِبٍ: ابْعَثِ ابْنَكَ يَحْمِلْهُ مَعِي. قَالَ: فَحَمَلْتُهُ مَعَهُ، وَخَرَجَ أَبِي يَنْتَقِدُ ثَمَنَهُ، فَقَالَ لَهُ أَبِي: يَا أَبَا بَكْرٍ، حَدِّثْنِي كَيْفَ صَنَعْتُمَا حِينَ سَرَيْتَ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: نَعَمْ، أَسْرَيْنَا لَيْلَتَنَا، وَمِنَ الْغَدِ، حَتَّى قَامَ قَائِمُ الظَّهِيرَةِ، وَخَلاَ الطَّرِيقُ لاَ يَمُرُّ فِيهِ أَحَدٌ، فَرُفِعَتْ لَنَا صَخْرَةٌ طَوِيلَةٌ، لَهَا ظِلٌّ، لَمْ تَأْتِ عَلَيْهِ الشَّمْسُ، فَنَزَلْنَا عِنْدَهُ، وَسَوَّيْتُ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَكَانًا بِيَدِي يَنَامُ عَلَيْهِ، وَبَسَطْتُ فِيهِ فَرْوَةً، وَقُلْتُ: نَمْ يَا رَسُولَ اللَّهِ، وَأَنَا أَنْفُضُ لَكَ مَا حَوْلَكَ. فَنَامَ وَخَرَجْتُ أَنْفُضُ مَا حَوْلَهُ، فَإِذَا أَنَا بِرَاعٍ مُقْبِلٍ بِغَنَمِهِ إِلَى الصَّخْرَةِ، يُرِيدُ مِنْهَا مِثْلَ الَّذِي أَرَدْنَا، فَقُلْتُ: لِمَنْ أَنْتَ يَا غُلاَمُ، فَقَالَ: لِرَجُلٍ مِنْ أَهْلِ الْمَدِينَةِ أَوْ مَكَّةَ. قُلْتُ: أَفِي غَنَمِكَ لَبَنٌ قَالَ: نَعَمُ. قُلْتُ: أَفَتَحْلُبُ، قَالَ: نَعَمْ. فَأَخَذَ شَاةً. فَقُلْتُ: انْفُضِ الضَّرْعَ مِنَ التُّرَابِ وَالشَّعَرِ وَالْقَذَى. قَالَ: فَرَأَيْتُ الْبَرَاءَ يَضْرِبُ إِحْدَى يَدَيْهِ عَلَى الأُخْرَى يَنْفُضُ، فَحَلَبَ فِي قَعْبٍ كُثْبَةً مِنْ لَبَنٍ، وَمَعِي إِدَاوَةٌ حَمَلْتُهَا لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَرْتَوِي مِنْهَا، يَشْرَبُ وَيَتَوَضَّأُ، فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَكَرِهْتُ أَنْ أُوقِظَهُ، فَوَافَقْتُهُ حِينَ اسْتَيْقَظَ، فَصَبَبْتُ مِنَ الْمَاءِ عَلَى اللَّبَنِ حَتَّى بَرَدَ أَسْفَلُهُ، فَقُلْتُ: اشْرَبْ يَا رَسُولَ اللَّهِ، ـ قَالَ: ـ فَشَرِبَ، حَتَّى رَضِيتُ، ثُمَّ قَالَ: أَلَمْ يَأْنِ لِلرَّحِيلِ. قُلْتُ: بَلَى، ـ قَالَ: ـ فَارْتَحَلْنَا بَعْدَ مَا مَالَتِ الشَّمْشُ، وَاتَّبَعَنَا سُرَاقَةُ بْنُ مَالِكٍ، فَقُلْتُ: أُتِينَا يَا رَسُولَ اللَّهِ. فَقَالَ: لاَ تَحْزَنْ، إِنَّ اللَّهَ مَعَنَا. فَدَعَا عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَارْتَطَمَتْ بِهِ فَرَسُهُ إِلَى بَطْنِهَا ـ أُرَى فِي جَلَدٍ مِنَ الأَرْضِ، شَكَّ زُهَيْرٌ ـ فَقَالَ: إِنِّي أُرَاكُمَا قَدْ دَعَوْتُمَا عَلَىَّ، فَادْعُوَا لِي، فَاللَّهُ لَكُمَا أَنْ أَرُدَّ عَنْكُمَا الطَّلَبَ. فَدَعَا لَهُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَجَا، فَجَعَلَ لاَ يَلْقَى أَحَدًا إِلاَّ قَالَ: كَفَيْتُكُمْ مَا هُنَا. فَلاَ يَلْقَى أَحَدًا إِلاَّ رَدَّهُ. قَالَ: وَوَفَى لَنَا."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3615) ومسلم في الزهد (75:2009) كلاهما من طريق زهير بن معاوية، حدثنا أبو إسحاق سمعت البراء بن عازب يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب دعائه ﷺ على سراقة في سفر الهجرة وظهور أثره عليه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3615) and Muslim (2009:75).","chapter_en":"The Prophet ﷺ Supplicated Against Surāqah During the Migration, and Its Effect Became Manifest","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":18,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib said: Abū Bakr came to my father at his home and purchased a camel saddle from him. He said to ʿĀzib, “Send your son with me to carry it.” I carried it with him, while my father accompanied us to receive its price. My father said, “Abū Bakr, tell me what happened when you traveled by night with the Messenger of Allah ﷺ.” Abū Bakr replied: Yes. We traveled throughout that night and continued through the following day until midday arrived and the road became deserted, with no one passing along it. A tall rock appeared before us with a shaded area untouched by the sun. We stopped beside it. With my own hands, I leveled a place where the Prophet ﷺ could sleep. I spread a hide over it and said, “Sleep, O Messenger of Allah, while I examine and clear the surroundings for you.” He slept, and I went out to inspect the surroundings. I then saw a shepherd approaching the rock with his sheep, seeking the same shade that we had sought. I asked him, “Whose servant are you, young man?” He replied, “A man from Madinah”—or Makkah. I asked, “Do your sheep have any milk?” He replied, “Yes.” I asked, “Will you milk one for us?” He replied, “Yes.” He took hold of a sheep, and I told him, “Clear its udder of dust, hair, and dirt.” At this point, I saw al-Barāʾ striking one hand against the other to demonstrate how the shepherd cleaned it. The shepherd milked a quantity of milk into a wooden bowl. I had with me a leather water vessel that I had carried for the Prophet ﷺ so that he could drink and perform ablution from it. I returned to the Prophet ﷺ. I disliked awakening him, but I arrived just as he awoke. I poured water over the milk until its lower portion became cool and said, “Drink, O Messenger of Allah.” He drank until I was satisfied that he had had enough. He then asked: “Has the time not come to depart?” I replied, “Yes.” We resumed our journey after the sun had passed its zenith. Surāqah ibn Mālik began pursuing us. I said, “They have reached us, O Messenger of Allah!” He replied: “Do not grieve; indeed, Allah is with us.” The Prophet ﷺ supplicated against Surāqah, and his horse sank into the firm ground up to its belly—or approximately that far; Zuhayr was uncertain. Surāqah said, “I believe that you have supplicated against me. Supplicate for me now, and I swear by Allah that I shall turn the pursuers away from you.” The Prophet ﷺ supplicated for him, and he was saved. Thereafter, whenever Surāqah encountered anyone searching for them, he would say, “I have dealt with everything in this direction for you.” He turned back everyone he met. Abū Bakr said: “He faithfully fulfilled his promise to us.”"]}},"tuhfa":{},"voc":["seerah",1667],"full":1,"rep":[9825],"tks":"متفق عليه: رواه البخاري (3615)، ومسلم (75: 2009)."},{"num":9708,"demo":false,"sanad":"","matn":["عن البراء بن عازب قَالَ: بَعَثَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى أَبِي رَافِعٍ الْيَهُودِيِّ رِجَالاً مِنَ الأَنْصَارِ، فَأَمَّرَ عَلَيْهِمْ عَبْدَ الله بْنَ عَتِيكٍ، وَكَانَ أَبُو رَافِعٍ يُؤْذِي رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَيُعِينُ عَلَيْهِ، وَكَانَ فِي حِصْنٍ لَهُ بِأَرْضِ الحِجَازِ، فَلَمَّا دَنَوْا مِنْهُ، وَقَدْ غَرَبَتِ الشَّمْسُ، وَرَاحَ النَّاسُ بِسَرْحِهِمْ فَقَالَ عَبْدُ الله لأَصْحَابِهِ: اجْلِسُوا مَكَانَكُمْ، فَإِنِّي مُنْطَلِقٌ، وَمُتَلَطِّفٌ لِلْبَوَّابِ، لَعَلِّي أَنْ أَدْخُلَ. فَأَقْبَلَ حَتَّى دَنَا مِنَ الْبَابِ، ثُمَّ تَقَنَّعَ بِثَوْبِهِ كَأَنَّهُ يَقْضِي حَاجَةً، وَقَدْ دَخَلَ النَّاسُ، فَهَتَفَ بِهِ الْبَوَّابُ: يَا عَبْدَ الله إِنْ كُنْتَ تُرِيدُ أَنْ تَدْخُلَ فَادْخُلْ، فَإِنِّي أُرِيدُ أَنْ أُغْلِقَ الْبَابَ. فَدَخَلْتُ فَكَمَنْتُ، فَلَمَّا دَخَلَ النَّاسُ أَغْلَقَ الْبَابَ، ثُمَّ عَلَّقَ الأَغَالِيقَ عَلَى وَتَدٍ قَالَ فَقُمْتُ إِلَى الأَقَالِيدِ، فَأَخَذْتُهَا فَفَتَحْتُ الْبَابَ، وَكَانَ أَبُو رَافِعٍ يُسْمَرُ عِنْدَهُ، وَكَانَ فِي عَلاَلِيَّ لَهُ، فَلَمَّا ذَهَبَ عَنْهُ أَهْلُ سَمَرِهِ صَعِدْتُ إِلَيْهِ، فَجَعَلْتُ كُلَّمَا فَتَحْتُ بَابًا أَغْلَقْتُ عَلَيَّ مِنْ دَاخِلٍ، قُلْتُ إِنِ الْقَوْمُ نَذِرُوا بِي لَمْ يَخْلُصُوا إِلَيَّ حَتَّى أَقْتُلَهُ. فَانْتَهَيْتُ إِلَيْهِ، فَإِذَا هُوَ فِي بَيْتٍ مُظْلِمٍ وَسْطَ عِيَالِهِ، لاَ أَدْرِي أَيْنَ هُوَ مِنَ الْبَيْتِ فَقُلْتُ: يَا أَبَا رَافِعٍ. قَالَ: مَنْ هَذَا؟ فَأَهْوَيْتُ نَحْوَ الصَّوْتِ، فَأَضْرِبُهُ ضَرْبَةً بِالسَّيْفِ، وَأَنَا دَهِشٌ فَمَا أَغْنَيْتُ شَيْئًا، وَصَاحَ فَخَرَجْتُ مِنَ الْبَيْتِ، فَأَمْكُثُ غَيْرَ بَعِيدٍ ثُمَّ دَخَلْتُ إِلَيْهِ فَقُلْتُ: مَا هَذَا الصَّوْتُ يَا أَبَا رَافِعٍ؟ فَقَالَ: لأُمِّكَ الْوَيْلُ، إِنَّ رَجُلاً فِي الْبَيْتِ ضَرَبَنِي قَبْلُ بِالسَّيْفِ، قَالَ: فَأَضْرِبُهُ ضَرْبَةً أَثْخَنَتْهُ وَلَمْ أَقْتُلْهُ، ثُمَّ وَضَعْتُ ضبيب السَّيْفِ فِي بَطْنِهِ حَتَّى أَخَذَ فِي ظَهْرِهِ، فَعَرَفْتُ أَنِّي قَتَلْتُهُ، فَجَعَلْتُ أَفْتَحُ الأَبْوَابَ بَابًا بَابًا حَتَّى انْتَهَيْتُ إِلَى دَرَجَةٍ لَهُ، فَوَضَعْتُ رِجْلِي وَأَنَا أُرَى أَنِّي قَدِ انْتَهَيْتُ إِلَى الأَرْضِ فَوَقَعْتُ فِي لَيْلَةٍ مُقْمِرَةٍ، فَانْكَسَرَتْ سَاقِي، فَعَصَبْتُهَا بِعِمَامَةٍ، ثُمَّ انْطَلَقْتُ حَتَّى جَلَسْتُ عَلَى الْبَابِ فَقُلْتُ لاَ أَخْرُجُ اللَّيْلَةَ حَتَّى أَعْلَمَ أَقَتَلْتُهُ؟ فَلَمَّا صَاحَ الدِّيكُ قَامَ النَّاعِي عَلَى السُّورِ فَقَالَ :أَنْعَى أَبَا رَافِعٍ تَاجِرَ أَهْلِ الْحِجَازِ. فَانْطَلَقْتُ إِلَى أَصْحَابِي فَقُلْتُ النَّجَاءَ، فَقَدْ قَتَلَ الله أَبَا رَافِعٍ. فَانْتَهَيْتُ إِلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَحَدَّثْتُهُ فَقَالَ: ابْسُطْ رِجْلَكَ فَبَسَطْتُ رِجْلِي، فَمَسَحَهَا، فَكَأَنَّهَا لَمْ أَشْتَكِهَا قَطُّ."],"takhrij":"صحيح: رواه البخاري في المغازي (4039) عن يوسف بن موسى، حدثنا عبيد الله بن موسى، عن إسرائيل، عن أبي إسحاق، عن البراء قال: فذكره.","grade":"صحيح","chapter_ar":"باب شفاء عبد الله بن عتيك بمسح النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4039).","chapter_en":"ʿAbdullāh ibn ʿAtīk Was Healed by the Prophet’s Touch ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":19,"content":{"translation":{"en":["Al-Barāʾ ibn ʿĀzib reported: The Messenger of Allah ﷺ sent a group of Anṣār to Abū Rāfiʿ the Jew and appointed ʿAbdullāh ibn ʿAtīk as their leader. Abū Rāfiʿ used to harm the Messenger of Allah ﷺ and assist others against him. He lived in a fortress in the land of the Ḥijāz. When the men drew near after sunset, the people were returning with their grazing animals. ʿAbdullāh said to his companions, “Remain where you are. I shall go ahead and deal tactfully with the gatekeeper so that I may be able to enter.” He approached the gate and, when he came near it, covered himself with his garment as though relieving himself. By then, the people had entered the fortress. The gatekeeper called to him, “Servant of Allah, if you wish to enter, then enter, for I am about to close the gate.” ʿAbdullāh continued: I entered and concealed myself. When all the people had entered, the gatekeeper closed the gate and hung its keys upon a peg. I went to the keys, took them, and opened the gate. People used to gather with Abū Rāfiʿ in the evening, and he was staying in some upper rooms belonging to him. When his evening guests departed, I climbed up to him. Whenever I opened a door, I locked it behind me from the inside. I thought: If the people discover me, they will not be able to reach me before I kill him. I eventually reached him. He was in a dark room surrounded by his family, and I did not know where in the room he was. I called, “Abū Rāfiʿ!” He asked, “Who is that?” I moved toward the sound and struck him with my sword. I was startled and confused, so the blow accomplished nothing decisive. He cried out, and I left the room. I waited nearby for a short time and then reentered, saying, “What was that sound, Abū Rāfiʿ?” He replied, “May your mother be bereaved of you! A man in the house struck me with a sword a moment ago.” I struck him again with a blow that wounded him severely but did not kill him. I then placed the point of my sword against his abdomen and drove it through until it reached his back. I knew then that I had killed him. I began opening the doors one after another until I reached a stairway belonging to the house. Thinking I had reached the ground, I stepped forward and fell. It was a moonlit night, and my leg broke. I bound it with my turban. I then went and sat at the gate, saying to myself: I shall not leave tonight until I know whether I killed him. When the rooster crowed, a herald stood upon the wall and announced, “I proclaim the death of Abū Rāfiʿ, the merchant of the people of the Ḥijāz.” I went to my companions and said, “Escape! Allah has killed Abū Rāfiʿ.” When I reached the Prophet ﷺ, I told him what had happened. He said: “Extend your leg.” I extended it, and he passed his hand over it. Thereafter, it was as though I had never suffered any pain in it."]}},"tuhfa":{},"voc":["seerah",1668],"full":1,"tks":"صحيح: رواه البخاري (4039)."},{"num":9709,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ أَبِي عُبَيْدٍ قَالَ: رَأَيْتُ أَثَرَ ضَرْبَةٍ فِي سَاقِ سَلَمَةَ، فَقُلْتُ: يَا أَبَا مُسْلِمٍ، مَا هَذِهِ الضَّرْبَةُ؟ قَالَ هَذِهِ ضَرْبَةٌ أَصَابَتْنِي يَوْمَ خَيْبَرَ، فَقَالَ النَّاسُ: أُصِيبَ سَلَمَةُ. فَأَتَيْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَفَثَ فِيهِ ثَلاَثَ نَفَثَاتٍ، فَمَا اشْتَكَيْتُهَا حَتَّى السَّاعَةِ."],"takhrij":"صحيح: رواه البخاري في المغازي (4206) عن المكي بن إبراهيم، حدثنا يزيد بن أبي عبيد فذكره.","grade":"صحيح","chapter_ar":"شفاء سلمة بن الأكوع بنفث النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Military Campaigns (4206), from al-Makkī ibn Ibrāhīm, from Yazīd ibn Abī ʿUbayd, who related it.","chapter_en":"Salamah ibn al-Akwaʿ Was Healed by the Prophet’s Blowing ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":20,"content":{"translation":{"en":["Yazīd ibn Abī ʿUbayd said: I saw the mark of a wound upon Salamah’s leg and asked, “Abū Muslim, what is this wound?” He replied: “This is a wound I received on the day of Khaybar. The people said, ‘Salamah has been wounded.’ I went to the Prophet ﷺ, and he blew lightly upon it three times. I have not felt any pain from it up to this very moment.”"]}},"tuhfa":{},"voc":["seerah",1669],"full":1,"rep":[9081,10224],"tks":"صحيح: رواه البخاري (4206)."},{"num":9710,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ! إِنِّي سَمِعْتُ مِنْكَ حَدِيثًا كَثِيرًا فَأَنْسَاهُ فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : ابْسُطْ رِدَاءَكَ فَبَسَطْتُ فَغَرَفَ بِيَدِهِ فِيهِ ثُمَّ قَالَ: ضُمَّهُ فضممت، فَمَا نَسِيتُ حَدِيثًا بَعْدُ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3648) عن إبراهيم بن المنذر، حدثنا ابن أبي الفديك، عن ابن أبي ذئب، عن المقبري، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب دعاء النبي ﷺ لقوة حفظ أبي هريرة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3648).","chapter_en":"The Prophet ﷺ Supplicated That Abū Hurayrah Be Granted a Powerful Memory","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":21,"content":{"translation":{"en":["Abū Hurayrah said: I said, “O Messenger of Allah, I hear many hadiths from you, but I forget them.” The Prophet ﷺ said: “Spread out your outer garment.” I spread it out. He made a scooping motion with his hand into it and then said: “Gather it and hold it against yourself.” I gathered it against myself, and after that I never forgot a hadith."]}},"tuhfa":{},"voc":["seerah",1670],"full":1,"tks":"صحيح: رواه البخاري (3648)."},{"num":9711,"demo":false,"sanad":"","matn":["عن أَبِي زيد عمر بن أَخْطَبَ الأنصاري قَالَ: قَالَ لِي رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: ادْنُ مِنِّي، قَالَ: فَمَسَحَ بِيَدِهِ عَلَى رَأْسِهِ، وَلِحْيَتِهِ، قَالَ: ثُمَّ قَالَ: اللهُمَّ جَمِّلْهُ، وَأَدِمْ جَمَالَهُ، قَالَ: فَلَقَدْ بَلَغَ بِضْعًا، وَمِائَةَ سَنَةٍ وَمَا فِي رَأْسِهِ وَلِحْيَتِهِ بَيَاضٌ، إِلَّا نَبْذٌ يَسِيرٌ، وَلَقَدْ كَانَ مُنْبَسِطَ الْوَجْهِ، وَلَمْ يَنْقَبِضْ وَجْهُهُ حَتَّى مَاتَ."],"takhrij":"حسن: رواه أحمد (20733) واللفظ له – والترمذي (3629) وأبو يعلى (6847) وابن حبان (7171) كلهم من طريق عزرة بن ثابت الأنصاري، حدثنا علباء بن أحمر، حدثنا أبو زيد عمرو بن أخطب فذكره.","grade":"حسن","chapter_ar":"باب دعاء النبي ﷺ لعمرو بن أخطب بجماله","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (20733), whose wording this is; al-Tirmidhī (3629); Abū Yaʿlā (6847); and Ibn Ḥibbān (7171).","chapter_en":"The Prophet ﷺ Supplicated That ʿAmr ibn Akhṭab Retain His Handsomeness","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":22,"content":{"translation":{"en":["Abū Zayd ʿAmr ibn Akhṭab al-Anṣārī said: The Messenger of Allah ﷺ said to me: “Come near me.” He passed his hand over my head and beard and then supplicated: “O Allah, make him handsome and preserve his handsomeness.” He lived to be more than one hundred years old, yet there were only a few scattered white hairs upon his head and in his beard. His face remained smooth and radiant and did not become wrinkled or contracted before his death."]}},"tuhfa":{},"voc":["seerah",1671],"full":1,"dr":1,"tks":"حسن: رواه أحمد (20733) واللفظ له، والترمذي (3629)، وأبو يعلى (6847)، وابن حبان (7171)."},{"num":9712,"demo":false,"sanad":"","matn":["عَنِ الْجُعَيْدِ بْنِ عَبْدِ الرَّحْمَنِ، رَأَيْتُ السَّائِبَ بْنَ يَزِيدَ ابْنَ أَرْبَعٍ وَتِسْعِينَ جَلْدًا مُعْتَدِلاً فَقَالَ: قَدْ عَلِمْتُ مَا مُتِّعْتُ بِهِ سَمْعِي وَبَصَرِي إِلاَّ بِدُعَاءِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، إِنَّ خَالَتِي ذَهَبَتْ بِي إِلَيْهِ فَقَالَتْ يَا رَسُولَ اللَّهِ، إِنَّ ابْنَ أُخْتِي شَاكٍ فَادْعُ اللَّهَ. قَالَ: فَدَعَا لِي."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3540) عن إسحاق بن إبراهيم، أخبرنا الفضل بن موسى، عن الجعيد بن عبد الرحمن فذكره. ورواه مسلم في الفضائل (111:2345) من طريق آخر عن الجعد بن عبدالرحمن به.","grade":"متفق عليه","chapter_ar":"دعاؤه ﷺ للسائب بن يزيد وظهور بركته عليه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3540) and Muslim (2345:111).","chapter_en":"The Prophet’s Supplication ﷺ for al-Sā’ib ibn Yazīd and the Manifestation of Its Blessing upon Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":23,"content":{"translation":{"en":["Al-Juʿayd ibn ʿAbd al-Raḥmān said: I saw al-Sā’ib ibn Yazīd when he was ninety-four years old, still strong and upright. He said: “I know that the continued enjoyment of my hearing and eyesight is due only to the supplication of the Messenger of Allah ﷺ. My maternal aunt took me to him and said, ‘O Messenger of Allah, my sister’s son is ill, so supplicate to Allah for him.’ He then supplicated for me.”"]}},"tuhfa":{},"voc":["seerah",1672],"full":1,"tks":"متفق عليه: رواه البخاري (3540)، ومسلم (111: 2345)."},{"num":9713,"demo":false,"sanad":"","matn":["عَنِ أَبِي الْعَلَاءِ بْنِ عُمَيْرٍ، قَالَ: كُنْتُ عِنْدَ قَتَادَةَ بْنِ مِلْحَانَ حِينَ حُضِرَ، فَمَرَّ رَجُلٌ فِي أَقْصَى الدَّارِ، قَالَ: فَأَبْصَرْتُهُ فِي وَجْهِ قَتَادَةَ، قَالَ: وَكُنْتُ إِذَا رَأَيْتُهُ كَأَنَّ عَلَى وَجْهِهِ الدِّهَانَ، قَالَ: وَكَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَسَحَ عَلَى وَجْهِهِ."],"takhrij":"صحيح: رواه أحمد (20317) ومن طريقه البيهقي في الدلائل (2241) عن عارم (هو: محمد بن الفضل) حدثنا معتمر قال: وحدث أبي، عن أبي العلاء بن عمير فذكره.","grade":"صحيح","chapter_ar":"باب أثر مسح النبي ﷺ على وجه قتادة بن ملحان","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (20317).","chapter_en":"The Lasting Effect of the Prophet’s Touch ﷺ upon the Face of Qatādah ibn Milḥān","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":24,"content":{"translation":{"en":["Abū al-ʿAlāʾ ibn ʿUmayr said: I was present with Qatādah ibn Milḥān when death approached him. A man passed by at the far end of the house, and I saw his reflection upon Qatādah’s face. Whenever I looked at him, it appeared as though oil had been applied to his face. The Messenger of Allah ﷺ had passed his hand over his face."]}},"tuhfa":{},"voc":["seerah",1673],"full":1,"dr":1,"tks":"صحيح: رواه أحمد (20317)."},{"num":9714,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ يوم خَيْبَرَ: لأُعْطِيَنَّ هَذِهِ الرَّايَةَ رَجُلاً يَفْتَحُ اللَّهُ عَلَى يَدَيْهِ، يحب الله ورسوله، ويحبه الله ورسوله قَالَ: فَبَاتَ النَّاسُ يَدُوكُونَ لَيْلَتَهُمْ أَيُّهُمْ يُعْطَاهَا، قَالَ: فَلَمَّا أَصْبَحَ النَّاسُ غَدَوْا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كُلُّهُمْ يرجون أَنْ يُعْطَاهَا فَقَالَ: أَيْنَ عَلِيُّ بْنُ أَبِي طَالِبٍ؟ فَقَالُوا: هُوَ يَا رَسُولَ اللَّهِ يَشْتَكِي عَيْنَيْهِ، فَدَعَا لَهُ فَبَرَأَ حَتَّى كَأَنْ لَمْ يَكُنْ بِهِ وَجَعٌ...الحديث فِي قِصَّةِ خيبر."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4210) ومسلم في فضائل الصحابة (34:2406) كلاهما عن قتيبة بن سعيد، حدثنا يعقوب بن عبد الرحمن، عن أبي حازم أخبرني سهل بن سعد فذكره.","grade":"متفق عليه","chapter_ar":"شفاء علي بن أبي طالب ببصاقه ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4210) and Muslim (2406:34).","chapter_en":"ʿAlī ibn Abī Ṭālib Was Healed by the Prophet’s Saliva ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":25,"content":{"translation":{"en":["Sahl ibn Saʿd reported that on the day of Khaybar, the Messenger of Allah ﷺ said: “I shall certainly give this banner to a man through whose hands Allah will grant victory. He loves Allah and His Messenger, and Allah and His Messenger love him.” The people spent the night discussing among themselves which of them would be given the banner. When morning came, they all went early to the Messenger of Allah ﷺ, each hoping that it would be given to him. He asked: “Where is ʿAlī ibn Abī Ṭālib?” They replied, “O Messenger of Allah, he is suffering from pain in his eyes.” The Prophet ﷺ supplicated for him, and he was healed until it was as though he had never suffered any pain. The remainder of the hadith concerns the account of Khaybar."]}},"tuhfa":{},"voc":["seerah",1674],"full":1,"tks":"متفق عليه: رواه البخاري (4210)، ومسلم (34: 2406)."},{"num":9715,"demo":false,"sanad":"","matn":["عَنْ علي قَالَ: مَا رَمِدْتُ وَلَا صُدِعْتُ مُنْذُ مَسَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَجْهِي، وَتَفَلَ فِي عَيْنَيَّ يَوْمَ خَيْبَرَ حِينَ أَعْطَانِي الرَّايَةَ."],"takhrij":"حسن: رواه أحمد (579) مختصرا، وأبو يعلى (593) – واللفظ له – وأبو داود الطيالسي (185) كلهم من طرق عن المغيرة بن مقسم الضبي، عن أم موسى، قالت: سمعت عليّاً يقول: فذكره.","grade":"حسن","chapter_ar":"شفاء علي بن أبي طالب ببصاقه ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated in abridged form by Aḥmad (579), Abū Yaʿlā (593)—whose wording this is—and Abū Dāwūd al-Ṭayālisī (185).","chapter_en":"ʿAlī ibn Abī Ṭālib Was Healed by the Prophet’s Saliva ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":25,"content":{"translation":{"en":["ʿAlī ibn Abī Ṭālib said: “I have neither suffered inflammation of the eyes nor experienced a headache since the Messenger of Allah ﷺ passed his hand over my face and spat lightly into my eye on the day of Khaybar, when he gave me the banner.”"]}},"tuhfa":{},"voc":["seerah",1675],"full":1,"dr":1,"tks":"حسن: رواه أحمد (579) مختصرا، وأبو يعلى (593) - واللفظ له - وأبو داود الطيالسي (185)."},{"num":9716,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ تَفَلَ فِي رِجْلِ عَمْرِو بْنِ مُعَاذٍ حِينَ قُطِعَتْ رِجْلُهُ فَبَرَأَ."],"takhrij":"حسن: رواه ابن حبان (6509) وأبو نعيم في معرفة الصحابة (5118) كلاهما من طريق الحسين بن حريث أبي عمار، حدثنا علي بن الحسين بن واقد، حدثني أبي، حدثني عبد الله بن بريدة قال: سمعت أبي بريدة يقول: فذكره.","grade":"حسن","chapter_ar":"بُرْءُ رِجْلِ عمرو بن معاذ بتفل النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Ḥibbān (6509) and Abū Nuʿaym in Maʿrifat al-Ṣaḥābah (4/2036).","chapter_en":"The Leg of ʿAmr ibn Muʿādh Was Healed by the Prophet’s Spittle ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في معجزات النبي ﷺ ودلائل نبوته","group_en":"A Collection Concerning the Miracles of the Prophet ﷺ and the Proofs of His Prophethood","part_no":48,"group_no":37,"chapter_no":26,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said: The Messenger of Allah ﷺ spat lightly upon the leg of ʿAmr ibn Muʿādh when his leg had been severed, and it was healed."]}},"tuhfa":{},"voc":["seerah",1676],"full":1,"dr":1,"tks":"حسن: رواه ابن حبان (6509)، وأبو نعيم في معرفة الصحابة (5118)."},{"num":9717,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ رَضِيَ اللَّهُ عَنْهَا قَالَتْ: دَعَا النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَاطِمَةَ ابْنَتَهُ فِي شَكْوَاهُ الَّذِي قُبِضَ فِيهِ، فَسَارَّهَا بِشَىْءٍ فَبَكَتْ، ثُمَّ دَعَاهَا، فَسَارَّهَا فَضَحِكَتْ، قَالَتْ: فَسَأَلْتُهَا عَنْ ذَلِكَ. فَقَالَتْ: سَارَّنِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَأَخْبَرَنِي أَنَّهُ يُقْبَضُ فِي وَجَعِهِ الَّذِي تُوُفِّيَ فِيهِ فَبَكَيْتُ، ثُمَّ سَارَّنِي فَأَخْبَرَنِي أَنِّي أَوَّلُ أَهْلِ بَيْتِهِ أَتْبَعُهُ فَضَحِكْتُ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3626،3625) ومسلم في الفضائل (2450) كلاهما من حديث إبراهيم بن سعد، عن أبيه، عن عروة، عن عائشة فذكرته. وتوفيت فاطمة –رضي الله عنها- بعد وفاة أبيها بستة أشهر.","grade":"متفق عليه","chapter_ar":"باب إخبار النبي ﷺ بأن فاطمة تكون أول من تلحق بالنبي ﷺ من أهل بيته","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3625, 3626) and Muslim (2450).","chapter_en":"The Prophet ﷺ Foretold That Fāṭimah Would Be the First of His Household to Join Him","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":1,"content":{"translation":{"en":["ʿĀ’ishah said: During the illness in which the Prophet ﷺ passed away, he called his daughter Fāṭimah and whispered something to her, whereupon she wept. He then called her again and whispered something to her, whereupon she laughed. I later asked her about that, and she said: “The Prophet ﷺ privately informed me that he would pass away during the illness from which he was then suffering, so I wept. He then privately informed me that I would be the first member of his household to follow him, so I laughed.”"]}},"tuhfa":{},"voc":["seerah",1677],"full":1,"tks":"متفق عليه: رواه البخاري (3625، 3626)، ومسلم (2450)."},{"num":9718,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ أُمِّ الْمُؤْمِنِينَ قَالَتْ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  أَسْرَعُكُنَّ لَحَاقًا بِي أَطْوَلُكُنَّ يَدًا.","قَالَتْ: فَكُنَّ يَتَطَاوَلْنَ أَيَّتُهُنَّ أَطْوَلُ يَدًا. قَالَتْ: فَكَانَتْ أَطْوَلَنَا يَدًا زَيْنَبُ؛ لِأَنَّهَا كَانَتْ تَعْمَلُ بِيَدِهَا، وَتَصَدَّقُ."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (2452) عن محمود بن غيلان، حدثنا الفضل بن موسى السيناني، أخبرنا طلحة بن يحيى بن طلحة، عن عائشة بنت طلحة، عن عائشة أم المؤمنين فذكرته.","grade":"صحيح","chapter_ar":"باب أن أسرع أزواجه لحوقًا به أطولهن يدًا","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2452).","chapter_en":"The First of His Wives to Join Him Would Be the One with the Longest Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah, Mother of the Believers, said that the Messenger of Allah ﷺ said: “The first of you to join me will be the one with the longest hand.” She said: They began measuring themselves to determine which of them had the longest hand. Zaynab proved to have the longest hand among us because she used to work with her hands and give generously in charity."]},"buhuth":{"en":["What the Prophet ﷺ meant by “the longest hand” was abundance in charity, not literal physical length. According to the unanimous agreement of the scholars of prophetic biography, Zaynab was the first of his wives to join him after his death, and she was known for giving abundant charity. From this, the omission that occurred in the following narration of al-Bukhārī becomes apparent:"]}},"tuhfa":{},"voc":["seerah",1678],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (2452)."},{"num":9719,"demo":false,"sanad":"","matn":["عَنْ عَائِشَةَ، رَضِيَ اللَّهُ عَنْهَا أَنَّ بَعْضَ، أَزْوَاجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْنَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَيُّنَا أَسْرَعُ بِكَ لُحُوقًا؟ قَالَ: أَطْوَلُكُنَّ يَدًا. فَأَخَذُوا قَصَبَةً يَذْرَعُونَهَا، فَكَانَتْ سَوْدَةُ أَطْوَلَهُنَّ يَدًا، فَعَلِمْنَا بَعْدُ أَنَّمَا كَانَتْ طُولَ يَدِهَا الصَّدَقَةُ، وَكَانَتْ أَسْرَعَنَا لُحُوقًا بِهِ وَكَانَتْ تُحِبُّ الصَّدَقَةَ."],"takhrij":"صحيح: رواه البخاري في الزكاة (1420) عن موسى بن إسماعيل، حدثنا أبو عوانة، عن فراس، عن الشعبي، عن مسروق، عن عائشة فذكرته.","grade":"صحيح","chapter_ar":"باب أن أسرع أزواجه لحوقًا به أطولهن يدًا","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1420). Her statement, “She was the first of us to join him,” refers to Zaynab, whose name was omitted from this narration. Zaynab died in the year 20 AH, whereas Sawdah died near the end of ʿUmar’s caliphate, who died in 23 AH.","chapter_en":"The First of His Wives to Join Him Would Be the One with the Longest Hand","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":2,"content":{"translation":{"en":["ʿĀ’ishah reported that some of the Prophet’s wives asked him ﷺ: “Which of us will be the first to join you?” He replied: “The one of you with the longest hand.” They took a reed and began measuring their hands with it, and Sawdah had the longest hand among them. We later came to understand that the meaning of having a long hand was giving in charity. She was the first of us to join him, and she loved giving charity."]}},"tuhfa":{},"voc":["seerah",1679],"full":1,"dr":1,"rep":[10410],"tks":"صحيح: رواه البخاري (1420). وقولها: «وكانت أسرعنا لحوقا به» أي زينب، التي سقط ذكرها من هذه الرواية، وهي ماتت سنة عشرين، وماتت سودة في آخر خلافة عمر (ت 23ه)."},{"num":9720,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ رَضِيَ اللَّهُ عَنْهُ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَى جَعْفَرًا، وَزَيْدًا قَبْلَ أَنْ يَجِيءَ خَبَرُهُمْ، وَعَيْنَاهُ تَذْرِفَانِ."],"takhrij":"صحيح: رواه البخاري في المناقب (3630) عن سليمان بن حرب، حدثنا حماد بن زيد، عن أيوب، عن حميد بن هلال، عن أنس بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب نعي جعفر وزيد قبل أن يجيء خبرهم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3630).","chapter_en":"The Prophet ﷺ Announced the Deaths of Jaʿfar and Zayd Before News of Them Arrived","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":3,"content":{"translation":{"en":["Anas reported: The Prophet ﷺ announced the deaths of Jaʿfar and Zayd before news of their deaths arrived, while tears flowed from his eyes."]}},"tuhfa":{},"voc":["seerah",1680],"full":1,"tks":"صحيح: رواه البخاري (3630)."},{"num":9721,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ أَنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ نَعَى زَيْدًا وَجَعْفَرًا وَابْنَ رَوَاحَةَ لِلنَّاسِ، قَبْلَ أَنْ يَأْتِيَهُمْ خَبَرُهُمْ فَقَالَ: أَخَذَ الرَّايَةَ زَيْدٌ فَأُصِيبَ، ثُمَّ أَخَذَ جَعْفَرٌ فَأُصِيبَ، ثُمَّ أَخَذَ ابْنُ رَوَاحَةَ فَأُصِيبَ وَعَيْنَاهُ تَذْرِفَانِ حَتَّى أَخَذَ الرَّايَةَ سَيْفٌ مِنْ سُيُوفِ الله حَتَّى فَتَحَ الله عَلَيْهِمْ."],"takhrij":"صحيح: رواه البخاري في المغازي (4262) عن أحمد بن واقد، حدثنا حماد بن زيد، عن أيوب، عن حميد بن هلال، عن أنس قال: فذكره.","grade":"صحيح","chapter_ar":"باب نعي جعفر وزيد قبل أن يجيء خبرهم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4262).","chapter_en":"The Prophet ﷺ Announced the Deaths of Jaʿfar and Zayd Before News of Them Arrived","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":3,"content":{"translation":{"en":["Anas reported: Before news reached the people, the Prophet ﷺ announced to them the deaths of Zayd, Jaʿfar, and Ibn Rawāḥah. He said: “Zayd took the banner and was struck down. Then Jaʿfar took it and was struck down. Then Ibn Rawāḥah took it and was struck down.” His eyes were shedding tears as he continued: “Then one of the swords of Allah took the banner, and Allah granted them victory through him.”"]}},"tuhfa":{},"voc":["seerah",1681],"full":1,"rep":[9118],"tks":"صحيح: رواه البخاري (4262)."},{"num":9722,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لاَ تَقُومُ السَّاعَةُ حَتَّى يَقْتَتِلَ فِئَتَانِ، فَيَكُونَ بَيْنَهُمَا مَقْتَلَةٌ عَظِيمَةٌ دَعْوَاهُمَا وَاحِدَةٌ."],"takhrij":"متفق عليه: رواه البخاري في المناقب (3609)، ومسلم في الفتن (2888: 17) كلاهما من حديث عبد الرزاق، حدثنا معمر، عن همام بن منبه قال: هذا ما حدثنا أبو هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب مقتلة عظيمة بين الفئتين كلٌّ منهما يدّعي الإسلام","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3609) and Muslim (2888:17).","chapter_en":"A Great Slaughter Between Two Groups, Each Professing Islam","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":4,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “The Hour will not be established until two groups fight one another and a great slaughter occurs between them, although their claim is one and the same.”"]},"buhuth":{"en":["This prophecy was fulfilled through what occurred between ʿAlī ibn Abī Ṭālib and Muʿāwiyah ibn Abī Sufyān at Ṣiffīn, between the forces of Syria and Iraq.","The statement, “Their claim is one and the same,” means that their religion is one: both groups affiliate themselves with Islam, and each claims to be upon the truth."]}},"tuhfa":{},"voc":["seerah",1682],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (3609)، ومسلم (2888: 17)."},{"num":9723,"demo":false,"sanad":"","matn":["عن أَبِي بَكْرَةَ يَقُولُ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَلَى الْمِنْبَرِ، وَالْحَسَنُ بْنُ عَلِيٍّ إِلَى جَنْبِهِ، وَهْوَ يُقْبِلُ عَلَى النَّاسِ مَرَّةً، وَعَلَيْهِ أُخْرَى وَيَقُولُ: إِنَّ ابْنِي هَذَا سَيِّدٌ، وَلَعَلَّ اللَّهَ أَنْ يُصْلِحَ بِهِ بَيْنَ فِئَتَيْنِ عَظِيمَتَيْنِ مِنَ الْمُسْلِمِينَ."],"takhrij":"صحيح: رواه البخاري في الصلح (2704) عن عبد الله بن محمد: حدثنا سفيان، عن أبي موسى قال: سمعت الحسن يقول: استقبل والله الحسن بن علي معاويةَ بكتائب أمثال الجبال، فقال عمرو بن العاص: إني لأرى كتائب لا تولي حتى تقتل أقرانها، فقال له معاوية - وكان والله خير الرجلين - أي عمرو، إن قتل هؤلاء هؤلاء، وهؤلاء هؤلاء، من لي بأمور الناس، من لي بنسائهم، من لي بضيعتهم، فبعث إليه رجلين من قريش، من بني عبد شمس، عبد الرحمن بن سمرة وعبد الله بن عامر بن كريز، فقال: اذهبا إلى هذا الرجل، فاعرضا عليه، وقولا له، واطلبا إليه. فأتياه فدخلا عليه، فتكلما وقالا له، فطلبا إليه، فقال لهما الحسن بن علي: إنا بنو عبد المطلب، قد أصبنا من هذا المال، وإن هذه الأمة قد عاثت في دمائها. قالا: فإنه يعرض عليك كذا وكذا، ويطلب إليك ويسألك، قال: فمن لي بهذا؟ قالا: نحن لك به، فما سألهما شيئا إلا قالا: نحن لك به، فصالحه. فقال الحسن: ولقد سمعت أبا بكرة يقول: فذكره.","grade":"صحيح","chapter_ar":"باب الصلح بين الحسن بن علي ومعاوية","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2704).","chapter_en":"The Reconciliation Between al-Ḥasan ibn ʿAlī and Muʿāwiyah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":5,"content":{"translation":{"en":["Abū Bakrah said: I saw the Messenger of Allah ﷺ upon the pulpit with al-Ḥasan ibn ʿAlī beside him. He would turn toward the people at one moment and toward al-Ḥasan at another, saying: “This son of mine is a leader, and perhaps Allah will bring reconciliation through him between two great groups of Muslims.”"]}},"tuhfa":{},"voc":["seerah",1683],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (2704)."},{"num":9724,"demo":false,"sanad":"","matn":["عن عَمْرو بْنُ مَيْمُونٍ، أَنَّهُ سَمِعَ عَبْدَ الله بْنَ مَسْعُودٍ حَدَّثَ عَنْ سَعْدِ بْنِ مُعَاذٍ، أَنَّهُ قَالَ: كَانَ صَدِيقًا لأُمَيَّةَ بْنِ خَلَفٍ، وَكَانَ أُمَيَّةُ إِذَا مَرَّ بِالمَدِينَةِ نَزَلَ عَلَى سَعْدٍ، وَكَانَ سَعْدٌ إِذَا مَرَّ بِمَكَّةَ نَزَلَ عَلَى أُمَيَّةَ، فَلَمَّا قَدِمَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ المَدِينَةَ انْطَلَقَ سَعْدٌ مُعْتَمِرًا، فَنَزَلَ عَلَى أُمَيَّةَ بِمَكَّةَ، فَقَالَ لأُمَيَّةَ: انْظُرْ لِي سَاعَةَ خَلْوَةٍ لَعَلِّي أَنْ أَطُوفَ بِالْبَيْتِ. فَخَرَجَ بِهِ قَرِيبًا مِنْ نِصْفِ النَّهَارِ، فَلَقِيَهُمَا أَبُو جَهْلٍ فَقَالَ: يَا أَبَا صَفْوَانَ، مَنْ هَذَا مَعَكَ؟ فَقَالَ: هَذَا سَعْدٌ. فَقَالَ لَهُ أَبُو جَهْلٍ: أَلاَ أَرَاكَ تَطُوفُ بِمَكَّةَ آمِنًا، وَقَدْ أَوَيْتُمُ الصُّبَاةَ، وَزَعَمْتُمْ أَنَّكُمْ تَنْصُرُونَهُمْ وَتُعِينُونَهُمْ، أَمَا والله لَوْلاَ أَنَّكَ مَعَ أَبِي صَفْوَانَ مَا رَجَعْتَ إِلَى أَهْلِكَ سَالمًا. فَقَالَ لَهُ سَعْدٌ وَرَفَعَ صَوْتَهُ عَلَيْهِ: أَمَا والله لَئِنْ مَنَعْتَنِي هَذَا لأَمْنَعَنَّكَ مَا هُوَ أَشَدُّ عَلَيْكَ مِنْهُ: طَرِيقَكَ عَلَى المَدِينَةِ. فَقَالَ لَهُ أُمَيَّةُ: لاَ تَرْفَعْ صَوْتَكَ يَا سَعْدُ عَلَى أَبِي الحَكَمِ سَيِّدِ أَهْلِ الْوَادِي. فَقَالَ سَعْدٌ: دَعْنَا عَنْكَ يَا أُمَيَّةُ، فوالله لَقَدْ سَمِعْتُ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ إِنَّهُمْ قَاتِلُوكَ. قَالَ: بِمَكَّةَ؟ قَالَ: لاَ أَدْرِي. فَفَزِعَ لِذَلِكَ أُمَيَّةُ فَزَعًا شَدِيدًا، فَلَمَّا رَجَعَ أُمَيَّةُ إِلَى أَهْلِهِ قَالَ: يَا أُمَّ صَفْوَانَ، أَلَمْ تَرَىْ مَا قَالَ لِي سَعْدٌ؟ قَالَتْ: وَمَا قَالَ لَكَ؟ قَالَ :زَعَمَ أَنَّ مُحَمَّدًا أَخْبَرَهُمْ أَنَّهُمْ قَاتِلِيَّ، فَقُلْتُ لَهُ :بِمَكَّةَ؟ قَالَ: لاَ أَدْرِي. فَقَالَ أُمَيَّةُ: والله لاَ أَخْرُجُ مِنْ مَكَّةَ، فَلَمَّا كَانَ يَوْمَ بَدْرٍ اسْتَنْفَرَ أَبُو جَهْلٍ النَّاسَ قَالَ: أَدْرِكُوا عِيرَكُمْ. فَكَرِهَ أُمَيَّةُ أَنْ يَخْرُجَ، فَأَتَاهُ أَبُو جَهْلٍ فَقَالَ: يَا أَبَا صَفْوَانَ، إِنَّكَ مَتَى مَا يَرَاكَ النَّاسُ قَدْ تَخَلَّفْتَ وَأَنْتَ سَيِّدُ أَهْلِ الْوَادِي تَخَلَّفُوا مَعَكَ، فَلَمْ يَزَلْ بِهِ أَبُو جَهْلٍ حَتَّى قَالَ: أَمَّا إِذْ غَلَبْتَنِي، فوالله لأَشْتَرِيَنَّ أَجْوَدَ بَعِيرٍ بِمَكَّةَ ثُمَّ قَالَ أُمَيَّةُ: يَا أُمَّ صَفْوَانَ جَهِّزِينِي. فَقَالَتْ لَهُ: يَا أَبَا صَفْوَانَ وَقَدْ نَسِيتَ مَا قَالَ لَكَ أَخُوكَ الْيَثْرِبِيُّ؟ قَالَ: لاَ، مَا أُرِيدُ أَنْ أَجُوزَ مَعَهُمْ إِلاَّ قَرِيبًا. فَلَمَّا خَرَجَ أُمَيَّةُ أَخَذَ لاَ يَنْزِلُ مَنْزِلاً إِلاَّ عَقَلَ بَعِيرَهُ، فَلَمْ يَزَلْ بِذَلِكَ حَتَّى قَتَلَهُ الله عَزَّ وَجَلَّ بِبَدْرٍ."],"takhrij":"صحيح: رواه البخاري في المغازي (3950) حدثني أحمد بن عثمان، حدثنا شريح بن مسلمة، حدثنا إبراهيم بن يوسف، عن أبيه، عن أبي إسحاق قال: حدثني عمرو بن ميمون أنه سمع عبد الله بن مسعود فذكره.","grade":"صحيح","chapter_ar":"إخباره ﷺ بقتل أمية بن خلف","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3950).","chapter_en":"His ﷺ Foretelling the Killing of Umayyah ibn Khalaf","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":6,"content":{"translation":{"en":["ʿAmr ibn Maymūn reported that he heard ʿAbdullāh ibn Masʿūd narrate from Saʿd ibn Muʿādh, who said: “Saʿd was a friend of Umayyah ibn Khalaf. Whenever Umayyah passed through Madīnah, he would stay with Saʿd, and whenever Saʿd passed through Makkah, he would stay with Umayyah. “After the Messenger of Allah ﷺ arrived in Madīnah, Saʿd set out to perform ʿumrah and stayed with Umayyah in Makkah. He said to Umayyah, ‘Find me a quiet time when I may perhaps circumambulate the House.’ “So Umayyah took him out around midday. Abū Jahl met them and said, ‘O Abū Ṣafwān, who is this with you?’ “He replied, ‘This is Saʿd.’ “Abū Jahl said to him, ‘I see you circumambulating Makkah in safety even though you have given refuge to those who have abandoned our religion, and you claim that you support and assist them. By Allah, were it not that you are with Abū Ṣafwān, you would not return safely to your family.’ “Saʿd raised his voice at him and said, ‘By Allah, if you prevent me from this, I will surely prevent you from something even more severe for you: your route through Madīnah.’ “Umayyah said to him, ‘Do not raise your voice, O Saʿd, against Abū al-Ḥakam, the chief of the people of the valley.’ “Saʿd said, ‘Leave us alone, O Umayyah. By Allah, I heard the Messenger of Allah ﷺ say that they will kill you.’ “He asked, ‘In Makkah?’ “Saʿd replied, ‘I do not know.’ “Umayyah became extremely frightened by this. “When Umayyah returned to his family, he said, ‘O Umm Ṣafwān, did you not hear what Saʿd said to me?’ “She asked, ‘What did he say?’ “He replied, ʿHe claims that Muḥammad informed them that they will kill me. I asked him, “In Makkah?” and he said, “I do not know.”’ “Umayyah said, ‘By Allah, I will not leave Makkah.’ “Then, when the Day of Badr came, Abū Jahl called the people to arms, saying, ‘Go and protect your caravan!’ “Umayyah disliked going out. Abū Jahl came to him and said, ‘O Abū Ṣafwān, if the people see that you have stayed behind while you are the chief of the people of the valley, they will remain behind with you.’ “Abū Jahl continued urging him until Umayyah said, ‘Since you have overcome me, by Allah, I will buy the finest camel in Makkah.’ “Then Umayyah said, ‘O Umm Ṣafwān, prepare me for the journey.’ “She said, ‘O Abū Ṣafwān, have you forgotten what your Yathribī brother said to you?’ “He replied, ‘No. I only intend to accompany them for a short distance.’ “Whenever Umayyah stopped at a place after leaving Makkah, he would tether his camel, remaining prepared to flee. He continued doing so until Allah, Mighty and Majestic, caused him to be killed at Badr.”"]}},"tuhfa":{},"voc":["seerah",1684],"full":1,"tks":"صحيح: رواه البخاري (3950)."},{"num":9725,"demo":false,"sanad":"","matn":["عَنْ سَهْلِ بْنِ سَعْدٍ السَّاعِدِيِّ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْتَقَى هُوَ وَالمُشْرِكُونَ فَاقْتَتَلُوا، فَلَمَّا مَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى عَسْكَرِهِ، وَمَالَ الآخَرُونَ إِلَى عَسْكَرِهِمْ، وَفِي أَصْحَابِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ رَجُلٌ لاَ يَدَعُ لهُمْ شَاذَّةً إِلاَّ اتَّبَعَهَا، يَضْرِبُهَا بِسَيْفِهِ، فقالوا: مَا أَجْزَأَ مِنَّا الْيَوْمَ أَحَدٌ كَمَا أَجْزَأَ فُلاَنٌ. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ . فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: أَنَا صَاحِبُهُ أبداً. قَالَ: فَخَرَجَ مَعَهُ كُلَّمَا وَقَفَ وَقَفَ مَعَهُ، وَإِذَا أَسْرَعَ أَسْرَعَ مَعَهُ – قَالَ: - فَجُرِحَ الرَّجُلُ جُرْحًا شَدِيدًا، فَاسْتَعْجَلَ المَوْتَ، فَوَضَعَ سَيْفَهُ بِالأَرْضِ وَذُبَابهُ بَيْنَ ثَدْيَيْهِ، ثُمَّ تَحَامَلَ عَلَى سَيْفِهِ، فَقَتَلَ نَفْسَهُ، فَخَرَجَ الرَّجُلُ إِلَى رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَشْهَدُ أَنَّكَ رَسُولُ الله قَالَ: وَمَا ذَاكَ؟ قَالَ: الرَّجُلُ الَّذِي ذَكَرْتَ آنِفًا أَنَّهُ مِنْ أَهْلِ النَّارِ، فَأَعْظَمَ النَّاسُ ذَلِكَ، فَقُلْتُ: أَنَا لَكُمْ بِهِ. فَخَرَجْتُ فِي طَلَبِهِ، ثُمَّ جُرِحَ جُرْحًا شَدِيدًا، فَاسْتَعْجَلَ المَوْتَ، فَوَضَعَ نَصْلَ سَيْفِهِ فِي الأَرْضِ وَذُبَابهُ بَيْنَ ثَدْيَيْهِ، ثُمَّ تَحَامَلَ عَلَيْهِ، فَقَتَلَ نَفْسَهُ. فَقَالَ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عِنْدَ ذَلِكَ إِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ الجَنَّةِ، فِيمَا يَبْدُو لِلنَّاسِ، وَهْوَ مِنَ أَهْلِ النَّارِ، وَإِنَّ الرَّجُلَ لَيَعْمَلُ عَمَلَ أَهْلِ النَّارِ، فِيمَا يَبْدُو لِلنَّاسِ، وَهْوَ مِنْ أَهْلِ الجَنَّةِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4203) ومسلم في الإيمان (179:112) كلاهما عن قتيبة بن سعيد، حدثنا يعقوب (هو ابن عبد الرحمن القاري) عن أبي حازم (هو سلمة بن دينار)، عن سهل بن سعد قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ لرجل: إنه من أهل النار","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4203) and Muslim (179:112).","chapter_en":"The Prophet ﷺ Saying About a Man That He Was Among the People of the Fire","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":7,"content":{"translation":{"en":["Sahl ibn Saʿd al-Sāʿidī reported that the Messenger of Allah ﷺ and the polytheists met in battle and fought one another. When the Messenger of Allah ﷺ returned toward his camp and the others returned toward their camp, there was a man among the Companions of the Messenger of Allah ﷺ who would pursue every isolated enemy fighter and strike him with his sword. The people said, “No one among us has been as effective today as so-and-so.” The Messenger of Allah ﷺ said: “Indeed, he is among the people of the Fire.” A man from the people said, “I will remain with him continuously.” So he went out with him. Whenever the man stopped, he stopped with him, and whenever he moved quickly, he moved quickly with him. The man was then severely wounded and became impatient for death. He placed the point of his sword on the ground and its tip against his chest, then threw his weight upon the sword and killed himself. The man who had followed him went to the Messenger of Allah ﷺ and said, “I testify that you are the Messenger of Allah.” He ﷺ asked: “Why is that?” He said, “The man whom you mentioned earlier as being among the people of the Fire—the people found that difficult to comprehend, so I said, ‘I will keep watch over him for you.’ I followed him, and then he was severely wounded. He became impatient for death, placed the point of his sword on the ground and its tip between his breasts, then threw himself upon it and killed himself.” The Messenger of Allah ﷺ then said: “Indeed, a man may perform the deeds of the people of Paradise, as it appears to the people, while he is among the people of the Fire; and a man may perform the deeds of the people of the Fire, as it appears to the people, while he is among the people of Paradise.”"]},"buhuth":{"en":["The name of the man who killed himself was Quzmān al-Ẓafarī, and he was among the hypocrites. See: Sharḥ al-Nawawī and Fatḥ al-Bārī (7/473)."]}},"tuhfa":{},"voc":["seerah",1685],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4203)، ومسلم (179: 112)."},{"num":9726,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: شَهِدْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيْبَرَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِرَجُلٍ مِمَّنْ مَعَهُ يَدَّعِي الإِسْلاَمَ: هَذَا مِنْ أَهْلِ النَّارِ. فَلَمَّا حَضَرَ الْقِتَالُ قَاتَلَ الرَّجُلُ مِنْ أَشَدِّ الْقِتَالِ، وَكَثُرَتْ بِهِ الْجِرَاحُ فَأَثْبَتَتْهُ، فَجَاءَ رَجُلٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ الَّذِي تَحَدَّثْتَ أَنَّهُ مِنْ أَهْلِ النَّارِ، قَدْ قَاتَلَ فِي سَبِيلِ اللَّهِ مِنْ أَشَدِّ الْقِتَالِ، فَكَثُرَتْ بِهِ الْجِرَاحُ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ. فَكَادَ بَعْضُ الْمُسْلِمِينَ يَرْتَابُ، فَبَيْنَمَا هُوَ عَلَى ذَلِكَ إِذْ وَجَدَ الرَّجُلُ أَلَمَ الْجِرَاحِ، فَأَهْوَى بِيَدِهِ إِلَى كِنَانَتِهِ، فَانْتَزَعَ مِنْهَا سَهْمًا فَانْتَحَرَ بِهَا، فَاشْتَدَّ رِجَالٌ مِنَ الْمُسْلِمِينَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالُوا: يَا رَسُولَ اللَّهِ صَدَّقَ اللَّهُ حَدِيثَكَ، قَدِ انْتَحَرَ فُلاَنٌ فَقَتَلَ نَفْسَهُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَا بِلاَلُ، قُمْ فَأَذِّنْ، لاَ يَدْخُلُ الْجَنَّةَ إِلاَّ مُؤْمِنٌ، وَإِنَّ اللَّهَ لَيُؤَيِّدُ هَذَا الدِّينَ بِالرَّجُلِ الْفَاجِرِ."],"takhrij":"متفق عليه: رواه البخاري في القدر (6606) ومسلم في الإيمان (178:111) كلاهما من طريق معمر، عن الزهري، عن سعيد بن المسيب، عن أبي هريرة رضي الله عنه قال: فذكره، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب قول النبي ﷺ لرجل: إنه من أهل النار","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (6606) and Muslim (178:111). The wording is that of al-Bukhārī.","chapter_en":"The Prophet ﷺ Saying About a Man That He Was Among the People of the Fire","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":7,"content":{"translation":{"en":["Abū Hurayrah said: “We were present with the Messenger of Allah ﷺ at Khaybar. The Messenger of Allah ﷺ said concerning a man who was with him and claimed Islām: ‘This man is among the people of the Fire.’ “When the fighting began, the man fought with extreme intensity and suffered many wounds that incapacitated him. “One of the Companions of the Prophet ﷺ came and said, ‘O Messenger of Allah, what about the man whom you said was among the people of the Fire? He fought in the cause of Allah with the fiercest fighting and has suffered many wounds.’ “The Prophet ﷺ said: ‘Indeed, he is among the people of the Fire.’ “Some of the Muslims almost began to doubt. While matters stood thus, the man felt the pain of his wounds, reached toward his quiver, pulled out an arrow, and killed himself with it. “Some Muslim men hurried to the Messenger of Allah ﷺ and said, ‘O Messenger of Allah, Allah has confirmed the truth of what you said. So-and-so has killed himself.’ “The Messenger of Allah ﷺ said: ‘O Bilāl, stand and announce: None shall enter Paradise except a believer, and indeed Allah may support this religion by means of a wicked man.’”"]},"buhuth":{"en":["Note: In one narration of Muslim, “Ḥunayn” occurs instead of “Khaybar.” Al-Qāḍī ʿIyāḍ said: The correct wording is Khaybar, with the letter khāʾ."]}},"tuhfa":{},"voc":["seerah",1686],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (6606)، ومسلم (178:111)، والسياق للبخاري."},{"num":9727,"demo":false,"sanad":"","matn":["عن عَبْدِ الرَّحْمَنِ بن عَبْدِ اللَّهِ بن كَعْبٍ بن مَالِكٍ أَنَّهُ أَخْبَرَهُ بَعْضُ مَنْ شَهِدَ النَّبِيَّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِخَيْبَرَ، أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ لِرَجُلٍ مِمَّنْ مَعَهُ: إِنَّ هَذَا لَمِنْ أَهْلِ النَّارِ، فَلَمَّا حَضَرَ الْقِتَالُ، قَاتَلَ الرَّجُلُ أَشَدَّ الْقِتَالِ، حَتَّى كَثُرَتْ بِهِ الْجِرَاحُ، فَأَتَاهُ رِجَالٌ مِنْ أَصْحَابِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالُوا: يَا رَسُولَ اللَّهِ، أَرَأَيْتَ الرَّجُلَ الَّذِي ذَكَرْتَ أَنَّهُ مِنْ أَهْلِ النَّارِ، فَقَدْ وَاللهِ قَاتَلَ فِي سَبِيلِ اللَّهِ أَشَدَّ الْقِتَالِ، وَكَثُرَتْ بِهِ الْجِرَاحُ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَمَا إِنَّهُ مِنْ أَهْلِ النَّارِ. وَكَادَ بَعْضُ النَّاسِ أَنْ يَرْتَابَ، فَبَيْنَمَا هُمْ عَلَى ذَلِكَ وَجَدَ الرَّجُلُ أَلَمَ الْجِرَاحِ، فَأَهْوَى بِيَدِهِ الرَّجُلُ إِلَى كِنَانَتِهِ، فَانْتَزَعَ مِنْهَا سَهْمًا، فَانْتَحَرَ بِهِ، فَاشْتَدَّ رَجُلٌ مِنَ الْمُسْلِمِينَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا نَبِيَّ اللَّهِ، قَدْ صَدَّقَ اللَّهُ حَدِيثَكَ، قَدِ انْتَحَرَ فُلَانٌ، فَقَتَلَ نَفْسَهُ."],"takhrij":"صحيح: رواه أحمد (17218) عن يعقوب (هو: ابن إبراهيم بن سعد بن إبراهيم الزهري) حدثنا أبي، عن صالح بن كيسان، قال ابن شهاب: أخبرني عبد الرحمن بن عبدالله بن كعب بن مالك فذكره.","grade":"صحيح","chapter_ar":"باب قول النبي ﷺ لرجل: إنه من أهل النار","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Aḥmad (17218).","chapter_en":"The Prophet ﷺ Saying About a Man That He Was Among the People of the Fire","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":7,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbdullāh ibn Kaʿb ibn Mālik reported that one of those who witnessed Khaybar with the Prophet ﷺ informed him that the Messenger of Allah ﷺ said concerning a man who was with him: “Indeed, this man is among the people of the Fire.” When the fighting began, the man fought with extreme intensity until his wounds became numerous. Some men from among the Companions of the Prophet ﷺ came to him and said, “O Messenger of Allah, what about the man whom you said was among the people of the Fire? By Allah, he has fought in the cause of Allah with the fiercest fighting, and his wounds have become numerous.” The Messenger of Allah ﷺ said: “Indeed, he is among the people of the Fire.” Some of the people nearly began to doubt. While they were in that state, the man felt the pain of his wounds, reached for his quiver, took an arrow from it, and killed himself with it. A Muslim man hurried to the Messenger of Allah ﷺ and said, “O Prophet of Allah, Allah has confirmed the truth of what you said. So-and-so has killed himself.”"]}},"tuhfa":{},"voc":["seerah",1687],"full":1,"dr":1,"tks":"صحيح: رواه أحمد (17218)."},{"num":9728,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: لمَّا فُتِحَتْ خَيْبَرُ أُهْدِيَتْ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاةٌ فِيهَا سُمٌّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اجْمَعُوا إِلَيَّ مَنْ كَانَ هَا هُنَا مِنْ يَهُودَ. فَجُمِعُوا لَهُ فَقَالَ: إِنِّي سَائِلُكُمْ عَنْ شَيْءٍ فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْهُ؟. فَقَالُوا: نَعَمْ. قَالَ لَهُمُ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ أَبُوكُمْ؟ قَالُوا: فُلاَنٌ، فَقَالَ: كَذَبْتُمْ، بَلْ أَبُوكُمْ فُلاَنٌ قَالُوا: صَدَقْتَ. قَالَ: فَهَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ إِنْ سَأَلْتُ عَنْهُ؟ فَقَالُوا: نَعَمْ يَا أَبَا الْقَاسِمِ، وَإِنْ كَذَبْنَا عَرَفْتَ كَذِبَنَا كَمَا عَرَفْتَهُ فِي أَبِينَا. فَقَالَ لهُمْ: مَنْ أَهْلُ النَّارِ؟ قَالُوا: نَكُونُ فِيهَا يَسِيرًا ثُمَّ تَخْلُفُونَا فِيهَا. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اخْسَئُوا فِيهَا، والله لاَ نَخْلُفُكُمْ فِيهَا أَبَدًا ثُمَّ قَالَ: هَلْ أَنْتُمْ صَادِقِيَّ عَنْ شَيْءٍ إِنْ سَأَلْتُكُمْ عَنْهُ؟ فَقَالُوا: نَعَمْ يَا أَبَا الْقَاسِمِ. قَالَ: هَلْ جَعَلْتُمْ فِي هَذِهِ الشَّاةِ سُمًّا؟ قَالُوا: نَعَمْ. قَالَ: مَا حَمَلَكُمْ عَلَى ذَلِكَ؟. قَالُوا: أَرَدْنَا إِنْ كُنْتَ كَاذِبًا نَسْتَرِيحُ، وَإِنْ كُنْتَ نَبِيًّا لَمْ يَضُرَّكَ."],"takhrij":"صحيح: رواه البخاري في الجزية والموادعة (3169) عن عبد الله بن يوسف، حدثنا الليث، قال: حدثني سعيد، عن أبي هريرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب الشاة التي سُمَّت للنبي ﷺ بخيبر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3169).","chapter_en":"The Sheep That Was Poisoned for the Prophet ﷺ at Khaybar","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":9,"content":{"translation":{"en":["Abū Hurayrah said: “When Khaybar was conquered, a poisoned sheep was presented to the Prophet ﷺ. “The Prophet ﷺ said: ‘Gather for me the Jews who are here.’ “They were gathered before him, and he said: ‘I am going to ask you about something. Will you tell me the truth about it?’ “They replied, ‘Yes.’ “The Prophet ﷺ asked them: ‘Who is your father?’ “They replied, ‘So-and-so.’ “He said: ‘You have lied. Rather, your father is so-and-so.’ “They said, ‘You have spoken the truth.’ “He asked: ‘Will you tell me the truth about something if I ask you?’ “They replied, ‘Yes, O Abū al-Qāsim. If we lie, you will recognize our lie just as you recognized it concerning our father.’ “He asked them: ‘Who are the people of the Fire?’ “They replied, ‘We will remain in it only for a short time, then you will replace us in it.’ “The Prophet ﷺ said: ‘Remain disgraced in it! By Allah, we will never replace you in it.’ “Then he asked: ‘Will you tell me the truth about something if I ask you?’ “They replied, ‘Yes, O Abū al-Qāsim.’ “He asked: ‘Did you put poison in this sheep?’ “They replied, ‘Yes.’ “He asked: ‘What caused you to do that?’ “They replied, ‘We wanted that, if you were a liar, we would be rid of you; and if you were a prophet, it would not harm you.’”"]}},"tuhfa":{},"voc":["seerah",1691],"full":1,"rep":[9077],"tks":"صحيح: رواه البخاري (3169)."},{"num":9729,"demo":false,"sanad":"","matn":["عن سُلَيْمَانَ بن صرد يَقُولُ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ حِينَ أَجْلَى الأَحْزَابُ عَنْهُ: الْآنَ نَغْزُوهُمْ، وَلاَ يَغْزُونَنَا، نَحْنُ نَسِيرُ إِلَيْهِمْ."],"takhrij":"صحيح: رواه البخاري في المغازي (4110) عن عبد الله بن محمد، حدثنا يحيى بن آدم، حدثنا إسرائيل: سمعت أبا إسحاق يقول: سمعت سليمان بن صرد يقول: فذكره.","grade":"صحيح","chapter_ar":"إخباره ﷺ عن عدم غزو قريش بعد غزوة الأحزاب","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4110).","chapter_en":"His ﷺ Foretelling That Quraysh Would Not Attack After the Battle of the Confederates","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":10,"content":{"translation":{"en":["Sulaymān ibn Ṣurad said: “I heard the Prophet ﷺ say when the Confederates had been driven away from him: ‘Now we will attack them, and they will not attack us. We will march against them.’”"]},"buhuth":{"en":["His saying, “when the Confederates had been driven away from him,” means: when they had withdrawn and departed from him."]}},"tuhfa":{},"voc":["seerah",1692],"full":1,"dr":1,"rep":[8933,13054],"tks":"صحيح: رواه البخاري (4110). قوله: «حين أجلي الأحزاب عنه»: أي رجعوا عنه."},{"num":9730,"demo":false,"sanad":"","matn":["عَنْ أَبِي حُمَيْدٍ قَالَ:  خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ غَزْوَةَ تَبُوكَ، فَأَتَيْنَا وَادِيَ الْقُرَى عَلَى حَدِيقَةٍ لِامْرَأَةٍ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اخْرُصُوهَا! فَخَرَصْنَاهَا، وَخَرَصَهَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَشَْرَةَ أَوْسُقٍ، وَقَالَ: أَحْصِيهَا حَتَّى نَرْجِعَ إِلَيْكِ، إِنْ شَاءَ اللَّهُ. وَانْطَلَقْنَا، حَتَّى قَدِمْنَا تَبُوكَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: سَتَهُبُّ عَلَيْكُمُ اللَّيْلَةَ رِيحٌ شَدِيدَةٌ، فَلَا يَقُمْ فِيهَا أَحَدٌ مِنْكُمْ، فَمَنْ كَانَ لَهُ بَعِيرٌ فَلْيَشُدَّ عِقَالَهُ. فَهَبَّتْ رِيحٌ شَدِيدَةٌ، فَقَامَ رَجُلٌ فَحَمَلَتْهُ الرِّيحُ حَتَّى أَلْقَتْهُ بِجَبَلَيْ طَيِّئٍ، وَجَاءَ رَسُولُ ابْنِ الْعَلْمَاءِ، صَاحِبِ أَيْلَةَ، إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِكِتَابٍ، وَأَهْدَى لَهُ بَغْلَةً بَيْضَاءَ، فَكَتَبَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَهْدَى لَهُ بُرْدًا، ثُمَّ أَقْبَلْنَا حَتَّى قَدِمْنَا وَادِيَ الْقُرَى، فَسَأَلَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْمَرْأَةَ عَنْ حَدِيقَتِهَا كَمْ بَلَغَ ثَمَرُهَا؟ فَقَالَتْ: عَشَرَةَ أَوْسُقٍ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي مُسْرِعٌ، فَمَنْ شَاءَ مِنْكُمْ فَلْيُسْرِعْ مَعِيَ، وَمَنْ شَاءَ فَلْيَمْكُثْ. فَخَرَجْنَا حَتَّى أَشْرَفْنَا عَلَى الْمَدِينَةِ، فَقَالَ: هَذِهِ طَابَةُ، وَهَذَا أُحُدٌ، وَهُوَ جَبَلٌ يُحِبُّنَا وَنُحِبُّهُ. ثُمَّ قَالَ: إِنَّ خَيْرَ دُورِ الْأَنْصَارِ دَارُ بَنِي النَّجَّارِ، ثُمَّ دَارُ بَنِي عَبْدِ الْأَشْهَلِ، ثُمَّ دَارُ بَنِي عَبْدِ الْحَارِثِ بْنِ الْخَزْرَجِ، ثُمَّ دَارُ بَنِي سَاعِدَةَ، وَفِي كُلِّ دُورِ الْأَنْصَارِ خَيْرٌ. فَلَحِقَنَا سَعْدُ بْنُ عُبَادَةَ، فَقَالَ أَبُو أُسَيْدٍ: أَلَمْ تَرَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَيَّرَ دُورَ الْأَنْصَارِ، فَجَعَلَنَا آخِرًا، فَأَدْرَكَ سَعْدٌ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، خَيَّرْتَ دُورَ الْأَنْصَارِ فَجَعَلْتَنَا آخِرًا! فَقَالَ: أَوَلَيْسَ بِحَسْبِكُمْ أَنْ تَكُونُوا مِنَ الْخِيَارِ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1481) ومسلم في الفضائل (11:1392) كلاهما من طريق عمرو بن يحيى، عن عباس بن سهل الساعدي، عن أبي حميد الساعدي قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن هبوب ريح شديدة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (1481) and Muslim (1392:11).","chapter_en":"His ﷺ Foretelling the Blowing of a Severe Wind","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":11,"content":{"translation":{"en":["Abū Ḥumayd said: “We went out with the Messenger of Allah ﷺ on the expedition of Tabūk. We came to Wādī al-Qurā and stopped by a garden belonging to a woman. “The Messenger of Allah ﷺ said: ‘Estimate its produce.’ “We estimated it, and the Messenger of Allah ﷺ estimated it at ten wasqs. He said to the woman: ‘Keep account of it until we return to you, if Allah wills.’ “We continued until we reached Tabūk. The Messenger of Allah ﷺ said: ‘A severe wind will blow upon you tonight. None of you should stand during it, and whoever has a camel should firmly tie its hobble.’ “A severe wind then blew. A man stood up, and the wind carried him away until it threw him at the two mountains of Ṭayyiʾ. “The messenger of Ibn al-ʿUlamāʾ, the ruler of Aylah, came to the Messenger of Allah ﷺ carrying a letter and presented him with a white mule. The Messenger of Allah ﷺ wrote back to him and gave him a mantle as a gift. “Then we returned until we reached Wādī al-Qurā. The Messenger of Allah ﷺ asked the woman about her garden: ‘How much did its produce amount to?’ “She replied, ‘Ten wasqs.’ “The Messenger of Allah ﷺ then said: ‘I am going to travel quickly. Whoever wishes may hasten with me, and whoever wishes may remain.’ “We continued until we overlooked Madīnah. He said: ‘This is Ṭābah, and this is Uḥud. It is a mountain that loves us and that we love.’ “Then he said: ‘The best dwellings of the Anṣār are the dwellings of Banū al-Najjār, then the dwellings of Banū ʿAbd al-Ashhal, then the dwellings of Banū al-Ḥārith ibn al-Khazraj, then the dwellings of Banū Sāʿidah; and there is good in all the dwellings of the Anṣār.’ “Saʿd ibn ʿUbādah caught up with us, and Abū Usayd said to him, ‘Have you not seen that the Messenger of Allah ﷺ ranked the dwellings of the Anṣār and placed us last?’ “Saʿd caught up with the Messenger of Allah ﷺ and said, ‘O Messenger of Allah, you ranked the dwellings of the Anṣār and placed us last.’ “He ﷺ said: ‘Is it not enough for you that you are among the best?’”"]},"buhuth":{"en":["Regarding the wording “then the dwellings of Banū ʿAbd al-Ḥārith ibn al-Khazraj,” this is an error. The correct wording is “Banū al-Ḥārith ibn al-Khazraj,” as found in al-Bukhārī, without the word “ʿAbd.” See: al-Nawawī’s commentary on Ṣaḥīḥ Muslim."]}},"tuhfa":{},"voc":["seerah",1693],"full":1,"dr":1,"rep":[9272],"tks":"متفق عليه: رواه البخاري (1481)، ومسلم (11:1392)."},{"num":9731,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: بَيْنَمَا نَحْنُ عِنْدَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَهْوَ يَقْسِمُ قَسْمًا، أَتَاهُ ذُو الْخُوَيْصِرَةِ، وَهْوَ رَجُلٌ مِنْ بَنِي تَمِيمٍ، فَقَالَ: يَا رَسُولَ اللَّهِ اعْدِلْ، فَقَالَ: وَيْلَكَ، وَمَنْ يَعْدِلُ إِذَا لَمْ أَعْدِلْ، قَدْ خِبْتَ وَخَسِرْتَ إِنْ لَمْ أَكُنْ أَعْدِلُ . فَقَالَ عُمَرُ: يَا رَسُولَ اللَّهِ، ائْذَنْ لِي فِيهِ فَأَضْرِبَ عُنُقَهُ ؟ فَقَالَ: دَعْهُ، فَإِنَّ لَهُ أَصْحَابًا يَحْقِرُ أَحَدُكُمْ صَلاَتَهُ مَعَ صَلاَتِهِمْ، وَصِيَامَهُ مَعَ صِيَامِهِمْ، يقرؤون الْقُرْآنَ لاَ يُجَاوِزُ تَرَاقِيَهُمْ، يَمْرُقُونَ مِنَ الدِّينِ كَمَا يَمْرُقُ السَّهْمُ مِنَ الرَّمِيَّةِ، يُنْظَرُ إِلَى نَصْلِهِ فَلاَ يُوجَدُ فِيهِ شيء، ثُمَّ يُنْظَرُ إِلَى رِصَافِهِ فَمَا يُوجَدُ فِيهِ شيء، ثُمَّ يُنْظَرُ إِلَى نَضِيِّهِ - وَهْوَ قِدْحُهُ - فَلاَ يُوجَدُ فِيهِ شيء، ثُمَّ يُنْظَرُ إِلَى قُذَذِهِ فَلاَ يُوجَدُ فِيهِ شيء، قَدْ سَبَقَ الْفَرْثَ وَالدَّمَ، آيَتُهُمْ رَجُلٌ أَسْوَدُ، إِحْدَى عَضُدَيْهِ مِثْلُ ثدي الْمَرْأَةِ، أَوْ مِثْلُ الْبَضْعَةِ تَدَرْدَرُ، وَيَخْرُجُونَ عَلَى حِينِ فُرْقَةٍ مِنَ النَّاسِ . قَالَ أَبُو سَعِيدٍ: فَأَشْهَدُ أَنِّي سَمِعْتُ هَذَا الْحَدِيثَ مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، وَأَشْهَدُ أَنَّ عَلِيَّ بْنَ أَبِي طَالِبٍ قَاتَلَهُمْ وَأَنَا مَعَهُ، فَأَمَرَ بِذَلِكَ الرَّجُلِ فَالْتُمِسَ فَأُتِيَ بِهِ، حَتَّى نَظَرْتُ إِلَيْهِ عَلَى نَعْتِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي نَعَتَهُ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3610) ومسلم في الزكاة (148:1064) كلاهما من طريق الزهري، أخبرني أبو سلمة بن عبد الرحمن، عن أبي سعيد الخدري فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن الخوارج","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3610) and Muslim (1064:148).","chapter_en":"His ﷺ Foretelling the Khawārij","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":12,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: “While we were with the Messenger of Allah ﷺ as he was distributing some property, Dhū al-Khuwayṣirah, a man from Banū Tamīm, came to him and said, ‘O Messenger of Allah, be just!’ “He ﷺ said: ‘Woe to you! Who would be just if I were not just? You would indeed be ruined and lost if I were not just.’ “ʿUmar said, ‘O Messenger of Allah, give me permission to strike his neck.’ “He ﷺ said: ʿLeave him. He will have companions in comparison with whose prayer one of you will consider his own prayer insignificant, and in comparison with whose fasting one of you will consider his own fasting insignificant. They will recite the Qurʾān, but it will not go beyond their throats. They will pass out of the religion just as an arrow passes through the game animal. ʿThe arrowhead will be examined, but nothing will be found upon it. Then its shaft fitting will be examined, but nothing will be found upon it. Then its shaft itself will be examined, but nothing will be found upon it. Then its feathers will be examined, but nothing will be found upon them, for it will have passed through the dung and blood before either could cling to it. ‘Their sign will be a black man, one of whose upper arms will be like a woman’s breast, or like a piece of flesh that shakes loosely. They will emerge at a time when the people are divided.’” Abū Saʿīd said: “I testify that I heard this hadith from the Messenger of Allah ﷺ, and I testify that ʿAlī ibn Abī Ṭālib fought them while I was with him. He ordered that the man described be sought out, and he was brought. I looked at him and found him exactly according to the description given by the Prophet ﷺ.”"]}},"tuhfa":{},"voc":["seerah",1694],"full":1,"tks":"متفق عليه: رواه البخاري (3610)، ومسلم (148:1064)."},{"num":9732,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، أَنَّهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا هَلَكَ كِسْرَى فَلاَ كِسْرَى بَعْدَهُ، وَإِذَا هَلَكَ قَيْصَرُ فَلاَ قَيْصَرَ بَعْدَهُ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ لَتُنْفِقُنَّ كُنُوزَهُمَا فِي سَبِيلِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3618) ومسلم في الفتن (75:2918) كلاهما من طريق الزهري، عن سعيد بن المسيب، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن هلاك قيصر وكسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3618) and Muslim (2918:75).","chapter_en":"His ﷺ Foretelling the Destruction of Caesar and Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":13,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “When Khosrow is destroyed, there will be no Khosrow after him; and when Caesar is destroyed, there will be no Caesar after him. By the One in Whose hand is the soul of Muḥammad, their treasures will surely be spent in the cause of Allah.”"]}},"tuhfa":{},"voc":["seerah",1695],"full":1,"tks":"متفق عليه: رواه البخاري (3618)، ومسلم (75:2918)."},{"num":9733,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِذَا هَلَكَ كِسْرَى فَلاَ كِسْرَى بَعْدَهُ، وَإِذَا هَلَكَ قَيْصَرُ فَلاَ قَيْصَرَ بَعْدَهُ، وَالَّذِي نَفْسِي بِيَدِهِ، لَتُنْفَقَنَّ كُنُوزُهُمَا فِي سَبِيلِ اللَّهِ."],"takhrij":"متفق عليه: رواه البخاري في فرض الخمس (3121) ومسلم في الفتن (77:2919) كلاهما من طريق جرير، عن عبد الملك بن عمير، عن جابر بن سمرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن هلاك قيصر وكسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3121) and Muslim (2919:77).","chapter_en":"His ﷺ Foretelling the Destruction of Caesar and Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":13,"content":{"translation":{"en":["Jābir ibn Samurah reported that the Messenger of Allah ﷺ said: “When Khosrow is destroyed, there will be no Khosrow after him; and when Caesar is destroyed, there will be no Caesar after him. By the One in Whose hand is the soul of Muḥammad, their treasures will surely be spent in the cause of Allah.”"]}},"tuhfa":{},"voc":["seerah",1696],"full":1,"rep":[7054],"tks":"متفق عليه: رواه البخاري (3121)، ومسلم (77:2919)."},{"num":9734,"demo":false,"sanad":"","matn":["عَنْ عَدِيِّ بْنِ حَاتِمٍ، قَالَ: بَيْنَا أَنَا عِنْدَ النَّبِيِّ، صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِذْ أَتَاهُ رَجُلٌ فَشَكَا إِلَيْهِ الْفَاقَةَ، ثُمَّ أَتَاهُ آخَرُ، فَشَكَا قَطْعَ السَّبِيلِ. فَقَالَ: يَا عَدِيُّ، هَلْ رَأَيْتَ الْحِيرَةَ. قُلْتُ: لَمْ أَرَهَا، وَقَدْ أُنْبِئْتُ عَنْهَا. قَالَ: فَإِنْ طَالَتْ بِكَ حَيَاةٌ لَتَرَيَنَّ الظَّعِينَةَ تَرْتَحِلُ مِنَ الْحِيرَةِ، حَتَّى تَطُوفَ بِالْكَعْبَةِ، لاَ تَخَافُ أَحَدًا إِلاَّ اللَّهَ ـ قُلْتُ فِيمَا بَيْنِي وَبَيْنَ نَفْسِي: فَأَيْنَ دُعَّارُ طَيِّئٍ الَّذِينَ قَدْ سَعَّرُوا الْبِلاَدَ؟ وَلَئِنْ طَالَتْ بِكَ حَيَاةٌ لَتُفْتَحَنَّ كُنُوزُ كِسْرَى. قُلْتُ: كِسْرَى بْنِ هُرْمُزَ؟ قَالَ: كِسْرَى بْنِ هُرْمُزَ، وَلَئِنْ طَالَتْ بِكَ حَيَاةٌ، لَتَرَيَنَّ الرَّجُلَ يُخْرِجُ مِلْءَ كَفِّهِ مِنْ ذَهَبٍ أَوْ فِضَّةٍ، يَطْلُبُ مَنْ يَقْبَلُهُ مِنْهُ، فَلاَ يَجِدُ أَحَدًا يَقْبَلُهُ مِنْهُ، وَلَيَلْقَيَنَّ اللَّهَ أَحَدُكُمْ يَوْمَ يَلْقَاهُ، وَلَيْسَ بَيْنَهُ وَبَيْنَهُ تُرْجُمَانٌ يُتَرْجِمُ لَهُ. فَيَقُولَنَّ: أَلَمْ أَبْعَثْ إِلَيْكَ رَسُولاً فَيُبَلِّغَكَ؟ فَيَقُولُ: بَلَى. فَيَقُولُ: أَلَمْ أُعْطِكَ مَالاً وَأُفْضِلْ عَلَيْكَ؟ فَيَقُولُ: بَلَى. فَيَنْظُرُ عَنْ يَمِينِهِ فَلاَ يَرَى إِلاَّ جَهَنَّمَ، وَيَنْظُرُ عَنْ يَسَارِهِ فَلاَ يَرَى إِلاَّ جَهَنَّمَ. قَالَ عَدِيٌّ: سَمِعْتُ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ: اتَّقُوا النَّارَ وَلَوْ بِشِقَّةِ تَمْرَةٍ، فَمَنْ لَمْ يَجِدْ شِقَّةَ تَمْرَةٍ، فَبِكَلِمَةٍ طَيِّبَةٍ. قَالَ عَدِيٌّ: فَرَأَيْتُ الظَّعِينَةَ تَرْتَحِلُ مِنَ الْحِيرَةِ حَتَّى تَطُوفَ بِالْكَعْبَةِ، لاَ تَخَافُ إِلاَّ اللَّهَ، وَكُنْتُ فِيمَنِ افْتَتَحَ كُنُوزَ كِسْرَى بْنِ هُرْمُزَ، وَلَئِنْ طَالَتْ بِكُمْ حَيَاةٌ لَتَرَوُنَّ مَا قَالَ النَّبِيُّ أَبُو الْقَاسِمِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يُخْرِجُ مِلْءَ كَفِّهِ."],"takhrij":"متفق عليه: رواه البخاري في علامات النبوة (3595) عن محمد بن الحكم، أخبرنا النضر، أخبرنا إسرائيل، أخبرنا سعد الطائي، أخبرنا محل بن خليفة، عن عدي بن حاتم فذكره. ورواه مسلم في الزكاة (67:1016) من وجه آخر عن عدي بن حاتم مختصراً.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن هلاك قيصر وكسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3595) and Muslim (1016:67).","chapter_en":"His ﷺ Foretelling the Destruction of Caesar and Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":13,"content":{"translation":{"en":["ʿAdī ibn Ḥātim said: “While I was with the Prophet ﷺ, a man came to him and complained of poverty. Then another man came and complained about the danger of highway robbery. “He said to me, ‘O ʿAdī, have you seen al-Ḥīrah?’ “I replied, ‘I have not seen it, but I have been informed about it.’ “He said: ‘If you live long enough, you will surely see a woman traveling in her howdah from al-Ḥīrah until she circumambulates the Kaʿbah, fearing no one except Allah.’ “I said to myself, ‘Then where will the brigands of Ṭayyiʾ be, who have spread havoc throughout the land?’ “He continued: ‘And if you live long enough, the treasures of Khosrow will surely be conquered.’ “I asked, ‘Khosrow ibn Hurmuz?’ “He replied, ʿKhosrow ibn Hurmuz. And if you live long enough, you will surely see a man bring out a handful of gold or silver, seeking someone who will accept it from him, yet he will find no one willing to accept it. “‘And each one of you will surely meet Allah on the Day he meets Him, with no interpreter between him and Allah to translate for him. Allah will say, “Did I not send you a messenger who conveyed the message to you?” He will reply, “Yes.” He will say, “Did I not give you wealth and children and bestow favors upon you?” He will reply, “Yes.” Then he will look to his right and see nothing but Hell, and he will look to his left and see nothing but Hell.’” ʿAdī said: “I heard the Prophet ﷺ say: ‘Protect yourselves from the Fire even with half a date, and whoever cannot find even half a date, then with a good word.’ “I later saw a woman traveling in her howdah from al-Ḥīrah until she circumambulated the Kaʿbah, fearing none but Allah. And I was among those who conquered the treasures of Khosrow ibn Hurmuz. And if you live long enough, you will indeed see what the Prophet Abū al-Qāsim ﷺ said: ‘A man will bring out a handful.’”"]}},"tuhfa":{},"voc":["seerah",1697],"full":1,"rep":[10279,12451,12894],"tks":"متفق عليه: رواه البخاري (3595)، ومسلم (67:1016)."},{"num":9735,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ سَمُرَةَ قَالَ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  لَتَفْتَحَنَّ عِصَابَةٌ مِنَ الْمُسْلِمِينَ أَوْ مِنَ الْمُؤْمِنِينَ كَنْزَ آلِ كِسْرَى الَّذِي فِي الْأَبْيَضِ."],"takhrij":"صحيح: رواه مسلم في الفتن (78:2919) عن قتيبة بن سعيد وأبي كامل الجحدري قالا: حدثنا أبو عوانة عن سماك بن حرب، عن جابر بن سمرة فذكره.","grade":"صحيح","chapter_ar":"باب إخباره ﷺ عن فتح كنوز كسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2919:78).","chapter_en":"His ﷺ Foretelling the Conquest of the Treasures of Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":14,"content":{"translation":{"en":["Jābir ibn Samurah said: “I heard the Messenger of Allah ﷺ say: ‘A group of Muslims—or believers—will surely conquer the treasure of the family of Khosrow that is in al-Abyaḍ.’”"]}},"tuhfa":{},"voc":["seerah",1698],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (78:2919)."},{"num":9736,"demo":false,"sanad":"","matn":["عَنْ خَبَّابِ بْنِ الأَرَتِّ، قَالَ: شَكَوْنَا إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَهْوَ مُتَوَسِّدٌ بُرْدَةً لَهُ فِي ظِلِّ الْكَعْبَةِ، قُلْنَا لَهُ: أَلاَ تَسْتَنْصِرُ لَنَا، أَلاَ تَدْعُو اللَّهَ لَنَا؟ قَالَ: كَانَ الرَّجُلُ فِيمَنْ قَبْلَكُمْ يُحْفَرُ لَهُ فِي الأَرْضِ، فَيُجْعَلُ فِيهِ، فَيُجَاءُ بِالْمِنْشَارِ، فَيُوضَعُ عَلَى رَأْسِهِ فَيُشَقُّ بِاثْنَتَيْنِ، وَمَا يَصُدُّهُ ذَلِكَ عَنْ دِينِهِ، وَيُمْشَطُ بِأَمْشَاطِ الْحَدِيدِ، مَا دُونَ لَحْمِهِ مِنْ عَظْمٍ أَوْ عَصَبٍ، وَمَا يَصُدُّهُ ذَلِكَ عَنْ دِينِهِ، وَاللَّهِ لَيُتِمَّنَّ هَذَا الأَمْرَ، حَتَّى يَسِيرَ الرَّاكِبُ مِنْ صَنْعَاءَ إِلَى حَضْرَمَوْتَ، لاَ يَخَافُ إِلاَّ اللَّهَ، أَوِ الذِّئْبَ عَلَى غَنَمِهِ، وَلَكِنَّكُمْ تَسْتَعْجِلُونَ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3612) عن محمد بن المثنى، حدثني يحيى، عن إسماعيل، حدثنا قيس، عن خباب بن الأرت فذكره.","grade":"صحيح","chapter_ar":"باب إخباره عن سير الراكب من صنعاء إلى حضرموت لا يخاف إلا الله","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Signs of Prophethood (3612), from Muḥammad ibn al-Muthannā, from Yaḥyā, from Ismāʿīl, from Qays, from Khabbāb ibn al-Aratt.","chapter_en":"His Foretelling That a Rider Would Travel from Ṣanʿāʾ to Ḥaḍramawt Fearing None but Allah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":15,"content":{"translation":{"en":["Khabbāb ibn al-Aratt said: “We complained to the Messenger of Allah ﷺ while he was reclining upon his cloak in the shade of the Kaʿbah. We said to him, ‘Will you not seek victory for us? Will you not supplicate to Allah for us?’ “He said: ʿAmong those before you, a man would have a pit dug for him in the ground and be placed inside it. Then a saw would be brought and placed upon his head, and he would be split into two halves, yet that would not turn him away from his religion. Iron combs would be drawn through his flesh down to his bones and sinews, yet that would not turn him away from his religion. ‘By Allah, this matter will surely be completed until a rider travels from Ṣanʿāʾ to Ḥaḍramawt, fearing none but Allah—or the wolf concerning his sheep—but you are being impatient.’”"]}},"tuhfa":{},"voc":["seerah",1699],"full":1,"rep":[12368],"tks":"صحيح: رواه البخاري (3612)."},{"num":9737,"demo":false,"sanad":"","matn":["عَنْ أَبِي نَوْفَلٍ:  رَأَيْتُ عَبْدَ اللَّهِ بْنَ الزُّبَيْرِ عَلَى عَقَبَةِ الْمَدِينَةِ، قَالَ: فَجَعَلَتْ قُرَيْشٌ تَمُرُّ عَلَيْهِ وَالنَّاسُ، حَتَّى مَرَّ عَلَيْهِ عَبْدُ اللَّهِ بْنُ عُمَرَ، فَوَقَفَ عَلَيْهِ، فَقَالَ: السَّلَامُ عَلَيْكَ، أَبَا خُبَيْبٍ، السَّلَامُ عَلَيْكَ، أَبَا خُبَيْبٍ، السَّلَامُ عَلَيْكَ، أَبَا خُبَيْبٍ، أَمَا وَاللهِ! لَقَدْ كُنْتُ أَنْهَاكَ عَنْ هَذَا، أَمَا وَاللهِ! لَقَدْ كُنْتُ أَنْهَاكَ عَنْ هَذَا، أَمَا وَاللهِ! لَقَدْ كُنْتُ أَنْهَاكَ عَنْ هَذَا، أَمَا وَاللهِ! إِنْ كُنْتَ، مَا عَلِمْتُ، صَوَّامًا، قَوَّامًا، وَصُولًا لِلرَّحِمِ، أَمَا وَاللهِ! لَأُمَّةٌ أَنْتَ أَشَرُّهَا لَأُمَّةٌ خَيْرٌ. ثُمَّ نَفَذَ عَبْدُ اللَّهِ بْنُ عُمَرَ، فَبَلَغَ الْحَجَّاجَ مَوْقِفُ عَبْدِ اللَّهِ وَقَوْلُهُ، فَأَرْسَلَ إِلَيْهِ، فَأُنْزِلَ عَنْ جِذْعِهِ، فَأُلْقِيَ فِي قُبُورِ الْيَهُودِ، ثُمَّ أَرْسَلَ إِلَى أُمِّهِ أَسْمَاءَ بِنْتِ أَبِي بَكْرٍ، فَأَبَتْ أَنْ تَأْتِيَهُ، فَأَعَادَ عَلَيْهَا الرَّسُولَ: لَتَأْتِيَنِّي أَوْ لَأَبْعَثَنَّ إِلَيْكِ مَنْ يَسْحَبُكِ بِقُرُونِكِ! قَالَ: فَأَبَتْ، وَقَالَتْ: وَاللهِ! لَا آتِيكَ حَتَّى تَبْعَثَ إِلَيَّ مَنْ يَسْحَبُنِي بِقُرُونِي! قَالَ: فَقَالَ: أَرُونِي سِبْتَيَّ! فَأَخَذَ نَعْلَيْهِ، ثُمَّ انْطَلَقَ يَتَوَذَّفُ، حَتَّى دَخَلَ عَلَيْهَا، فَقَالَ: كَيْفَ رَأَيْتِنِي صَنَعْتُ بِعَدُوِّ اللهِ؟ قَالَتْ: رَأَيْتُكَ أَفْسَدْتَ عَلَيْهِ دُنْيَاهُ، وَأَفْسَدَ عَلَيْكَ آخِرَتَكَ! بَلَغَنِي أَنَّكَ تَقُولُ لَهُ: يَا ابْنَ ذَاتِ النِّطَاقَيْنِ، أَنَا، وَاللهِ! ذَاتُ النِّطَاقَيْنِ؛ أَمَّا أَحَدُهُمَا فَكُنْتُ أَرْفَعُ بِهِ طَعَامَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَطَعَامَ أَبِي بَكْرٍ مِنَ الدَّوَابِّ، وَأَمَّا الْآخَرُ فَنِطَاقُ الْمَرْأَةِ الَّتِي لَا تَسْتَغْنِي عَنْهُ، أَمَا إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حَدَّثَنَا أَنَّ فِي ثَقِيفٍ كَذَّابًا وَمُبِيرًا، فَأَمَّا الْكَذَّابُ فَرَأَيْنَاهُ، وَأَمَّا الْمُبِيرُ فَلَا إِخَالُكَ إِلَّا إِيَّاهُ! قَالَ: فَقَامَ عَنْهَا وَلَمْ يُرَاجِعْهَا."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (229:2545) عن عقبة بن مكرم العمي، حدثنا يعقوب (يعني ابن إسحاق الحضرمي) أخبرنا الأسود بن شيبان، عن أبي نوفل فذكره.","grade":"صحيح","chapter_ar":"باب إخباره عن كذاب ثقيف ومبيره","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2545:229).","chapter_en":"His Foretelling the Liar of Thaqīf and Its Destroyer","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":16,"content":{"translation":{"en":["Abū Nawfal said: “I saw ʿAbdullāh ibn al-Zubayr on the pass of Madīnah, and Quraysh and the people were passing by him, until ʿAbdullāh ibn ʿUmar passed by. He stopped and said: ʿPeace be upon you, O Abū Khubayb. Peace be upon you, O Abū Khubayb. Peace be upon you, O Abū Khubayb. ʿBy Allah, I used to forbid you from this. By Allah, I used to forbid you from this. By Allah, I used to forbid you from this. ‘By Allah, as far as I knew you, you were one who fasted often, prayed much, and maintained ties of kinship. By Allah, a nation of which you are the worst member is certainly a good nation.’ “Then ʿAbdullāh ibn ʿUmar departed. “When al-Ḥajjāj was informed of where ʿAbdullāh had stood and what he had said, he sent someone to the body, and Ibn al-Zubayr was taken down from the wooden beam and thrown into the graves of the Jews. “Then al-Ḥajjāj sent for his mother, Asmāʾ bint Abī Bakr, but she refused to come to him. He sent the messenger back to her saying, ‘Either you come to me, or I will send someone who will drag you by your braids.’ “She refused and said, ‘By Allah, I will not come to you until you send someone to drag me by my braids.’ “He said, ‘Bring me my sandals.’ He took his sandals and hurried along until he entered upon her. “He said, ‘What do you think of what I have done to the enemy of Allah?’ “She replied, ʿI see that you have ruined his worldly life, while he has ruined your Hereafter. ʿI have been informed that you used to say to him, “O son of the woman of the two waist-belts!” By Allah, I am indeed the woman of the two waist-belts. As for one of them, I used it to secure the food of the Messenger of Allah ﷺ and Abū Bakr upon the riding animals. As for the other, it was the waist-belt that a woman cannot do without. ‘The Messenger of Allah ﷺ informed us that “Among Thaqīf there will be a liar and a destroyer.” As for the liar, we have already seen him. As for the destroyer, I do not think it is anyone but you.’ “So he stood up and left her without responding.”"]},"buhuth":{"en":["His saying “a liar” refers to al-Mukhtār ibn Abī ʿUbayd al-Thaqafī.","His saying “a destroyer” means one who causes great destruction and killing.","Al-Tirmidhī mentioned from Hishām ibn Ḥassān that he said: “They counted those whom al-Ḥajjāj killed in captivity, and the number reached one hundred and twenty thousand.”"]}},"tuhfa":{},"voc":["seerah",1700],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (229:2545)."},{"num":9738,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَدِمَ مُسَيْلِمَةُ الْكَذَّابُ عَلَى عَهْدِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَعَلَ يَقُولُ: إِنْ جَعَلَ لِي مُحَمَّدٌ مِنْ بَعْدِهِ تَبِعْتُهُ. وَقَدِمَهَا فِي بَشَرٍ كَثِيرٍ مِنْ قَوْمِهِ، فَأَقْبَلَ إِلَيْهِ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَفِي يَدِ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِطْعَةُ جَرِيدٍ حَتَّى وَقَفَ عَلَى مُسَيْلِمَةَ فِي أَصْحَابِهِ، فَقَالَ: لَوْ سَأَلْتَنِي هَذِهِ الْقِطْعَةَ مَا أَعْطَيْتُكَهَا وَلَنْ تَعْدُوَ أَمْرَ الله فِيكَ، وَلَئِنْ أَدْبَرْتَ لَيَعْقِرَنَّكَ الله، وَإِنِّي لأَرَاكَ الَّذِي أُرِيتُ فِيهِ مَا رَأَيْتُ، وَهَذَا ثَابِتٌ يُجِيبُكَ عَنِّي. ثُمَّ انْصَرَفَ عَنْهُ.","قَالَ ابْنُ عَبَّاسٍ فَسَأَلْتُ عَنْ قَوْلِ، رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ : إِنَّكَ أُرَى الَّذِي أُرِيتُ فِيهِ مَا أُرِيتُ فَأَخْبَرَنِي أَبُو هُرَيْرَةَ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بَيْنَا أَنَا نَائِمٌ رَأَيْتُ فِي يَدَيَّ سِوَارَيْنِ مِنْ ذَهَبٍ، فَأَهَمَّنِي شَأْنُهُمَا، فَأُوحِيَ إِلَيَّ فِي المَنَامِ: أَنِ انْفُخْهُمَا، فَنَفَخْتُهُمَا فَطَارَا، فَأَوَّلْتُهُمَا كَذَّابَيْنِ يَخْرُجَانِ بَعْدِي، أَحَدُهُمَا الْعَنْسِيُّ، وَالآخَرُ مُسَيْلِمَةُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4373) ومسلم في الرؤيا 21:2274،2273) كلاهما من طريق شعيب، عن عبد الله بن أبي حسين، حدثنا نافع بن جبير عن ابن عباس قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره عن كذاب ثقيف ومبيره","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4373, 4374) and Muslim (2273, 2274:21).","chapter_en":"His Foretelling the Liar of Thaqīf and Its Destroyer","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":16,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: “Musaylimah the Liar came during the lifetime of the Messenger of Allah ﷺ, saying, ‘If Muḥammad appoints me as his successor after him, I will follow him.’ “He came with a large number of his people. The Messenger of Allah ﷺ went toward him accompanied by Thābit ibn Qays ibn Shammās, while the Messenger of Allah ﷺ held a piece of palm stalk in his hand. “He stood before Musaylimah among his companions and said: ‘Even if you asked me for this piece, I would not give it to you. You will never escape what Allah has decreed concerning you. If you turn away, Allah will surely destroy you. I indeed see you as the one concerning whom I was shown what I was shown. And this is Thābit; he will answer you on my behalf.’ “Then he turned away from him.” Ibn ʿAbbās said: “I asked about the statement of the Messenger of Allah ﷺ: ‘I indeed see you as the one concerning whom I was shown what I was shown.’ “Abū Hurayrah informed me that the Messenger of Allah ﷺ said: ‘While I was sleeping, I saw two bracelets of gold on my hands, and their matter concerned me. It was revealed to me in the dream that I should blow upon them, so I blew upon them and they flew away. I interpreted them as two liars who would appear after me.’","“One of them was al-ʿAnsī, and the other was Musaylimah.”"]},"buhuth":{"en":["His saying “If you turn away, Allah will surely destroy you” means: if you turn away from obedience to me, Allah will kill you. This was one of the miracles of Prophethood, for Allah caused him to be killed on the Day of al-Yamāmah."]}},"tuhfa":{},"voc":["seerah",1701],"full":1,"dr":1,"rep":[9781],"tks":"متفق عليه: رواه البخاري (4373، 4374)، ومسلم (2273، 2274: 21)."},{"num":9739,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : بَيْنَا أَنَا نَائِمٌ أُتِيتُ بِخَزَائِنِ الأَرْضِ، فَوُضِعَ فِي كَفِّي سِوَارَانِ مِنْ ذَهَبٍ، فَكَبُرَا علي، فَأُوحِيَ إِلَى أَنِ انْفُخْهُمَا، فنختهما فَذَهَبَا، فَأَوَّلْتُهُمَا الْكَذَّابَيْنِ اللَّذَيْنِ أَنَا بَيْنَهُمَا: صَاحِبَ صَنْعَاءَ، وَصَاحِبَ الْيَمَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4375) ومسلم في الرؤيا (22:2274) كلاهما من طريق عبد الرزاق، عن معمر، عن همام، أنه سمع أبا هريرة يقول: فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره عن كذاب ثقيف ومبيره","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4375) and Muslim (2274:22).","chapter_en":"His Foretelling the Liar of Thaqīf and Its Destroyer","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":16,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “While I was sleeping, the treasures of the earth were brought to me, and two bracelets of gold were placed in my hands. They became burdensome to me, so it was revealed to me that I should blow upon them. I blew upon them and they disappeared. I interpreted them as the two liars between whom I am situated: the man of Ṣanʿāʾ and the man of al-Yamāmah.”"]},"buhuth":{"en":["The man of Ṣanʿāʾ was al-Aswad al-ʿAnsī, and the man of al-Yamāmah was Musaylimah the Liar, as explicitly stated in al-Bukhārī (3621)."]}},"tuhfa":{},"voc":["seerah",1702],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (4375)، ومسلم (22:2274). صاحب صنعاء هو: الأسود العنسي، وصاحب اليمامة هو: مسيلمة الكذاب. كما جاء عند البخاري (3621) مصرحا."},{"num":9740,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ:  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَدِمَ مِنْ سَفَرٍ، فَلَمَّا كَانَ قُرْبَ الْمَدِينَةِ هَاجَتْ رِيحٌ شَدِيدَةٌ تَكَادُ أَنْ تَدْفِنَ الرَّاكِبَ، فَزَعَمَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: بُعِثَتْ هَذِهِ الرِّيحُ لِمَوْتِ مُنَافِقٍ. فَلَمَّا قَدِمَ الْمَدِينَةَ، فَإِذَا مُنَافِقٌ عَظِيمٌ مِنَ الْمُنَافِقِينَ قَدْ مَاتَ."],"takhrij":"صحيح: رواه مسلم في صفات المنافقين (15:2782) عن أبي كريب محمد بن العلاء، حدثنا حفص – يعني ابن غياث – عن الأعمش، عن أبي سفيان، عن جابر فذكره.","grade":"صحيح","chapter_ar":"إخباره بهبوب الريح لموت منافق","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2782:15).","chapter_en":"His Foretelling the Blowing of the Wind Because of the Death of a Hypocrite","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":17,"content":{"translation":{"en":["Jābir reported that the Messenger of Allah ﷺ returned from a journey. When he came near Madīnah, a violent wind arose that almost buried the rider. He reported that the Messenger of Allah ﷺ said: “This wind has been sent because of the death of a hypocrite.” When he arrived in Madīnah, it was found that a prominent hypocrite had died."]}},"tuhfa":{},"voc":["seerah",1703],"full":1,"rep":[15049],"tks":"صحيح: رواه مسلم (15:2782)."},{"num":9741,"demo":false,"sanad":"","matn":["عَنْ أَبِي شَهْمٍ قَالَ: مَرَّتْ بِي جَارِيَةٌ بِالْمَدِينَةِ فَأَخَذْتُ بِكَشْحِهَا. قَالَ: وَأَصْبَحَ الرَّسُولُ يُبَايِعُ النَّاسَ، يَعْنِي النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، قَالَ: فَأَتَيْتُهُ، فَلَمْ يُبَايِعْنِي. فَقَالَ: صَاحِبُ الْجُبَيْذَةِ قَالَ: قُلْتُ: وَاللهِ لَا أَعُودُ. قَالَ: فَبَايَعَنِي."],"takhrij":"صحيح: رواه النسائي في الكبرى (7288) وأحمد (22511) وصححه الحاكم (4/377) كلهم من طريق الأسود بن عامر شاذان، حدثنا هريم بن سفيان، عن بيان بن بشر الأحمسي، عن قيس بن أبي حازم، عن أبي شهم فذكره.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ أبا شهم بجبذته","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (7288) and Aḥmad (22511), and authenticated by al-Ḥākim (4/377).","chapter_en":"The Prophet ﷺ Informing Abū Shahm About His Grabbing","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":18,"content":{"translation":{"en":["Abū Shahm said: “A slave girl passed by me in Madīnah, and I grabbed her by her side. “The next morning, the Messenger—meaning the Prophet ﷺ—was accepting the people’s pledges of allegiance. I came to him, but he did not accept my pledge. “He said: ‘The one who grabbed her!’ “I said, ‘By Allah, I will never do it again.’ “Then he accepted my pledge.”"]}},"tuhfa":{},"voc":["seerah",1704],"full":1,"dr":1,"tks":"صحيح: رواه النسائي في الكبرى (7288)، وأحمد (22511)، وصححه الحاكم (4/377)."},{"num":9742,"demo":false,"sanad":"","matn":["عَنِ الْفَلَتَانِ بْنِ عَاصِمٍ، قَالَ: كُنَّا قُعُودًا مَعَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي الْمَسْجِدِ، فَشَخَصَ بَصَرُهُ إِلَى رَجُلٍ يَمْشِي فِي الْمَسْجِدِ، فَقَالَ: يَا فُلَانُ، أَتَشْهَدُ أَنِّي رَسُولُ اللَّهِ؟ قَالَ: لَا، قَالَ: أَتَقْرَأُ التَّوْرَاةَ؟ قَالَ: نَعَمْ، قَالَ: وَالإِنْجِيلَ؟ قَالَ: نَعَمْ، قَالَ: وَالْقُرْآنَ؟ قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ أَشَاءُ لَقَرَأْتُهُ، قَالَ: ثُمَّ أَنْشَدَهُ، فَقَالَ: تَجِدُنِي فِي التَّوْرَاةِ وَالإِنْجِيلِ؟ قَالَ: نَجِدُ مِثْلَكَ، وَمَثَلَ أُمَّتِكَ، وَمَثَلَ مَخْرَجِكَ، وَكُنَّا نَرْجُو أَنْ تَكُونَ فِينَا، فَلَمَّا خَرَجْتَ، تَخَوَّفْنَا أَنْ تَكُونَ أَنْتَ، فَنَظَرْنَا، فَإِذَا لَيْسَ أَنْتَ هُوَ، قَالَ: وَلِمَ ذَاكَ؟ قَالَ: إِنَّ مَعَهُ مِنْ أُمَّتِهِ سَبْعِينَ أَلْفًا لَيْسَ عَلَيْهِمْ حِسَابٌ وَلَا عِقَابٌ، وَإِنَّ مَا مَعَكَ نَفَرٌ يَسِيرٌ، قَالَ: فَوَالَّذِي نَفْسِي بِيَدِهِ، لأَنَا هُوَ، وَإِنَّهَا لأُمَّتِي، وَإِنَّهُمْ لأَكْثَرُ مِنْ سَبْعِينَ أَلْفًا وَسَبْعِينَ أَلْفًا، وَسَبْعِينَ أَلْفًا."],"takhrij":"حسن: رواه البزار (3700) وابن حبان (6580) واللفظ له – والطبراني في الكبير (18/ح 854) كلهم من طرق عن عاصم بن كليب، حدثني أبي، عن خاله الفلتان بن عاصم فذكره.","grade":"حسن","chapter_ar":"باب إخباره عن كثرة أمته","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (3700), Ibn Ḥibbān (6580)—whose wording this is—and al-Ṭabarānī in al-Kabīr (18/332–333).","chapter_en":"His Foretelling the Great Number of His Nation","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":19,"content":{"translation":{"en":["Al-Faltān ibn ʿĀṣim said: “We were sitting with the Prophet ﷺ in the mosque when he fixed his gaze upon a man walking in the mosque. “He said, ‘O so-and-so, do you testify that I am the Messenger of Allah?’ “He replied, ‘No.’ “He asked, ‘Do you read the Torah?’ “He replied, ‘Yes.’ “He asked, ‘And the Gospel?’ “He replied, ‘Yes.’ “He asked, ‘And the Qurʾān?’ “He replied, ‘By the One in Whose hand is my soul, if I wished, I could recite it.’ “Then he questioned him and said: ‘Do you find mention of me in the Torah and the Gospel?’ “He replied, ‘We find someone like you, a nation like your nation, and a place of emergence like yours. We had hoped that he would arise among us. But when you appeared, we feared that you might be him. Then we examined the description and found that you were not he.’ “He ﷺ asked, ‘Why is that?’ “The man replied, ‘With him will be seventy thousand from his nation upon whom there will be no reckoning and no punishment, whereas only a small number are with you.’ “He ﷺ said: ‘By the One in Whose hand is my soul, I am indeed that man, and it is indeed my nation. And they will be more than seventy thousand, and seventy thousand, and seventy thousand.’”"]}},"tuhfa":{},"voc":["seerah",1705],"full":1,"dr":1,"tks":"حسن: رواه البزار (3700)، وابن حبان (6580) - واللفظ له -، والطبراني في الكبير (18/332-333)."},{"num":9743,"demo":false,"sanad":"","matn":["عَنْ رَجُلٍ من الأنصار قَالَ: خَرَجْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي جِنَازَةٍ، فَلَمَّا رَجَعْنَا لَقِيَنَا دَاعِي امْرَأَةٍ مِنْ قُرَيْشٍ، فَقَالَ: يَا رَسُولَ اللَّهِ، إِنَّ فُلَانَةً تَدْعُوكَ وَمَنْ مَعَكَ إِلَى طَعَامٍ، فَانْصَرَفَ فَانْصَرَفْنَا مَعَهُ، فَجَلَسْنَا مَجَالِسَ الْغِلْمَانِ مِنْ آبَائِهِمْ بَيْنَ يديهم، ثُمَّ جِيءَ بِالطَّعَامِ فَوَضَعَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَهُ، وَوَضَعَ الْقَوْمُ أَيْدِيَهُمْ، فَفَطِنَ لَهُ الْقَوْمُ، وَهُوَ يَلُوكُ لُقْمَتَهُ لَا يُجِيزُهَا، فَرَفَعُوا أَيْدِيَهُمْ وَغَفَلُوا عَنَّا، ثُمَّ ذَكَرُوا فَأَخَذُوا بِأَيْدِينَا، فَجَعَلَ الرَّجُلُ يَضْرِبُ اللُّقْمَةَ بِيَدِهِ حَتَّى تَسْقُطَ، ثُمَّ أَمْسَكُوا بِأَيْدِينَا يَنْظُرُونَ مَا يَصْنَعُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَفَظَهَا، فَأَلْقَاهَا، فَقَالَ: أَجِدُ لَحْمَ شَاةٍ أُخِذَتْ بِغَيْرِ إِذْنِ أَهْلِهَا  فَقَامَتِ الْمَرْأَةُ، فَقَالَتْ: يَا رَسُولَ اللَّهِ، إِنَّهُ كَانَ فِي نَفْسِي أَنْ أَجْمَعَكَ وَمَنْ مَعَكَ عَلَى طَعَامٍ، فَأَرْسَلْتُ إِلَى الْبَقِيعِ، فَلَمْ أَجِدْ شَاةً تُبَاعُ، وَكَانَ عَامِرُ بْنُ أَبِي وَقَّاصٍ ابْتَاعَ شَاةً أَمْسِ مِنَ الْبَقِيعِ، فَأَرْسَلْتُ إِلَيْهِ: أَنْ ابْتُغِيَ لِي شَاةً فِي الْبَقِيعِ فَلَمْ تُوجَدْ، فَذُكِرَ لِي أَنَّكَ اشْتَرَيْتَ شَاةً، فَأَرْسِلْ بِهَا إِلَيَّ، فَلَمْ يَجِدْهُ الرَّسُولُ وَوَجَدَ أَهْلَهُ فَدَفَعُوهَا إِلَى رَسُولِي فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أَطْعِمُوهَا الْأُسَارَى."],"takhrij":"حسن: رواه أحمد (22509) واللفظ له – وأبو داود (3332) كلاهما من طرق عن عاصم بن كليب، عن أبيه، عن رجل من الأنصار فذكره.","grade":"حسن","chapter_ar":"إخباره عن الشاة التي أخذت بغير إذن أهلها","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (22509)—whose wording this is—and Abū Dāwūd (3332).","chapter_en":"His Informing About the Sheep That Had Been Taken Without Its Owners’ Permission","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":20,"content":{"translation":{"en":["A man from the Anṣār said: “We went out with the Messenger of Allah ﷺ for a funeral. When we returned, we met the messenger of a Qurashī woman. “He said, ‘O Messenger of Allah, so-and-so invites you and those with you to a meal.’ “So he turned aside toward her, and we went with him. We sat in the places of boys in front of their fathers. “Then the food was brought. The Messenger of Allah ﷺ put his hand toward it, and the people put their hands toward it. “They noticed that he was chewing a morsel but could not swallow it, so they withdrew their hands. They initially forgot about us, then remembered us and took hold of our hands. A man would strike the morsel from our hands until it fell. “Then they kept hold of our hands and watched what the Messenger of Allah ﷺ would do. He spat the morsel out and threw it away, saying: ‘I sense that this is the meat of a sheep that was taken without its owners’ permission.’ “The woman stood and said, ‘O Messenger of Allah, I had wanted to gather you and those with you for a meal. I sent someone to al-Baqīʿ but found no sheep for sale. ʿĀmir ibn Abī Waqqāṣ had purchased a sheep from al-Baqīʿ yesterday, so I sent someone to him saying, “Find me a sheep in al-Baqīʿ.” None was found, and I was told that you had purchased a sheep, so I sent to you asking that it be sent to me. The messenger did not find him, but found his family, and they handed it over to my messenger.’ “The Messenger of Allah ﷺ said: ‘Feed it to the prisoners.’”"]}},"tuhfa":{},"voc":["seerah",1706],"full":1,"dr":1,"tks":"حسن: رواه أحمد (22509) - واللفظ له -، وأبو داود (3332)."},{"num":9744,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: خَرَجَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي مَرَضِهِ الَّذِي مَاتَ فِيهِ، بِمِلْحَفَةٍ، قَدْ عَصَّبَ بِعِصَابَةٍ دَسْمَاءَ، حَتَّى جَلَسَ عَلَى الْمِنْبَرِ، فَحَمِدَ اللَّهَ وَأَثْنَى عَلَيْهِ ثُمَّ قَالَ: أَمَّا بَعْدُ، فَإِنَّ النَّاسَ يَكْثُرُونَ، وَيَقِلُّ الأَنْصَارُ، حَتَّى يَكُونُوا فِي النَّاسِ بِمَنْزِلَةِ الْمِلْحِ فِي الطَّعَامِ، فَمَنْ وَلِيَ مِنْكُمْ شَيْئًا يَضُرُّ فِيهِ قَوْمًا، وَيَنْفَعُ فِيهِ آخَرِينَ، فَلْيَقْبَلْ مِنْ مُحْسِنِهِمْ، وَيَتَجَاوَزْ عَنْ مُسِيئِهِمْ. فَكَانَ آخِرَ مَجْلِسٍ جَلَسَ بِهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في علامات النبوة (3628) عن أبي نعيم، حدثنا عبد الرحمن بن سليمان بن حنظلة بن الغسيل، حدثنا عكرمة، عن ابن عباس فذكره.","grade":"صحيح","chapter_ar":"باب إخبار النبي ﷺ عن قلة الأنصار","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (3628).","chapter_en":"The Prophet ﷺ Foretelling the Decline in the Number of the Anṣār","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":21,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās said: “During the illness from which the Messenger of Allah ﷺ died, he came out wrapped in a sheet, with a dark-colored band tied around his head, until he sat upon the pulpit. “He praised Allah and extolled Him, then said: ‘To proceed: The people will increase in number while the Anṣār will decrease, until they become among the people like salt in food. Whoever among you is placed in authority over something by which he may harm some people and benefit others, let him accept the good deeds of the virtuous among the Anṣār and overlook the faults of those among them who do wrong.’ “This was the last gathering in which the Prophet ﷺ sat.”"]}},"tuhfa":{},"voc":["seerah",1707],"full":1,"rep":[10514],"tks":"صحيح: رواه البخاري (3628)."},{"num":9745,"demo":false,"sanad":"","matn":["عَنْ بُرَيْدَةَ بْنِ الحصيب قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : لَا ينقصني مِائَةُ سَنَةٍ وَعَيْنٌ تَطْرِفُ.","وَفِي رِوَايَةٍ: إِنَّ لِلَّهِ تَبَارَكَ وَتَعَالَى رِيحًا يَبْعَثُهَا عِنْدَ رَأْسِ مِائَةِ سَنَةٍ فَتَقْبِضُ رُوحَ كُلِّ مُؤْمِنٍ."],"takhrij":"حسن: رواه البزار (229،228) – كشف الأستار، من طريقين عن بشير بن المهاجر، عن عبد الله بن بريدة، عن أبيه، فذكر الحديث.","grade":"حسن","chapter_ar":"باب إخباره بأنه لا يبقى على رأس المائة أحد","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Bazzār (228, 229) in Kashf al-Astār.","chapter_en":"His Foretelling That No One Would Remain at the End of One Hundred Years","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":22,"content":{"translation":{"en":["Buraydah ibn al-Ḥuṣayb said that the Messenger of Allah ﷺ said: “One hundred years will not pass while an eye that now blinks remains alive.” In another narration: “Indeed, Allah, Blessed and Most High, will send a wind at the end of one hundred years, and it will take the soul of every believer.”"]},"buhuth":{"en":["This prophecy was fulfilled. Abū al-Ṭufayl ʿĀmir ibn Wāthilah al-Kinānī, who was born in the year of Uḥud and lived for eight years during the lifetime of the Prophet ﷺ, was the last of the Companions to die, in the year 110 AH. Before his death, he used to say: “There is no man on the face of the earth today who saw the Prophet ﷺ other than me.”"]}},"tuhfa":{},"voc":["seerah",1708],"full":1,"dr":1,"tks":"حسن: رواه البزار (228، 229) - كشف الأستار. لقد تحقق هذا التنبؤ، فكان أبو الطفيل عامر بن واثلة الكناني، الذي ولد عام أحد، وأدرك من حياة النبي ﷺ ثمان سنين، آخر من مات من الصحابة سنة عشر ومائة، وكان يقول قبل موته: ما على وجه الأرض رجل اليوم رأى النبي ﷺ غيري."},{"num":9746,"demo":false,"sanad":"","matn":["عَنْ نَافِعِ بْنِ عُتْبَةَ قَالَ:  كُنَّا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي غَزْوَةٍ، قَالَ: فَأَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَوْمٌ مِنْ قِبَلِ الْمَغْرِبِ، عَلَيْهِمْ ثِيَابُ الصُّوفِ، فَوَافَقُوهُ عِنْدَ أَكَمَةٍ، فَإِنَّهُمْ لَقِيَامٌ وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَاعِدٌ، قَالَ: فَقَالَتْ لِي نَفْسِي: ائْتِهِمْ فَقُمْ بَيْنَهُمْ وَبَيْنَهُ، لَا يَغْتَالُونَهُ. قَالَ: ثُمَّ قُلْتُ: لَعَلَّهُ نَجِيٌّ مَعَهُمْ، فَأَتَيْتُهُمْ فَقُمْتُ بَيْنَهُمْ وَبَيْنَهُ، قَالَ: فَحَفِظْتُ مِنْهُ أَرْبَعَ كَلِمَاتٍ، أَعُدُّهُنَّ فِي يَدِي، قَالَ: تَغْزُونَ جَزِيرَةَ الْعَرَبِ، فَيَفْتَحُهَا اللهُ، ثُمَّ فَارِسَ، فَيَفْتَحُهَا اللهُ، ثُمَّ تَغْزُونَ الرُّومَ، فَيَفْتَحُهَا اللهُ، ثُمَّ تَغْزُونَ الدَّجَّالَ، فَيَفْتَحُهُ اللهُ.","قَالَ: فَقَالَ نَافِعٌ: يَا جَابِرُ ! لاَ نَرَى الدَّجَّالَ يَخْرُجُ حَتَّى تُفْتَحَ الرُّومُ."],"takhrij":"صحيح: رواه مسلم في الفتن (38:2900) عن قتيبة بن سعيد، حدثنا جرير، عن عبدالملك بن عمير، عن جابر بن سمرة، عن نافع بن عتبة فذكره.","grade":"صحيح","chapter_ar":"إخباره عن فتح جزيرة العرب وفارس والروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2900:38).","chapter_en":"His Foretelling the Conquest of the Arabian Peninsula, Persia, and the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":23,"content":{"translation":{"en":["Nāfiʿ ibn ʿUtbah said: “We were with the Messenger of Allah ﷺ on an expedition when some people came to the Prophet ﷺ from the direction of the west, wearing woolen garments. They met him near a small hill while they were standing and the Messenger of Allah ﷺ was seated. “I said to myself, ‘Go to them and stand between them and him, lest they assassinate him.’ “Then I thought, ‘Perhaps he is speaking privately with them.’ “So I went and stood between them and him. I memorized four statements from him, counting them on my hand. He said: ‘You will fight the Arabian Peninsula, and Allah will grant you victory over it. Then Persia, and Allah will grant you victory over it. Then you will fight the Romans, and Allah will grant you victory over them. Then you will fight the Dajjāl, and Allah will grant you victory over him.’ “Nāfiʿ then said, ‘O Jābir, we do not think that the Dajjāl will emerge until the Romans have been conquered.’”"]}},"tuhfa":{},"voc":["seerah",1709],"full":1,"rep":[15972,15975],"tks":"صحيح: رواه مسلم (38:2900)."},{"num":9747,"demo":false,"sanad":"","matn":["عَنْ عَوْفِ بْنِ مَالِكٍ، أَنَّهُ قَالَ: إِنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَامَ فِي أَصْحَابِهِ فَقَالَ: الْفَقْرَ تَخَافُونَ، أَوِ الْعَوَزَ، أَوَ تُهِمُّكُمُ الدُّنْيَا؟ فَإِنَّ اللَّهَ فَاتِحٌ لَكُمْ أَرْضَ فَارِسَ وَالرُّومِ، وَتُصَبُّ عَلَيْكُمُ الدُّنْيَا صَبًّا، حَتَّى لَا يُزِيغُكُمْ بَعْدِي إِنْ أَزَاغَكُمْ إِلَّا هِيَ."],"takhrij":"حسن: رواه أحمد (23982) والطبراني (18/ح 93) كلاهما من طريق بقية بن الوليد، حدثني بحير بن سعد، عن خالد بن معدان، عن جبير بن نفير، عن عوف بن مالك فذكره.","grade":"حسن","chapter_ar":"إخباره عن فتح جزيرة العرب وفارس والروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (23982) and al-Ṭabarānī in al-Kabīr (18/52).","chapter_en":"His Foretelling the Conquest of the Arabian Peninsula, Persia, and the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":23,"content":{"translation":{"en":["ʿAwf ibn Mālik reported that the Messenger of Allah ﷺ stood among his Companions and said: “Is it poverty that you fear, or need, or is it this worldly life that concerns you? Indeed, Allah will open for you the lands of Persia and Rome, and the wealth of this world will be poured upon you abundantly, until nothing after me will cause you to deviate, if anything does, except it.”"]}},"tuhfa":{},"voc":["seerah",1710],"full":1,"dr":1,"tks":"حسن: رواه أحمد (23982)، والطبراني في الكبير (18/ح 93)."},{"num":9748,"demo":false,"sanad":"","matn":["عَنْ أَبِي ذَرٍّ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّكُمْ سَتَفْتَحُونَ مِصْرَ، وَهِيَ أَرْضٌ يُسَمَّى فِيهَا الْقِيرَاطُ، فَإِذَا فَتَحْتُمُوهَا فَأَحْسِنُوا إِلَى أَهْلِهَا، فَإِنَّ لَهُمْ ذِمَّةً وَرَحِمًا - أَوْ قَالَ: ذِمَّةً وَصِهْرًا، فَإِذَا رَأَيْتَ رَجُلَيْنِ يَخْتَصِمَانِ فِيهَا فِي مَوْضِعِ لَبِنَةٍ فَاخْرُجْ مِنْهَا. قَالَ: فَرَأَيْتُ عَبْدَ الرَّحْمَنِ بْنَ شُرَحْبِيلَ بْنِ حَسَنَةَ وَأَخَاهُ رَبِيعَةَ يَخْتَصِمَانِ فِي مَوْضِعِ لَبِنَةٍ، فَخَرَجْتُ مِنْهَا."],"takhrij":"صحيح: رواه مسلم في فضائل الصحابة (227:2543) عن زهير بن حرب وعبد الله بن سعيد قالا: حدثنا وهب بن جرير، حدثنا أبي، سمعت حرملة المصري، يحدث عن عبدالرحمن بن شماسة، عن أبي بصرة، عن أبي ذر قال: فذكره.","grade":"صحيح","chapter_ar":"إخباره عن فتح مصر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2543:227).","chapter_en":"His Foretelling the Conquest of Egypt","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":24,"content":{"translation":{"en":["Abū Dharr reported that the Messenger of Allah ﷺ said: “You will conquer Egypt, a land in which the qīrāṭ is commonly mentioned. When you conquer it, treat its people well, for they have a covenant and ties of kinship—or he said: a covenant and ties through marriage. “And when you see two men disputing there over the space of a single brick, then leave it.” Abū Dharr said: “I later saw ʿAbd al-Raḥmān ibn Shuraḥbīl ibn Ḥasanah and his brother Rabīʿah disputing over the space of a single brick, so I left Egypt.”"]}},"tuhfa":{},"voc":["seerah",1711],"full":1,"rep":[10556],"tks":"صحيح: رواه مسلم (227:2543)."},{"num":9749,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، قَالَ: لَقَدْ نَفَعَنِي اللَّهُ بِكَلِمَةٍ سَمِعْتُهَا مِنْ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيَّامَ الْجَمَلِ، بَعْدَ مَا كِدْتُ أَنْ أَلْحَقَ بِأَصْحَابِ الْجَمَلِ فَأُقَاتِلَ مَعَهُمْ قَالَ: لَمَّا بَلَغَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ أَهْلَ فَارِسَ قَدْ مَلَّكُوا عَلَيْهِمْ بِنْتَ كِسْرَى قَالَ: لَنْ يُفْلِحَ قَوْمٌ وَلَّوْا أَمْرَهُمُ امْرَأَةً."],"takhrij":"صحيح: رواه البخاري في المغازي (4425) عن عثمان بن الهيثم، حدثنا عوف، عن الحسن، عن أبي بكرة فذكره.","grade":"صحيح","chapter_ar":"باب إخباره أنه لن يفلح قوم ولوا أمرهم امرأة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Military Campaigns (4425).","chapter_en":"His Foretelling That a People Who Entrust Their Affairs to a Woman Will Not Prosper","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":25,"content":{"translation":{"en":["Abū Bakrah said: “Allah benefited me through a statement that I heard from the Messenger of Allah ﷺ during the events of the Camel, after I had nearly joined the people of the Camel and fought alongside them. “When the Messenger of Allah ﷺ was informed that the people of Persia had appointed the daughter of Khosrow as their ruler, he said: ‘A people who entrust their affairs to a woman will never prosper.’”"]}},"tuhfa":{},"voc":["seerah",1712],"full":1,"rep":[8287,9797,10329],"tks":"صحيح: رواه البخاري (4425)."},{"num":9750,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ:  لَمَّا كَذَّبَتْنِي قُرَيْشٌ، قُمْتُ فِي الْحِجْرِ، فَجَلَا اللهُ لِي بَيْتَ الْمَقْدِسِ، فَطَفِقْتُ أُخْبِرُهُمْ عَنْ آيَاتِهِ، وَأَنَا أَنْظُرُ إِلَيْهِ."],"takhrij":"متفق عليه: رواه البخاري في مناقب الأنصار (3886) ومسلم في الإيمان (276:170) كلاهما من طريق الليث، عن عقيل، عن ابن شهاب الزهري، عن أبي سلمة بن عبد الرحمن، عن جابر بن عبد الله فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره عن صفة بيت المقدس بعد ما رفعه الله له إلى مكة ليراه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (3886) and Muslim (170:276).","chapter_en":"His Description of Bayt al-Maqdis After Allah Raised It Before Him in Makkah So That He Could See It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":26,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh reported that the Messenger of Allah ﷺ said: “When Quraysh accused me of lying, I stood in al-Ḥijr, and Allah displayed Bayt al-Maqdis before me. I then began describing its signs to them while looking directly at it.”"]}},"tuhfa":{},"voc":["seerah",1713],"full":1,"tks":"متفق عليه: رواه البخاري (3886)، ومسلم (276:170)."},{"num":9751,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  لَقَدْ رَأَيْتُنِي فِي الْحِجْرِ، وَقُرَيْشٌ تَسْأَلُنِي عَنْ مَسْرَايَ، فَسَأَلَتْنِي عَنْ أَشْيَاءَ مِنْ بَيْتِ الْمَقْدِسِ لَمْ أُثْبِتْهَا، فَكُرِبْتُ كُرْبَةً مَا كُرِبْتُ مِثْلَهُ قَطُّ، قَالَ: فَرَفَعَهُ اللهُ لِي أَنْظُرُ إِلَيْهِ، مَا يَسْأَلُونِي عَنْ شَيْءٍ إِلَّا أَنْبَأْتُهُمْ بِهِ، وَقَدْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (278:172) عن زهير بن حرب، حدثنا جحين بن المثنى، حدثنا عبد العزيز – وهو ابن أبي سلمة، عن عبد الله بن الفضل، عن أبي سلمة بن عبد الرحمن، عن أبي هريرة فذكره.","grade":"صحيح","chapter_ar":"باب إخباره عن صفة بيت المقدس بعد ما رفعه الله له إلى مكة ليراه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (172:278).","chapter_en":"His Description of Bayt al-Maqdis After Allah Raised It Before Him in Makkah So That He Could See It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":26,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “I remember myself standing in al-Ḥijr while Quraysh questioned me about my Night Journey. They asked me about certain details of Bayt al-Maqdis that I had not firmly retained, and I became distressed with a distress unlike anything I had ever experienced. “Then Allah raised it before me so that I could look at it. They did not ask me about anything except that I informed them of it…” The hadith continues."]}},"tuhfa":{},"voc":["seerah",1714],"full":1,"tks":"صحيح: رواه مسلم (278:172)."},{"num":9752,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ  أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ شَاوَرَ حِينَ بَلَغَهُ إِقْبَالُ أَبِي سُفْيَانَ، قَالَ: فَتَكَلَّمَ أَبُو بَكْرٍ فَأَعْرَضَ عَنْهُ، ثُمَّ تَكَلَّمَ عُمَرُ فَأَعْرَضَ عَنْهُ، فَقَامَ سَعْدُ بْنُ عُبَادَةَ فَقَالَ: إِيَّانَا تُرِيدُ؟ يَا رَسُولَ اللَّهِ، وَالَّذِي نَفْسِي بِيَدِهِ، لَوْ أَمَرْتَنَا أَنْ نُخِيضَهَا الْبَحْرَ لَأَخَضْنَاهَا، وَلَوْ أَمَرْتَنَا أَنْ نَضْرِبَ أَكْبَادَهَا إِلَى بَرْكِ الْغِمَادِ لَفَعَلْنَا. قَالَ: فَنَدَبَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ النَّاسَ، فَانْطَلَقُوا حَتَّى نَزَلُوا بَدْرًا، وَوَرَدَتْ عَلَيْهِمْ رَوَايَا قُرَيْشٍ، وَفِيهِمْ غُلَامٌ أَسْوَدُ لِبَنِي الْحَجَّاجِ. فَأَخَذُوهُ، فَكَانَ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَسْأَلُونَهُ عَنْ أَبِي سُفْيَانَ وَأَصْحَابِهِ، فَيَقُولُ: مَا لِي عِلْمٌ بِأَبِي سُفْيَانَ، وَلَكِنْ هَذَا أَبُو جَهْلٍ، وَعُتْبَةُ، وَشَيْبَةُ، وَأُمَيَّةُ بْنُ خَلَفٍ. فَإِذَا قَالَ ذَلِكَ، ضَرَبُوهُ، فَقَالَ: نَعَمْ، أَنَا أُخْبِرُكُمْ، هَذَا أَبُو سُفْيَانَ، فَإِذَا تَرَكُوهُ فَسَأَلُوهُ فَقَالَ: مَا لِي بِأَبِي سُفْيَانَ عِلْمٌ، وَلَكِنْ هَذَا أَبُو جَهْلٍ، وَعُتْبَةُ، وَشَيْبَةُ، وَأُمَيَّةُ بْنُ خَلَفٍ فِي النَّاسِ، فَإِذَا قَالَ هَذَا أَيْضًا ضَرَبُوهُ. وَرَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يُصَلِّي، فَلَمَّا رَأَى ذَلِكَ انْصَرَفَ. قَالَ: وَالَّذِي نَفْسِي بِيَدِهِ، لَتَضْرِبُوهُ إِذَا صَدَقَكُمْ. وَتَتْرُكُوهُ إِذَا كَذَبَكُمْ. قَالَ: فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا مَصْرَعُ فُلَانٍ. قَالَ: وَيَضَعُ يَدَهُ عَلَى الْأَرْضِ، هَا هُنَا وَهَا هُنَا، قَالَ: فَمَا مَاطَ أَحَدُهُمْ عَنْ مَوْضِعِ يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (83:1779) عن أبي بكر بن أبي شيبة، حدثنا عفان، حدثنا حماد بن سلمة، عن ثابت، عن أنس بن مالك قال: فذكره.","grade":"صحيح","chapter_ar":"باب إخباره عن موضع قتل رؤساء قريش في غزوة بدر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1779:83).","chapter_en":"His Foretelling the Places Where the Leaders of Quraysh Would Be Killed at the Battle of Badr","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":27,"content":{"translation":{"en":["Anas reported that when news reached the Messenger of Allah ﷺ that Abū Sufyān was approaching, he consulted his Companions. “Abū Bakr spoke, but he turned away from him. Then ʿUmar spoke, but he turned away from him. “Saʿd ibn ʿUbādah stood and said, ‘Is it us you mean, O Messenger of Allah? By the One in Whose hand is my soul, if you commanded us to plunge into the sea, we would plunge into it. And if you commanded us to drive our camels all the way to Bark al-Ghimād, we would do so.’ “The Messenger of Allah ﷺ then called the people to march. They set out until they encamped at Badr. “Some water-carriers of Quraysh came to them, among them a black slave belonging to Banū al-Ḥajjāj. They seized him. “The Companions of the Messenger of Allah ﷺ began asking him about Abū Sufyān and his companions. “He would say, ‘I have no knowledge of Abū Sufyān. But Abū Jahl, ʿUtbah, Shaybah, and Umayyah ibn Khalaf are here.’ “Whenever he said this, they would strike him. “He would then say, ‘Yes, I will tell you. Abū Sufyān is here.’ “When they stopped striking him and questioned him again, he would say, ‘I have no knowledge of Abū Sufyān, but Abū Jahl, ʿUtbah, Shaybah, and Umayyah ibn Khalaf are among the people.’ “Whenever he said this, they would strike him again. “The Messenger of Allah ﷺ was standing in prayer. When he saw this, he finished and said: ‘By the One in Whose hand is my soul, you strike him when he tells you the truth, and you leave him alone when he lies to you!’ “Then the Messenger of Allah ﷺ said: ‘This is the place where so-and-so will be killed.’ “He would place his hand upon the ground and say: ‘Here, and here.’ “Not one of them moved away from the place where the Messenger of Allah ﷺ had placed his hand.”"]},"buhuth":{"en":["His saying “none of them moved away” means: none of them fell at a distance from the place indicated."]}},"tuhfa":{},"voc":["seerah",1715],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (83:1779). قوله: «فما ماط أحدهم» أي تباعد."},{"num":9753,"demo":false,"sanad":"","matn":["عَنْ ثَوْبَانَ قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ:  إِنَّ اللَّهَ زَوَى لِي الْأَرْضَ، فَرَأَيْتُ مَشَارِقَهَا وَمَغَارِبَهَا، وَإِنَّ أُمَّتِي سَيَبْلُغُ مُلْكُهَا مَا زُوِيَ لِي مِنْهَا، وَأُعْطِيتُ."],"takhrij":"صحيح: رواه مسلم في الفتن (19:2889) من طرق عن حماد بن زيد، عن أيوب، عن أبي قلابة، عن أبي أسماء، عن ثوبان فذكره.","grade":"صحيح","chapter_ar":"باب إخباره عن بلوغ ملك أمته إلى مشارق الأرض ومغاربها","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (2889:19).","chapter_en":"His Foretelling That the Dominion of His Nation Would Reach the East and West of the Earth","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":28,"content":{"translation":{"en":["Thawbān reported that the Messenger of Allah ﷺ said: “Indeed, Allah drew the earth together for me, and I saw its eastern and western extremities. The dominion of my nation will surely reach all that was drawn together for me…” The hadith continues."]},"buhuth":{"en":["Al-Nawawī said:","“This hadith contains an indication that the dominion of this nation would extend primarily in the directions of the east and the west, and this is exactly what occurred. As for its extension toward the south and the north, it was comparatively less than its extension toward the east and the west.”"]}},"tuhfa":{},"voc":["seerah",1716],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (19:2889)."},{"num":9754,"demo":false,"sanad":"","matn":["عن حَارِثَةَ بن وَهْبٍ يَقُولُ: سَمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ:  تَصَدَّقُوا، فَيُوشِكُ الرَّجُلُ يَمْشِي بِصَدَقَتِهِ، فَيَقُولُ الَّذِي أُعْطِيَهَا: لَوْ جِئْتَنَا بِهَا بِالْأَمْسِ قَبِلْتُهَا، فَأَمَّا الْآنَ فَلَا حَاجَةَ لِي بِهَا، فَلَا يَجِدُ مَنْ يَقْبَلُهَا."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1411) ومسلم في الزكاة (58:1011) كلاهما من طريق شعبة، عن معبد بن خالد، قال: سمعت حارثة بن وهب قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن إفاضة المال واستغناء الناس عنه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1411) and Muslim (1011:58).","chapter_en":"His Foretelling ﷺ That Wealth Would Become Abundant and People Would Have No Need of It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":29,"content":{"translation":{"en":["Ḥārithah ibn Wahb said: I heard the Messenger of Allah ﷺ say: “Give in charity, for soon a man will walk about carrying his charity, but the person to whom it is offered will say, ‘Had you brought it to us yesterday, I would have accepted it, but now I have no need of it.’ He will then find no one willing to accept it.”"]}},"tuhfa":{},"voc":["seerah",1717],"full":1,"rep":[15948],"tks":"متفق عليه: رواه البخاري (1411)، ومسلم (58: 1011)."},{"num":9755,"demo":false,"sanad":"","matn":["عَنْ أَبِي مُوسَى رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لَيَأْتِيَنَّ عَلَى النَّاسِ زَمَانٌ يَطُوفُ الرَّجُلُ فِيهِ بِالصَّدَقَةِ مِنَ الذَّهَبِ، ثُمَّ لاَ يَجِدُ أَحَدًا يَأْخُذُهَا مِنْهُ، وَيُرَى الرَّجُلُ الْوَاحِدُ يَتْبَعُهُ أَرْبَعُونَ امْرَأَةً، يَلُذْنَ بِهِ مِنْ قِلَّةِ الرِّجَالِ وَكَثْرَةِ النِّسَاءِ."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1414) ومسلم في الزكاة (59:1012) كلاهما عن أبي كريب محمد بن العلاء، حدثنا أبو أسامة، عن بريد، عن أبي بردة، عن أبي موسى قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن إفاضة المال واستغناء الناس عنه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī in the Book of Zakāh (1414) and Muslim in the Book of Zakāh (1012:59), both of them from Abū Kurayb Muḥammad ibn al-ʿAlāʾ: Abū Usāmah narrated to us, from Burayd, from Abū Burdah, from Abū Mūsā, and he mentioned it.","chapter_en":"His Foretelling ﷺ That Wealth Would Become Abundant and People Would Have No Need of It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":29,"content":{"translation":{"en":["Abū Mūsā reported that the Prophet ﷺ said: “A time will certainly come upon the people when a man will go about carrying charity in gold but will find no one willing to take it from him. One man will be seen followed by forty women who seek refuge with him because of the scarcity of men and the abundance of women.”"]}},"tuhfa":{},"voc":["seerah",1718],"full":1,"tks":"متفق عليه: رواه البخاري (1414)، ومسلم (59: 1012)."},{"num":9756,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ قَالَ قَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لاَ تَقُومُ السَّاعَةُ حَتَّى يَكْثُرَ فِيكُمُ الْمَالُ فَيَفِيضَ، حَتَّى يُهِمَّ رَبَّ الْمَالِ مَنْ يَقْبَلُ صَدَقَتَهُ، وَحَتَّى يَعْرِضَهُ فَيَقُولَ الَّذِي يَعْرِضُهُ عَلَيْهِ: لاَ أَرَبَ لِي."],"takhrij":"متفق عليه: رواه البخاري في الزكاة (1412) عن أبي اليمان، أخبرنا شعيب، حدثنا أبو الزناد، عن عبد الرحمن، عن أبي هريرة فذكره.","grade":"متفق عليه","chapter_ar":"باب إخباره ﷺ عن إفاضة المال واستغناء الناس عنه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (1412) and Muslim (157:60).","chapter_en":"His Foretelling ﷺ That Wealth Would Become Abundant and People Would Have No Need of It","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":29,"content":{"translation":{"en":["Abū Hurayrah reported that the Prophet ﷺ said: “The Hour will not be established until wealth becomes so abundant among you that it overflows, until the owner of wealth becomes concerned about who will accept his charity. He will offer it to someone, but the person to whom it is offered will say, ‘I have no need of it.’”"]},"buhuth":{"en":["Muslim also narrated (157:60) that the Messenger of Allah ﷺ said:","“The Hour will not be established until wealth becomes abundant and overflows, until a man goes out carrying the zakāh of his wealth but finds no one willing to accept it from him, and until the land of Arabia returns to being meadows and rivers.”","I say: What the Prophet ﷺ foretold was indeed fulfilled, as wealth became so abundant that all the people were free of need in the year 100 AH, during the caliphate of ʿUmar ibn ʿAbd al-ʿAzīz, may Allah have mercy upon him. Al-Bayhaqī stated something similar in Dalā’il al-Nubuwwah (6/323)."]}},"tuhfa":{},"voc":["seerah",1719],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (1412)، ومسلم (60: 157)."},{"num":9757,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: لاَ تَقُومُ السَّاعَةُ حَتَّى تَخْرُجَ نَارٌ مِنْ أَرْضِ الْحِجَازِ تُضِيءُ أَعْنَاقَ الإِبِلِ بِبُصْرَى."],"takhrij":"متفق عليه: رواه البخاري في الفتن (7118) ومسلم في الفتن (42:2902) كلاهما من طريق الزهري، أنه قال: قال سعيد بن المسيب، أخبرني أبو هريرة فذكره.","grade":"متفق عليه","chapter_ar":"إخباره عن خروج النار بأرض الحجاز","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7118) and Muslim (2902:42).","chapter_en":"His Foretelling of the Emergence of a Fire in the Land of the Ḥijāz","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":30,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “The Hour will not be established until a fire emerges from the land of the Ḥijāz that illuminates the necks of the camels at Buṣrā.”"]},"buhuth":{"en":["Al-Nawawī said:","“A fire did indeed emerge in our time at Madīnah in the year 654 AH. It was an exceedingly great fire on the eastern side of Madīnah, beyond the volcanic tract. Knowledge of it was mass-transmitted among all the people of al-Shām and the other lands, and some of the people of Madīnah who witnessed it informed me about it.”"]}},"tuhfa":{},"voc":["seerah",1720],"full":1,"dr":1,"rep":[15958],"tks":"متفق عليه: رواه البخاري (7118)، ومسلم (42: 2902)."},{"num":9758,"demo":false,"sanad":"","matn":["عن الْحَسَنِ بن أيوب الحضرمي قَالَ: أَرَانِي عَبْدُ اللَّهِ بْنُ بُسْرٍ شَامَةً فِي قَرْنِهِ، فَوَضَعْتُ إِصْبُعِي عَلَيْهَا، فَقَالَ: وَضَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِصْبُعَهُ عَلَيْهَا، ثُمَّ قَالَ: لَتَبْلُغَنَّ قَرْنًا.","قَالَ أَبُو عَبْدِ اللَّهِ: وَكَانَ ذَا جُمَّةٍ."],"takhrij":"حسن: رواه الإمام أحمد (17689) وابن أبي عاصم في الآحاد والمثاني (1343) كلاهما من طريق أبي عبد الله الحسن بن أيوب الحضرمي قال: فذكره.","grade":"حسن","chapter_ar":"باب إخباره أن عبد الله بن بسر سيعيش مائة سنة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (17689) and Ibn Abī ʿĀṣim in al-Āḥād wa-al-Mathānī (1343).","chapter_en":"His Foretelling That ʿAbdullāh ibn Busr Would Live for One Hundred Years","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":31,"content":{"translation":{"en":["Al-Ḥasan ibn Ayyūb al-Ḥaḍramī said: ʿAbdullāh ibn Busr showed me a mark upon the side of his head, so I placed my finger upon it. He said: “The Messenger of Allah ﷺ placed his finger upon it and then said, ‘You will certainly reach a century.’” Abū ʿAbdullāh said: He had long hair reaching his shoulders."]}},"tuhfa":{},"voc":["seerah",1721],"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (17689)، وابن أبي عاصم في الآحاد والمثاني (1343)."},{"num":9759,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: حَدَّثَنِي خَلِيلِي الصَّادِقُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، أَنَّهُ قَالَ: يَكُونُ فِي هَذِهِ الْأُمَّةِ بَعْثٌ إِلَى السِّنْدِ وَالْهِنْدِ، فَإِنْ أَنَا أَدْرَكْتُهُ فَاسْتُشْهِدْتُ فَذَاكَ، وَإِنْ أَنَا فَذَكَرَ كَلِمَةً رَجَعْتُ وَأَنَا أَبُو هُرَيْرَةَ الْمُحَرَّرُ قَدْ أَعْتَقَنِي مِنَ النَّارِ."],"takhrij":"حسن: رواه أحمد (8823) عن يحيى بن إسحاق، أخبرنا البراء، عن الحسن، عن أبي هريرة فذكره.","grade":"حسن","chapter_ar":"باب إخباره ﷺ بغزو الهند والسند","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Aḥmad (8823).","chapter_en":"His Foretelling ﷺ of the Campaign to India and Sindh","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":32,"content":{"translation":{"en":["Abū Hurayrah said: My truthful beloved, the Messenger of Allah ﷺ, told me: “There will be an expedition from this nation to Sindh and India.” If I live to witness it and am martyred, then that will be so; but if I—then he mentioned a word—return, I shall be Abū Hurayrah, the one set free, whom Allah has delivered from the Fire."]},"buhuth":{"en":["The Muslims campaigned in India during the time of Muʿāwiyah in the year 44 AH. Thereafter, campaigns continued at the hands of Muḥammad ibn al-Qāsim, Maḥmūd ibn Sabuktakīn, and others. See al-Bidāyah wa-al-Nihāyah (9/218–219). India remained part of the abode of Islam for approximately eight centuries, and thus the glad tidings of the Prophet ﷺ were fulfilled."]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه أحمد (8823)."},{"num":9760,"demo":false,"sanad":"","matn":["عَنْ جَابِرِ بْنِ عَبْدِ اللَّهِ، قَالَ: أَقْبَلْنَا مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مِنْ سَفَرٍ، حَتَّى إِذَا دَفَعْنَا إِلَى حَائِطٍ مِنْ حِيطَانِ بَنِي النَّجَّارِ، إِذَا فِيهِ جَمَلٌ لَا يَدْخُلُ الْحَائِطَ أَحَدٌ إِلَّا شَدَّ عَلَيْهِ، قَالَ: فَذَكَرُوا ذَلِكَ لِلنَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ حَتَّى أَتَى الْحَائِطَ، فَدَعَا الْبَعِيرَ، فَجَاءَ وَاضِعًا مِشْفَرَهُ إِلَى الْأَرْضِ، حَتَّى بَرَكَ بَيْنَ يَدَيْهِ، قَالَ: فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَاتُوا خِطَامَهُ، فَخَطَمَهُ، وَدَفَعَهُ إِلَى صَاحِبِهِ، قَالَ: ثُمَّ الْتَفَتَ إِلَى النَّاسِ، قَالَ: إِنَّهُ لَيْسَ شَيْءٌ بَيْنَ السَّمَاءِ وَالْأَرْضِ، إِلَّا يَعْلَمُ أَنِّي رَسُولُ اللَّهِ، إِلَّا عَاصِيَ الْجِنِّ وَالْإِنْسِ."],"takhrij":"حسن: رواه الإمام أحمد (14333) وعبد بن حميد (1122) والدارمي (18) كلهم من طرق عن الأجلح، عن الذيال بن حرملة، عن جابر فذكر مثله.","grade":"حسن","chapter_ar":"باب ما من شيء بين السماء والأرض إلا يشهد لنبوة محمد ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Imām Aḥmad (14333), ʿAbd ibn Ḥumayd (1122), and al-Dārimī (18).","chapter_en":"Everything Between Heaven and Earth Bears Witness to the Prophethood of Muḥammad ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما تحقق من نبوءاته ﷺ","group_en":"A Collection of the Prophet’s Fulfilled Prophecies ﷺ","part_no":48,"group_no":38,"chapter_no":33,"content":{"translation":{"en":["Jābir ibn ʿAbdullāh said: We returned with the Messenger of Allah ﷺ from a journey. When we reached one of the gardens belonging to Banū al-Najjār, there was a camel inside it that would charge anyone who entered the garden. They mentioned this to the Prophet ﷺ. He came to the garden and called the camel. It approached him with its muzzle lowered toward the ground until it knelt before him. The Prophet ﷺ said: “Bring me its halter.” He placed the halter upon it and handed it over to its owner. He then turned toward the people and said: “There is nothing between heaven and earth except that it knows I am the Messenger of Allah, apart from the disobedient among the jinn and humankind.”"]}},"tuhfa":{},"voc":["seerah",1724],"full":1,"dr":1,"tks":"حسن: رواه الإمام أحمد (14333)، وعبد بن حميد (1122)، والدارمي (18)."},{"num":9761,"demo":false,"sanad":"","matn":["عَنْ طَارِقِ بْنِ عَبْدِ اللَّهِ الْمُحَارِبِيِّ، قَالَ: رَأَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي سُوقِ ذِي الْمَجَازِ وَعَلَيْهِ حُلَّةٌ حَمْرَاءُ، وَهُوَ يَقُولُ: يَا أَيُّهَا النَّاسُ، قُولُوا: لَا إِلَهَ إِلَاّ اللَّهُ تُفْلِحُوا، وَرَجُلٌ يَتْبَعُهُ يَرْمِيهِ بِالْحِجَارَةِ، وَقَدْ أَدْمَى عُرْقُبَيْهِ وَكَعْبَيْهِ، وَهُوَ يَقُولُ: يَا أَيُّهَا النَّاسُ، لَا تُطِيعُوهُ، فَإِنَّهُ كَذَّابٌ، فَقُلْتُ: مَنْ هَذَا؟ فَقِيلَ: هَذَا غُلَامُ بَنِي عَبْدِ الْمُطَّلِبِ، قُلْتُ: فَمَنْ هَذَا الَّذِي يَتْبَعُهُ يَرْمِيهِ بِالْحِجَارَةِ؟ قِيلَ: هَذَا عَمُّهُ عَبْدُ الْعُزَّى أَبُو لَهَبٍ، قَالَ: فَلَمَّا أَظْهَرَ اللهُ الإِسْلَامَ، خَرَجْنَا فِي ركب حَتَّى نَزَلْنَا قَرِيبًا مِنَ الْمَدِينَةِ، وَمَعَنَا ظَعِينَةٌ لَنَا، فَبَيْنَمَا نَحْنُ قُعُودٌ إِذْ أَتَانَا رَجُلٌ عَلَيْهِ ثَوْبَانِ أَبْيَضَانِ، فَسَلَّمَ، وَقَالَ: مِنْ أَيْنَ أَقْبَلَ الْقَوْمُ؟ قُلْنَا: مِنَ الرَّبَذَةِ، قَالَ: وَمَعَنَا جَمَلٌ، قَالَ: أَتَبِيعُونَ هَذَا الْجَمَلَ؟ قُلْنَا: نَعَمْ، قَالَ: بِكَمْ؟ قُلْنَا: بِكَذَا وَكَذَا صَاعًا مِنْ تَمْرٍ، قَالَ: فَأَخَذَهُ، وَلَمْ يَسْتَنْقِصْنَا، قَالَ: قَدْ أَخَذْتُهُ، ثُمَّ تَوَارَى بِحِيطَانِ الْمَدِينَةِ، فَتَلَاوَمْنَا فِيمَا بَيْنَنَا، فَقُلْنَا: أَعْطَيْتُمْ جَمَلَكُمْ رَجُلًا لَا تَعْرِفُونَهُ. قَالَ: فَقَالَتِ الظَّعِينَةُ: لَا تَلَاوَمُوا، فَإِنِّي رَأَيْتُ وَجْهَ رَجُلٍ لَمْ يَكُنْ لِيُخْفِرَكُمْ، مَا رَأَيْتُ شَيْئًا أَشْبَهَ بِالْقَمَرِ لَيْلَةَ الْبَدْرِ مِنْ وَجْهِهِ، قَالَ: فَلَمَّا كَانَ مِنَ الْعَشِيِّ، أَتَانَا رَجُلٌ فَسَلَّمَ عَلَيْنَا، وَقَالَ: أَنَا رَسُولُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، يَقُولُ: إِنَّ لَكُمْ أَنْ تَأْكُلُوا حَتَّى تَشْبَعُوا، وَتَكْتَالُوا حَتَّى تَسْتَوْفُوا، قَالَ: فَأَكَلْنَا حَتَّى شَبِعْنَا، وَاكْتَلْنَا حَتَّى اسْتَوْفَيْنَا، قَالَ: ثُمَّ قَدِمْنَا الْمَدِينَةَ مِنَ الْغَدِ، فَإِذَا رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَائِمٌ يَخْطُبُ عَلَى الْمِنْبَرِ وَهُوَ يَقُولُ: يَدُ الْمُعْطِي يَدُ الْعُلْيَا، وَابْدَأْ بِمَنْ تَعُولُ: أُمَّكَ وَأَبَاكَ، أُخْتَكَ وَأَخَاكَ، ثُمَّ أَدْنَاكَ أَدْنَاكَ، فَقَامَ رَجُلٌ، فَقَالَ: يَا رَسُولَ اللَّهِ، هَؤُلَاءِ بَنُو ثَعْلَبَةَ بْنِ يَرْبُوعٍ قَتَلُوا قَتْلَانَا فِي الْجَاهِلِيَّةِ، فَخُذْ لَنَا بِثَأْرِنَا مِنْهُ، فَرَفَعَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَدَيْهِ حَتَّى رَأَيْتُ بَيَاضَ إِبْطَيْهِ، وَقَالَ: أَلَا لَا تَجْنِي أُمٌّ عَلَى وَلَدٍ، أَلَا لَا تَجْنِي أُمٌّ عَلَى وَلَدٍ."],"takhrij":"حسن: رواه النسائي (4839) وابن ماجه (2670) وصحّحه ابن حبان (6562) والحاكم (4219) كلهم من حديث يزيد بن زياد بن أبي الجعد، عن جامع بن شداد، عن طارق بن عبد الله المحاربي، فذكره.","grade":"حسن","chapter_ar":"وفد طارق بن عبد الله المحاربي وأصحابه من أهل الربذة في مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī (4839) and Ibn Mājah (2670), and authenticated by Ibn Ḥibbān (6562) and al-Ḥākim (4219), all through Yazīd ibn Ziyād ibn Abī al-Jaʿd, from Jāmiʿ ibn Shaddād, from Ṭāriq ibn ʿAbdullāh al-Muḥāribī. The wording is Ibn Ḥibbān’s; al-Nasā’ī and Ibn Mājah confined themselves to the portion concerning liability. Its chain is good because of Yazīd ibn Ziyād ibn Abī al-Jaʿd.","chapter_en":"The Delegation of Ṭāriq ibn ʿAbdullāh al-Muḥāribī and His Companions from al-Rabadhah in Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":1,"content":{"translation":{"en":["Ṭāriq ibn ʿAbdullāh al-Muḥāribī said: I saw the Messenger of Allah ﷺ in the marketplace of Dhū al-Majāz wearing a red suit of clothing and saying: “O people, say, ‘There is no deity worthy of worship except Allah,’ and you will succeed.” A man followed him, throwing stones at him until he had made his heels and the tendons above them bleed. The man was saying: “O people, do not obey him, for he is a liar.” I asked, “Who is this?” It was said, “This is the young man of Banū ʿAbd al-Muṭṭalib.” I asked, “Then who is this man following him and throwing stones at him?” They replied, “This is ʿAbd al-ʿUzzā, Abū Lahab.” He continued: When Islam became dominant, we set out until we camped near Madīnah, accompanied by one of our women. While we were sitting, a man wearing two white garments came to us. He greeted us and asked: “From where have the people come?” We replied, “From al-Rabadhah.” We had a camel with us, and he asked: “Will you sell this camel?” We replied, “Yes.” He asked, “For how much?” We said, “For such-and-such a number of ṣāʿs of dates.” He took it without asking us to reduce the price and said: “I have taken it.” He then disappeared among the gardens of Madīnah. We began reproaching one another, saying: “You gave your camel to a man whom you do not know!” The woman said: “Do not reproach one another. I saw the face of a man who would never treat you contemptuously. I have never seen anything more closely resembling the moon on the night when it is full than his face.” In the evening, a man came to us, greeted us, and said: “I am the messenger of the Messenger of Allah ﷺ to you. He says, ‘You may eat until you are satisfied and measure out for yourselves until you receive your payment in full.’” He said: We ate until we were satisfied and measured out the dates until we had received our payment in full. The following day, we entered Madīnah and found the Messenger of Allah ﷺ standing upon the pulpit delivering a sermon. He was saying: “The hand of the giver is the upper hand. Begin with those whom you support: your mother and your father, your sister and your brother, and then those closest to you, followed by those next closest.” A man stood up and said: “O Messenger of Allah, Banū Thaʿlabah ibn Yarbūʿ killed so-and-so during the pre-Islamic period, so take vengeance for us upon them.” The Messenger of Allah ﷺ raised his hands until I could see the whiteness of his armpits and said: “Indeed, no mother shall bear the guilt of her child! Indeed, no mother shall bear the guilt of her child!”"]},"intro_majmu":{"ar":["قال ابن إسحاق: لما افتتح رسول الله ﷺ مكة، وفرغ من تبوك، وأسلمت ثقيف وبايعت، ضربت إليه وفود العرب من كل وجه. وقال: وإنما كانت العرب تربَّص بالإسلام أمر هذا الحي من قريش، وأمر رسول الله ﷺ، وذلك أن قريشًا كانوا إمام الناس وهاديهم، وأهل البيت الحرام… سيرة ابن هشام (٥٥٩-٥٦٠).","وفي حديث عمرو بن سلمة في قصة الفتح عند البخاري (٤٣٠٢) قال: كانت العرب تلوَّم ـ تنتظر ـ بإسلامهم الفتح، يقولون: اتركوه وقومه، فإنه إن ظهر عليهم فهو نبي صادق، فلما كانت وقعة أهل الفتح بادر كل قوم بإسلامهم، وبدر أبي قومي بإسلامهم….","قال ابن هشام صاحب السيرة: حدثني أبو عبيدة أن ذلك في سنة تسع، وأنها كانت تسمى سنة الوفود.","ولكن هذا لا يمنع أن تكون بعض الوفود مقدمة على هذه السنة، مثل وفد ضمام بن ثعلبة كان سنة خمس، ووفد مزينة كان سنة خمس، وغيرهما. وقد أخرج البخاري في صحيحه جملة من هذه الوفود بالأسانيد المتصلة الصحيحة، وكان محمد بن سعد أوفى من ذكر هذه الوفود، بلغ مجموعها ما يزيد على ستين، ومعظمها سندها عن شيخه الواقدي، وهو متهم مع سعة علمه في أيام رسول الله ﷺ ومغازيه.","وأنا أكتفي هنا بذكر جملة من الوفود بالأسانيد الصحيحة، وأسرد بعضها سردًا، ولكن لا يعني هذا أن هذه لم تثبت، وأنها مختلقة، بل أقول بكل جزم: إن ورود هذه الوفود على النبي ﷺ حقيقة تاريخية لا يمكن إنكارها، ولكن لم يهتم المؤرخون في السيرة النبوية، مثل محمد بن إسحاق والواقدي وابن سعد، بذكر الأسانيد المتصلة كما اهتم المحدثون في ذكر الأحكام والمعاملات في مصنفاتهم بالأسانيد المتصلة، ليتمكن الناقد البارع من معرفة الصحيح من السقيم، بخلاف كتب السير والتواريخ، والله المستعان."],"en":["Ibn Isḥāq said:","When the Messenger of Allah ﷺ conquered Makkah, completed the expedition of Tabūk, and Thaqīf embraced Islam and pledged allegiance, the delegations of the Arabs began coming to him from every direction.","He also said:","The Arabs had been waiting to see what would happen regarding this clan of Quraysh and the affair of the Messenger of Allah ﷺ. This was because Quraysh were regarded as the leaders and guides of the people and were the custodians of the Sacred House…","Sīrat Ibn Hishām (559–560).","In the hadith of ʿAmr ibn Salamah concerning the Conquest, narrated by al-Bukhārī (4302), he said:","The Arabs delayed—meaning that they waited—before embracing Islam until the Conquest. They would say, “Leave him to his people. If he overcomes them, then he is a true prophet.” When the Conquest took place, every tribe hastened to embrace Islam, and my father preceded my tribe in accepting Islam….","Ibn Hishām, the author of the prophetic biography, said:","Abū ʿUbaydah informed me that this occurred in the ninth year and that it was known as the Year of Delegations.","This does not preclude some delegations having arrived before that year. The delegation of Ḍimām ibn Thaʿlabah, for example, arrived in the fifth year, as did the delegation of Muzaynah and others.","Al-Bukhārī narrated accounts of several of these delegations in his Ṣaḥīḥ through sound, connected chains of transmission. Muḥammad ibn Saʿd provided the most comprehensive enumeration of these delegations, whose total exceeded sixty. Most of their chains, however, passed through his teacher al-Wāqidī, who was accused of unreliability despite his extensive knowledge of the days and military campaigns of the Messenger of Allah ﷺ.","Here I shall suffice with mentioning a number of the delegations through authentic chains of transmission while listing some of the others briefly. This does not mean that those other delegations are unsubstantiated or fabricated. Rather, I state with complete certainty that the arrival of these delegations before the Prophet ﷺ is a historical reality that cannot be denied.","However, historians of the prophetic biography—such as Muḥammad ibn Isḥāq, al-Wāqidī, and Ibn Saʿd—did not devote the same attention to citing connected chains of transmission as hadith scholars did when recording legal rulings and transactions in their works. The hadith scholars did so to enable the skilled critic to distinguish the sound from the unsound, unlike the authors of biographies and historical works. Allah is the One whose help is sought."]}},"tuhfa":{},"voc":["seerah",985],"full":1,"dr":1,"rep":[8588],"tks":"حسن: رواه النسائي (4839)، وابن ماجه (2670)، وصححه ابن حبان (6562)، والحاكم (4219). واللفظ لابن حبان، واقتصر النسائي وابن ماجه على جزء الجناية. وإسناده حسن من أجل يزيد بن زياد بن أبي الجعد."},{"num":9762,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ قَالَ:  نُهِينَا أَنْ نَسْأَلَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنْ شَيْءٍ، فَكَانَ يُعْجِبُنَا أَنْ يَجِيءَ الرَّجُلُ مِنْ أَهْلِ الْبَادِيَةِ، الْعَاقِلُ، فَيَسْأَلَهُ وَنَحْنُ نَسْمَعُ، فَجَاءَ رَجُلٌ مِنْ أَهْلِ الْبَادِيَةِ، فَقَالَ: يَا مُحَمَّدُ، أَتَانَا رَسُولُكَ، فَزَعَمَ لَنَا أَنَّكَ تَزْعُمُ أَنَّ اللَّهَ أَرْسَلَكَ؟ قَالَ: صَدَقَ، قَالَ: فَمَنْ خَلَقَ السَّمَاءَ؟ قَالَ: اللَّهُ، قَالَ: فَمَنْ خَلَقَ الْأَرْضَ؟ قَالَ: اللَّهُ، قَالَ: فَمَنْ نَصَبَ هَذِهِ الْجِبَالَ، وَجَعَلَ فِيهَا مَا جَعَلَ؟ قَالَ: اللَّهُ، قَالَ: فَبِالَّذِي خَلَقَ السَّمَاءَ وَخَلَقَ الْأَرْضَ وَنَصَبَ هَذِهِ الْجِبَالَ، آللهُ أَرْسَلَكَ؟ قَالَ: نَعَمْ، قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا خَمْسَ صَلَوَاتٍ فِي يَوْمِنَا وَلَيْلَتِنَا، قَالَ: صَدَقَ، قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: نَعَمْ، قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا زَكَاةً فِي أَمْوَالِنَا؟ قَالَ: صَدَقَ، قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: نَعَمْ، قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا صَوْمَ شَهْرِ رَمَضَانَ فِي سَنَتِنَا؟ قَالَ: صَدَقَ، قَالَ: فَبِالَّذِي أَرْسَلَكَ، آللهُ أَمَرَكَ بِهَذَا؟ قَالَ: نَعَمْ، قَالَ: وَزَعَمَ رَسُولُكَ أَنَّ عَلَيْنَا حَجَّ الْبَيْتِ مَنِ اسْتَطَاعَ إِلَيْهِ سَبِيلًا؟ قَالَ: صَدَقَ، قَالَ: ثُمَّ وَلَّى، قَالَ: وَالَّذِي بَعَثَكَ بِالْحَقِّ، لَا أَزِيدُ عَلَيْهِنَّ وَلَا أَنْقُصُ مِنْهُنَّ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَئِنْ صَدَقَ لَيَدْخُلَنَّ الْجَنَّةَ."],"takhrij":"متفق عليه: رواه مسلم في الإيمان (10: 12) عن عمرو بن محمد بن بكير الناقد، حدثنا هاشم بن القاسم أبو النضر، حدثنا سليمان بن المغيرة، عن ثابت، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"قدوم ضمام بن ثعلبة وافدًا من قومه بني سعد بن بكر سنة خمس","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (10:12) and al-Bukhārī (63).","chapter_en":"The Arrival of Ḍimām ibn Thaʿlabah as a Delegate from His People, Banū Saʿd ibn Bakr, in the Fifth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":3,"content":{"translation":{"en":["Anas ibn Mālik said: We were forbidden from asking the Messenger of Allah ﷺ unnecessary questions, so we were pleased whenever an intelligent man from the desert came and questioned him while we listened. A Bedouin man came and said: “O Muḥammad, your messenger came to us and claimed that you say Allah has sent you.” He replied, “He spoke the truth.” The man asked, “Who created the sky?” He replied, “Allah.” He asked, “Who created the earth?” He replied, “Allah.” He asked, “Who erected these mountains and placed within them whatever He placed?” He replied, “Allah.” The man said, “By the One who created the sky, created the earth, and erected these mountains, did Allah send you?” He replied, “Yes.” The man said: “Your messenger also claimed that we are required to perform five prayers during each day and night.” He replied, “He spoke the truth.” The man asked, “By the One who sent you, did Allah command you to do this?” He replied, “Yes.” The man said, “Your messenger claimed that zakāh is due from our wealth.” He replied, “He spoke the truth.” The man asked, “By the One who sent you, did Allah command you to do this?” He replied, “Yes.” The man said, “Your messenger claimed that we must fast the month of Ramadan each year.” He replied, “He spoke the truth.” The man asked, “By the One who sent you, did Allah command you to do this?” He replied, “Yes.” The man said: “Your messenger claimed that whoever among us is able to find a way to the House must perform its pilgrimage.” He replied, “He spoke the truth.” The man then turned away, saying: “By the One who sent you with the truth, I shall neither add anything to these nor omit anything from them.” The Prophet ﷺ said: “If he is truthful, he will certainly enter Paradise.”"]},"intro":{"ar":["قال الواقدي: حدثني أبو بكر بن عبد الله بن أبي سبرة، عن شريك بن عبد الله بن أبي نمر، عن كريب، عن ابن عباس، قال: بعث بنو سعد بن بكر في رجب سنة خمس ضمام بن ثعلبة، وكان جلدًا أشعر ذا غديرين، وافدًا إلى رسول الله ﷺ. فأقبل حتى وقف على رسول الله ﷺ فسأله، فأغلظ في المسألة، سأله عمن أرسله، وبما أرسله، وسأله عن شرائع الإسلام، فأجابه رسول الله ﷺ في ذلك كله. فرجع إلى قومه مسلمًا، قد خلع الأنداد، فأخبرهم بما أمرهم به ونهاهم عنه، فما أمسى في ذلك اليوم في حاضره رجل ولا امرأة إلا مسلمًا، وبنوا المساجد وأذنوا بالصلاة. أخرجه ابن سعد في الطبقات (١/ ٢٩٩)."],"en":["Al-Wāqidī said:","Abū Bakr ibn ʿAbdullāh ibn Abī Sabrah narrated to me, from Sharīk ibn ʿAbdullāh ibn Abī Namir, from Kurayb, from Ibn ʿAbbās, who said:","In Rajab of the fifth year, Banū Saʿd ibn Bakr sent Ḍimām ibn Thaʿlabah as their delegate to the Messenger of Allah ﷺ. He was a strong, hairy man with two long braids. He came and stood before the Messenger of Allah ﷺ, questioned him, and spoke harshly while asking his questions. He asked who had sent him, what message he had been sent with, and about the laws of Islam. The Messenger of Allah ﷺ answered all his questions.","He returned to his people as a Muslim, having renounced all false deities. He informed them of what the Prophet ﷺ had commanded and forbidden them. By that evening, there was not a man or woman present among his people who had not embraced Islam. They built mosques and called the adhān for prayer.","Narrated by Ibn Saʿd in al-Ṭabaqāt (1/299)."]}},"tuhfa":{},"voc":["seerah",988],"full":1,"dr":1,"rep":[8210,13712],"tks":"متفق عليه: رواه مسلم (10: 12)، والبخاري (63)."},{"num":9763,"demo":false,"sanad":"","matn":["عن أنس بْنِ مَالِكٍ الأنصاري يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: يَقْدَمُ عَلَيْكُمْ غَدًا أَقْوَامٌ، هُمْ أَرَقُّ قُلُوبًا لِلْإِسْلَامِ مِنْكُمْ. قَالَ: فَقَدِمَ الْأَشْعَرِيُّونَ، فِيهِمْ أَبُو مُوسَى الْأَشْعَرِيُّ، فَلَمَّا دَنَوْا مِنَ الْمَدِينَةِ جَعَلُوا يَرْتَجِزُونَ، يَقُولُونَ: [البحر الرجز] غَدًا نَلْقَى الْأَحِبَّهْ... مُحَمَّدًا وَحِزْبَهْ، فَلَمَّا أَنْ قَدِمُوا تَصَافَحُوا، فَكَانُوا هُمْ أَوَّلَ مَنْ أَحْدَثَ الْمُصَافَحَةَ."],"takhrij":"صحيح: رواه الإمام أحمد (12582) وصححه ابن حبان (7193) كلاهما من طريق يحيى بن أيوب، عن حميد الطويل، عن أنس، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب قدوم الأشعريين في سنة سبع عند فتح خيبر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Imām Aḥmad (12582) and authenticated by Ibn Ḥibbān (7193).","chapter_en":"The Arrival of the Ashʿarīs in the Seventh Year, at the Time of the Conquest of Khaybar","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":4,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ said: “Tomorrow, a people will come to you whose hearts are more tender toward Islam than yours.” The Ashʿarīs then arrived, among them Abū Mūsā al-Ashʿarī. As they drew near Madīnah, they began chanting: “Tomorrow we shall meet the beloved ones: Muḥammad and his companions.” When they arrived, they shook hands with one another, and they were the first to introduce handshaking."]}},"tuhfa":{},"voc":["seerah",989],"full":1,"dr":1,"tks":"صحيح: رواه الإمام أحمد (12582)، وصححه ابن حبان (7193)."},{"num":9764,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ: لَمَّا قَدِمْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قُلْتُ فِي الطَّرِيقِ: يَا لَيْلَةً مِنْ طُولِهَا وَعَنَائِهَا عَلَى أَنَّهَا مِنْ دَارَةِ الْكُفْرِ نَجَّتِ وَأَبَقَ غُلاَمٌ لِي فِي الطَّرِيقِ، فَلَمَّا قَدِمْتُ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَبَايَعْتُهُ، فَبَيْنَا أَنَا عِنْدَهُ إِذْ طَلَعَ الْغُلاَمُ، فَقَالَ لِي النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَا أَبَا هُرَيْرَةَ هَذَا غُلاَمُكَ. فَقُلْتُ هُوَ لِوَجْهِ اللَّهِ تَعَالَى. فَأَعْتَقْتُهُ."],"takhrij":"صحيح: رواه البخاري في المغازي (4393) عن محمد بن العلاء، حدثنا أبو أسامة، حدثنا إسماعيل، عن قيس، عن أبي هريرة، فذكره.","grade":"صحيح","chapter_ar":"قدوم أبي هريرة على النبي ﷺ","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4393).","chapter_en":"The Arrival of Abū Hurayrah Before the Prophet ﷺ","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":5,"content":{"translation":{"en":["Abū Hurayrah said: While travelling to join the Prophet ﷺ, I recited: “What a night, for all its length and hardship— yet it delivered me from the abode of disbelief.” A servant of mine ran away during the journey. When I reached the Prophet ﷺ, I pledged allegiance to him. While I was with him, the servant suddenly appeared. The Prophet ﷺ said to me: “O Abū Hurayrah, here is your servant.” I replied: “He is free for the sake of Allah.” I then set him free."]}},"tuhfa":{},"voc":["seerah",990],"full":1,"rep":[10357],"tks":"صحيح: رواه البخاري (4393)."},{"num":9765,"demo":false,"sanad":"","matn":["عَنْ جَابِرٍ،  أَنَّ الطُّفَيْلَ بْنَ عَمْرٍو الدَّوْسِيَّ أَتَى النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: يَا رَسُولَ اللَّهِ، هَلْ لَكَ فِي حِصْنٍ حَصِينٍ وَمَنَْعَةٍ؟ قَالَ: حِصْنٌ كَانَ لِدَوْسٍ: فِي الْجَاهِلِيَّةِ، فَأَبَى ذَلِكَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِلَّذِي ذَخَرَ اللهُ لِلْأَنْصَارِ، فَلَمَّا هَاجَرَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ إِلَى الْمَدِينَةِ هَاجَرَ إِلَيْهِ الطُّفَيْلُ بْنُ عَمْرٍو، وَهَاجَرَ مَعَهُ رَجُلٌ مِنْ قَوْمِهِ، فَاجْتَوَوُا الْمَدِينَةَ، فَمَرِضَ فَجَزِعَ، فَأَخَذَ مَشَاقِصَ لَهُ، فَقَطَعَ بِهَا بَرَاجِمَهُ، فَشَخَبَتْ يَدَاهُ حَتَّى مَاتَ، فَرَآهُ الطُّفَيْلُ بْنُ عَمْرٍو فِي مَنَامِهِ، فَرَآهُ وَهَيْئَتُهُ حَسَنَةٌ، وَرَآهُ مُغَطِّيًا يَدَيْهِ، فَقَالَ لَهُ: مَا صَنَعَ بِكَ رَبُّكَ؟ فَقَالَ: غَفَرَ لِي بِهِجْرَتِي إِلَى نَبِيِّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: مَا لِي أَرَاكَ مُغَطِّيًا يَدَيْكَ؟ قَالَ: قِيلَ لِي: لَنْ نُصْلِحَ مِنْكَ مَا أَفْسَدْتَ. فَقَصَّهَا الطُّفَيْلُ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اللَّهُمَّ وَلِيَدَيْهِ فَاغْفِرْ."],"takhrij":"صحيح: رواه مسلم في الإيمان (116) من طريق سليمان بن حرب، حدثنا حماد بن زيد، عن حجاج الصواف، عن أبي الزبير، عن جابر، فذكره.","grade":"صحيح","chapter_ar":"قدوم الطفيل بن عمرو الدوسي وأصحابه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (116).","chapter_en":"The Arrival of al-Ṭufayl ibn ʿAmr al-Dawsī and His Companions","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":6,"content":{"translation":{"en":["Jābir reported that al-Ṭufayl ibn ʿAmr al-Dawsī came to the Prophet ﷺ and said: “O Messenger of Allah, would you like the protection of a strong fortress and a place of defence?” The narrator said: It was a fortress belonging to Daws during the pre-Islamic period. The Prophet ﷺ declined because of what Allah had reserved for the Anṣār. When the Prophet ﷺ emigrated to Madīnah, al-Ṭufayl ibn ʿAmr emigrated to join him, accompanied by a man from his tribe. They found the climate of Madīnah unhealthy. The man became ill and lost patience. He took some broad-headed arrows and cut the joints of his fingers with them. His hands bled profusely until he died. Al-Ṭufayl ibn ʿAmr later saw him in a dream. He appeared in a good condition, but al-Ṭufayl saw him covering his hands. He asked him: “What has your Lord done with you?” He replied: “He forgave me because of my emigration to His Prophet ﷺ.” Al-Ṭufayl asked: “Why do I see you covering your hands?” He replied: “I was told, ‘We will not restore what you yourself have ruined.’” Al-Ṭufayl related the dream to the Messenger of Allah ﷺ, whereupon the Messenger of Allah ﷺ said: “O Allah, forgive even his hands.”"]}},"tuhfa":{},"voc":["seerah",991],"full":1,"rep":[6832],"tks":"صحيح: رواه مسلم (116)."},{"num":9766,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ، قَالَ:  قَدِمَ الطُّفَيْلُ وَأَصْحَابُهُ فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّ دَوْسًا قَدْ كَفَرَتْ، وَأَبَتْ، فَادْعُ اللَّهَ عَلَيْهَا! فَقِيلَ: هَلَكَتْ دَوْسٌ! فَقَالَ: اللَّهُمَّ اهْدِ دَوْسًا وَائْتِ بِهِمْ."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2937) ومسلم في فضائل الصحابة (2524) كلاهما من طريق أبي الزناد، عن عبد الرحمن الأعرج، عن أبي هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"قدوم الطفيل بن عمرو الدوسي وأصحابه","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (2937) and Muslim (2524).","chapter_en":"The Arrival of al-Ṭufayl ibn ʿAmr al-Dawsī and His Companions","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":6,"content":{"translation":{"en":["Abū Hurayrah said: Al-Ṭufayl and his companions came and said: “O Messenger of Allah, Daws has persisted in disbelief and refused to accept Islam, so supplicate to Allah against them.” It was said, “Daws is ruined!” But he ﷺ said: “O Allah, guide Daws and bring them to me.”"]}},"tuhfa":{},"voc":["seerah",992],"full":1,"rep":[10529],"tks":"متفق عليه: رواه البخاري (2937)، ومسلم (2524)."},{"num":9767,"demo":false,"sanad":"","matn":["عَنْ أَبِي جَمْرَةَ، قَالَ: كُنْتُ أَقْعُدُ مَعَ ابْنِ عَبَّاسٍ، يُجْلِسُنِي عَلَى سَرِيرِهِ فَقَالَ: أَقِمْ عِنْدِي حَتَّى أَجْعَلَ لَكَ سَهْمًا مِنْ مَالِي، فَأَقَمْتُ مَعَهُ شَهْرَيْنِ، ثُمَّ قَالَ: إِنَّ وَفْدَ عَبْدِ الْقَيْسِ لَمَّا أَتَوُا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ: مَنِ الْقَوْمُ؟ أَوْ مَنِ الْوَفْدُ. قَالُوا: رَبِيعَةُ. قَالَ: مَرْحَبًا بِالْقَوْمِ ـ أَوْ بِالْوَفْدِ ـ غَيْرَ خَزَايَا وَلاَ نَدَامَى. فَقَالُوا: يَا رَسُولَ اللَّهِ، إِنَّا لاَ نَسْتَطِيعُ أَنْ نَأْتِيَكَ إِلاَّ فِي شَهْرِ الْحَرَامِ، وَبَيْنَنَا وَبَيْنَكَ هَذَا الْحَىُّ مِنْ كُفَّارِ مُضَرَ، فَمُرْنَا بِأَمْرٍ فَصْلٍ، نُخْبِرْ بِهِ مَنْ وَرَاءَنَا، وَنَدْخُلْ بِهِ الْجَنَّةَ. وَسَأَلُوهُ عَنِ الأَشْرِبَةِ. فَأَمَرَهُمْ بِأَرْبَعٍ، وَنَهَاهُمْ عَنْ أَرْبَعٍ، أَمَرَهُمْ: بِالإِيمَانِ بِاللَّهِ وَحْدَهُ. قَالَ: أَتَدْرُونَ مَا الإِيمَانُ بِاللَّهِ وَحْدَهُ. قَالُوا: اللَّهُ وَرَسُولُهُ أَعْلَمُ. قَالَ: شَهَادَةُ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ، وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ، وَإِقَامُ الصَّلاَةِ، وَإِيتَاءُ الزَّكَاةِ، وَصِيَامُ رَمَضَانَ، وَأَنْ تُعْطُوا مِنَ الْمَغْنَمِ الْخُمُسَ. وَنَهَاهُمْ عَنْ أَرْبَعٍ: عَنِ الْحَنْتَمِ، وَالدُّبَّاءِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ. وَرُبَّمَا قَالَ: الْمُقَيَّرِ. وَقَالَ: احْفَظُوهُنَّ وَأَخْبِرُوا بِهِنَّ مَنْ وَرَاءَكُمْ."],"takhrij":"متفق عليه: رواه البخاريّ في الإيمان (53)، ومسلم في الإيمان (17) كلاهما من طريق شعبة، عن أبي جمرة، فذكره، واللّفظ للبخاريّ، ولفظ مسلم نحوه.","grade":"متفق عليه","chapter_ar":"وفد عبد القيس، وكان قبل فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (53) and Muslim (17).","chapter_en":"The Delegation of ʿAbd al-Qays, Which Arrived Before the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":7,"content":{"translation":{"en":["Abū Jamrah said: I used to sit with Ibn ʿAbbās, and he would seat me upon his couch. He said to me: “Stay with me so that I may assign you a share from my wealth.” I remained with him for two months. He then said: When the delegation of ʿAbd al-Qays came to the Prophet ﷺ, he asked: “Who are these people—or who is this delegation?” They replied, “Rabīʿah.” He said: “Welcome to the people—or the delegation—who shall suffer neither disgrace nor regret.” They said: “O Messenger of Allah, we are unable to come to you except during the sacred month, for between us and you lies this tribe of the disbelievers of Muḍar. Therefore, command us with a decisive matter that we may convey to those whom we have left behind and by which we may enter Paradise.” They also asked him about drinks. He commanded them to observe four things and forbade them four things. He commanded them to believe in Allah alone and asked: “Do you know what belief in Allah alone means?” They replied: “Allah and His Messenger know best.” He said: “To testify that there is no deity worthy of worship except Allah and that Muḥammad is the Messenger of Allah; to establish prayer, give zakāh, fast Ramadan, and give one-fifth of the spoils of war.” He forbade them four types of vessels: al-ḥantam, al-dubbāʾ, al-naqīr, and al-muzaffat—perhaps he said al-muqayyar—and told them: “Memorize these instructions and convey them to those whom you have left behind.”"]},"buhuth":{"en":["Muslim added in another narration that the Messenger of Allah ﷺ said to al-Ashajj—the Ashajj of ʿAbd al-Qays:","“You possess two qualities that Allah loves: forbearance and deliberateness.”","The term “al-muqayyar” means al-muzaffat: a vessel coated with pitch or tar.","Al-Ḥāfiẓ Ibn Kathīr said:","“The context of Ibn ʿAbbās’s hadith indicates that the delegation of ʿAbd al-Qays arrived before the Conquest of Makkah, because they said: ‘Between us and you lies this tribe of Muḍar, and we cannot reach you except during a sacred month.’”","Al-Bidāyah wa-al-Nihāyah (7/251)."]}},"tuhfa":{},"voc":["seerah",993],"full":1,"dr":1,"rep":[58],"tks":"متفق عليه: رواه البخاري (53)، ومسلم (17)."},{"num":9768,"demo":false,"sanad":"","matn":["عَنْ أَبِي سَعِيدٍ الْخُدْرِيِّ قَالَ: إنّ أُنَاسًا من عبدالقيس قَدِمُوا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ ، فَقَالُوا: يَا نبيَّ اللَّهِ، إنّا حيٌّ مِنْ رَبِيعَةَ وَبَيْنَنَا وَبَيْنَكَ كُفَّارُ مُضَرَ، وَلَا نَقْدِرُ عَلَيْكَ إِلَّا فِي أَشْهُرِ الْحُرُمِ فَمُرْنَا بِأَمْرٍ نأْمُرُ بِهِ مَنْ وَرَاءَنَا وَنَدْخُلُ بِهِ الْجَنَّةَ، إِذَا نَحْنُ أَخَذْنَا بِهِ فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : آمُرُكُمْ بِأَرْبَعٍ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: اعْبُدُوا اللهَ وَلَا تُشْرِكُوا بِهِ شَيْئًا، وَأَقِيمُوا الصَّلَاةَ، وَآتُوا الزَّكَاةَ، وَصُومُوا رَمَضَانَ وَأَعْطُوا الْخُمُسَ مِنَ الْغَنَائِمِ، وَأَنْهَاكُمْ عَنْ أَرْبَعٍ: عَنِ الدُّبّاء، والحَنْتَم، وَالْمُزَفَّتِ وَالنَّقِيرِ. قَالُوا: يَا نَبِيَّ اللَّهِ، مَا عِلْمُكَ بِالنَّقِيرِ؟ قَالَ: بَلَى جِذعٌ تَنْقُرُونَهُ فَتَقْذِفُونَ فِيهِ مِنَ الْقُطَيْعَاءِ -قَالَ سَعِيدٌ: أَوْ قَالَ مِنَ التَّمْرِ-، ثُمَّ تصبُّون فِيهِ مِنَ الْمَاءِ، حَتَّى إِذَا سَكَنَ غَلَيَانُهُ شَرِبْتُمُوهُ، حَتَّى إنّ أَحَدَكُمْ - أَوْ إنَّ أَحَدَهُمْ - لَيَضْرِبُ ابنَ عمِّه بِالسَّيْفِ قَالَ: وَفِي الْقَوْمِ رَجُلٌ أَصَابَتْهُ جِرَاحَةٌ كَذَلِكَ. قَالَ: وَكُنْتُ أَخْبأُها حَيَاءً مِنْ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. . فَقُلْتُ: فَفِيمَ نَشْرَبُ يَا رَسُولَ اللَّهِ؟ قَالَ: فِي أَسْقِية الأَدَم الَّتِي يُلاثُ عَلَى أَفْوَاهِهَا. قَالُوا: يَا رَسُولَ اللَّهِ، إنّ أَرْضَنَا كَثِيرَةُ الْجِرْذَانِ، وَلَا تَبْقَى بِهَا أَسْقِيَةُ الأَدَم. فَقَالَ نبيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ، وَإِنْ أَكَلَتْهَا الْجِرْذَانُ قَالَ: وَقَالَ نبيُّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَشَجِّ عبدالقيس: إنّ فِيكَ لَخَصْلَتَيْنِ يُحِبُّهُمَا اللَّهُ الحِلْمُ وَالْأَنَاةُ."],"takhrij":"صحيح: رواه مسلم في الإيمان (18) عن يحيى بن أيوب، حدثنا ابنُ عليّة، حدّثنا سعيد بن أبي عروبة، عن قتادة، قال: حدّثنا من لقي الوفدَ الذين قدموا على رسول الله صلى الله عليه وسلم من عبدالقيس. قال سعيد (ابن أبي عروبة): وذكر قتادة أبا نضرة، عن أبي سعيد في حديثه هذا: أنّ ناساً من عبد القيس فذكره.","grade":"صحيح","chapter_ar":"وفد عبد القيس، وكان قبل فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (18).","chapter_en":"The Delegation of ʿAbd al-Qays, Which Arrived Before the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":7,"content":{"translation":{"en":["Abū Saʿīd al-Khudrī said: Some people from ʿAbd al-Qays came to the Messenger of Allah ﷺ and said: “O Prophet of Allah, we are a tribe of Rabīʿah, and between us and you are the disbelievers of Muḍar. We are unable to reach you except during the sacred months. Therefore, command us with something that we may command those whom we have left behind and by which we may enter Paradise if we adhere to it.” The Messenger of Allah ﷺ said: “I command you to observe four things and forbid you four things. Worship Allah and associate nothing with Him, establish prayer, give zakāh, fast Ramadan, and give one-fifth of the spoils of war. I forbid you four vessels: al-dubbāʾ, al-ḥantam, al-muzaffat, and al-naqīr.” They asked: “O Prophet of Allah, what do you know about al-naqīr?” He replied: “Indeed, it is a tree trunk that you hollow out. You place small dates—or Saʿīd said: dates—inside it and then pour water over them. When its fermentation subsides, you drink it until one of you strikes his cousin with the sword.” There was among the delegation a man who had suffered such an injury. He said: “I used to conceal it out of embarrassment before the Messenger of Allah ﷺ.” I asked: “Then from what should we drink, O Messenger of Allah?” He replied: “From leather waterskins whose mouths are tied with cords.” They said: “O Messenger of Allah, our land has many rats, and leather waterskins do not survive there.” The Prophet of Allah ﷺ replied: “Even if the rats eat them; even if the rats eat them; even if the rats eat them.” The Prophet of Allah ﷺ also said to al-Ashajj of ʿAbd al-Qays: “You possess two qualities that Allah loves: forbearance and deliberateness.”"]}},"tuhfa":{},"voc":["seerah",994],"full":1,"tks":"صحيح: رواه مسلم (18)."},{"num":9769,"demo":false,"sanad":"","matn":["عن ثمامة بن حزن القشيري قَالَ:  لَقِيتُ عَائِشَةَ فَسَأَلْتُهَا عَنِ النَّبِيذِ؟ فَحَدَّثَتْنِي: أَنَّ وَفْدَ عَبْدِ الْقَيْسِ قَدِمُوا عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَسَأَلُوا النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ عَنِ النَّبِيذِ، فَنَهَاهُمْ أَنْ يَنْتَبِذُوا فِي الدُّبَّاءِ، وَالنَّقِيرِ، وَالْمُزَفَّتِ، وَالْحَنْتَمِ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1995: 37) عن شيبان بن فروخ، حدثنا القاسم بن الفضل، حدثنا ثمامة بن حزن القشيري، قال: فذكره.","grade":"صحيح","chapter_ar":"وفد عبد القيس، وكان قبل فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1995:37).","chapter_en":"The Delegation of ʿAbd al-Qays, Which Arrived Before the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":7,"content":{"translation":{"en":["Thumāmah ibn Ḥazn al-Qushayrī said: I met ʿĀ’ishah and asked her about nabīdh. She informed me that the delegation of ʿAbd al-Qays came to the Prophet ﷺ and asked him about nabīdh. He forbade them from preparing it in gourds, hollowed-out tree trunks, pitch-coated vessels, and earthenware jars."]}},"tuhfa":{},"voc":["seerah",995],"full":1,"rep":[7505],"tks":"صحيح: رواه مسلم (1995: 37)."},{"num":9770,"demo":false,"sanad":"","matn":["عن سَعِيدِ بْنِ المسيب يَقُولُ: سَمِعْتُ عَبْدَ اللَّهِ بْنَ عُمَرَ يَقُولُ: عِنْدَ هَذَا الْمِنْبَرِ، وَأَشَارَ إِلَى مِنْبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ،  قَدِمَ وَفْدُ عَبْدِ الْقَيْسِ عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَسَأَلُوهُ عَنِ الْأَشْرِبَةِ، فَنَهَاهُمْ عَنِ الدُّبَّاءِ وَالنَّقِيرِ وَالْحَنْتَمِ، فَقُلْتُ لَهُ: يَا أَبَا مُحَمَّدٍ، وَالْمُزَفَّتِ؟ وَظَنَنَّا أَنَّهُ نَسِيَهُ فَقَالَ: لَمْ أَسْمَعْهُ يَوْمَئِذٍ مِنْ عَبْدِ اللَّهِ بْنِ عُمَرَ، وَقَدْ كَانَ يَكْرَهُ."],"takhrij":"صحيح: رواه مسلم في الأشربة (1997: 58) عن أبي بكر بن أبي شيبة، حدثنا يزيد بن هارون، أخبرنا عبد الخالق بن سلمة، قال: سمعت سعيد بن المسيب، يقول: فذكره.","grade":"صحيح","chapter_ar":"وفد عبد القيس، وكان قبل فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1997:58).","chapter_en":"The Delegation of ʿAbd al-Qays, Which Arrived Before the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":7,"content":{"translation":{"en":["Saʿīd ibn al-Musayyib said: I heard ʿAbdullāh ibn ʿUmar speaking beside this pulpit—and he pointed toward the pulpit of the Messenger of Allah ﷺ—saying: “The delegation of ʿAbd al-Qays came to the Messenger of Allah ﷺ and asked him about drinks. He forbade them gourds, hollowed-out tree trunks, and earthenware jars.” I asked him: “O Abū Muḥammad, what about pitch-coated vessels?” We thought he had forgotten to mention them. He replied: “I did not hear it from ʿAbdullāh ibn ʿUmar that day, although he disliked them.”"]}},"tuhfa":{},"voc":["seerah",996],"full":1,"dr":1,"rep":[7502],"tks":"صحيح: رواه مسلم (1997: 58)."},{"num":9771,"demo":false,"sanad":"","matn":["عن طلق بن عَلِيٍّ قَالَ: جَلَسْنَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَجَاءَ وَفْدُ عَبْدِ الْقَيْسِ، فَقَالَ: مَا لَكُمْ قَدِ اصْفَرَّتْ أَلْوَانُكُمْ، وَعَظُمَتْ بُطُونُكُمْ، وَظَهَرَتْ عُرُوقُكُمْ؟ قَالَ: قَالُوا: أَتَاكَ سَيِّدُنَا، فَسَأَلَكَ عَنْ شَرَابٍ كَانَ لَنَا مُوَافِقًا فَنَهَيْتَهُ عَنْهُ، وَكُنَّا بِأَرْضٍ وَخِمَةٍ، قَالَ: فَاشْرَبُوا مَا طَابَ لَكُمْ."],"takhrij":"حسن: رواه ابن أبي شيبة (24368) عن ملازم بن عمرو، عن عجيبة بن عبد الحميد، عن عمه قيس بن طلق، عن أبيه طلق بن علي، قال: فذكره.","grade":"حسن","chapter_ar":"وفد عبد القيس، وكان قبل فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Abī Shaybah (24368).","chapter_en":"The Delegation of ʿAbd al-Qays, Which Arrived Before the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":7,"content":{"translation":{"en":["Ṭalq ibn ʿAlī said: We were sitting with the Prophet ﷺ when the delegation of ʿAbd al-Qays arrived. He asked: “Why have your complexions turned yellow, your stomachs become enlarged, and your veins become prominent?” They replied: “Our leader came to you and asked you about a drink that suited us, but you forbade him from it, and we live in a fever-ridden land.” He said: “Then drink whatever wholesome drink suits you.”"]},"buhuth":{"en":["His statement, “Drink whatever wholesome drink suits you,” applies if it is not intoxicating. As for an intoxicating drink, it is not permitted, because its prohibition has already been established."]}},"tuhfa":{},"voc":["seerah",997],"full":1,"dr":1,"rep":[7550],"tks":"حسن: رواه ابن أبي شيبة (24368)."},{"num":9772,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ قَالَ: قَدِمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفْدُ بَنِي أَسَدٍ، فَتَكَلَّمُوا، فَأَبَانُوا، فَقَالُوا: يَا رَسُولَ اللَّهِ، قَاتَلَتْكَ مُضَرُ كُلُّهَا، وَلَمْ نُقَاتِلْكَ، وَلَسْنَا بِأَقَلِّهِمْ عَدَدًا، وَلَا أَكَلِّهِمْ شَوْكَةً. وَصَلْنَا رَحِمَكَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ لِأَبِي بَكْرٍ وَعُمَرَ حَيْثُ سَمِعَ كَلَامَهُمْ: أَيَتَكَلَّمُونَ هَكَذَا؟ قَالَ: يَا رَسُولَ اللَّهِ، إِنَّ فِقْهَهُمْ لَقَلِيلٌ، وَإِنَّ الشَّيْطَانَ لَيَنْطِقُ عَلَى لِسَانِهِمْ.","زَادَ فِي رِوَايَةِ: ونزلت هَذِهِ الآية: ﴿يَمُنُّونَ عَلَيْكَ أَنْ أَسْلَمُوا قُلْ لَا تَمُنُّوا عَلَيَّ إِسْلَامَكُمْ بَلِ اللَّهُ يَمُنُّ عَلَيْكُمْ أَنْ هَدَاكُمْ لِلْإِيمَانِ إِنْ كُنْتُمْ صَادِقِينَ﴾ [الحجرات: 17]."],"takhrij":"حسن: رواه النسائي في الكبرى (11455) وأبو يعلى (2363) والبزار (5141) كلهم من حديث يحيى بن سعيد الأموي، عن محمد بن قيس الأسدي، عن أبي عون محمد بن عبيد الله الثقفي، عن سعيد بن جبير، عن ابن عباس، فذكره، واللفظ لأبي يعلى، والزيادة للبزار.","grade":"حسن","chapter_ar":"وفد بني أسد، وكان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by al-Nasā’ī in al-Sunan al-Kubrā (11455), Abū Yaʿlā (2363), and al-Bazzār (5141).","chapter_en":"The Delegation of Banū Asad, Which Arrived in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":9,"content":{"translation":{"en":["Ibn ʿAbbās said: A delegation from Banū Asad came to the Prophet ﷺ. They spoke clearly and eloquently, saying: “O Messenger of Allah, all of Muḍar fought against you, but we did not fight you. We are neither the least numerous among them nor the weakest in strength, and we maintained your ties of kinship.” When the Messenger of Allah ﷺ heard their words, he asked Abū Bakr and ʿUmar: “Do they speak in this manner?” They replied: “O Messenger of Allah, their understanding is indeed limited, and Satan is certainly speaking upon their tongues.” Another narration adds that the following verse was revealed: “They regard their acceptance of Islam as a favour to you. Say, ‘Do not regard your Islam as a favour to me. Rather, Allah has conferred favour upon you by guiding you to faith, if you are truthful.’” [Al-Ḥujurāt: 17]"]}},"tuhfa":{},"full":1,"dr":1,"tks":"حسن: رواه النسائي في الكبرى (11455)، وأبو يعلى (2363)، والبزار (5141)."},{"num":9773,"demo":false,"sanad":"","matn":["عَنِ الْبَرَاءِ قَالَ: بَعَثَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ خَالِدَ بْنَ الْوَلِيدِ إِلَى أَهْلِ الْيَمَنِ يَدْعُوهُمْ إِلَى الْإِسْلَامِ فَلَمْ يُجِيبُوهُ، ثُمَّ إِنَّ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ عَلِيَّ بْنَ أَبِي طَالِبٍ وَأَمَرَهُ أَنْ يَقْفُلَ خَالِدٌ وَمَنْ كَانَ مَعَهُ إِلَّا رَجُلٌ مِمَّنْ كَانَ مَعَ خَالِدٍ أَحَبَّ أَنْ يُعَقِّبَ مَعَ عَلِيٍّ رَضِيَ اللَّهُ عَنْهُ فَلْيُعَقِّبْ مَعَهُ، قَالَ الْبَرَاءُ: فَكُنْتُ مِمَّنْ عَقَّبَ مَعَهُ، فَلَمَّا دَنَوْنَا مِنَ الْقَوْمِ خَرَجُوا إِلَيْنَا، فَصَلَّى بِنَا عَلِيٌّ، رَضِيَ اللَّهُ عَنْهُ وَصَفَّنَا صَفًّا وَاحِدًا، ثُمَّ تَقَدَّمَ بَيْنَ أَيْدِينَا، فَقَرَأَ عَلَيْهِمْ كِتَابَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَأَسْلَمَتْ هَمْدَانُ جَمِيعًا، فَكَتَبَ عَلِيٌّ رَضِيَ اللَّهُ عَنْهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِإِسْلَامِهِمْ، فَلَمَّا قَرَأَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الْكِتَابَ خَرَّ سَاجِدًا، ثُمَّ رَفَعَ رَأْسَهُ، فَقَالَ: السَّلَامُ عَلَى هَمْدَانَ، السَّلَامُ عَلَى هَمْدَانَ."],"takhrij":"صحيح: رواه البيهقي في الكبرى (3932) من طريقين عن أبي عبيدة بن أبي السفر، قال: سمعت إبراهيم بن يوسف بن أبي إسحاق، عن أبيه، عن أبي إسحاق، عن البراء بن عازب، قال: فذكره.","grade":"صحيح","chapter_ar":"قدوم وفد همدان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bayhaqī in al-Sunan al-Kubrā (2/369).","chapter_en":"The Arrival of the Delegation of Hamdān in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":10,"content":{"translation":{"en":["Al-Barāʾ said: The Prophet ﷺ sent Khālid ibn al-Walīd to the people of Yemen to invite them to Islam, but they did not respond to him. The Prophet ﷺ then sent ʿAlī ibn Abī Ṭālib and instructed him to send Khālid and those accompanying him back, except that anyone who wished to remain and continue with ʿAlī could do so. Al-Barāʾ said: I was among those who remained with him. When we drew near the people, they came out to meet us. ʿAlī led us in prayer and arranged us in a single row. He then stepped forward before us and read the letter of the Messenger of Allah ﷺ to them. All of Hamdān embraced Islam. ʿAlī wrote to the Messenger of Allah ﷺ informing him of their acceptance of Islam. When the Messenger of Allah ﷺ read the letter, he fell down in prostration. He then raised his head and said: “Peace be upon Hamdān! Peace be upon Hamdān!”"]},"intro":{"ar":["قال ابن هشام: وقدم وفد همدان على رسول الله ﷺ، فيما حدثني من أثق به، عن عمرو بن عبد الله بن أذينة العبدي، عن أبي إسحاق السبيعي، قال: قدم وفد همدان على رسول الله ﷺ، منهم مالك بن نمط، وأبو ثور، وهو ذو المشعار، ومالك بن أيفع، وضمام بن مالك السلماني، وعميرة بن مالك الخارفي، فلقوا رسول الله ﷺ مرجعه من تبوك. وعليهم مقطعات الحبرات، والعمائم العدنية، برحال الميس على المهرية والأرحبية.","وكتب لهم رسول الله ﷺ كتابًا فيه: «بسم الله الرحمن الرحيم. هذا كتاب من رسول الله محمد، لمخلاف خارف وأهل جناب الهضب وحقاف الرمل، مع وافدها ذي المشعار مالك بن نمط، ومن أسلم من قومه، على أن لهم فراعها ووهاطها، ما أقاموا الصلاة وآتوا الزكاة، يأكلون علافها ويرعون عافيها، لهم بذلك عهد الله وذمام رسوله، وشاهدهم المهاجرون والأنصار». سيرة ابن هشام (٢/٥٩٦-٥٩٨).","وفي الإسناد رجل لم يُسمَّ، كما أن فيه إرسالًا، فإن أبا إسحاق السبيعي من التابعين.","قوله: «مقطعات»: ثياب مخيطة. وقوله: «الحبرات»: برود يمنية. وقوله: «الميس»: خشب تصنع منه الرحال التي تكون على ظهر الإبل. وقوله: «المهرية»: الإبل النجيبة، تنسب إلى مهرة، قبيلة باليمن. وقوله: «الأرحبية»: إبل تنسب إلى أرحب، وهم قبيلة من همدان. وقوله: «المخلاف»: المدينة بلغة اليمن. وقوله: «خارف»: قبيلة من اليمن. وقوله: «الحقاف»: جمع حقف، وهو الرمل المستدير. وقوله: «الفراع»: أعالي الأرض. وقوله: «الوهاط»: المنخفض من الأرض. وقوله: «العلاف»: ثمر الطلح. وقوله: «عافيها»: نباتها الكثير.","وجاء ذكر إسلام همدان مسندًا في الحديث التالي:"],"en":["Ibn Hishām said:","The delegation of Hamdān came to the Messenger of Allah ﷺ, according to what someone whom I trust narrated to me, from ʿAmr ibn ʿAbdullāh ibn Udhaynah al-ʿAbdī, from Abū Isḥāq al-Sabīʿī, who said:","The delegation of Hamdān came to the Messenger of Allah ﷺ. Among them were Mālik ibn Namaṭ; Abū Thawr, who was known as Dhū al-Mishʿār; Mālik ibn Ayfaʿ; Ḍimām ibn Mālik al-Salmānī; and ʿUmayrah ibn Mālik al-Khārifī.","They met the Messenger of Allah ﷺ as he was returning from Tabūk. They wore tailored garments of striped Yemeni cloth and ʿAdanī turbans, riding noble Mahriyyah and Arḥabiyyah camels fitted with saddles made of mays wood.","The Messenger of Allah ﷺ wrote a document for them containing:","“In the name of Allah, the Most Compassionate, the Most Merciful. This is a document from the Messenger of Allah, Muḥammad, for the district of Khārif and the people living beside the highlands and the curved sand dunes, together with their delegate Dhū al-Mishʿār, Mālik ibn Namaṭ, and those of his people who have embraced Islam.","Their highlands and lowlands shall belong to them so long as they establish prayer and give zakāh. They may eat its acacia fruits and graze their animals upon its abundant vegetation. For this, they possess the covenant of Allah and the protection of His Messenger. The Emigrants and the Anṣār are witnesses on their behalf.”","Sīrat Ibn Hishām (2/596–598).","The chain of transmission contains an unnamed man and is also disconnected, because Abū Isḥāq al-Sabīʿī was one of the Tābiʿīn.","The term “muqaṭṭaʿāt” means tailored garments. “Al-ḥibarāt” refers to striped Yemeni cloaks. “Al-mays” is a type of wood from which camel saddles are made. “Al-Mahriyyah” refers to noble camels attributed to Mahrah, a tribe of Yemen. “Al-Arḥabiyyah” refers to camels attributed to Arḥab, a tribe of Hamdān. “Al-mikhlāf” means a city or district in the language of Yemen. Khārif is a tribe of Yemen. “Al-aḥqāf” is the plural of ḥiqf, meaning a curved or rounded sand dune. “Al-firāʿ” means the elevated parts of the land. “Al-wihāṭ” means the low-lying parts of the land. “Al-ʿilāf” is the fruit of the acacia tree. “ʿĀfiyahā” means its abundant vegetation.","The conversion of Hamdān to Islam is mentioned through a connected chain in the following hadith:"]}},"tuhfa":{},"voc":["seerah",1001],"full":1,"dr":1,"rep":[3026],"tks":"صحيح: رواه البيهقي في الكبرى (3932)."},{"num":9774,"demo":false,"sanad":"","matn":["عَنْ حُذَيْفَةَ، قَالَ: جَاءَ الْعَاقِبُ وَالسَّيِّدُ صَاحِبَا نَجْرَانَ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يُرِيدَانِ أَنْ يُلاَعِنَاهُ، قَالَ: فَقَالَ أَحَدُهُمَا لِصَاحِبِهِ: لاَ تَفْعَلْ، فَوَاللَّهِ لَئِنْ كَانَ نَبِيًّا فَلاَعَنَّا، لاَ نُفْلِحُ نَحْنُ، وَلاَ عَقِبُنَا مِنْ بَعْدِنَا. قَالاَ: إِنَّا نُعْطِيكَ مَا سَأَلْتَنَا، وَابْعَثْ مَعَنَا رَجُلاً أَمِينًا، وَلاَ تَبْعَثْ مَعَنَا إِلاَّ أَمِينًا. فَقَالَ: لأَبْعَثَنَّ مَعَكُمْ رَجُلاً أَمِينًا حَقَّ أَمِينٍ. فَاسْتَشْرَفَ لَهُ أَصْحَابُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقَالَ: قُمْ يَا أَبَا عُبَيْدَةَ بْنَ الْجَرَّاحِ. فَلَمَّا قَامَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: هَذَا أَمِينُ هَذِهِ الأُمَّةِ."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4380) ومسلم في فضائل الصحابة (2420: 55) كلاهما من طريق أبي إسحاق، عن صلة بن زفر، عن حذيفة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"قصة وفد أهل نجران، وكان بعد فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4380) and Muslim (2420:55).","chapter_en":"The Story of the Delegation of the People of Najrān, Which Took Place After the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":11,"content":{"translation":{"en":["Ḥudhayfah said: “Al-ʿĀqib and al-Sayyid, the two leaders of Najrān, came to the Messenger of Allah ﷺ intending to invoke mutual cursing with him. “One of them said to the other, ‘Do not do it. By Allah, if he truly is a Prophet and we invoke mutual cursing against him, neither we nor our descendants after us will prosper.’ “They said, ‘We will give you what you have asked of us, but send with us a trustworthy man, and do not send with us anyone except one who is truly trustworthy.’ “He ﷺ said: ‘I will certainly send with you a man who is trustworthy in the fullest sense of the word.’ “The Companions of the Messenger of Allah ﷺ eagerly looked forward to being chosen. “He said: ‘Stand, O Abū ʿUbaydah ibn al-Jarrāḥ.’ “When he stood, the Messenger of Allah ﷺ said: ‘This is the trustworthy man of this nation.’”"]},"intro":{"ar":["قال ابن إسحاق: وقدم على رسول اللّٰه ﷺ وفد نصارى نجران، ستون راكبًا، فيهم أربعة عشر رجلًا من أشرافهم، في الأربعة عشر منهم ثلاثة نفر إليهم يؤول أمرهم: العاقب أمير القوم وذو رأيهم، وصاحب شورتهم والذي لا يصدرون إلا عن رأيه، واسمه عبد المسيح. والسيد لهم ثمالهم، وصاحب رحلهم ومجتمعهم، واسمه الأيهم. وأبو حارثة بن علقمة، أحد بني بكر بن وائل، أسقفهم وحبرهم وإمامهم وصاحب مدراسهم. وأطال في ذكرهم. سيرة ابن هشام (١/٥٧٣).","قوله: «ثمالهم» أي أصلهم الذي يقصدون إليه."],"en":["Ibn Isḥāq said:","“A delegation of the Christians of Najrān came to the Messenger of Allah ﷺ. They consisted of sixty riders, among whom were fourteen of their nobles. Among those fourteen were three men to whom their affairs ultimately referred:","“Al-ʿĀqib was their leader and man of counsel, the one whose opinion they sought and from whose judgment they would not depart. His name was ʿAbd al-Masīḥ.","“Al-Sayyid was their mainstay, responsible for their travel arrangements and gathering. His name was al-Ayham.","“And Abū Ḥārithah ibn ʿAlqamah, from Banū Bakr ibn Wā’il, was their bishop, scholar, imam, and head of their school.”","Ibn Isḥāq then spoke at length concerning them. See: Sīrat Ibn Hishām (1/573).","His saying “thimāluhum” means: their principal support and the person to whom they would turn."]}},"tuhfa":{},"voc":["seerah",1003],"full":1,"rep":[12071],"tks":"متفق عليه: رواه البخاري (4380)، ومسلم (2420: 55)."},{"num":9775,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ، قَالَ: صَالَحَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَهْلَ نَجْرَانَ عَلَى أَلْفَىْ حُلَّةٍ: النِّصْفُ فِي صَفَرٍ وَالْبَقِيَّةُ فِي رَجَبٍ، يُؤَدُّونَهَا إِلَى الْمُسْلِمِينَ، وَعَارِيَةِ ثَلاَثِينَ دِرْعًا، وَثَلاَثِينَ فَرَسًا، وَثَلاَثِينَ بَعِيرًا، وَثَلاَثِينَ مِنْ كُلِّ صِنْفٍ مِنْ أَصْنَافِ السِّلاَحِ يَغْزُونَ بِهَا، وَالْمُسْلِمُونَ ضَامِنُونَ لَهَا حَتَّى يَرُدُّوهَا عَلَيْهِمْ إِنْ كَانَ بِالْيَمَنِ كَيْدٌ أَوْ غَدْرَةٌ: عَلَى أَنْ لاَ تُهْدَمَ لَهُمْ بَيْعَةٌ، وَلاَ يُخْرَجُ لَهُمْ قَسٌّ، وَلاَ يُفْتَنُوا عَنْ دِينِهِمْ مَا لَمْ يُحْدِثُوا حَدَثًا أَوْ يَأْكُلُوا الرِّبَا. قَالَ إِسْمَاعِيلُ: فَقَدْ أَكَلُوا الرِّبَا. قَالَ أَبُو دَاوُدَ: إِذَا نَقَضُوا بَعْضَ مَا اشْتَرَطَ عَلَيْهِمْ فَقَدْ أَحْدَثُوا."],"takhrij":"حسن: رواه أبو داود (3041) والبيهقي (18680) والضياء المقدسي في المختارة (492) كلهم من حديث يونس بن بكير، حدثنا أسباط بن نصر الهمداني، عن إسماعيل بن عبد الرحمن القرشي، عن ابن عباس، فذكره.","grade":"حسن","chapter_ar":"قصة وفد أهل نجران، وكان بعد فتح مكة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3041), al-Bayhaqī (9/187), and al-Ḍiyāʾ al-Maqdisī in al-Mukhtārah (9/508).","chapter_en":"The Story of the Delegation of the People of Najrān, Which Took Place After the Conquest of Makkah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":11,"content":{"translation":{"en":["Ibn ʿAbbās said: “The Messenger of Allah ﷺ concluded a treaty with the people of Najrān for two thousand garments: half to be paid in Ṣafar and half in Rajab, which they would deliver to the Muslims. “They were also to lend thirty coats of armor, thirty horses, thirty camels, and thirty items of every category of weaponry for use in military expeditions. The Muslims would be responsible for guaranteeing those items until they were returned to them if treachery or hostile action occurred in Yemen. “The agreement stipulated that no church of theirs would be demolished, no priest of theirs would be expelled, and they would not be forced away from their religion, so long as they did not introduce some violation or consume usury.” Ismāʿīl said: “They did consume usury.” Abū Dāwūd said: “If they violated any part of what had been stipulated upon them, then they had committed a breach.”"]}},"tuhfa":{},"voc":["seerah",1004],"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3041)، والبيهقي (18680)، والضياء المقدسي في المختارة (492)."},{"num":9776,"demo":false,"sanad":"","matn":["عن عِمْرَانَ بْنِ حُصَيْنٍ قَالَ: جَاءَتْ بَنُو تَمِيمٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: أَبْشِرُوا يَا بَنِي تَمِيمٍ. قَالُوا أَمَّا إِذْ بَشَّرْتَنَا فَأَعْطِنَا. فَتَغَيَّرَ وَجْهُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَاءَ نَاسٌ مِنْ أَهْلِ الْيَمَنِ، فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: اقْبَلُوا الْبُشْرَى إِذْ لَمْ يَقْبَلْهَا بَنُو تَمِيمٍ. قَالُوا: قَدْ قَبِلْنَا يَا رَسُولَ اللَّهِ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (4386) عن عمرو بن علي، حدثنا أبو عاصم، حدثنا سفيان، حدثنا أبو صخرة جامع بن شداد، حدثنا صفوان بن محرز المازني، حدثنا عمران بن حصين، قال: فذكره.","grade":"صحيح","chapter_ar":"وفد بني تميم من اليمن، وكان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4386).","chapter_en":"The Delegation of Banū Tamīm from Yemen, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":12,"content":{"translation":{"en":["ʿImrān ibn Ḥuṣayn said: “Banū Tamīm came to the Messenger of Allah ﷺ, and he said: ‘Receive glad tidings, O Banū Tamīm.’ “They replied, ‘Since you have given us glad tidings, then give us something.’ “The expression of the Messenger of Allah ﷺ changed. “Then some people from Yemen came, and the Prophet ﷺ said: ‘Accept the glad tidings, since Banū Tamīm did not accept them.’ “They said, ‘We accept them, O Messenger of Allah.’”"]}},"tuhfa":{},"voc":["seerah",1005],"full":1,"tks":"صحيح: رواه البخاري (4386)."},{"num":9777,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ رَضِيَ اللَّهُ عَنْهُ عَنِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَالَ أَتَاكُمْ أَهْلُ الْيَمَنِ، هُمْ أَرَقُّ أَفْئِدَةً وَأَلْيَنُ قُلُوبًا، الإِيمَانُ يَمَانٍ، وَالْحِكْمَةُ يَمَانِيَةٌ، وَالْفَخْرُ وَالْخُيَلاَءُ فِي أَصْحَابِ الإِبِلِ، وَالسَّكِينَةُ وَالْوَقَارُ فِي أَهْلِ الْغَنَمِ."],"takhrij":"متفق عليه: رواه البخاريّ في المغازي (4388) ومسلم في الإيمان (52: 91) كلاهما من طريق ابن أبي عدي، حدثنا شعبة، عن سليمان الأعمش، عن أبي صالح ذكوان، عن أبي هريرة، قال: فذكره.","grade":"متفق عليه","chapter_ar":"وفد بني تميم من اليمن، وكان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4388) and Muslim (52:91).","chapter_en":"The Delegation of Banū Tamīm from Yemen, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":12,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “The people of Yemen have come to you. They have the most tender hearts and the softest hearts. Faith is Yemeni, and wisdom is Yemeni. Pride and arrogance are among the owners of camels, while tranquility and dignity are among the people who tend sheep.”"]}},"tuhfa":{},"voc":["seerah",1006],"full":1,"tks":"متفق عليه: رواه البخاري (4388)، ومسلم (52: 91)."},{"num":9778,"demo":false,"sanad":"","matn":["9778 - عَنْ عَبْدِ اللَّهِ بن الزُّبَيْرِ أَنَّهُ قَدِمَ رَكْبٌ مِنْ بَنِي تَمِيمٍ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، فَقَالَ أَبُو بَكْرٍ: أمِّر الْقَعْقَاعَ بْنَ مَعْبَدِ بْنِ زُرَارَةَ. قَالَ عُمَرُ: بَلْ أمِّر الأَقْرَعَ بْنَ حَابِسٍ. قَالَ أَبُو بَكْرٍ: مَا أَرَدْتَ إِلاَّ خِلاَفِي. قَالَ عُمَرُ: مَا أَرَدْتُ خِلاَفَكَ. فَتَمَارَيَا حَتَّى ارْتَفَعَتْ أَصْوَاتُهُمَا، فَنَزَلَ فِي ذَلِكَ: يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تُقَدِّمُوا [الحجرات:١] حَتَّى انْقَضَتْ."],"takhrij":"صحيح: رواه البخاريّ في المغازي (4367) عن إبراهيم بن موسى، حدثنا هشام بن يوسف، أن ابن جريج أخبرهم، عن ابن أبي مليكة، أن عبد الله بن الزبير، أخبرهم فذكره.","grade":"صحيح","chapter_ar":"وفد بني تميم من اليمن، وكان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4367).","chapter_en":"The Delegation of Banū Tamīm from Yemen, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":12,"content":{"translation":{"en":["ʿAbdullāh ibn al-Zubayr reported: “A group from Banū Tamīm came to the Prophet ﷺ. “Abū Bakr said, ‘Appoint al-Qaʿqāʿ ibn Maʿbad ibn Zurārah as their leader.’ “ʿUmar said, ‘Rather, appoint al-Aqraʿ ibn Ḥābis.’ “Abū Bakr said, ‘You only intended to contradict me.’ “ʿUmar replied, ‘I did not intend to contradict you.’ “They continued disputing until their voices became raised. “Then concerning that, the verse was revealed: ‘O you who believe, do not put yourselves forward…’ [al-Ḥujurāt: 1], continuing to the end of the passage.”"]}},"tuhfa":{},"voc":["seerah",1007],"full":1,"tks":"صحيح: رواه البخاري (4367)."},{"num":9779,"demo":false,"sanad":"","matn":["عَنِ ابْنِ أَبِي مُلَيْكَةَ، قَالَ: كَادَ الْخَيِّرَانِ أَنْ يَهْلِكَا: أَبُو بَكْرٍ، وَعُمَرُ، لَمَّا قَدِمَ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَفْدُ بَنِي تَمِيمٍ، أَشَارَ أَحَدُهُمَا بِالأَقْرَعِ بْنِ حَابِسٍ الْحَنْظَلِيِّ أَخِي بَنِي مُجَاشِعٍ، وَأَشَارَ الآخَرُ بِغَيْرِهِ، فَقَالَ أَبُو بَكْرٍ لِعُمَرَ: إِنَّمَا أَرَدْتَ خِلاَفِي. فَقَالَ عُمَرُ: مَا أَرَدْتُ خِلاَفَكَ. فَارْتَفَعَتْ أَصْوَاتُهُمَا عِنْدَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَنَزَلَتْ: ﴿يَا أَيُّهَا الَّذِينَ آمَنُوا لاَ تَرْفَعُوا أَصْوَاتَكُمْ﴾ [سورة الحجرات: 2]} إِلَى قَوْلِهِ {عَظِيمٌ}. قَالَ ابْنُ أَبِي مُلَيْكَةَ: قَالَ ابْنُ الزُّبَيْرِ: فَكَانَ عُمَرُ بَعْدُ ـ وَلَمْ يَذْكُرْ ذَلِكَ عَنْ أَبِيهِ، يَعْنِي أَبَا بَكْرٍ ـ إِذَا حَدَّثَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بِحَدِيثٍ حَدَّثَهُ كَأَخِي السِّرَارِ، لَمْ يُسْمِعْهُ حَتَّى يَسْتَفْهِمَهُ."],"takhrij":"صحيح: رواه البخاريّ في الاعتصام (7302) عن محمد بن مقاتل، أخبرنا وكيع، عن نافع بن عمر، عن ابن أبي مليكة، فذكره.","grade":"صحيح","chapter_ar":"وفد بني تميم من اليمن، وكان في سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (7302).","chapter_en":"The Delegation of Banū Tamīm from Yemen, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":12,"content":{"translation":{"en":["Ibn Abī Mulaykah said: “The two excellent men, Abū Bakr and ʿUmar, nearly came to ruin when the delegation of Banū Tamīm came to the Prophet ﷺ. “One of them suggested al-Aqraʿ ibn Ḥābis al-Ḥanẓalī, the brother of Banū Mujāshiʿ, while the other suggested someone else. “Abū Bakr said to ʿUmar, ‘You only intended to contradict me.’ “ʿUmar replied, ‘I did not intend to contradict you.’ “Their voices became raised in the presence of the Prophet ﷺ, so the following was revealed: ‘O you who believe, do not raise your voices above the voice of the Prophet…’ until His saying, ‘a tremendous reward.’ [al-Ḥujurāt: 2–3] Ibn Abī Mulaykah said that Ibn al-Zubayr said: “After that, whenever ʿUmar spoke to the Prophet ﷺ, he would speak almost like someone whispering a secret. The Prophet ﷺ could scarcely hear him until he asked him to repeat himself.” He did not mention this concerning his father, meaning Abū Bakr."]}},"tuhfa":{},"voc":["seerah",1008],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (7302)."},{"num":9780,"demo":false,"sanad":"","matn":["عَنِ الأَشْعَثِ بْنِ قَيْسٍ، قَالَ: أَتَيْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فِي وَفْدِ كِنْدَةَ، وَلاَ يَرَوْنِي أَفْضَلَهُمْ، فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَلَسْتُمْ مِنَّا. فَقَالَ: نَحْنُ بَنُو النَّضْرِ بْنِ كِنَانَةَ، لاَ نَقْفُو أُمَّنَا، وَلاَ نَنْتَفِي مِنْ أَبِينَا."],"takhrij":"حسن: رواه ابن ماجه (2616) وأحمد (21839) كلاهما من حديث حماد بن سلمة، عن عقيل بن طلحة السلمي، عن مسلم بن هيضم، عن الأشعث بن قيس، فذكره.","grade":"حسن","chapter_ar":"باب وفد كندة","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Mājah (2616) and Aḥmad (21839).","chapter_en":"The Delegation of Kindah","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":13,"content":{"translation":{"en":["Al-Ashʿath ibn Qays said: “I came to the Messenger of Allah ﷺ as part of the delegation of Kindah, and they regarded me as the best among them. “I said, ‘O Messenger of Allah, are you not from us?’ “He replied: ‘We are the descendants of al-Naḍr ibn Kinānah. We do not falsely attribute ourselves through our mother, nor do we deny our father.’”"]},"buhuth":{"en":["Ibn Isḥāq also said:","“Al-Ashʿath ibn Qays came to the Messenger of Allah ﷺ with the delegation of Kindah.","“Al-Zuhrī ibn Shihāb informed me that he came to the Messenger of Allah ﷺ with eighty riders from Kindah. They entered the mosque of the Messenger of Allah ﷺ having combed their long hair and applied kohl. They were wearing striped robes whose edges had been trimmed with silk.","“When they entered upon the Messenger of Allah ﷺ, he said:","‘Have you not embraced Islām?’","“They replied, ‘Yes.’","“He said:","‘Then what is this silk around your necks?’","“So they tore it off and threw it away.”","Sīrat Ibn Hishām (2/585)."]}},"tuhfa":{},"voc":["seerah",1009],"full":1,"dr":1,"tks":"حسن: رواه ابن ماجه (2616)، وأحمد (21839)."},{"num":9781,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ رَضِيَ اللَّهُ عَنْهُمَا قَالَ: قَدِمَ مُسَيْلِمَةُ الْكَذَّابُ عَلَى عَهْدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَجَعَلَ يَقُولُ: إِنْ جَعَلَ لِي مُحَمَّدٌ مِنْ بَعْدِهِ تَبِعْتُهُ. وَقَدِمَهَا فِي بَشَرٍ كَثِيرٍ مِنْ قَوْمِهِ، فَأَقْبَلَ إِلَيْهِ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَفِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قِطْعَةُ جَرِيدٍ حَتَّى وَقَفَ عَلَى مُسَيْلِمَةَ فِي أَصْحَابِهِ، فَقَالَ: لَوْ سَأَلْتَنِي هَذِهِ الْقِطْعَةَ مَا أَعْطَيْتُكَهَا، وَلَنْ تَعْدُوَ أَمْرَ اللَّهِ فِيكَ، وَلَئِنْ أَدْبَرْتَ لَيَعْقِرَنَّكَ اللَّهُ، وَإِنِّي لأَرَاكَ الَّذِي أُرِيتُ فِيهِ مَا رَأَيْتُ، وَهَذَا ثَابِتٌ يُجِيبُكَ عَنِّي. ثُمَّ انْصَرَفَ عَنْهُ.","قَالَ ابْنُ عَبَّاسٍ: فَسَأَلْتُ عَنْ قَوْلِ رَسُولِ اللَّهِ صلى الله عليه وسلم: إِنَّكَ أُرَى الَّذِي أُرِيتُ فِيهِ مَا أُرِيتُ فَأَخْبَرَنِي أَبُو هُرَيْرَةَ أَنَّ رَسُولَ اللَّهِ صلى الله عليه وسلم قَالَ: بَيْنَا أَنَا نَائِمٌ رَأَيْتُ فِي يَدَيَّ سِوَارَيْنِ مِنْ ذَهَبٍ، فَأَهَمَّنِي شَأْنُهُمَا، فَأُوحِيَ إِلَيَّ فِي الْمَنَامِ: أَنِ انْفُخْهُمَا، فَنَفَخْتُهُمَا فَطَارَا، فَأَوَّلْتُهُمَا كَذَّابَيْنِ يَخْرُجَانِ بَعْدِي أَحَدُهُمَا الْعَنْسِيُّ، وَالْآخَرُ مُسَيْلِمَةُ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4373) ومسلم في الرؤيا (2273-2274: 21) كلاهما من طريق شعيب، عن عبدالله بن أبي حسين، حدثنا نافع بن جبير، عن ابن عباس، قال: فذكره.","grade":"متفق عليه","chapter_ar":"باب وفد بني حنيفة ومعهم مسيلمة الكذاب، وكان ذلك بعد سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4373, 4374) and Muslim (2273–2274:21).","chapter_en":"The Delegation of Banū Ḥanīfah, Accompanied by Musaylimah the Liar, Which Took Place After the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿAbbās said: “Musaylimah the Liar came during the lifetime of the Messenger of Allah ﷺ, saying, ‘If Muḥammad gives me authority after him, I will follow him.’ “He came with a large number of his people. “The Messenger of Allah ﷺ went to him accompanied by Thābit ibn Qays ibn Shammās, while the Messenger of Allah ﷺ held a piece of palm stalk in his hand. “He stood before Musaylimah among his companions and said: ‘Even if you asked me for this piece, I would not give it to you. You will not escape what Allah has decreed concerning you. If you turn away, Allah will surely destroy you. I indeed see you as the one concerning whom I was shown what I was shown. And this is Thābit; he will answer you on my behalf.’ “Then he turned away from him.” Ibn ʿAbbās said: “I asked about the statement of the Messenger of Allah ﷺ: ‘I indeed see you as the one concerning whom I was shown what I was shown.’ “Abū Hurayrah informed me that the Messenger of Allah ﷺ said: ‘While I was asleep, I saw two bracelets of gold in my hands, and their matter troubled me. It was revealed to me in the dream that I should blow upon them. I blew upon them and they flew away. I interpreted them as two liars who would emerge after me.’","“One was al-ʿAnsī and the other was Musaylimah.”"]}},"tuhfa":{},"voc":["seerah",1011],"full":1,"rep":[9738],"tks":"متفق عليه: رواه البخاري (4373، 4374)، ومسلم (2273-2274: 21)."},{"num":9782,"demo":false,"sanad":"","matn":["عَنْ أَبِي هُرَيْرَةَ يَقُولُ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : بَيْنَا أَنَا نَائِمٌ، أُتِيتُ بِخَزَائِنِ الأَرْضِ، فوُضِع فِي كفِّي سِوَارَانِ مِنْ ذَهَبٍ، فكَبُرَا عليَّ، فأوحى اللَّهِ إِلَى أَنِ انْفُخْهُمَا، فَنَفَخْتُهُمَا، فَذَهَبَا، فَأَوَّلْتُهُمَا الْكَذَّابَيْنِ اللَّذَيْنِ أَنَا بَيْنَهُمَا: صَاحِبَ صَنْعَاءَ، وَصَاحِبَ الْيَمَامَةِ."],"takhrij":"متفق عليه: رواه البخاري في المغازي (4375) ومسلم في الفضائل (2274: 22) كلاهما من حديث عبد الرزاق، عن معمر، عن همام، أنه سمع أبا هريرة، فذكره.","grade":"متفق عليه","chapter_ar":"باب وفد بني حنيفة ومعهم مسيلمة الكذاب، وكان ذلك بعد سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (4375) and Muslim (2274:22).","chapter_en":"The Delegation of Banū Ḥanīfah, Accompanied by Musaylimah the Liar, Which Took Place After the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":15,"content":{"translation":{"en":["Abū Hurayrah reported that the Messenger of Allah ﷺ said: “While I was sleeping, the treasures of the earth were brought to me, and two bracelets of gold were placed in my hands. They became burdensome to me, so Allah revealed to me that I should blow upon them. I blew upon them and they disappeared. I interpreted them as the two liars between whom I am situated: the man of Ṣanʿāʾ and the man of al-Yamāmah.”"]}},"tuhfa":{},"voc":["seerah",1012],"full":1,"tks":"متفق عليه: رواه البخاري (4375)، ومسلم (2274: 22)."},{"num":9783,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عُبَيْدَةَ بْنِ نَشِيطٍ ـ وَكَانَ فِي مَوْضِعٍ آخَرَ اسْمُهُ عَبْدُ اللَّهِ ـ أَنَّ عُبَيْدَ اللَّهِ بْنَ عَبْدِ اللَّهِ بْنِ عُتْبَةَ قَالَ: بَلَغَنَا أَنَّ مُسَيْلِمَةَ الْكَذَّابَ قَدِمَ الْمَدِينَةَ، فَنَزَلَ فِي دَارِ بِنْتِ الْحَارِثِ، وَكَانَ تَحْتَهُ بِنْتُ الْحَارِثِ بْنِ كُرَيْزٍ، وَهْىَ أُمُّ عَبْدِ اللَّهِ بْنِ عَامِرٍ، فَأَتَاهُ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَمَعَهُ ثَابِتُ بْنُ قَيْسِ بْنِ شَمَّاسٍ، وَهْوَ الَّذِي يُقَالُ لَهُ خَطِيبُ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَفِي يَدِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَضِيبٌ، فَوَقَفَ عَلَيْهِ فَكَلَّمَهُ، فَقَالَ لَهُ مُسَيْلِمَةُ: إِنْ شِئْتَ خَلَّيْتَ بَيْنَنَا وَبَيْنَ الأَمْرِ، ثُمَّ جَعَلْتَهُ لَنَا بَعْدَكَ. فَقَالَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: لَوْ سَأَلْتَنِي هَذَا الْقَضِيبَ مَا أَعْطَيْتُكَهُ، وَإِنِّي لأَرَاكَ الَّذِي أُرِيتُ فِيهِ مَا أُرِيتُ، وَهَذَا ثَابِتُ بْنُ قَيْسٍ، وَسَيُجِيبُكَ عَنِّي. فَانْصَرَفَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في المغازي (4378) عن سعيد بن محمد الجرمي، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح، عن ابن عبيدة بن نشيط، فذكره.","grade":"صحيح","chapter_ar":"باب وفد بني حنيفة ومعهم مسيلمة الكذاب، وكان ذلك بعد سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (4378).","chapter_en":"The Delegation of Banū Ḥanīfah, Accompanied by Musaylimah the Liar, Which Took Place After the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":15,"content":{"translation":{"en":["Ibn ʿUbaydah ibn Nashīṭ—whose name in another place is given as ʿAbdullāh—reported that ʿUbaydullāh ibn ʿAbdullāh ibn ʿUtbah said: “We were informed that Musaylimah the Liar came to Madīnah and stayed in the house of the daughter of al-Ḥārith. He was married to the daughter of al-Ḥārith ibn Kurayz, who was the mother of ʿAbdullāh ibn ʿĀmir. “The Messenger of Allah ﷺ went to him accompanied by Thābit ibn Qays ibn Shammās, who was known as the orator of the Messenger of Allah ﷺ. The Messenger of Allah ﷺ had a small stick in his hand. “He stood before Musaylimah and spoke to him. “Musaylimah said, ‘If you wish, leave the authority between us and yourself, then assign it to us after you.’ “The Prophet ﷺ replied: ‘Even if you asked me for this stick, I would not give it to you. I indeed see you as the one concerning whom I was shown what I was shown. And this is Thābit ibn Qays; he will answer you on my behalf.’ “Then the Prophet ﷺ departed.”"]}},"tuhfa":{},"voc":["seerah",1013],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4378)."},{"num":9784,"demo":false,"sanad":"","matn":["عَنْ نُعَيْمِ بن مَسْعُودٍ الأشجعي قَالَ: سمِعْتُ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ يَقُولُ لِلرَّسُولَيْنِ حِينَ قَرَأَ كِتَابَ مُسَيْلِمَةَ الْكَذَّابِ: فَمَا تَقُولَانِ أَنْتُمَا؟ قَالَا: نَقُولُ كَمَا قَالَ. فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : أما وَاللهِ لَوْلَا أَنَّ الرُّسُلَ لَا تُقْتَلُ لَضَرَبْتُ أَعْنَاقَكُمَا."],"takhrij":"حسن: رواه أبو داود (2761) وأحمد (15989) والترمذي في العلل الكبير (2/953) والحاكم (3/52-53 و2/142-143) كلهم من طريق محمد بن إسحاق، قال: حدثني سعد بن طارق الأشجعي، عن سلمة بن نعيم بن مسعود الأشجعي، عن أبيه، قال: فذكره.","grade":"حسن","chapter_ar":"باب وفد بني حنيفة ومعهم مسيلمة الكذاب، وكان ذلك بعد سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (2761), Aḥmad (15989), and al-Tirmidhī in al-ʿIlal al-Kabīr (2/953).","chapter_en":"The Delegation of Banū Ḥanīfah, Accompanied by Musaylimah the Liar, Which Took Place After the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":15,"content":{"translation":{"en":["Nuʿaym ibn Masʿūd al-Ashjaʿī said: “I heard the Messenger of Allah ﷺ say to the two envoys when they read out the letter of Musaylimah the Liar: ‘And what do the two of you say?’ “They replied, ‘We say what he says.’ “The Messenger of Allah ﷺ said: ‘By Allah, were it not that messengers are not to be killed, I would strike both of your necks.’”"]}},"tuhfa":{},"voc":["seerah",1014],"full":1,"dr":1,"rep":[7917],"tks":"حسن: رواه أبو داود (2761)، وأحمد (15989)، والترمذي في العلل الكبير (2/953)."},{"num":9785,"demo":false,"sanad":"","matn":["عَنْ وَهْبٍ، قَالَ: سَأَلْتُ جَابِرًا عَنْ شَأْنِ، ثَقِيفٍ إِذْ بَايَعَتْ قَالَ: اشْتَرَطَتْ عَلَى النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: أَنْ لاَ صَدَقَةَ عَلَيْهَا، وَلاَ جِهَادَ، وَأَنَّهُ سَمِعَ النَّبِيَّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعْدَ ذَلِكَ يَقُولُ: سَيَتَصَدَّقُونَ وَيُجَاهِدُونَ إِذَا أَسْلَمُوا."],"takhrij":"حسن: رواه أبو داود (3025) وابن أبي عاصم في الآحاد والمثاني (1525) كلاهما من حديث إسماعيل بن عبد الكريم، حدثني إبراهيم بن عقيل بن منبه، عن أبيه، عن وهب قال: فذكره.","grade":"حسن","chapter_ar":"باب في وفد ثقيف، وكان ذلك سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Abū Dāwūd (3025) and Ibn Abī ʿĀṣim in al-Āḥād wa al-Mathānī (1525).","chapter_en":"The Delegation of Thaqīf, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":16,"content":{"translation":{"en":["Wahb ibn Munabbih said: “I asked Jābir about the matter of Thaqīf when they gave the pledge of allegiance. “He said: ‘They stipulated to the Prophet ﷺ that no charity would be required of them and that they would not be required to fight in jihād.’ “He later heard the Prophet ﷺ say: ‘They will give charity and fight in jihād once they have truly embraced Islām.’”"]}},"tuhfa":{},"voc":["seerah",1015],"full":1,"dr":1,"tks":"حسن: رواه أبو داود (3025)، وابن أبي عاصم في الآحاد والمثاني (1525)."},{"num":9786,"demo":false,"sanad":"","matn":["عَنْ الشريد قَالَ: كَانَ فِي وَفْدِ ثَقِيفٍ رَجُلٌ مَجْذُومٌ فَأَرْسَلَ إِلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: : إِنَّا قَدْ بَايَعْنَاكَ فَارْجِعْ."],"takhrij":"صحيح: رواه مسلم في السلام (2231) من طرق عن يعلى بن عطاء، عن عمروبن الشريد، عن أبيه، قال: فذكره.","grade":"صحيح","chapter_ar":"باب في وفد ثقيف، وكان ذلك سنة تسع","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim in The Book of Salām (2231).","chapter_en":"The Delegation of Thaqīf, Which Came in the Ninth Year","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في ذكر الوفود إلى رسول الله ﷺ","group_en":"A Collection of Reports Concerning the Delegations to the Messenger of Allah ﷺ","part_no":48,"group_no":39,"chapter_no":16,"content":{"translation":{"en":["Al-Sharīd said: “There was a man afflicted with leprosy among the delegation of Thaqīf. “The Prophet ﷺ sent word to him: ‘We have accepted your pledge, so return.’”"]}},"tuhfa":{},"voc":["seerah",1016],"full":1,"rep":[7654,11652],"tks":"صحيح: رواه مسلم (2231)."},{"num":9787,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ اللَّهِ بْنِ حَسَّانَ أَخِي بَنِي كَعْبٍ مِنْ بَلْعَنْبَرٍ، أَنَّهُ حَدَّثَتْهُ جَدَّتَاهُ صَفِيَّةُ بِنْتُ عُلَيْبَةَ وَدُحَيْبَةُ بِنْتُ عُلَيْبَةَ حَدَّثَتَاهُ عَنْ حَدِيثِ قَيْلَةَ بِنْتِ مَخْرَمَةَ، وَكَانَتَا رَبِيبَتَيْهَا، وَقَيْلَةُ جَدَّةُ أَبِيهِمَا أُمُّ أُمِّهِ، أَنَّهَا كَانَتْ تَحْتَ حَبِيبِ بْنِ أَزْهَرَ أَخِي بَنِي جِنَابٍ، وَأَنَّهَا وَلَدَتْ لَهُ النِّسَاءِ، ثُمَّ تُوُفِّيَ فِي أَوَّلِ الإِسْلَامِ فَانْتَزَعَ بَنَاتِهَا مِنْهَا عمهن أَثُؤبُ بْنُ أَزْهَرَ، فَخَرَجَتْ تَبْتَغِي الصَّحَابَةَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم فِي أَوَّلِ الإِسْلَامِ، فَبَكَتْ جُوَيْرِيَةٌ مِنْهُنَّ حَدَيْبَاءُ، وَكَانَتْ أَخَذَتْهَا الفُرْصَةُ، عَلَيْهَا سَبِيجٌ مِنْ صُوفٍ، قَالَ: فَذَهَبَتْ بِهَا مَعَهَا، فبينا هُمَا تَرْتِكان الجَمَلَ إِذْ انْتَفَجَتِ الأَرْنَبُ، فَقَالَتِ الحَدَيْبَاءُ القُصِيَّةُ: وَاللَّهِ لَا يَزَالُ كَعْبُكَ أَعْلَى مِنْ كَعْبِ أَثُؤبٍ فِي هَذَا الحَدِيثِ أَبَدًا! ثُمَّ سَنَحَ الثَّعْلَبُ فَسَمَّتْهُ بِاسْمٍ نَسِيَهُ عَبْدُ اللَّهِ بْنُ حَسَّانَ، ثُمَّ قَالَتْ فِيهِ مِثْلَ مَا قَالَتْ فِي الأَرْنَبِ، فَبَيْنَمَا هُمَا تَرْتِكان الجَمَلَ إِذْ بَرَكَ الجَمَلُ، فَأَخَذَتْهُ رَعْدَةٌ، فَقَالَتِ الحَدَيْبَاءُ: أَدْرَكْتُكَ وَالأَمَانَةُ أَخْذَةُ أَثُؤبٍ، فَقُلْتُ وَاضْطُرِرْتُ إِلَيْهَا: وَيْحَكِ فَمَا أَصْنَعُ؟ فَقَالَتْ: اقْلِبْي ثِيَابَكِ ظُهُورَهَا لِبُطُونِهَا، وَادْحَرِجِي ظَهْرَكِ لِبَطْنِكِ، وَاقْلِبِي أَحْلَاسَ جَمَلِكِ، ثُمَّ خَلَعَتْ سَبِيجَهَا فَقَلَبَتْهُ، ثُمَّ ادْحَرَجَتْ ظَهْرَهَا لِبَطْنِهَا، فَلَمَّا فَعَلْتُ مَا أَمَرَتْنِي بِهِ انتَفَضَ الجَمَلُ، ثُمَّ قَامَ فَفَاجَ وبَالَ، فَقَالَتْ: أَعِيدِي عَلَيْكَ أَدَاتَكِ، فَفَعَلْتُ، ثُمَّ خَرَجْنَا نَرْتَكُ، فَإِذَا أَثُؤبُ يَسْعَى وَرَاءَنَا بِالسَّيْفِ صِلْتًا، فَوَأَلْنَا إِلَى حَوَّاءَ ضَخْمٍ، قَدْ أَرَاهُ حِينَ أَلْقَى الجَمَلَ إِلَى رُوَاقِ الْبَيْتِ الأَوْسَطِ جَمَلًا ذَلُولًا، وَاقْتَحَمْتُ دَاخِلَهُ وَأَدْرَكَنِي بِالسَّيْفِ، فَأَصَابَتْ ظُبَّتُهُ طَائِفَةً مِنْ قُرُونِي، ثُمَّ قَالَ: ألقي إِلَيَّ بِنْتَ أخي يَا دَفَّارُ! فَرَمَيْتُ بِهَا إِلَيْهِ فَجَعَلَهَا عَلَى مَنْكِبِهِ فَذَهَبَ بِهَا، وَكَانَتْ أَعْلَمَ بِهِ مِنْ أَهْلِ الْبَيْتِ، وَخَرَجْتُ إِلَى أُخْتٍ لِي نَاكِحٍ فِي بَنِي شَيْبَانَ أَبْتَغِي الصَّحَابَةَ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم، فَبَيْنَمَا أَنَا عِنْدَهَا لَيْلَةً مِنَ اللَّيَالِي تَحْسِبُنِي نَائِمَةً إِذْ جَاءَ زَوْجُهَا مِنَ السَّامِرِ فَقَالَ: وَأَبِيكِ لَقَدْ وَجَدْتُ لِقَيْلَةَ صَاحِبَ صِدْقٍ، فَقَالَتْ أُخْتِي: مَنْ هُوَ؟ قَالَ: حُرَيْثُ بْنُ حَسَّانٍ الشَّيْبَانِيُّ غَادِيًا، وَافِدُ بَكْرِ بْنِ وَائِلٍ إِلَى رَسُولِ اللَّهِ صلى الله عليه وسلم ذا صباح، فَغَدَوْتُ إِلَى جَمَلِي وَقَدْ سَمِعْتُ مَا قَالَا، فَشَدَدْتُ عَلَيْهِ ثُمَّ نَشَدْتُ عَنْهُ فَوَجَدْتُهُ غَيْرَ بَعِيدٍ، فَسَأَلْتُهُ الصُّحْبَةَ فَقَالَ: نَعَمْ وَكَرَامَةً، وركابهم مِنَاخَةٌ، فَخَرَجْتُ مَعَهُ صَاحِبَ صِدْقٍ، حَتَّى قَدِمْنَا عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَهُوَ يُصَلِّي بِالنَّاسِ صَلَاةَ الْغَدَاةِ، وَقَدْ أُقِيمَتْ حِينَ انْشَقَّ الفَجْرُ وَالنُّجُومُ شَابِكَةٌ فِي السَّمَاءِ، وَالرِّجَالُ لَا تَكَادُ تَعَارَفُ مَعَ ظُلْمَةِ اللَّيْلِ، فَصَفَفْتُ مَعَ الرِّجَالِ وَكُنْتُ امْرَأَةً حَدِيثَةَ عَهْدٍ بِجَاهِلِيَّةٍ، فَقَالَ لِي الرَّجُلُ الَّذِي يُلِينِي مِنَ الصَّفِّ: امْرَأَةٌ أَنْتِ أَمْ رَجُلٌ؟ فَقُلْتُ: لَا بَلِ امْرَأَةٌ، فَقَالَ: إِنَّكِ قَدْ كِدْتِ تَفْتِنِينِي، فصلِّي مَعَ النِّسَاءِ وَرَاءَكِ، وَإِذَا صَفٌّ مِنْ نِسَاءِ قَدْ حَدَثَ عِنْدَ الحُجُرَاتِ لَمْ أَكُنْ رَأَيْتُهُ حِينَ دَخَلْتُ، فَكُنْتُ فِيهِنَّ حَتَّى إِذَا طَلَعَتِ الشَّمْسُ دَنَوْتُ فَجَعَلْتُ إِذَا رَأَيْتُ رَجُلًا ذَا رَوَاءٍ وَذَا قِشْرٍ طَمَحَ إِلَيْهِ بَصَرِي لِأَرَى رَسُولَ اللَّهِ صلى الله عليه وسلم فَوْقَ النَّاسِ، حَتَّى جَاءَ رَجُلٌ وَقَدِ ارْتَفَعَتِ الشَّمْسُ فَقَالَ: السَّلامُ عَلَيْكَ يَا رَسُولَ اللَّهِ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم: وَعَلَيْكَ السَّلَامُ وَرَحْمَةُ اللَّهِ وَبَرَكَاتُهُ. وَعَلَيْهِ، تَعْنِي النَّبِيَّ صلى الله عليه وسلم أَسْمَالٌ ملببتين كَانَتَا بِزَعْفَرَانٍ فَقَدْ نَفَضَتَا، وَمَعَهُ عَسِيبٌ نَخْلَةٌ مَقْشُورٌ غَيْرُ خَوَصَتَيْنِ مِنْ أَعْلَاهُ، وَهُوَ قَاعِدٌ القُرْفُصَاءَ، فَلَمَّا رَأَيْتُ رَسُولَ اللَّهِ صلى الله عليه وسلم مُتَخَشِّعًا فِي الجُلْسَةِ أَرْعَدْتُ مِنَ الفَرَقِ، فَقَالَ جَلِيسُهُ: يَا رَسُولَ اللَّهِ، أَرْعَدَتِ المسكينةُ، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم وَلَمْ يَنْظُرْ إِلَيَّ وَأَنَا عِنْدَ ظَهْرِهِ: يَا مَسْكِينَةُ عَلَيْكِ السَّكِينَةُ، فَلَمَّا قَالَهَا رَسُولُ اللَّهِ صلى الله عليه وسلم أَذْهَبَ اللَّهُ مَا كَانَ أَدْخَلَ قَلْبِي مِنَ الرُّعْبِ، وَتَقَدَّمَ صَاحِبِي أَوَّلَ رَجُلٍ، فَبَايَعَهُ عَلَى الإِسْلَامِ عَلَيْهِ وَعَلَى قَوْمِهِ، ثُمَّ قَالَ: يَا رَسُولَ اللَّهِ، اكْتُبْ بَيْنَنَا وَبَيْنَ بَنِي تَمِيمٍ بِالدَّهْنَاءِ لايجاوزها إِلَيْنَا مِنْهُمْ إِلَّا مُسَافِرٌ أَوْ مُجَاوِرٌ، فقال: يَا غُلَامُ، اكْتُبْ لَهُ بِالدَّهْنَاءِ؛ فَلَمَّا رَأَيْتُهُ أَمَرَ لَهُ بأن يَكْتُبَ لَهُ بِهَا شَخْصٌ بِي وَهِيَ وَطَنِي وَدَارِي، فقلت: يَا رَسُولَ اللَّهِ، إِنَّهُ لَمْ يَسْأَلْكَ السُّوِيَّةَ مِنَ الأَرْضِ إِذْ سَأَلَكَ، إِنَّمَا هَذِهِ الدَّهْنَاءُ عِنْدَكَ مُقَيَّدُ الجَمَلِ وَمَرْعَى الغَنَمِ، وَنِسَاءُ تَمِيمٍ وَأَبْنَاؤُهَا وَرَاءَ ذَلِكَ! فَقَالَ: أَمْسِكْ يَا غُلَامُ، صَدَقَتِ المَسْكِينَةُ، المُسْلِمُ أَخُو المُسْلِمِ، يَسْعَهُمَا الْمَاءِ وَالشَّجَرُ، وَيَتَعَاوَنَانِ عَلَى الفَتَّانِ. فَلَمَّا رَأَى حُرَيْثٌ أَنَّ قَدْ حِيلَ دُونَ كِتَابِهِ ضَرَبَ بِإِحْدَى يَدَيْهِ عَلَى الأُخْرَى، وَقَالَ: كُنْتُ أَنَا وَأَنْتَ كَمَا قِيلَ: حَتْفَهَا تَحْمِلُ ضأن بِأَظْلَافِهَا، فَقُلْتُ: أَمَا وَاللَّهِ إن كُنْتُ لَدَلِيلًا فِي الظُّلْمَاءِ، جَوَادًا بِذِي الرَّحِلِ، عَفِيفًا عَنْ الرَّفِيقَةِ، حَتَّى قَدِمْتُ عَلَى رَسُولِ اللَّهِ صلى الله عليه وسلم وَلَكِنْ لَا تَلُمْنِي عَلَى حَظِّي إِذْ سَأَلْتَ حَظَّكَ، فَقَالَ: وَمَا حَظُّكَ فِي الدَّهْنَاءِ لَا أَبَا لَكَ؟ فَقُلْتُ: مُقَيَّدُ جَمَلِي تَسْأَلُهُ لِجَمَلِ امْرَأَتِكَ؟ فَقَالَ: لَا جَرَمَ إِنِّي أَشْهَدُ رَسُولَ اللَّهِ أَنِّي لَكَ أَخٌ مَا حَيِيتُ إِذْ أَثْنَيْتَ هَذَا عَلَيَّ عِنْدَهُ، فَقُلْتُ: إِذْ بَدَأْتَهَا فَلَنْ أَضِيعَهَا، فَقَالَ رَسُولُ اللَّهِ صلى الله عليه وسلم أَيْلَامُ ابْنُ ذه أَنْ يَفْصِلَ الخُطَّةَ وَيَنْتَصِرَ مِنْ وَرَاءِ الحُجُرَةِ؟ فَبَكَيْتُ ثُمَّ قُلْتُ: قَدْ وَاللَّهِ كُنْتُ ولدته يَا رَسُولَ اللَّهِ حَازِمًا، فَقَاتَلَ مَعَكَ يَوْمَ الرَّبَذَةِ، ثُمَّ ذَهَبَ يُمِيرُنِي مِنْ خَيْبَرَ، فَأَصَابَتْهُ حماها وَتَرَكَ عَلَيَّ النِّسَاءِ، فَقَالَ: وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، لَوْ لَمْ تَكُونِي مَسْكِينَةً لَجَرَرْنَاكِ الْيَوْمَ عَلَى وَجْهِكَ، أَوْ لَجَرَرْتُ عَلَى وَجْهِكَ، -شَكَّ عَبْدُ اللَّهِ- أَيُغْلِبُ أَحِيدُكُمْ أَنْ يُصَاحِبَ صويحبه فِي الدُّنْيَا مَعْرُوفًا فَإِذَا حَالَ بَيْنَهُ وَبَيْنَهُ مَنْ هُوَ أَوْلَىٰ بِهِ مِنْهُ اسْتَرْجَعَ؟ ثُمَّ قَالَ: رَبِّ أَنِسْنِي مَا أَمْضَيْتُ، وَأَعِنِّي عَلَى مَا أَبْقَيْتُ، وَالَّذِي نَفْسُ مُحَمَّدٍ بِيَدِهِ، أَنْ أَحِيدَكُمْ لِيَبْكِي فَيَسْتَعْبِرُ إِلَيْهِ صويحبه، فَيَا عِبَادَ اللَّهِ لَا تُعَذِّبُوا إِخْوَانَكُمْ. وَكَتَبَ لَهَا فِي قِطْعَةٍ مِنْ أَدِيمٍ أَحْمَرَ لِقَيْلَةَ وللنسوة بَنَاتِ قَيْلَةَ: أَنْ لَا يَظْلِمْنَ حَقًّا، وَلَا يُكْرَهْنَ عَلَى مَنْكِحٍ، وَكُلُّ مُؤْمِنٍ مُسْلِمٍ لَهُنَّ نَصِيرٌ، أحسن وَلَا تسئن."],"takhrij":"حسن: رواه ابن سعد (262) والطبراني في الكبير (15/7-10) بهذا الطول، واختصره أبو داود (3070، 4847) والترمذي (2814) والبيهقي (6/150) كلهم من حديث عبد الله بن حسان، فذكره.","grade":"حسن","chapter_ar":"وفد بكر بن وائل","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Hasan: Narrated by Ibn Saʿd (1/317–320) and al-Ṭabarānī in al-Kabīr (15/7–10) at this length. Abū Dāwūd (3070, 4847), al-Tirmidhī (2814), and al-Bayhaqī (6/150) narrated it in abbreviated form. Some portions of the report contain unusual wording.","chapter_en":"The Delegation of Bakr ibn Wā’il","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في الوفود التي لا يُعرف تاريخها","group_en":"A Collection of Reports Concerning Delegations Whose Dates Are Unknown","part_no":48,"group_no":40,"chapter_no":1,"content":{"translation":{"en":["ʿAbdullāh ibn Ḥassān, a man from Banū Kaʿb of Balʿanbar, reported that his two grandmothers, Ṣafiyyah bint ʿUlayyah and Duḥaybah bint ʿUlaybah, narrated to him the account of Qaylah bint Makhramah. They had both been raised in her care, and Qaylah was the maternal grandmother of their father. Qaylah had been married to Ḥabīb ibn Azhar, a man from Banū Jināb, and she bore him daughters. He died at the beginning of Islām. The girls’ paternal uncle, Athwāb ibn Azhar, then took them away from her. So she set out seeking companionship to reach the Messenger of Allah ﷺ in the early period of Islām. One of the young girls, Ḥudaybāʾ, began to cry, and Qaylah took her along. The girl was wearing a woolen wrap. While they were making the camel move quickly, a rabbit suddenly sprang out. Ḥudaybāʾ said: “By Allah, your standing will always remain above the standing of Athwāb in this affair!” Then a fox crossed their path, and she called it by a name that ʿAbdullāh ibn Ḥassān later forgot, and she said about it the same as she had said about the rabbit. While they were again urging the camel forward, it suddenly knelt down and began trembling. Ḥudaybāʾ said: “By the trust, Athwāb’s seizure has overtaken you!” Qaylah said: “I was forced to rely upon her, so I said, ‘Woe to you, what should I do?’” She replied: “Turn your garments inside out, roll your back toward your belly, and overturn the saddle-cloths of your camel.” The girl removed her woolen wrap and turned it inside out, then rolled herself over. When Qaylah did what she had been told, the camel shook itself, stood up, passed wind, and urinated. The girl said: “Put your things back as they were.” Qaylah did so, and they continued quickly. Suddenly Athwāb was running behind them with a drawn sword. They sought refuge in a large enclosure. Qaylah said that she could still picture the place: the camel was brought to the middle section of the tent like a docile camel, and she rushed inside. Athwāb caught up with her and struck with the sword, its edge cutting part of the hair from her head. He said: “Give me my brother’s daughter, O foul woman!” She handed the girl to him, and he placed her upon his shoulder and took her away. The girl knew him better than anyone in the household. Qaylah then went to a sister of hers who was married among Banū Shaybān, still seeking someone who could accompany her to the Messenger of Allah ﷺ. One night while she was staying with her sister and they thought she was asleep, her sister’s husband returned from an evening gathering and said: “By your father, I have found for Qaylah a trustworthy companion.” Her sister asked: “Who is he?” He replied: “Ḥurayth ibn Ḥassān al-Shaybānī. He will leave in the morning as the delegate of Bakr ibn Wā’il to the Messenger of Allah ﷺ.” Qaylah heard what they said, went early to her camel, prepared it, and searched for him. She found him not far away and asked to accompany him. He replied: “Yes, with honor.” Their riding animals were already kneeling and prepared, so she set out with him. She found him to be a trustworthy companion until they reached the Messenger of Allah ﷺ. He was leading the people in the dawn prayer. The prayer had begun just as daybreak split, while the stars were still densely visible in the sky, and because of the darkness the men could scarcely recognize one another. Qaylah joined the row with the men, for she was a woman only recently removed from the customs of Jāhiliyyah. The man beside her asked: “Are you a woman or a man?” She replied: “No, rather I am a woman.” He said: “You have nearly caused me temptation. Pray with the women behind you.” There was a row of women near the chambers that she had not noticed when she first entered, so she joined them. When the sun had risen, she moved closer. Whenever she saw a man of impressive appearance, her gaze would rise toward him, thinking perhaps that the Messenger of Allah ﷺ would stand out above the people. Eventually, after the sun had risen higher, a man came and said: “Peace be upon you, O Messenger of Allah.” The Messenger of Allah ﷺ replied: “And upon you be peace, and the mercy of Allah, and His blessings.” Qaylah described the Prophet ﷺ as wearing two worn garments that had once been dyed with saffron but whose color had faded. He had with him a stripped palm branch with only two leaves remaining at its top, and he was sitting with his knees drawn up. When she saw the Messenger of Allah ﷺ sitting with such humility, she began trembling with fear. The man sitting beside him said: “O Messenger of Allah, the poor woman is trembling.” Without turning to look at her, while she was behind him, the Messenger of Allah ﷺ said: “O poor woman, be calm.” When the Messenger of Allah ﷺ said this, Allah removed the terror that had entered her heart. Her companion then stepped forward first and pledged allegiance to the Messenger of Allah ﷺ upon Islām, both for himself and on behalf of his people. Then he said: “O Messenger of Allah, write an agreement between us and Banū Tamīm regarding al-Dahnāʾ, so that none of them may cross it toward us except as a traveler or someone temporarily residing.” The Prophet ﷺ said: “O young man, write for him concerning al-Dahnāʾ.” When Qaylah saw that he had ordered the land to be written over to him, she became alarmed, because it was her homeland and home territory. She said: “O Messenger of Allah, he has not asked you for a fair portion of land. This al-Dahnāʾ may seem to you merely a place where a camel is tethered and sheep are pastured, but beyond it are the women and children of Tamīm!” The Prophet ﷺ said: “Stop, O young man. The poor woman has spoken the truth. The Muslim is the brother of the Muslim. Water and vegetation are sufficient for them both, and they cooperate against those who cause temptation and misguidance.” When Ḥurayth saw that the written grant had been prevented, he struck one hand against the other and said: “You and I have become like the saying: ‘The sheep carries its own death upon its hooves.’” Qaylah said: “By Allah, you were indeed an excellent guide in the darkness, generous with your mount, and honorable toward your female companion until you brought me to the Messenger of Allah ﷺ. But do not blame me for seeking my own right when you sought yours.” He said: “What right do you have in al-Dahnāʾ, may you be bereft?” She replied: “The place where my camel is tethered—you seek it for your wife’s camel?” He said: “Very well. I call the Messenger of Allah ﷺ to witness that I will be your brother for as long as I live, since you have praised me before him in this way.” She replied: “Since you have begun it, I will not waste that bond.” The Messenger of Allah ﷺ then said words concerning her son and her grief. Qaylah wept and said: “By Allah, O Messenger of Allah, I had raised him to be a resolute man. He fought with you on the day of al-Rabadhah, then went to bring me provisions from Khaybar. Its fever afflicted him, and he left the women in my care.” The Prophet ﷺ said: “By the One in Whose hand is the soul of Muḥammad, were you not a poor woman, we would have dragged you today upon your face—or I would have dragged you upon your face.” ʿAbdullāh was uncertain about the exact wording. He then said: “Is one of you incapable of living honorably with his companion in this world, then when someone with a greater claim over him comes between them, saying: ‘Indeed we belong to Allah, and to Him we return’?” Then he said: “My Lord, console me regarding what You have taken away, and aid me regarding what You have left. By the One in Whose hand is the soul of Muḥammad, one of you may weep until his companion is moved to tears by his weeping. So, servants of Allah, do not torment your brothers.” He then wrote for Qaylah and the women who were the daughters of Qaylah upon a piece of red leather: “They are not to be wronged in any right, nor compelled into marriage. Every believing Muslim is their supporter. Do good and do not do evil.”"]},"buhuth":{"en":["His saying “they were making their camels move quickly” means that they were urging them into rapid travel. The Arabic expression rataka yartiku ratkan wa-ratakānan means to move quickly.","His saying “al-futtān” is transmitted with either ḍammah or fatḥah on the letter fāʾ. With ḍammah, it is the plural of fātin and means those who mislead and tempt people, so each Muslim assists the other against them. With fatḥah, it refers to Satan."]}},"tuhfa":{},"voc":["seerah",1017],"full":1,"dr":1,"tks":"حسن: رواه ابن سعد (262)، والطبراني في الكبير (15/7-10) بهذا الطول، واختصره أبو داود (3070، 4847)، والترمذي (2814)، والبيهقي (6/150). وفي بعض فقراته غرابة."},{"num":9788,"demo":false,"sanad":"","matn":["عَنْ لَقيط بن صَبرة قَالَ: كُنْتُ وَافِدَ بَنِي المُنْتَفِق، أَوْ فِي وَفْدِ بَنِي الْمُنْتَفِقِ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، ، قَالَ: فَلَمَّا قَدِمْنَا عَلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمْ نُصَادِفْهُ فِي مَنْزِلِهِ، وَصَادَفْنَا عَائِشَةَ أُمَّ الْمُؤْمِنِينَ. قَالَ: فَأَمَرَتْ لَنَا بِخَزِيرَةٍ فَصُنِعَت لَنَا. قَالَ: وَأُتِينَا بِقِنَاعٍ، وَلَمْ يَقُلْ قُتَيْبَةُ: الْقِنَاعَ، وَالْقِنَاعُ الطَّبَقُ فِيهِ تَمْرٌ، ثُمَّ جَاءَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَقَالَ: هَلْ أَصَبْتُمْ شَيْئًا أَوْ أُمِرَ لَكُمْ بشيء؟ قَالَ: قُلْنَا: نَعَمْ يَا رَسُولَ اللَّهِ. قَالَ: فَبَيْنَا نَحْنُ مَعَ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ جُلُوسٌ إِذْ دَفَعَ الرَّاعِي غَنَمَهُ إِلَى الْمُرَاحِ وَمَعَهُ سَخْلَةٌ تَيْعِرُ، فَقَالَ: مَا وَلَّدْتَ يَا فُلاَنُ قَالَ: بَهْمَةً، قَالَ: فَاذْبَحْ لَنَا مَكَانَهَا شَاةً ثُمَّ قَالَ: لاَ تحسِبَنَّ -وَلَمْ يَقُلْ: لاَ تحسَبَنَّ- أَنَّا مِنْ أَجْلِكَ ذَبَحْنَاهَا، لَنَا غَنَمٌ مِائَةٌ لاَ نُرِيدُ أَنْ تَزِيدَ، فَإِذَا وَلَّدَ الرَّاعِي بَهْمَةً ذَبَحْنَا مَكَانَهَا شَاةً قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ لِي امْرَأَةً، وَإِنَّ فِي لِسَانِهَا شَيْئًا –يَعْنِي: الْبَذَاءَ- قَالَ: فطلِّقْها إِذًا قَالَ: قُلْتُ: يَا رَسُولَ اللَّهِ، إِنَّ لَهَا صُحْبَةً وَلِي مِنْهَا وَلَدٌ. قَالَ: فَمُرْهَا –يَقُولُ: عِظْهَا- فَإِنْ يَكُ فِيهَا خَيْرٌ فَسَتَفْعَلُ، وَلاَ تَضْرِبْ ظَعِينَتَكَ كَضَرْبِكَ أُمَيَّتَكَ فَقُلْتُ: يَا رَسُولَ اللَّهِ، أَخْبِرْنِي عَنِ الْوُضُوءِ، قَالَ: أَسْبِغِ الْوُضُوءَ، وخلِّل بَيْنَ الاصابع، وَبَالِغْ فِي الاِسْتِنْشَاقِ إلاَّ أَنْ تَكُونَ صَائِمًا."],"takhrij":"صحيح: رواه أبو داود (142) مُطوَّلاً واللفظ له، والترمذي (38)، والنسائي (114)، وابن ماجه (407، 448) مُختصراً. كلهم من حديث إسماعيل بن كثير أبي هاشم المكي، عن عاصم بن لَقيط به.","grade":"صحيح","chapter_ar":"وفد بني المنتفق","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated at length by Abū Dāwūd (142), whose wording is cited here, as well as by al-Tirmidhī (38), al-Nasā’ī (114), and Ibn Mājah (407).","chapter_en":"The Delegation of Banū al-Muntafiq","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في الوفود التي لا يُعرف تاريخها","group_en":"A Collection of Reports Concerning Delegations Whose Dates Are Unknown","part_no":48,"group_no":40,"chapter_no":3,"content":{"translation":{"en":["Laqīṭ ibn Ṣabirah said: I was the delegate of Banū al-Muntafiq—or was among the delegation of Banū al-Muntafiq—to the Messenger of Allah ﷺ. When we arrived, we did not find the Messenger of Allah ﷺ at his home, but we found ʿĀ’ishah, the Mother of the Believers. She ordered that khazīrah be prepared for us, and it was prepared. We were also brought a qināʿ—Qutaybah did not say “the qināʿ”—which is a platter containing dates. The Messenger of Allah ﷺ then arrived and asked: “Have you been given anything to eat, or has anything been ordered for you?” We replied: “Yes, O Messenger of Allah.” While we were sitting with the Messenger of Allah ﷺ, the shepherd brought the sheep into their resting place, accompanied by a young lamb that was bleating. He ﷺ asked: “What did it give birth to, so-and-so?” He replied: “A ewe lamb.” He ﷺ said: “Then slaughter a sheep for us in its place.” He then said: “Do not suppose that we slaughtered it specifically because of you. We own one hundred sheep and do not want their number to increase. Whenever the shepherd has a ewe lamb born, we slaughter a sheep in its place.” I said: “O Messenger of Allah, I have a wife whose tongue contains something”—meaning foul or abusive speech. He said: “Then divorce her.” I said: “O Messenger of Allah, she has been my companion for a long time, and I have a child by her.” He said: “Then instruct her”—meaning admonish her—“for if there is goodness in her, she will comply. Do not beat your wife as you would beat your slave woman.” I then said: “O Messenger of Allah, tell me about ablution.” He said: “Perform ablution thoroughly, pass your fingers between your fingers and toes, and inhale water deeply into the nose unless you are fasting.”"]},"buhuth":{"en":["In some narrations, it states:","“When you perform ablution, rinse your mouth.”","Al-Tirmidhī said: “good authentic hadith.”"]}},"tuhfa":{},"voc":["seerah",1019],"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (142) مطولا، واللفظ له، والترمذي (38)، والنسائي (114)، وابن ماجه (407)."},{"num":9789,"demo":false,"sanad":"","matn":["عَنْ مُطَرِّفٍ، قَالَ: قَالَ أَبِي: انْطَلَقْتُ فِي وَفْدِ بَنِي عَامِرٍ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، فَقُلْنَا: أَنْتَ سَيِّدُنَا. فَقَالَ: السَّيِّدُ اللَّهُ تَبَارَكَ وَتَعَالَى. قُلْنَا: وَأَفْضَلُنَا فَضْلاً، وَأَعْظَمُنَا طَوْلاً. فَقَالَ: قُولُوا بِقَوْلِكُمْ أَوْ بَعْضِ قَوْلِكُمْ، وَلاَ يَسْتَجْرِيَنَّكُمُ الشَّيْطَانُ."],"takhrij":"صحيح: رواه أبو داود (4806) عن مسدّد، حدّثنا بشر -يعني ابن المفضَّل-، حدّثنا أبو سلمة، سعيد بن يزيد، عن أبي نضرة، عن مطرف، فذكره.","grade":"صحيح","chapter_ar":"وفد بني عامر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (4806). It was also narrated by Imām Aḥmad (16311) and al-Bayhaqī in al-Madkhal (537), with the addition: “and the splendid serving bowl.” At its conclusion, he narrated: “Do not allow him to entice you.”","chapter_en":"The Delegation of Banū ʿĀmir","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع في الوفود التي لا يُعرف تاريخها","group_en":"A Collection of Reports Concerning Delegations Whose Dates Are Unknown","part_no":48,"group_no":40,"chapter_no":4,"content":{"translation":{"en":["Muṭarrif ibn ʿAbdullāh ibn al-Shikhkhīr reported that his father said: I went as part of the delegation of Banū ʿĀmir to the Messenger of Allah ﷺ. We said: “You are our master.” He replied: “The Master is Allah, Blessed and Exalted.” We said: “And you are the most excellent of us in virtue and the greatest of us in eminence.” He said: “Say what you ordinarily say, or part of it, and do not allow Satan to draw you along.”"]},"buhuth":{"en":["Concerning the phrase “the splendid serving bowl,” Ibn al-Athīr said in al-Nihāyah:","“The Arabs used to call a generous chief who fed others a ‘serving bowl,’ because he would set it out and feed people from it, so he was named after it. ‘Al-gharrāʾ’ means white, indicating that it was filled with fat and grease.”","As for the expression “yastajriyannakum,” with the letter rāʾ doubled, it is derived from the word meaning “to drag.” Al-Sindī said that this wording is authentic."]}},"tuhfa":{},"voc":["seerah",1020],"full":1,"dr":1,"tks":"صحيح: رواه أبو داود (4806). ورواه الإمام أحمد (16311)، والبيهقي في المدخل (537)، وزاد فيه: «والجفنة الغراء». وقال في آخره: «ولا يستهوينكم»."},{"num":9790,"demo":false,"sanad":"","matn":["عَنْ أَنَسٍ بْنِ مَالِكٍ أَنَّ نَبِيَّ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى كِسْرَى، وَإِلَى قَيْصَرَ، وَإِلَى النَّجَاشِيِّ، وَإِلَى كُلِّ جَبَّارٍ، يَدْعُوهُمْ إِلَى اللَّهِ تَعَالَى، وَلَيْسَ بِالنَّجَاشِيِّ الَّذِي صَلَّى عَلَيْهِ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ. . وَزَادَ فِي رِوَايَةِ: وأكيدر دومة."],"takhrij":"صحيح: رواه مسلم في الجهاد والسير (1774: 75) عن يوسف بن حماد المعنيّ، حدثنا عبد الأعلى، عن سعيد، عن قتادة، عن أنس، فذكره. ورواه ابن حبان (653-654) من طريقين آخرين عن قتادة عنه، وزاد: \"أكيدر دومة\"، وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كتابة النبي ﷺ إلى الرؤساء والملوك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Muslim (1774:75) and Ibn Ḥibbān (653–654), who added: “Ukaydir of Dūmah.” Its chain of transmission is authentic.","chapter_en":"The Prophet ﷺ Writing to Rulers and Kings","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik reported that the Prophet of Allah ﷺ wrote to Khosrow, Caesar, the Negus, and every powerful ruler, inviting them to Allah Most High. This was not the same Negus over whom the Prophet ﷺ performed the funeral prayer. Another narration adds: “And Ukaydir of Dūmah.”"]},"buhuth":{"en":["The title “Negus” was given to every king who ruled Abyssinia. As for al-Aṣḥamah, the ruler who received Jaʿfar and his companions, he embraced Islam, and the Prophet ﷺ performed the funeral prayer for him. He died before the Conquest of Makkah, in the eighth year. The letters that the Messenger of Allah ﷺ wrote to the kings, inviting them to Islam, were sent after the death of the Muslim Negus over whom he had performed the funeral prayer. The text of the Prophet’s ﷺ letter to the Negus will appear later."]},"intro_majmu":{"ar":["ذكر الواقدي أن ذلك كان في آخر سنة ست، في ذي الحجة، بعد عمرة الحديبية.","وقال محمد بن إسحاق: كان ذلك ما بين الحديبية ووفاته عليه السلام.","أقول: لا خلاف بين أهل العلم أن بدء ذلك كان قبل فتح مكة؛ لقول أبي سفيان لهرقل حين سأله: هل يغدر؟ فقال: لا، ونحن منه في مدة لا ندري ما هو صانع فيها. وكتاب النبي ﷺ إلى هرقل كان قبل فتح مكة.","١٣٢"],"en":["Al-Wāqidī mentioned that this took place at the end of the sixth year, in Dhū al-Ḥijjah, following the ʿUmrah of al-Ḥudaybiyyah.","Muḥammad ibn Isḥāq said: This occurred sometime between al-Ḥudaybiyyah and the Prophet’s ﷺ death.","I say: There is no disagreement among the scholars that this began before the Conquest of Makkah. This is established by Abū Sufyān’s answer to Heraclius when he asked him, “Does he act treacherously?” Abū Sufyān replied, “No. We currently have a truce with him, and we do not know what he will do during it.” The Prophet’s ﷺ letter to Heraclius was sent before the Conquest of Makkah.","132"]}},"tuhfa":{},"voc":["seerah",651],"full":1,"dr":1,"tks":"صحيح: رواه مسلم (1774: 75)، ورواه ابن حبان (653-654)، وزاد: «أكيدر دومة»، وإسناده صحيح."},{"num":9791,"demo":false,"sanad":"","matn":["عَنْ أنس قَالَ: لَمَّا أَرَادَ النَّبِيُّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَكْتُبَ إِلَى الرُّومِ قِيلَ لَهُ: إِنَّهُمْ لاَ يقرؤون كِتَابًا إِلاَّ أَنْ يَكُونَ مَخْتُومًا، فَاتَّخَذَ خَاتَمًا مِنْ فِضَّةٍ، فَكَأَنِّي أَنْظُرُ إِلَى بَيَاضِهِ فِي يَدِهِ، وَنَقَشَ فِيهِ: مُحَمَّدٌ رَسُولُ اللَّهِ.","وفي رواية: أراد أن يكتب إلى العجم.","وفي رواية ثالثة: أراد أن يكتب إلى كسرى وقيصر والنجاشي."],"takhrij":"متفق عليه: رواه البخاري في الجهاد والسير (2938) ومسلم في اللباس (2091: 56) كلاهما من طريق شعبة، عن قتادة، عن أنس، فذكره.","grade":"متفق عليه","chapter_ar":"باب كتابة النبي ﷺ إلى الرؤساء والملوك","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2938) and Muslim (2091:56). Muslim narrated the second wording in (2091:57) and the third wording in (2091:58).","chapter_en":"The Prophet ﷺ Writing to Rulers and Kings","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":1,"content":{"translation":{"en":["Anas ibn Mālik said: When the Prophet ﷺ intended to write to the Romans, he was told: “They do not read a letter unless it is sealed.” He therefore had a silver signet ring made. It is as though I can still see its whiteness upon his hand. Engraved upon it were the words: “Muḥammad, the Messenger of Allah.” Another narration states: “He intended to write to the non-Arabs.” A third narration states: “He intended to write to Khosrow, Caesar, and the Negus.”"]}},"tuhfa":{},"voc":["seerah",652],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (2938)، ومسلم (2091: 56). ورواه مسلم (2091: 57) باللفظ الثاني، ورواه مسلم (2091: 58) باللفظ الثالث."},{"num":9792,"demo":false,"sanad":"","matn":["أَنَّ أَبَا سُفْيَانَ بْنَ حَرْبٍ، أَخْبَرَهُ أَنَّ هِرَقْلَ أَرْسَلَ إِلَيْهِ فِي رَكْبٍ مِنْ قُرَيْشٍ، ـ وَكَانُوا تُجَّارًا بِالشَّأْمِ ـ فِي الْمُدَّةِ الَّتِي كَانَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ مَادَّ فِيهَا أَبَا سُفْيَانَ وَكُفَّارَ قُرَيْشٍ، فَأَتَوْهُ وَهُمْ بِإِيلِيَاءَ، فَدَعَاهُمْ فِي مَجْلِسِهِ، وَحَوْلَهُ عُظَمَاءُ الرُّومِ، ثُمَّ دَعَاهُمْ وَدَعَا بِتَرْجُمَانِهِ، فَقَالَ: أَيُّكُمْ أَقْرَبُ نَسَبًا بِهَذَا الرَّجُلِ الَّذِي يَزْعُمُ أَنَّهُ نَبِيٌّ؟ فَقَالَ أَبُو سُفْيَانَ: فَقُلْتُ: أَنَا أَقْرَبُهُمْ نَسَبًا. فَقَالَ: أَدْنُوهُ مِنِّي، وَقَرِّبُوا أَصْحَابَهُ، فَاجْعَلُوهُمْ عِنْدَ ظَهْرِهِ. ثُمَّ قَالَ لِتَرْجُمَانِهِ: قُلْ لَهُمْ: إِنِّي سَائِلٌ هَذَا عَنْ هَذَا الرَّجُلِ، فَإِنْ كَذَبَنِي فَكَذِّبُوهُ. فَوَاللَّهِ لَوْلاَ الْحَيَاءُ مِنْ أَنْ يَأْثِرُوا عَلَىَّ كَذِبًا لَكَذَبْتُ عَنْهُ، ثُمَّ كَانَ أَوَّلَ مَا سَأَلَنِي عَنْهُ أَنْ قَالَ: كَيْفَ نَسَبُهُ فِيكُمْ؟ قُلْتُ: هُوَ فِينَا ذُو نَسَبٍ. قَالَ: فَهَلْ قَالَ هَذَا الْقَوْلَ مِنْكُمْ أَحَدٌ قَطُّ قَبْلَهُ؟ قُلْتُ: لاَ. قَالَ: فَهَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ؟ قُلْتُ: لاَ. قَالَ: فَأَشْرَافُ النَّاسِ يَتَّبِعُونَهُ أَمْ ضُعَفَاؤُهُمْ؟ فَقُلْتُ: بَلْ ضُعَفَاؤُهُمْ. قَالَ: أَيَزِيدُونَ أَمْ يَنْقُصُونَ؟ قُلْتُ: بَلْ يَزِيدُونَ. قَالَ: فَهَلْ يَرْتَدُّ أَحَدٌ مِنْهُمْ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ؟ قُلْتُ: لاَ. قَالَ: فَهَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ؟ قُلْتُ: لاَ. قَالَ: فَهَلْ يَغْدِرُ؟ قُلْتُ: لاَ، وَنَحْنُ مِنْهُ فِي مُدَّةٍ لاَ نَدْرِي مَا هُوَ فَاعِلٌ فِيهَا. قَالَ: وَلَمْ تُمْكِنِّي كَلِمَةٌ أُدْخِلُ فِيهَا شَيْئًا غَيْرُ هَذِهِ الْكَلِمَةِ. قَالَ: فَهَلْ قَاتَلْتُمُوهُ؟ قُلْتُ: نَعَمْ. قَالَ: فَكَيْفَ كَانَ قِتَالُكُمْ إِيَّاهُ؟ قُلْتُ: الْحَرْبُ بَيْنَنَا وَبَيْنَهُ سِجَالٌ، يَنَالُ مِنَّا وَنَنَالُ مِنْهُ. قَالَ: مَاذَا يَأْمُرُكُمْ؟ قُلْتُ: يَقُولُ: اعْبُدُوا اللَّهَ وَحْدَهُ، وَلاَ تُشْرِكُوا بِهِ شَيْئًا، وَاتْرُكُوا مَا يَقُولُ آبَاؤُكُمْ، وَيَأْمُرُنَا بِالصَّلاَةِ وَالصِّدْقِ وَالْعَفَافِ وَالصِّلَةِ. فَقَالَ لِلتَّرْجُمَانِ: قُلْ لَهُ: سَأَلْتُكَ عَنْ نَسَبِهِ، فَذَكَرْتَ أَنَّهُ فِيكُمْ ذُو نَسَبٍ، فَكَذَلِكَ الرُّسُلُ تُبْعَثُ فِي نَسَبِ قَوْمِهَا، وَسَأَلْتُكَ هَلْ قَالَ أَحَدٌ مِنْكُمْ هَذَا الْقَوْلَ، فَذَكَرْتَ أَنْ لاَ، فَقُلْتُ: لَوْ كَانَ أَحَدٌ قَالَ هَذَا الْقَوْلَ قَبْلَهُ لَقُلْتُ رَجُلٌ يَأْتَسِي بِقَوْلٍ قِيلَ قَبْلَهُ، وَسَأَلْتُكَ هَلْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ، فَذَكَرْتَ أَنْ لاَ، قُلْتُ: فَلَوْ كَانَ مِنْ آبَائِهِ مِنْ مَلِكٍ قُلْتُ: رَجُلٌ يَطْلُبُ مُلْكَ أَبِيهِ، وَسَأَلْتُكَ هَلْ كُنْتُمْ تَتَّهِمُونَهُ بِالْكَذِبِ قَبْلَ أَنْ يَقُولَ مَا قَالَ، فَذَكَرْتَ أَنْ لاَ، فَقَدْ أَعْرِفُ أَنَّهُ لَمْ يَكُنْ لِيَذَرَ الْكَذِبَ عَلَى النَّاسِ وَيَكْذِبَ عَلَى اللَّهِ، وَسَأَلْتُكَ أَشْرَافُ النَّاسِ اتَّبَعُوهُ أَمْ ضُعَفَاؤُهُمْ، فَذَكَرْتَ أَنَّ ضُعَفَاءَهُمُ اتَّبَعُوهُ، وَهُمْ أَتْبَاعُ الرُّسُلِ، وَسَأَلْتُكَ أَيَزِيدُونَ أَمْ يَنْقُصُونَ، فَذَكَرْتَ أَنَّهُمْ يَزِيدُونَ، وَكَذَلِكَ أَمْرُ الإِيمَانِ حَتَّى يَتِمَّ، وَسَأَلْتُكَ أَيَرْتَدُّ أَحَدٌ سَخْطَةً لِدِينِهِ بَعْدَ أَنْ يَدْخُلَ فِيهِ، فَذَكَرْتَ أَنْ لاَ، وَكَذَلِكَ الإِيمَانُ حِينَ تُخَالِطُ بَشَاشَتُهُ الْقُلُوبَ، وَسَأَلْتُكَ هَلْ يَغْدِرُ، فَذَكَرْتَ أَنْ لاَ، وَكَذَلِكَ الرُّسُلُ لاَ تَغْدِرُ، وَسَأَلْتُكَ بِمَا يَأْمُرُكُمْ، فَذَكَرْتَ أَنَّهُ يَأْمُرُكُمْ أَنْ تَعْبُدُوا اللَّهَ، وَلاَ تُشْرِكُوا بِهِ شَيْئًا، وَيَنْهَاكُمْ عَنْ عِبَادَةِ الأَوْثَانِ، وَيَأْمُرُكُمْ بِالصَّلاَةِ وَالصِّدْقِ وَالْعَفَافِ. فَإِنْ كَانَ مَا تَقُولُ حَقًّا فَسَيَمْلِكُ مَوْضِعَ قَدَمَىَّ هَاتَيْنِ، وَقَدْ كُنْتُ أَعْلَمُ أَنَّهُ خَارِجٌ، لَمْ أَكُنْ أَظُنُّ أَنَّهُ مِنْكُمْ، فَلَوْ أَنِّي أَعْلَمُ أَنِّي أَخْلُصُ إِلَيْهِ لَتَجَشَّمْتُ لِقَاءَهُ، وَلَوْ كُنْتُ عِنْدَهُ لَغَسَلْتُ عَنْ قَدَمِهِ. ثُمَّ دَعَا بِكِتَابِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ الَّذِي بَعَثَ بِهِ دِحْيَةُ إِلَى عَظِيمِ بُصْرَى، فَدَفَعَهُ إِلَى هِرَقْلَ، فَقَرَأَهُ فَإِذَا فِيهِ: بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ. مِنْ مُحَمَّدٍ عَبْدِ اللَّهِ وَرَسُولِهِ إِلَى هِرَقْلَ عَظِيمِ الرُّومِ. سَلاَمٌ عَلَى مَنِ اتَّبَعَ الْهُدَى، أَمَّا بَعْدُ! فَإِنِّي أَدْعُوكَ بِدِعَايَةِ الإِسْلاَمِ، أَسْلِمْ تَسْلَمْ، يُؤْتِكَ اللَّهُ أَجْرَكَ مَرَّتَيْنِ، فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الأَرِيسِيِّينَ، وَ{يَا أَهْلَ الْكِتَابِ تَعَالَوْا إِلَى كَلِمَةٍ سَوَاءٍ بَيْنَنَا وَبَيْنَكُمْ أَنْ ﴿لاَ نَعْبُدَ إِلاَّ اللَّهَ وَلاَ نُشْرِكَ بِهِ شَيْئًا وَلاَ يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِنْ دُونِ اللَّهِ فَإِنْ تَوَلَّوْا فَقُولُوا اشْهَدُوا بِأَنَّا مُسْلِمُونَ﴾ [سورة آل عمران: 64]} قَالَ أَبُو سُفْيَانَ: فَلَمَّا قَالَ مَا قَالَ، وَفَرَغَ مِنْ قِرَاءَةِ الْكِتَابِ، كَثُرَ عِنْدَهُ الصَّخَبُ، وَارْتَفَعَتِ الأَصْوَاتُ، وَأُخْرِجْنَا، فَقُلْتُ لأَصْحَابِي حِينَ أُخْرِجْنَا: لَقَدْ أَمِرَ أَمْرُ ابْنِ أَبِي كَبْشَةَ، إِنَّهُ يَخَافُهُ مَلِكُ بَنِي الأَصْفَرِ. فَمَا زِلْتُ مُوقِنًا أَنَّهُ سَيَظْهَرُ حَتَّى أَدْخَلَ اللَّهُ عَلَىَّ الإِسْلاَمَ. وَكَانَ ابْنُ النَّاظُورِ صَاحِبُ إِيلِيَاءَ وَهِرَقْلَ سُقُفًّا عَلَى نَصَارَى الشَّأْمِ، يُحَدِّثُ أَنَّ هِرَقْلَ حِينَ قَدِمَ إِيلِيَاءَ أَصْبَحَ يَوْمًا خَبِيثَ النَّفْسِ، فَقَالَ بَعْضُ بَطَارِقَتِهِ قَدِ اسْتَنْكَرْنَا هَيْئَتَكَ. قَالَ ابْنُ النَّاظُورِ وَكَانَ هِرَقْلُ حَزَّاءً يَنْظُرُ فِي النُّجُومِ، فَقَالَ لَهُمْ حِينَ سَأَلُوهُ إِنِّي رَأَيْتُ اللَّيْلَةَ حِينَ نَظَرْتُ فِي النُّجُومِ مَلِكَ الْخِتَانِ قَدْ ظَهَرَ، فَمَنْ يَخْتَتِنُ مِنْ هَذِهِ الأُمَّةِ قَالُوا لَيْسَ يَخْتَتِنُ إِلاَّ الْيَهُودُ فَلاَ يُهِمَّنَّكَ شَأْنُهُمْ وَاكْتُبْ إِلَى مَدَايِنِ مُلْكِكَ، فَيَقْتُلُوا مَنْ فِيهِمْ مِنَ الْيَهُودِ. فَبَيْنَمَا هُمْ عَلَى أَمْرِهِمْ أُتِيَ هِرَقْلُ بِرَجُلٍ أَرْسَلَ بِهِ مَلِكُ غَسَّانَ، يُخْبِرُ عَنْ خَبَرِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ فَلَمَّا اسْتَخْبَرَهُ هِرَقْلُ قَالَ اذْهَبُوا فَانْظُرُوا أَمُخْتَتِنٌ هُوَ أَمْ لاَ. فَنَظَرُوا إِلَيْهِ، فَحَدَّثُوهُ أَنَّهُ مُخْتَتِنٌ، وَسَأَلَهُ عَنِ الْعَرَبِ فَقَالَ هُمْ يَخْتَتِنُونَ. فَقَالَ هِرَقْلُ هَذَا مَلِكُ هَذِهِ الأُمَّةِ قَدْ ظَهَرَ. ثُمَّ كَتَبَ هِرَقْلُ إِلَى صَاحِبٍ لَهُ بِرُومِيَةَ، وَكَانَ نَظِيرَهُ فِي الْعِلْمِ، وَسَارَ هِرَقْلُ إِلَى حِمْصَ، فَلَمْ يَرِمْ حِمْصَ حَتَّى أَتَاهُ كِتَابٌ مِنْ صَاحِبِهِ يُوَافِقُ رَأْىَ هِرَقْلَ عَلَى خُرُوجِ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَأَنَّهُ نَبِيٌّ، فَأَذِنَ هِرَقْلُ لِعُظَمَاءِ الرُّومِ فِي دَسْكَرَةٍ لَهُ بِحِمْصَ ثُمَّ أَمَرَ بِأَبْوَابِهَا فَغُلِّقَتْ، ثُمَّ اطَّلَعَ فَقَالَ يَا مَعْشَرَ الرُّومِ، هَلْ لَكُمْ فِي الْفَلاَحِ وَالرُّشْدِ وَأَنْ يَثْبُتَ مُلْكُكُمْ فَتُبَايِعُوا هَذَا النَّبِيَّ، فَحَاصُوا حَيْصَةَ حُمُرِ الْوَحْشِ إِلَى الأَبْوَابِ، فَوَجَدُوهَا قَدْ غُلِّقَتْ، فَلَمَّا رَأَى هِرَقْلُ نَفْرَتَهُمْ، وَأَيِسَ مِنَ الإِيمَانِ قَالَ رُدُّوهُمْ عَلَىَّ. وَقَالَ إِنِّي قُلْتُ مَقَالَتِي آنِفًا أَخْتَبِرُ بِهَا شِدَّتَكُمْ عَلَى دِينِكُمْ، فَقَدْ رَأَيْتُ. فَسَجَدُوا لَهُ وَرَضُوا عَنْهُ، فَكَانَ ذَلِكَ آخِرَ شَأْنِ هِرَقْلَ."],"takhrij":"متفق عليه: رواه البخاري في بدء الوحي (7) ومسلم في الجهاد والسير (1773: 74) كلاهما من طريق الزهري قال: أخبرني عبيد الله بن عبدالله بن عتبة بن مسعود، أن عبد الله بن عباس أخبره، أن أبا سفيان أخبره، فذكره، والسياق للبخاري.","grade":"متفق عليه","chapter_ar":"باب كتاب النبي ﷺ إلى هرقل عظيم الروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Agreed upon: Narrated by al-Bukhārī (7) and Muslim (1773:74). The wording cited here is that of al-Bukhārī.","chapter_en":"The Prophet’s ﷺ Letter to Heraclius, the Great Ruler of the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":2,"content":{"translation":{"en":["Abū Sufyān ibn Ḥarb reported that Heraclius sent for him while he was travelling with a group of Quraysh. They were merchants in Greater Syria during the period in which the Messenger of Allah ﷺ had concluded a truce with Abū Sufyān and the disbelievers of Quraysh. They came to Heraclius while he was in Aelia—Jerusalem. He summoned them to his court while the Roman dignitaries were gathered around him. He then called for his interpreter and asked: “Which of you is most closely related to the man who claims to be a prophet?” Abū Sufyān said: I replied, “I am the closest of them to him in lineage.” Heraclius said: “Bring him close to me, and bring his companions near and place them behind him.” He then told his interpreter: “Tell them that I am going to question this man about the one who claims to be a prophet. If he lies to me, they must expose his lie.” By Allah, had I not been ashamed that they would later report me as a liar, I would have lied about him. The first thing he asked me was: “What is his lineage among you?” I replied: “He possesses a noble lineage among us.” He asked: “Has anyone among you ever made this claim before him?” I replied: “No.” He asked: “Was any of his forefathers a king?” I replied: “No.” He asked: “Are the nobles of the people following him, or are their weak following him?” I replied: “Rather, their weak are following him.” He asked: “Are they increasing or decreasing?” I replied: “They are increasing.” He asked: “Does anyone among them renounce his religion out of displeasure with it after embracing it?” I replied: “No.” He asked: “Did you ever accuse him of lying before he made this claim?” I replied: “No.” He asked: “Does he act treacherously?” I replied: “No. We currently have a truce with him, and we do not know what he will do during it.” Abū Sufyān said: That was the only statement into which I was able to insert something against him. Heraclius asked: “Have you fought against him?” I replied: “Yes.” He asked: “How has your warfare against him been?” I replied: “The war between us and him has alternated; sometimes he gains the advantage over us, and sometimes we gain the advantage over him.” He asked: “What does he command you to do?” I replied: “He says: ‘Worship Allah alone and associate nothing with Him, and abandon what your forefathers used to say.’ He commands us to pray, give zakāh, speak truthfully, remain chaste, and maintain the ties of kinship.” Heraclius then said to his interpreter: “Tell him: I asked you about his lineage, and you stated that he possesses a noble lineage among you. In the same way, messengers are sent from the noble lineages of their people. “I asked whether anyone among you had made this claim before him, and you said no. I reasoned that had someone made this claim before him, I would have said that he was merely imitating a statement made before him. “I asked whether any of his forefathers had been a king, and you said no. Had one of his forefathers been a king, I would have said that he was seeking to reclaim the kingdom of his father. “I asked whether you had accused him of lying before he made this claim, and you said no. I therefore know that a man who would not lie about people would never lie about Allah. “I asked whether the nobles or the weak among the people followed him, and you stated that their weak followed him. Such are the followers of the messengers. “I asked whether their numbers were increasing or decreasing, and you stated that they were increasing. Such is the nature of faith until it reaches completion. “I asked whether anyone renounced his religion out of displeasure with it after embracing it, and you stated that no one did. Such is faith when its delight permeates the heart. “I asked whether he acted treacherously, and you stated that he did not. Likewise, the messengers do not act treacherously. “I asked what he commanded you to do, and you stated that he commanded you to worship Allah without associating anything with Him, that he forbade you from worshipping idols, and that he commanded you to pray, speak truthfully, and remain chaste. “If what you have said is true, he will soon rule the very ground beneath these two feet of mine. I knew that he was about to appear, but I did not think that he would be from among you. If I knew that I could reach him, I would endure every hardship to meet him. If I were with him, I would wash his feet.” Heraclius then called for the letter of the Messenger of Allah ﷺ that he had sent with Diḥyah to the ruler of Buṣrā, who had delivered it to Heraclius. Heraclius read it, and it contained: “In the name of Allah, the Most Compassionate, the Most Merciful. “From Muḥammad, the servant of Allah and His Messenger, to Heraclius, the great ruler of the Romans: “Peace be upon whoever follows the guidance. “To proceed: I invite you with the call of Islam. Embrace Islam and you will be safe. Allah will grant you your reward twice. If you turn away, you will bear the sin of the Arīsiyyīn. “ʿO People of the Scripture, come to a word that is equitable between us and you: that we worship none but Allah, associate nothing with Him, and do not take one another as lords besides Allah. But if they turn away, then say, “Bear witness that we are Muslims.”’” [Āl ʿImrān: 64] Abū Sufyān said: When Heraclius had finished speaking and the reading of the letter had ended, a great uproar arose around him and voices were raised. We were then expelled. When we were taken out, I said to my companions: “The affair of the son of Abū Kabshah has indeed become momentous! Even the king of the Romans fears him.” From that time onward, I remained certain that he would prevail until Allah brought Islam into my heart. Ibn al-Nāẓūr, the governor of Aelia, and Heraclius’s bishop over the Christians of Greater Syria, used to relate that when Heraclius arrived in Aelia, he awoke one morning in a disturbed state of mind. Some of his patriarchs said to him: “We find your appearance unusual today.” Ibn al-Nāẓūr said: Heraclius was skilled in astrology and used to examine the stars. When they questioned him, he said: “Last night, while examining the stars, I saw that the king of those who practise circumcision had appeared. Who among the people of this age practises circumcision?” They replied: “No one practises circumcision except the Jews. Do not let their affair trouble you. Write to the cities of your kingdom, ordering that the Jews living within them be killed.” While they were deliberating, a man was brought to Heraclius whom the king of Ghassān had sent with news concerning the Messenger of Allah ﷺ. After Heraclius questioned him, he ordered: “Go and examine whether he is circumcised.” They examined him and informed Heraclius that he was circumcised. Heraclius then asked him about the Arabs, and the man replied: “They practise circumcision.” Heraclius said: “The king of this nation has now appeared.” Heraclius then wrote to a companion of his in Rome who was his equal in knowledge. Heraclius travelled to Ḥimṣ and had scarcely reached it when a letter arrived from his companion agreeing with Heraclius’s conclusion that the Prophet ﷺ had appeared and that he was indeed a prophet. Heraclius summoned the Roman dignitaries to a palace of his in Ḥimṣ. He then ordered its doors to be locked. Looking down upon them, he said: “O assembly of Romans! Do you desire success, right guidance, and the preservation of your kingdom? Then pledge allegiance to this Prophet.” They fled wildly toward the doors like startled wild donkeys, but found them locked. When Heraclius witnessed their aversion and despaired of their accepting faith, he said: “Bring them back to me.” He then told them: “I made that statement only to test the firmness of your adherence to your religion, and I have now seen it.” They prostrated themselves before him and became pleased with him. That was the end of the affair of Heraclius."]},"buhuth":{"en":["The phrase “mādda fīhā” means that he concluded a peace treaty with them to cease fighting.","The word “bishop” is an Arabized term meaning a Christian scholar or religious leader.","The term “ḥazzāʾ” means a soothsayer who claims to provide information about hidden matters.","Regarding the phrase “the sin of the Arīsiyyīn,” the commentators have not agreed upon its meaning. It occurred to me that the term may be attributed to Arius the Egyptian, who appeared in the third century CE. He taught that the Messiah was a prophet and denied that he was the son of Allah. His followers were persecuted after Constantine embraced Christianity and adopted the belief that the Messiah was the son of Allah and divine.","Perhaps Heraclius, the Roman emperor, and some of his close associates followed the doctrine of Arius but concealed it out of fear of losing their authority. The Prophet ﷺ may have been informed of this and therefore told him:","“You will bear the sin of the Arīsiyyīn.”","The word “baṭāriqah” is the plural of “baṭrīq,” referring to the senior officials of his state and the members of his council.","The word “daskarah” means a palace surrounded by—or containing—residences for servants and others like them."]}},"tuhfa":{},"voc":["seerah",653],"full":1,"dr":1,"tks":"متفق عليه: رواه البخاري (7)، ومسلم (1773: 74)، والسياق للبخاري."},{"num":9793,"demo":false,"sanad":"","matn":["عن عَبْدِالله بنَ عَبَّاسٍ: أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَكَتَبَ إِلَى قَيْصَرَ وَقَالَ: فَإِنْ تَوَلَّيْتَ فَإِنَّ عَلَيْكَ إِثْمَ الْأَرِيسِيِّينَ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2936) عن إسحاق، أخبرنا يعقوب بن إبراهيم، حدثنا ابن أخي ابن شهاب، عن عمّه قال: أخبرني عبيد الله بن عبد الله بن عتبة بن مسعود قال: فذكره.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى هرقل عظيم الروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2936).","chapter_en":"The Prophet’s ﷺ Letter to Heraclius, the Great Ruler of the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ wrote to Caesar, saying: “If you turn away, you will bear the sin of the Arīsiyyīn.”"]}},"tuhfa":{},"voc":["seerah",654],"full":1,"tks":"صحيح: رواه البخاري (2936)."},{"num":9794,"demo":false,"sanad":"","matn":["عَنْ عَبْدِالله بْنِ عَبَّاسٍ أَنَّ رَسُولَ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ كَتَبَ إِلَى قَيْصَرَ يَدْعُوهُ إِلَى الْإِسْلَامِ، وَبَعَثَ بِكِتَابِهِ إِلَيْهِ مَعَ دِحْيَةَ الْكَلْبِيِّ، وَأَمَرَهُ رَسُولُ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يَدْفَعَهُ إِلَى عَظِيمِ بُصْرَى لِيَدْفَعَهُ إِلَى قَيْصَرَ، وَكَانَ قَيْصَرُ لمَّا كَشَفَ الله عَنْهُ جُنُودَ فَارِسَ مَشَى مِنْ حِمْصَ إِلَى إِيلِيَاءَ شُكْرًا لمَا أَبْلَاهُ الله، فَلَمَّا جَاءَ قَيْصَرَ كِتَابُ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ قَالَ حِينَ قَرَأَهُ: الْتَمِسُوا لِي هَا هُنَا أَحَدًا مِنْ قَوْمِهِ لِأَسْأَلَهُمْ عَنْ رَسُولِ الله صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه البخاري في الجهاد والسير (2940) عن إبراهيم بن حمزة، حدثنا إبراهيم بن سعد، عن صالح بن كيسان، عن ابن شهاب، عن عبيدالله بن عبد الله بن عتبة، عن عبد الله بن عباس قال: فذكره.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى هرقل عظيم الروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī (2940).","chapter_en":"The Prophet’s ﷺ Letter to Heraclius, the Great Ruler of the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":2,"content":{"translation":{"en":["ʿAbdullāh ibn ʿAbbās reported that the Messenger of Allah ﷺ wrote to Caesar, inviting him to Islam. He sent the letter with Diḥyah al-Kalbī and instructed him to deliver it to the ruler of Buṣrā, who would then deliver it to Caesar. When Allah had removed the Persian armies from Caesar, he walked from Ḥimṣ to Aelia in gratitude for the favour Allah had granted him. When the letter of the Messenger of Allah ﷺ reached Caesar and he read it, he said: “Find someone from this man’s people who is present here so that I may question him concerning the Messenger of Allah ﷺ.”"]}},"tuhfa":{},"voc":["seerah",655],"full":1,"tks":"صحيح: رواه البخاري (2940)."},{"num":9795,"demo":false,"sanad":"","matn":["عَنْ أَنَسِ بْنِ مَالِكٍ، قَالَ: قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: مَنْ يَنْطَلِقُ بِصَحِيفَتِي هَذِهِ إِلَى قَيْصَرَ وَلَهُ الْجَنَّةُ؟ فَقَالَ رَجُلٌ مِنَ الْقَوْمِ: وَإِنْ لَمْ يُقْتَلْ؟ قَالَ: وَإِنْ لَمْ يُقْتَلْ، فَانْطَلَقَ الرَّجُلُ بِهِ، فَوَافَقَ قَيْصَرَ وَهُوَ يَأْتِي بَيْتَ الْمَقْدِسِ، قَدْ جُعِلَ لَهُ بِسَاطٌ لَا يَمْشِي عَلَيْهِ غَيْرُهُ، فَرَمَى بِالْكِتَابِ عَلَى الْبِسَاطِ وَتَنَحَّى، فَلَمَّا انْتَهَى قَيْصَرُ إِلَى الْكِتَابِ، أَخَذَهُ، ثُمَّ دَعَا رَأْسَ الْجَاثَلِيقِ، وَأَقْرَأَهُ، فَقَالَ: مَا عِلْمِي فِي هَذَا الْكِتَابِ إِلَاّ كَعِلْمِكَ، فَنَادَى قَيْصَرُ: مَنْ صَاحِبُ الْكِتَابِ؟ فَهُوَ آمِنٌ! فَجَاءَ الرَّجُلُ، فَقَالَ: إِذَا أَنَا قَدِمْتُ فَأْتِنِي! فَلَمَّا قَدِمَ أَتَاهُ، فَأَمَرَ قَيْصَرُ بِأَبْوَابِ قَصْرِهِ، فَغُلِّقَتْ، ثُمَّ أَمَرَ مُنَادِيًا فَنَادَى: أَلَا إِنَّ قَيْصَرَ قَدِ اتَّبَعَ مُحَمَّدًا صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَتَرَكَ النَّصْرَانِيَّةَ! فَأَقْبَلَ جُنْدُهُ وَقَدْ تَسَلَّحُوا حَتَّى أَطَافُوا بِقَصْرِهِ، فَقَالَ لِرَسُولِ رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: قَدْ تَرَى أَنِّي خَائِفٌ عَلَى مَمْلَكَتِي! ثُمَّ أَمَرَ مُنَادِيًا فَنَادَى: أَلَا إِنَّ قَيْصَرَ قَدْ رَضِيَ عَنْكُمْ، وَإِنَّمَا اخْتَبَرَكُمْ لَيَنْظُرَ كَيْفَ صَبْرُكُمْ عَلَى دِينِكُمْ، فَارْجِعُوا! فَانْصَرَفُوا، وَكَتَبَ قَيْصَرُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ: إِنِّي مُسْلِمٌ، وَبَعَثَ إِلَيْهِ بِدَنَانِيرَ، فَقَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ حِينَ قَرَأَ الْكِتَابَ: كَذَبَ عَدُوُّ اللَّهِ، لَيْسَ بِمُسْلِمٍ، وَهُوَ عَلَى النَّصْرَانِيَّةِ! وَقَسَّمَ الدَّنَانِيرَ."],"takhrij":"صحيح: رواه ابن حبان (4504) عن محمد بن إسحاق بن إبراهيم مولى ثقيف، قال: حدثنا أبو يحيى محمد بن عبد الرحيم صاعقة، قال: حدثنا علي بن بحر، قال: حدثنا مروان بن معاوية الفزاري، قال: حدثنا حميد، عن أنس بن مالك، فذكره. وإسناده صحيح.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى هرقل عظيم الروم","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Ibn Ḥibbān (4504).","chapter_en":"The Prophet’s ﷺ Letter to Heraclius, the Great Ruler of the Romans","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":2,"content":{"translation":{"en":["Anas ibn Mālik reported that the Messenger of Allah ﷺ said: “Who will take this letter of mine to Caesar? He shall have Paradise.” A man from among the people asked: “Even if I am not killed?” He replied: “Even if you are not killed.” The man departed with the letter and encountered Caesar as he was approaching Jerusalem. A special carpet had been laid out for Caesar upon which no one else was permitted to walk. The man threw the letter onto the carpet and stepped aside. When Caesar reached the letter, he picked it up. He then summoned the chief Catholicos and had him read it. The Catholicos said: “My knowledge concerning this letter is no greater than yours.” Caesar then proclaimed: “Whoever brought this letter shall be granted safety.” The man came forward, and Caesar said to him: “When I return, come to me.” When Caesar returned, the man came to him. Caesar ordered the doors of his palace to be locked. He then instructed a herald to proclaim: “Behold! Caesar has followed Muḥammad ﷺ and abandoned Christianity!” His soldiers advanced fully armed until they surrounded his palace. Caesar said to the messenger of the Messenger of Allah ﷺ: “You can see that I fear for my kingdom.” He then instructed a herald to proclaim: “Behold! Caesar is pleased with you. He merely tested you to see how firmly you would adhere to your religion. You may now return.” They therefore dispersed. Caesar wrote to the Messenger of Allah ﷺ, claiming: “I am a Muslim.” He also sent him some gold dinars. When the Messenger of Allah ﷺ read the letter, he said: “The enemy of Allah has lied. He is not a Muslim; he remains upon Christianity.” The Prophet ﷺ then distributed the dinars."]}},"tuhfa":{},"voc":["seerah",656],"full":1,"tks":"صحيح: رواه ابن حبان (4504)."},{"num":9796,"demo":false,"sanad":"","matn":["عَنِ ابْنِ عَبَّاسٍ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ بِكِتَابِهِ إِلَى كِسْرَى مَعَ عَبْدِ اللَّهِ بْنِ حُذَافَةَ السَّهْمِيِّ، فَأَمَرَهُ أَنْ يَدْفَعَهُ إِلَى عَظِيمِ الْبَحْرَيْنِ، فَدَفَعَهُ عَظِيمُ الْبَحْرَيْنِ إِلَى كِسْرَى، فَلَمَّا قَرَأَهُ مَزَّقَهُ، فَحَسِبْتُ (القائل هُوَ الزهري) أَنَّ ابْنَ الْمُسَيَّبِ قَالَ: فَدَعَا عَلَيْهِمْ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنْ يُمَزَّقُوا كُلَّ مُمَزَّقٍ."],"takhrij":"صحيح: رواه البخاري في المغازي (4424) عن إسحاق (هو ابن راهويه)، حدثنا يعقوب بن إبراهيم، حدثنا أبي، عن صالح (هو ابن كيسان)، عن ابن شهاب، قال: أخبرني عبيد الله بن عبد الله، أن ابن عباس أخبره قال: فذكره.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى كسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Military Campaigns (4424).","chapter_en":"The Prophet’s ﷺ Letter to Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":3,"content":{"translation":{"en":["Ibn ʿAbbās reported that the Messenger of Allah ﷺ sent his letter to Khosrow with ʿAbdullāh ibn Ḥudhāfah al-Sahmī and instructed him to deliver it to the ruler of Bahrain. The ruler of Bahrain then delivered it to Khosrow. When Khosrow read it, he tore it apart. Al-Zuhrī said: I believe that Ibn al-Musayyib said that the Messenger of Allah ﷺ then supplicated against them, asking that they be utterly torn apart."]},"buhuth":{"en":["Ibn Saʿd stated decisively that this occurred in the seventh year, during the truce. However, al-Bukhārī’s arrangement indicates that it occurred in the ninth year."]}},"tuhfa":{},"voc":["seerah",657],"full":1,"dr":1,"tks":"صحيح: رواه البخاري (4424)."},{"num":9797,"demo":false,"sanad":"","matn":["عَنْ أَبِي بَكْرَةَ، قَالَ: لَقَدْ نَفَعَنِي اللَّهُ بِكَلِمَةٍ سَمِعْتُهَا مِنْ، رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَيَّامَ الْجَمَلِ، بَعْدَ مَا كِدْتُ أَنْ أَلْحَقَ بِأَصْحَابِ الْجَمَلِ، فَأُقَاتِلَ مَعَهُمْ، قَالَ: لَمَّا بَلَغَ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ أَنَّ أَهْلَ فَارِسَ قَدْ مَلَّكُوا عَلَيْهِمْ بِنْتَ كِسْرَى قَالَ: لَنْ يُفْلِحَ قَوْمٌ وَلَّوْا أَمْرَهُمُ امْرَأَةً."],"takhrij":"صحيح: رواه البخاري في المغازي (4425) عن عثمان بن الهيثم، حدثنا عوف، عن الحسن، عن أبي بكرة قال: فذكره.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى كسرى","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Bukhārī in the Book of Military Campaigns (4425).","chapter_en":"The Prophet’s ﷺ Letter to Khosrow","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":3,"content":{"translation":{"en":["Abū Bakrah reported: Allah benefited me through a statement that I heard from the Messenger of Allah ﷺ during the days of the Battle of the Camel, after I had nearly joined the army of the Camel and fought alongside them. When news reached the Messenger of Allah ﷺ that the people of Persia had appointed the daughter of Khosrow as their ruler, he said: “A people who entrust their affairs to a woman will never prosper.”"]},"buhuth":{"en":["This occurred when news reached the Prophet ﷺ that Khosrow had been killed and that his daughter had succeeded him. This was narrated by al-Tirmidhī (2262), al-Nasā’ī (5388), and al-Ḥākim (3/118–119), all from the hadith of Abū Bakrah, who said:","“Allah protected me by means of something I had heard from the Messenger of Allah ﷺ. When Khosrow perished, he asked:","‘Whom have they appointed as his successor?’","They replied:","‘His daughter.’","The Prophet ﷺ then said:","‘A people who entrust their affairs to a woman will never prosper.’","When ʿĀ’ishah arrived—that is, in Basra—I remembered the statement of the Messenger of Allah ﷺ, and Allah protected me through it.”","The wording is that of al-Tirmidhī, who said: “This is an authentic hadith.”"]}},"tuhfa":{},"voc":["seerah",658],"full":1,"dr":1,"rep":[8287,9749,10329],"tks":"صحيح: رواه البخاري (4425)."},{"num":9798,"demo":false,"sanad":"","matn":["عَنْ عَبْدِ الرَّحْمَنِ بْنِ عَبْدِ الْقَارِيِّ أَنَّ رَسُولَ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ بَعَثَ حَاطِبَ بْنَ أَبِي بَلْتَعَةَ إِلَى الْمَقَوْقِسِ صَاحِبِ الإِسْكَنْدَرِيَّةِ، يَعْنِي بِكِتَابِهِ مَعَهُ إِلَيْهِ، فَقَبِلَ كِتَابَهُ وَأَكْرَمَ حَاطِبًا، وَأَحْسَنَ نُزُلَهُ، ثُمَّ سَرَّحَهُ إِلَى رَسُولِ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ، وَأَهْدَى لَهُ مَعَ حَاطِبٍ كُسْوَةً وَبَغْلَةً شَهْبَاءَ بِسَرِجِهَا وَجَارِيَتَيْنِ، إِحْدَاهُمَا أُمُّ إِبْرَاهِيمَ، وَأَمَّا الأُخْرَى فَوَهَبَهَا لِجَهْمِ بْنِ قَيْسٍ الْعَبْدَرِيِّ، وَهِيَ أُمُّ زَكَرِيَّا بْنِ جَهْمٍ الَّذِي كَانَ خَلِيفَةَ عَمْرٍو بْنِ الْعَاصِ عَلَى مِصْرَ."],"takhrij":"صحيح: رواه الطحاوي في شرح المشكل (2570،4349)، وابن عبدالحكم في الفتوح (ص 64) كلاهما من حديث عبد الله بن وهب، أخبرني يونس بن يزيد، عن ابن شهاب، قال: حدثني عبد الرحمن بن عبدٍ القاري، فذكره. واللفظ للطحاوي.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى المقوقس حاكم مصر","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by al-Ṭaḥāwī in Sharḥ al-Mushkil (2570, 4349) and Ibn ʿAbd al-Ḥakam in al-Futūḥ (p. 64).","chapter_en":"The Prophet’s ﷺ Letter to al-Muqawqis, the Ruler of Egypt","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":4,"content":{"translation":{"en":["ʿAbd al-Raḥmān ibn ʿAbd al-Qārī reported that the Messenger of Allah ﷺ sent Ḥāṭib ibn Abī Baltaʿah to al-Muqawqis, the ruler of Alexandria, carrying his letter to him. Al-Muqawqis kissed the letter, honoured Ḥāṭib, and provided him with gracious hospitality. He then sent him back to the Messenger of Allah ﷺ, sending with him as gifts a garment, a grey mule together with its saddle, and two bondwomen. One of them was the mother of Ibrāhīm. The other was given to Jahm ibn Qays al-ʿAbdarī; she was the mother of Zakariyyā ibn Jahm, who served as ʿAmr ibn al-ʿĀṣ’s deputy over Egypt."]},"buhuth":{"en":["The text of the letter was as follows:","“In the name of Allah, the Most Compassionate, the Most Merciful.","From Muḥammad, the Messenger of Allah, to al-Muqawqis, the great ruler of the Copts:","Peace be upon whoever follows the guidance.","To proceed: I invite you with the call of Islam. Embrace Islam and you will be safe. Embrace Islam, and Allah will grant you your reward twice. If you turn away, you will bear the sin of the Copts.","ʿO People of the Scripture, come to a word that is equitable between us and you: that we worship none but Allah, associate nothing with Him, and do not take one another as lords besides Allah. But if they turn away, then say, “Bear witness that we are Muslims.”’” [Āl ʿImrān: 64]","Al-Zubayr ibn Bakkār narrated it, as cited in Muntakhab Kitāb Azwāj al-Nabī ﷺ. He said:","Muḥammad ibn Ḥasan related to me, from Muḥammad ibn Ṭalḥah, from Saʿīd ibn ʿAbd al-Raḥmān ibn Ḥassān, from his father; and from Isḥāq ibn Ibrāhīm, from ʿAbdullāh ibn Ḥārithah ibn al-Nuʿmān:","When the Messenger of Allah ﷺ returned from al-Ḥudaybiyah in the sixth year, he dispatched six men, travelling in three pairs: Ḥāṭib ibn Abī Baltaʿah to al-Muqawqis, Shujāʿ ibn Wahb to al-Ḥārith ibn Abī Shamir, and Diḥyah al-Kalbī to Caesar. They travelled until they reached Wādī al-Qurā, whereupon Ḥāṭib took the route to al-Muqawqis carrying a letter from the Messenger of Allah ﷺ containing the foregoing text.","Al-Zaylaʿī also mentioned a similar account from al-Wāqidī in Naṣb al-Rāyah (4/421–422), saying:","Ḥāṭib departed with the letter until he reached Alexandria. When he entered the presence of al-Muqawqis, he said:","“Know that before you there was a man who claimed to be the supreme lord. Allah therefore seized him with an exemplary punishment in the Hereafter and in this world. Allah used him to exact retribution from others and then exacted retribution from him. Therefore, take warning from what happened to others, and do not let others be made to take warning from what happens to you.","“Know that we possess a religion that we will never abandon except for one better than it—and that is Islam, through which Allah has rendered everything else unnecessary. This Prophet called the people, and Quraysh were the fiercest in opposing him, the Jews were the most hostile toward him, and the Christians were the closest to him.","“By my life, Moses’s glad tidings of Jesus were no different from Jesus’s glad tidings of Muḥammad. Our invitation to you to follow the Qur’an is no different from your invitation to the people of the Torah to follow the Gospel. Whenever a prophet reaches a people, they become part of his nation and are obligated to obey him. You are among those whom this Prophet has reached. We are not forbidding you from the religion of the Messiah; rather, we are commanding you to adhere to it.”","Al-Muqawqis replied:","“I have considered the affair of this Prophet. I have found that he does not command that which ought to be shunned, nor forbid that which ought to be desired. I have not found him to be a misguided sorcerer or a lying soothsayer. I have found with him the signs of prophethood: disclosing that which is concealed and informing of secret conversations. I shall give the matter further consideration.”","He took the Prophet’s ﷺ letter, placed it in an ivory container, sealed it, and entrusted it to one of his bondwomen. He then summoned a scribe who could write Arabic and dictated the following reply to the Prophet ﷺ:","“In the name of Allah, the Most Compassionate, the Most Merciful.","To Muḥammad ibn ʿAbdullāh, from al-Muqawqis, the great ruler of the Copts:","Peace be upon you.","To proceed: I have read your letter and understood what you mentioned therein and that to which you invite. I knew that a prophet still remained to appear, but I believed that he would emerge in Greater Syria. I have honoured your messenger and am sending you two bondwomen who hold a distinguished position among the Copts, along with a garment and a mule for you to ride.","Peace be upon you.”","He handed the letter to Ḥāṭib and ordered that he be given one hundred dinars and five garments. He then told him:","“Return to your companion, and do not let the Copts hear a single word from you. The Copts would not obey me if I were to follow him, and I am too possessive of my kingdom to relinquish it. Your companion will prevail over the lands, and after him his Companions will descend upon this very territory of ours. Now depart from me.”","Ḥāṭib said:","“I departed from him after remaining with him for only five days. When I returned to the Messenger of Allah ﷺ, I told him what al-Muqawqis had said to me. He replied:","‘The wicked man clung miserly to his kingdom, but his kingdom will not endure.’”","Some parts of this account contain matters that are unusual."]}},"tuhfa":{},"voc":["seerah",659],"full":1,"dr":1,"tks":"صحيح: رواه الطحاوي في «شرح المشكل» (2570، 4349)، وابن عبد الحكم في «الفتوح» (ص 64)."},{"num":9799,"demo":false,"sanad":"","matn":["عن يَزِيدَ بْنِ عَبْدِ اللَّهِ قَالَ: كُنَّا بِالْمِرْبَدِ فَجَاءَ رَجُلٌ أَشْعَثُ الرَّأْسِ بِيَدِهِ قِطْعَةُ أَدِيمٍ أَحْمَرَ فَقُلْنَا كَأَنَّكَ مِنْ أَهْلِ الْبَادِيَةِ. فَقَالَ أَجَلْ. قُلْنَا: نَاوِلْنَا هَذِهِ الْقِطْعَةَ الأَدِيمَ الَّتِي فِي يَدِكَ فَنَاوَلَنَاهَا فَقَرَأْنَاهَا فَإِذَا فِيهَا: مِنْ مُحَمَّدٍ رَسُولِ اللَّهِ إِلَى بَنِي زُهَيْرِ بْنِ أُقَيْشٍ إِنَّكُمْ إِنْ شَهِدْتُمْ أَنْ لاَ إِلَهَ إِلاَّ اللَّهُ وَأَنَّ مُحَمَّدًا رَسُولُ اللَّهِ وَأَقَمْتُمُ الصَّلاَةَ وَآتَيْتُمُ الزَّكَاةَ وَأَدَّيْتُمُ الْخُمُسَ مِنَ الْمَغْنَمِ وَسَهْمَ النَّبِيِّ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ وَسَهْمَ الصَّفِيِّ أَنْتُمْ آمِنُونَ بِأَمَانِ اللَّهِ وَرَسُولِهِ. فَقُلْنَا مَنْ كَتَبَ لَكَ هَذَا الْكِتَابَ قَالَ رَسُولُ اللَّهِ صَلَّى اللَّهُ عَلَيْهِ وَسَلَّمَ."],"takhrij":"صحيح: رواه أبو داود (2999)، وأحمد (20740)، وصحّحه ابن حبان (6557) من طرق عن قرة بن خالد، سمعت يزيد بن عبد الله فذكره.","grade":"صحيح","chapter_ar":"باب كتاب النبي ﷺ إلى بني زهير بن أقيش، حيٍّ من عُكْل","chapter_ur":"","part_ar":"كتاب سيرة النبي ﷺ","part_ur":"","takhrij_en":"Authentic: Narrated by Abū Dāwūd (2999) and Aḥmad (20740), and authenticated by Ibn Ḥibbān (6557).","chapter_en":"The Prophet’s ﷺ Letter to Banū Zuhayr ibn Uqaysh, a Clan of ʿUkl","part_en":"Book of the Biography of the Prophet ﷺ","group_ar":"جموع ما جاء في كتب النبي ﷺ إلى الملوك والأمراء يدعوهم إلى الإسلام","group_en":"A Collection of Reports Concerning the Prophet’s ﷺ Letters to Kings and Rulers Inviting Them to Islam","part_no":48,"group_no":41,"chapter_no":5,"content":{"translation":{"en":["Yazīd ibn ʿAbdullāh reported: We were at al-Mirbad when a man with dishevelled hair arrived, holding a piece of red leather in his hand. We said: “You appear to be from the desert.” He replied: “Yes.” We said: “Hand us the piece of leather that you are holding.” He handed it to us, and we read it. It contained: “From Muḥammad, the Messenger of Allah, to Banū Zuhayr ibn Uqaysh: If you testify that there is no deity worthy of worship except Allah and that Muḥammad is the Messenger of Allah, establish the prayer, give zakāh, deliver one-fifth of the spoils, along with the Prophet’s ﷺ share and the selected share, then you shall be secure under the protection of Allah and His Messenger.” We asked: “Who wrote this document for you?” He replied: “The Messenger of Allah ﷺ.”"]}},"tuhfa":{},"voc":["seerah",660],"full":1,"dr":1,"rep":[8066],"tks":"صحيح: رواه أبو داود (2999)، وأحمد (20740)، وصححه ابن حبان (6557)."}]);